INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('WindowsPE', '', 2, 'private rule WindowsPE\n{\n    condition:\n        uint16(0) == 0x5A4D and uint32(uint32(0x3C)) == 0x00004550\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Check_Dlls', '', 2, 'rule Check_Dlls\n{\n	meta:\n		Author = \"Nick Hoffman\"\n		Description = \"Checks for common sandbox dlls\"\n		Sample = \"de1af0e97e94859d372be7fcf3a5daa5\"\n	strings:\n		$dll1 = \"sbiedll.dll\" wide nocase ascii fullword\n		$dll2 = \"dbghelp.dll\" wide nocase ascii fullword\n		$dll3 = \"api_log.dll\" wide nocase ascii fullword\n		$dll4 = \"dir_watch.dll\" wide nocase ascii fullword\n		$dll5 = \"pstorec.dll\" wide nocase ascii fullword\n		$dll6 = \"vmcheck.dll\" wide nocase ascii fullword\n		$dll7 = \"wpespy.dll\" wide nocase ascii fullword\n	condition:\n		2 of them\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Check_Qemu_Description', '', 2, 'rule Check_Qemu_Description\n{\n	meta:\n		Author = \"Nick Hoffman\"\n		Description = \"Checks for QEMU systembiosversion key\"\n		Sample = \"de1af0e97e94859d372be7fcf3a5daa5\"\n	strings:\n		$key = \"HARDWARE\\\\Description\\\\System\" nocase wide ascii\n		$value = \"SystemBiosVersion\" nocase wide ascii\n		$data = \"QEMU\" wide nocase ascii\n	condition:\n		all of them\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Check_Qemu_DeviceMap', '', 2, 'rule Check_Qemu_DeviceMap\n{\n	meta:\n		Author = \"Nick Hoffman\"\n		Description = \"Checks for Qemu reg keys\"\n		Sample = \"de1af0e97e94859d372be7fcf3a5daa5\"\n	strings:\n		$key = \"HARDWARE\\\\DEVICEMAP\\\\Scsi\\\\Scsi Port 0\\\\Scsi Bus 0\\\\Target Id 0\\\\Logical Unit Id 0\" nocase wide ascii\n		$value = \"Identifier\" nocase wide ascii\n		$data = \"QEMU\" wide nocase ascii\n	condition:\n		all of them\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Check_VBox_Description', '', 2, 'rule Check_VBox_Description\n{\n	meta:\n		Author = \"Nick Hoffman\"\n		Description = \"Checks Vbox description reg key\"\n		Sample = \"de1af0e97e94859d372be7fcf3a5daa5\"\n	strings:\n		$key = \"HARDWARE\\\\Description\\\\System\" nocase wide ascii\n		$value = \"SystemBiosVersion\" nocase wide ascii\n		$data = \"VBOX\" nocase wide ascii\n	condition:\n		all of them\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Check_VBox_DeviceMap', '', 2, 'rule Check_VBox_DeviceMap\n{\n	meta:\n		Author = \"Nick Hoffman\"\n		Description = \"Checks Vbox registry keys\"\n		Sample = \"de1af0e97e94859d372be7fcf3a5daa5\"\n	strings:\n		$key = \"HARDWARE\\\\DEVICEMAP\\\\Scsi\\\\Scsi Port 0\\\\Scsi Bus 0\\\\Target Id 0\\\\Logical Unit Id 0\" nocase wide ascii\n		$value = \"Identifier\" nocase wide ascii\n		$data = \"VBOX\" nocase wide ascii\n	condition:\n		all of them\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Check_VBox_Guest_Additions', '', 2, 'rule Check_VBox_Guest_Additions\n{\n	meta:\n		Author = \"Nick Hoffman\"\n		Description = \"Checks for the existence of the guest additions registry key\"\n		Sample = \"de1af0e97e94859d372be7fcf3a5daa5\"\n	strings:\n		$key = \"SOFTWARE\\\\Oracle\\\\VirtualBox Guest Additions\" wide ascii nocase\n	condition:\n		any of them\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Check_VBox_VideoDrivers', '', 2, 'rule Check_VBox_VideoDrivers\n{\n	meta:\n		Author = \"Nick Hoffman\"\n		Description = \"Checks for reg keys of Vbox video drivers\"\n		Sample = \"de1af0e97e94859d372be7fcf3a5daa5\"\n	strings:\n		$key = \"HARDWARE\\\\Description\\\\System\" nocase wide ascii\n		$value = \"VideoBiosVersion\" wide nocase ascii\n		$data = \"VIRTUALBOX\" nocase wide ascii\n	condition:\n		all of them\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Check_VMWare_DeviceMap', '', 2, 'rule Check_VMWare_DeviceMap\n{\n	meta:\n		Author = \"Nick Hoffman\"\n		Description = \"Checks for the existence of VmWare Registry Keys\"\n		Sample = \"de1af0e97e94859d372be7fcf3a5daa5\"\n	strings:\n		$key = \"HARDWARE\\\\DEVICEMAP\\\\Scsi\\\\Scsi Port 0\\\\Scsi Bus 0\\\\Target Id 0\\\\Logical Unit Id 0\" wide ascii nocase\n		$value = \"Identifier\" wide nocase ascii\n		$data = \"VMware\" wide nocase ascii\n	condition:\n		all of them\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Check_VmTools', '', 2, 'rule Check_VmTools\n{\n	meta:\n		Author = \"Nick Hoffman\"\n		Description = \"Checks for the existence of VmTools reg key\"\n		Sample = \"de1af0e97e94859d372be7fcf3a5daa5\"\n	strings:\n		$ =\"SOFTWARE\\\\VMware, Inc.\\\\VMware Tools\" nocase ascii wide\n	condition:\n		any of them\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Check_Wine', '', 2, 'rule Check_Wine\n{\n	meta:\n		Author = \"Nick Hoffman\"\n		Description = \"Checks for the existence of Wine\"\n		Sample = \"de1af0e97e94859d372be7fcf3a5daa5\"\n	strings:\n		$ =\"wine_get_unix_file_name\"\n	condition:\n		any of them\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('vmdetect', 'Possibly employs anti-virtualization techniques', 2, 'rule vmdetect\n{\n    meta:\n        author = \"nex\"\n        description = \"Possibly employs anti-virtualization techniques\"\n\n    strings:\n        \n        $vmware = {56 4D 58 68}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Check_Debugger', '', 2, 'rule Check_Debugger\n{\n	meta:\n		Author = \"Nick Hoffman\"\n		Description = \"Looks for both isDebuggerPresent and CheckRemoteDebuggerPresent\"\n		Sample = \"de1af0e97e94859d372be7fcf3a5daa5\"\n	condition:\n		pe.imports(\"kernel32.dll\",\"CheckRemoteDebuggerPresent\") and\n		pe.imports(\"kernel32.dll\",\"IsDebuggerPresent\")\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Check_DriveSize', '', 2, 'rule Check_DriveSize\n{\n	meta:\n		Author = \"Nick Hoffman\"\n		Description = \"Rule tries to catch uses of DeviceIOControl being used to get the drive size\"\n		Sample = \"de1af0e97e94859d372be7fcf3a5daa5\"\n\n	strings:\n		$physicaldrive = \"\\\\\\\\.\\\\PhysicalDrive0\" wide ascii nocase\n		$dwIoControlCode = {68 5c 40 07 00 [0-5] FF 15}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Check_FilePaths', '', 2, 'rule Check_FilePaths\n{\n	meta:\n		Author = \"Nick Hoffman\"\n		Description = \"Checks for filepaths containing popular sandbox names\"\n		Sample = \"de1af0e97e94859d372be7fcf3a5daa5\"\n	strings:\n		$path1 = \"SANDBOX\" wide ascii\n		$path2 = \"\\\\SAMPLE\" wide ascii\n		$path3 = \"\\\\VIRUS\" wide ascii\n	condition:\n		all of ($path*) and pe.imports(\"kernel32.dll\",\"GetModuleFileNameA\")\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Check_UserNames', '', 2, 'rule Check_UserNames\n{\n	meta:\n		Author = \"Nick Hoffman\"\n		Description = \"Looks for malware checking for common sandbox usernames\"\n		Sample = \"de1af0e97e94859d372be7fcf3a5daa5\"\n	strings:\n		$user1 = \"MALTEST\" wide ascii\n		$user2 = \"TEQUILABOOMBOOM\" wide ascii\n		$user3 = \"SANDBOX\" wide ascii\n		$user4 = \"VIRUS\" wide ascii\n		$user5 = \"MALWARE\" wide ascii\n	condition:\n		all of ($user*)  and pe.imports(\"advapi32.dll\",\"GetUserNameA\")\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Check_OutputDebugStringA_iat', '', 2, 'rule Check_OutputDebugStringA_iat\n{\n\n	meta:\n		Author = \"http:\n		Description = \"Detect in IAT OutputDebugstringA\"\n		Date = \"20/04/2015\"\n\n	condition:\n		pe.imports(\"kernel32.dll\",\"OutputDebugStringA\")\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Check_FindWindowA_iat', '', 2, 'rule Check_FindWindowA_iat {\n\n	meta:\n		Author = \"http:\n		Description = \"it''s checked if FindWindowA() is imported\"\n		Date = \"20/04/2015\"\n		Reference = \"http:\n\n	strings:\n		$ollydbg = \"OLLYDBG\"\n		$windbg = \"WinDbgFrameClass\"\n\n	condition:\n		pe.imports(\"user32.dll\",\"FindWindowA\") and ($ollydbg or $windbg)\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('WMI_VM_Detect', 'Detection of Virtual Appliances through the use of WMI for use of evasion.', 2, 'rule WMI_VM_Detect : WMI_VM_Detect\n{\n    meta:\n\n        version = 2\n        threat = \"Using WMI to detect virtual machines via querying video card information\"\n        behaviour_class = \"Evasion\"\n        author = \"Joe Giron\"\n        date = \"2015-09-25\"\n        description = \"Detection of Virtual Appliances through the use of WMI for use of evasion.\"\n\n		strings:\n\n		$selstr 	= \"SELECT Description FROM Win32_VideoController\" nocase ascii wide\n		$selstr2 	= \"SELECT * FROM Win32_VideoController\" nocase ascii wide\n		$vm1 		= \"virtualbox graphics adapter\" nocase ascii wide\n		$vm2 		= \"vmware svga ii\" nocase ascii wide\n		$vm3 		= \"vm additions s3 trio32/64\" nocase ascii wide\n		$vm4 		= \"parallel\" nocase ascii wide\n		$vm5 		= \"remotefx\" nocase ascii wide\n		$vm6 		= \"cirrus logic\" nocase ascii wide\n		$vm7 		= \"matrox\" nocase ascii wide\n\n		condition:\n		any of ($selstr*) and any of ($vm*)\n\n\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('anti_dbg', 'Checks if being debugged', 2, 'rule anti_dbg {\n    meta:\n        author = \"x0r\"\n        description = \"Checks if being debugged\"\n	version = \"0.2\"\n    strings:\n    	$d1 = \"Kernel32.dll\" nocase\n        $c1 = \"CheckRemoteDebuggerPresent\"\n        $c2 = \"IsDebuggerPresent\"\n        $c3 = \"OutputDebugString\"\n        $c4 = \"ContinueDebugEvent\"\n        $c5 = \"DebugActiveProcess\"\n    condition:\n        $d1 and 1 of ($c*)\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('anti_dbgtools', 'Checks for the presence of known debug tools', 2, 'rule anti_dbgtools {\n    meta:\n        author = \"x0r\"\n        description = \"Checks for the presence of known debug tools\"\n	version = \"0.1\"\n    strings:\n        $f1 = \"procexp.exe\" nocase\n        $f2 = \"procmon.exe\" nocase\n        $f3 = \"processmonitor.exe\" nocase\n        $f4 = \"wireshark.exe\" nocase\n        $f5 = \"fiddler.exe\" nocase\n        $f6 = \"windbg.exe\" nocase\n        $f7 = \"ollydbg.exe\" nocase\n        $f8 = \"winhex.exe\" nocase\n        $f9 = \"processhacker.exe\" nocase\n        $f10 = \"hiew32.exe\" nocase\n        $c11 = \"\\\\\\\\.\\\\NTICE\"\n        $c12 = \"\\\\\\\\.\\\\SICE\"\n        $c13 = \"\\\\\\\\.\\\\Syser\"\n        $c14 = \"\\\\\\\\.\\\\SyserBoot\"\n        $c15 = \"\\\\\\\\.\\\\SyserDbgMsg\"\n    condition:\n        any of them\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('antisb_joesanbox', 'Anti-Sandbox checks for Joe Sandbox', 2, 'rule antisb_joesanbox {\n     meta:\n        author = \"x0r\"\n        description = \"Anti-Sandbox checks for Joe Sandbox\"\n	version = \"0.1\"\n    strings:\n	$p1 = \"Software\\\\Microsoft\\\\Windows\\\\CurrentVersion\" nocase\n	$c1 = \"RegQueryValue\"\n	$s1 = \"55274-640-2673064-23950\"\n    condition:\n        all of them\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('antisb_anubis', 'Anti-Sandbox checks for Anubis', 2, 'rule antisb_anubis {\n    meta:\n        author = \"x0r\"\n        description = \"Anti-Sandbox checks for Anubis\"\n	version = \"0.1\"\n    strings:\n        $p1 = \"Software\\\\Microsoft\\\\Windows\\\\CurrentVersion\" nocase\n        $c1 = \"RegQueryValue\"\n        $s1 = \"76487-337-8429955-22614\"\n        $s2 = \"76487-640-1457236-23837\"\n    condition:\n        $p1 and $c1 and 1 of ($s*)\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('antisb_threatExpert', 'Anti-Sandbox checks for ThreatExpert', 2, 'rule antisb_threatExpert {\n    meta:\n        author = \"x0r\"\n        description = \"Anti-Sandbox checks for ThreatExpert\"\n	version = \"0.1\"\n    strings:\n        $f1 = \"dbghelp.dll\" nocase\n    condition:\n        all of them\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('antisb_sandboxie', 'Anti-Sandbox checks for Sandboxie', 2, 'rule antisb_sandboxie {\n    meta:\n        author = \"x0r\"\n        description = \"Anti-Sandbox checks for Sandboxie\"\n	version = \"0.1\"\n    strings:\n        $f1 = \"SbieDLL.dll\" nocase\n    condition:\n        all of them\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('antisb_cwsandbox', 'Anti-Sandbox checks for CWSandbox', 2, 'rule antisb_cwsandbox {\n    meta:\n        author = \"x0r\"\n        description = \"Anti-Sandbox checks for CWSandbox\"\n	version = \"0.1\"\n    strings:\n        $p1 = \"Software\\\\Microsoft\\\\Windows\\\\CurrentVersion\" nocase\n        $s1 = \"76487-644-3177037-23510\"\n    condition:\n        all of them\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('antivm_virtualbox', 'AntiVM checks for VirtualBox', 2, 'rule antivm_virtualbox {\n    meta:\n        author = \"x0r\"\n        description = \"AntiVM checks for VirtualBox\"\n	version = \"0.1\"\n    strings:\n        $s1 = \"VBoxService.exe\" nocase\n    condition:\n        any of them\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('antivm_vmware', 'AntiVM checks for VMWare', 2, 'rule antivm_vmware {\n    meta:\n        author = \"x0r\"\n        description = \"AntiVM checks for VMWare\"\n	version = \"0.1\"\n    strings:\n        $s1 = \"vmware.exe\" nocase\n        $s2 = \"vmware-authd.exe\" nocase\n        $s3 = \"vmware-hostd.exe\" nocase\n        $s4 = \"vmware-tray.exe\" nocase\n        $s5 = \"vmware-vmx.exe\" nocase\n        $s6 = \"vmnetdhcp.exe\" nocase\n        $s7 = \"vpxclient.exe\" nocase\n    	$s8 = { b868584d56bb00000000b90a000000ba58560000ed }', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('antivm_bios', 'AntiVM checks for Bios version', 2, 'rule antivm_bios {\n    meta:\n        author = \"x0r\"\n        description = \"AntiVM checks for Bios version\"\n	version = \"0.2\"\n    strings:\n        $p1 = \"HARDWARE\\\\DESCRIPTION\\\\System\" nocase\n        $p2 = \"HARDWARE\\\\DESCRIPTION\\\\System\\\\BIOS\" nocase\n        $c1 = \"RegQueryValue\"\n        $r1 = \"SystemBiosVersion\"\n        $r2 = \"VideoBiosVersion\"\n        $r3 = \"SystemManufacturer\"\n    condition:\n        1 of ($p*) and 1 of ($c*) and 1 of ($r*)\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('disable_antivirus', 'Disable AntiVirus', 2, 'rule disable_antivirus {\n    meta:\n        author = \"x0r\"\n        description = \"Disable AntiVirus\"\n	version = \"0.2\"\n    strings:\n        $p1 = \"Software\\\\Microsoft\\\\Windows\\\\CurrentVersion\\\\Policies\\\\Explorer\\\\DisallowRun\" nocase\n        $p2 = \"Software\\\\Microsoft\\\\Windows\\\\CurrentVersion\\\\Uninstall\\\\\" nocase\n        $p3 = \"SOFTWARE\\\\Policies\\\\Microsoft\\\\Windows Defender\" nocase\n        $c1 = \"RegSetValue\"\n        $r1 = \"AntiVirusDisableNotify\"\n        $r2 = \"DontReportInfectionInformation\"\n        $r3 = \"DisableAntiSpyware\"\n        $r4 = \"RunInvalidSignatures\"\n        $r5 = \"AntiVirusOverride\"\n        $r6 = \"CheckExeSignatures\"\n        $f1 = \"blackd.exe\" nocase\n        $f2 = \"blackice.exe\" nocase\n        $f3 = \"lockdown.exe\" nocase\n        $f4 = \"lockdown2000.exe\" nocase\n        $f5 = \"taskkill.exe\" nocase\n        $f6 = \"tskill.exe\" nocase\n        $f7 = \"smc.exe\" nocase\n        $f8 = \"sniffem.exe\" nocase\n        $f9 = \"zapro.exe\" nocase\n        $f10 = \"zlclient.exe\" nocase\n        $f11 = \"zonealarm.exe\" nocase\n    condition:\n        ($c1 and $p1 and 1 of ($f*)) or ($c1 and $p2) or 1 of ($r*) or $p3\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('disable_uax', 'Disable User Access Control', 2, 'rule disable_uax {\n    meta:\n        author = \"x0r\"\n        description = \"Disable User Access Control\"\n	version = \"0.1\"\n    strings:\n        $p1 = \"SOFTWARE\\\\Microsoft\\\\Security Center\" nocase\n        $r1 = \"UACDisableNotify\"\n    condition:\n        all of them\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('disable_firewall', 'Disable Firewall', 2, 'rule disable_firewall {\n    meta:\n        author = \"x0r\"\n        description = \"Disable Firewall\"\n	version = \"0.1\"\n    strings:\n        $p1 = \"SYSTEM\\\\CurrentControlSet\\\\Services\\\\SharedAccess\\\\Parameters\\\\FirewallPolicy\" nocase\n        $c1 = \"RegSetValue\"\n        $r1 = \"FirewallPolicy\"\n        $r2 = \"EnableFirewall\"\n        $r3 = \"FirewallDisableNotify\"\n        $s1 = \"netsh firewall add allowedprogram\"\n    condition:\n        (1 of ($p*) and $c1 and 1 of ($r*)) or $s1\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('disable_registry', 'Disable Registry editor', 2, 'rule disable_registry {\n    meta:\n        author = \"x0r\"\n        description = \"Disable Registry editor\"\n	version = \"0.1\"\n    strings:\n        $p1 = \"SOFTWARE\\\\Microsoft\\\\Windows\\\\CurrentVersion\\\\Policies\\\\System\" nocase\n        $c1 = \"RegSetValue\"\n        $r1 = \"DisableRegistryTools\"\n        $r2 = \"DisableRegedit\"\n    condition:\n        1 of ($p*) and $c1 and 1 of ($r*)\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('disable_dep', 'Bypass DEP', 2, 'rule disable_dep {\n    meta:\n        author = \"x0r\"\n        description = \"Bypass DEP\"\n	version = \"0.1\"\n    strings:\n        $c1 = \"EnableExecuteProtectionSupport\"\n        $c2 = \"NtSetInformationProcess\"\n        $c3 = \"VirtualProctectEx\"\n        $c4 = \"SetProcessDEPPolicy\"\n        $c5 = \"ZwProtectVirtualMemory\"\n    condition:\n        any of them\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('disable_taskmanager', 'Disable Task Manager', 2, 'rule disable_taskmanager {\n    meta:\n        author = \"x0r\"\n        description = \"Disable Task Manager\"\n	version = \"0.1\"\n    strings:\n        $p1 = \"SOFTWARE\\\\Microsoft\\\\Windows\\\\CurrentVersion\\\\Policies\\\\System\" nocase\n        $r1 = \"DisableTaskMgr\"\n    condition:\n        1 of ($p*) and 1 of ($r*)\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('check_patchlevel', 'Check if hotfix are applied', 2, 'rule check_patchlevel {\n    meta:\n        author = \"x0r\"\n        description = \"Check if hotfix are applied\"\n	version = \"0.1\"\n    strings:\n        $p1 = \"SOFTWARE\\\\Microsoft\\\\Windows NT\\\\CurrentVersion\\\\Hotfix\" nocase\n    condition:\n        any of them\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('win_hook', 'Affect hook table', 2, 'rule win_hook {\n    meta:\n        author = \"x0r\"\n        description = \"Affect hook table\"\n    version = \"0.1\"\n    strings:\n        $f1 = \"user32.dll\" nocase\n        $c1 = \"UnhookWindowsHookEx\"\n        $c2 = \"SetWindowsHookExA\"\n        $c3 = \"CallNextHookEx\"\n    condition:\n        $f1 and 1 of ($c*)\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('vmdetect_misc', 'Following Rule is referenced from AlienVault''s Yara rule repository.This rule contains additional processes and driver names.', 2, 'rule vmdetect_misc : vmdetect\n{\n	meta:\n    		author = \"@abhinavbom\"\n		maltype = \"NA\"\n		version = \"0.1\"\n		date = \"31/10/2015\"\n		description = \"Following Rule is referenced from AlienVault''s Yara rule repository.This rule contains additional processes and driver names.\"\n	strings:\n		$vbox1 = \"VBoxService\" nocase ascii wide\n		$vbox2 = \"VBoxTray\" nocase ascii wide\n		$vbox3 = \"SOFTWARE\\\\Oracle\\\\VirtualBox Guest Additions\" nocase ascii wide\n		$vbox4 = \"SOFTWARE\\\\\\\\Oracle\\\\\\\\VirtualBox Guest Additions\" nocase ascii wide\n\n		$wine1 = \"wine_get_unix_file_name\" ascii wide\n\n		$vmware1 = \"vmmouse.sys\" ascii wide\n		$vmware2 = \"VMware Virtual IDE Hard Drive\" ascii wide\n\n		$miscvm1 = \"SYSTEM\\\\ControlSet001\\\\Services\\\\Disk\\\\Enum\" nocase ascii wide\n		$miscvm2 = \"SYSTEM\\\\\\\\ControlSet001\\\\\\\\Services\\\\\\\\Disk\\\\\\\\Enum\" nocase ascii wide\n\n		\n		$vmdrv1 = \"hgfs.sys\" ascii wide\n		$vmdrv2 = \"vmhgfs.sys\" ascii wide\n		$vmdrv3 = \"prleth.sys\" ascii wide\n		$vmdrv4 = \"prlfs.sys\" ascii wide\n		$vmdrv5 = \"prlmouse.sys\" ascii wide\n		$vmdrv6 = \"prlvideo.sys\" ascii wide\n		$vmdrv7 = \"prl_pv32.sys\" ascii wide\n		$vmdrv8 = \"vpc-s3.sys\" ascii wide\n		$vmdrv9 = \"vmsrvc.sys\" ascii wide\n		$vmdrv10 = \"vmx86.sys\" ascii wide\n		$vmdrv11 = \"vmnet.sys\" ascii wide\n\n		\n		$vmsrvc1 = \"vmicheartbeat\" ascii wide\n		$vmsrvc2 = \"vmicvss\" ascii wide\n		$vmsrvc3 = \"vmicshutdown\" ascii wide\n		$vmsrvc4 = \"vmicexchange\" ascii wide\n		$vmsrvc5 = \"vmci\" ascii wide\n		$vmsrvc6 = \"vmdebug\" ascii wide\n		$vmsrvc7 = \"vmmouse\" ascii wide\n		$vmsrvc8 = \"VMTools\" ascii wide\n		$vmsrvc9 = \"VMMEMCTL\" ascii wide\n		$vmsrvc10 = \"vmware\" ascii wide\n		$vmsrvc11 = \"vmx86\" ascii wide\n		$vmsrvc12 = \"vpcbus\" ascii wide\n		$vmsrvc13 = \"vpc-s3\" ascii wide\n		$vmsrvc14 = \"vpcuhub\" ascii wide\n		$vmsrvc15 = \"msvmmouf\" ascii wide\n		$vmsrvc16 = \"VBoxMouse\" ascii wide\n		$vmsrvc17 = \"VBoxGuest\" ascii wide\n		$vmsrvc18 = \"VBoxSF\" ascii wide\n		$vmsrvc19 = \"xenevtchn\" ascii wide\n		$vmsrvc20 = \"xennet\" ascii wide\n		$vmsrvc21 = \"xennet6\" ascii wide\n		$vmsrvc22 = \"xensvc\" ascii wide\n		$vmsrvc23 = \"xenvdb\" ascii wide\n\n		\n		$miscproc1 = \"vmware2\" ascii wide\n		$miscproc2 = \"vmount2\" ascii wide\n		$miscproc3 = \"vmusrvc\" ascii wide\n		$miscproc4 = \"vmsrvc\" ascii wide\n		$miscproc5 = \"vboxservice\" ascii wide\n		$miscproc6 = \"vboxtray\" ascii wide\n		$miscproc7 = \"xenservice\" ascii wide\n\n		$vmware_mac_1a = \"00-05-69\"\n		$vmware_mac_1b = \"00:05:69\"\n		$vmware_mac_2a = \"00-50-56\"\n		$vmware_mac_2b = \"00:50:56\"\n		$vmware_mac_3a = \"00-0C-29\"\n		$vmware_mac_3b = \"00:0C:29\"\n		$vmware_mac_4a = \"00-1C-14\"\n		$vmware_mac_4b = \"00:1C:14\"\n		$virtualbox_mac_1a = \"08-00-27\"\n		$virtualbox_mac_1b = \"08:00:27\"\n\n	condition:\n		2 of them\n}', 2, '反调试/反虚拟机', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('inject_thread', 'Code injection with CreateRemoteThread in a remote process', 3, 'rule inject_thread {\n    meta:\n        author = \"x0r\"\n        description = \"Code injection with CreateRemoteThread in a remote process\"\n	version = \"0.1\"\n    strings:\n        $c1 = \"OpenProcess\"\n        $c2 = \"VirtualAllocEx\"\n        $c3 = \"NtWriteVirtualMemory\"\n        $c4 = \"WriteProcessMemory\"\n        $c5 = \"CreateRemoteThread\"\n        $c6 = \"CreateThread\"\n        $c7 = \"OpenProcess\"\n    condition:\n        $c1 and $c2 and ( $c3 or $c4 ) and ( $c5 or $c6 or $c7 )\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('hijack_network', 'Hijack network configuration', 3, 'rule hijack_network {\n    meta:\n        author = \"x0r\"\n        description = \"Hijack network configuration\"\n	version = \"0.1\"\n    strings:\n        $p1 = \"SOFTWARE\\\\Classes\\\\PROTOCOLS\\\\Handler\" nocase\n        $p2 = \"SOFTWARE\\\\Classes\\\\PROTOCOLS\\\\Filter\" nocase\n        $p3 = \"Microsoft\\\\Windows\\\\CurrentVersion\\\\Internet Settings\\\\ProxyServer\" nocase\n        $p4 = \"software\\\\microsoft\\\\windows\\\\currentversion\\\\internet settings\\\\proxyenable\" nocase\n        $f1 = \"drivers\\\\etc\\\\hosts\" nocase\n    condition:\n        any of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('create_service', 'Create a windows service', 3, 'rule create_service {\n    meta:\n        author = \"x0r\"\n        description = \"Create a windows service\"\n	version = \"0.2\"\n    strings:\n	$f1 = \"Advapi32.dll\" nocase\n        $c1 = \"CreateService\"\n        $c2 = \"ControlService\"\n        $c3 = \"StartService\"\n        $c4 = \"QueryServiceStatus\"\n    condition:\n        all of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('create_com_service', 'Create a COM server', 3, 'rule create_com_service {\n    meta:\n        author = \"x0r\"\n        description = \"Create a COM server\"\n	version = \"0.1\"\n    strings:\n        $c1 = \"DllCanUnloadNow\" nocase\n        $c2 = \"DllGetClassObject\"\n        $c3 = \"DllInstall\"\n        $c4 = \"DllRegisterServer\"\n        $c5 = \"DllUnregisterServer\"\n    condition:\n        all of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('network_udp_sock', 'Communications over UDP network', 3, 'rule network_udp_sock {\n    meta:\n        author = \"x0r\"\n        description = \"Communications over UDP network\"\n	version = \"0.1\"\n    strings:\n        $f1 = \"Ws2_32.dll\" nocase\n	$f2 = \"System.Net\" nocase\n        $f3 = \"wsock32.dll\" nocase\n        $c0 = \"WSAStartup\"\n        $c1 = \"sendto\"\n        $c2 = \"recvfrom\"\n        $c3 = \"WSASendTo\"\n        $c4 = \"WSARecvFrom\"\n        $c5 = \"UdpClient\"\n    condition:\n        (($f1 or $f3) and 2 of ($c*)) or ($f2 and $c5)\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('network_tcp_listen', 'Listen for incoming communication', 3, 'rule network_tcp_listen {\n    meta:\n        author = \"x0r\"\n        description = \"Listen for incoming communication\"\n	version = \"0.1\"\n    strings:\n        $f1 = \"Ws2_32.dll\" nocase\n        $f2 = \"Mswsock.dll\" nocase\n	    $f3 = \"System.Net\" nocase\n        $f4 = \"wsock32.dll\" nocase\n        $c1 = \"bind\"\n        $c2 = \"accept\"\n        $c3 = \"GetAcceptExSockaddrs\"\n        $c4 = \"AcceptEx\"\n        $c5 = \"WSAStartup\"\n        $c6 = \"WSAAccept\"\n        $c7 = \"WSASocket\"\n        $c8 = \"TcpListener\"\n        $c9 = \"AcceptTcpClient\"\n        $c10 = \"listen\"\n    condition:\n        1 of ($f*) and 2 of ($c*)\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('network_dyndns', 'Communications dyndns network', 3, 'rule network_dyndns {\n    meta:\n        author = \"x0r\"\n        description = \"Communications dyndns network\"\n	version = \"0.1\"\n    strings:\n	$s1 =\".no-ip.org\"\n        $s2 =\".publicvm.com\"\n        $s3 =\".linkpc.net\"\n        $s4 =\".dynu.com\"\n        $s5 =\".dynu.net\"\n        $s6 =\".afraid.org\"\n        $s7 =\".chickenkiller.com\"\n        $s8 =\".crabdance.com\"\n        $s9 =\".ignorelist.com\"\n        $s10 =\".jumpingcrab.com\"\n        $s11 =\".moo.com\"\n        $s12 =\".strangled.com\"\n        $s13 =\".twillightparadox.com\"\n        $s14 =\".us.to\"\n        $s15 =\".strangled.net\"\n        $s16 =\".info.tm\"\n        $s17 =\".homenet.org\"\n        $s18 =\".biz.tm\"\n        $s19 =\".continent.kz\"\n        $s20 =\".ax.lt\"\n        $s21 =\".system-ns.com\"\n        $s22 =\".adultdns.com\"\n        $s23 =\".craftx.biz\"\n        $s24 =\".ddns01.com\"\n        $s25 =\".dns53.biz\"\n        $s26 =\".dnsapi.info\"\n        $s27 =\".dnsd.info\"\n        $s28 =\".dnsdynamic.com\"\n        $s29 =\".dnsdynamic.net\"\n        $s30 =\".dnsget.org\"\n        $s31 =\".fe100.net\"\n        $s32 =\".flashserv.net\"\n        $s33 =\".ftp21.net\"\n    condition:\n        any of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('network_toredo', 'Communications over Toredo network', 3, 'rule network_toredo {\n    meta:\n        author = \"x0r\"\n        description = \"Communications over Toredo network\"\n	version = \"0.1\"\n    strings:\n	$f1 = \"FirewallAPI.dll\" nocase\n        $p1 = \"\\\\CurrentControlSet\\\\Services\\\\Tcpip6\\\\Parameters\\\\Interfaces\\\\\" nocase\n    condition:\n        all of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('network_smtp_dotNet', 'Communications smtp', 3, 'rule network_smtp_dotNet {\n    meta:\n        author = \"x0r\"\n        description = \"Communications smtp\"\n	version = \"0.1\"\n    strings:\n	$f1 = \"System.Net.Mail\" nocase\n        $p1 = \"SmtpClient\" nocase\n    condition:\n        all of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('network_smtp_raw', 'Communications smtp', 3, 'rule network_smtp_raw {\n    meta:\n        author = \"x0r\"\n        description = \"Communications smtp\"\n	version = \"0.1\"\n    strings:\n	$s1 = \"MAIL FROM:\" nocase\n        $s2 = \"RCPT TO:\" nocase\n    condition:\n        all of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('network_smtp_vb', 'Communications smtp', 3, 'rule network_smtp_vb {\n    meta:\n        author = \"x0r\"\n        description = \"Communications smtp\"\n	version = \"0.1\"\n    strings:\n	$c1 = \"CDO.Message\" nocase\n        $c2 = \"cdoSMTPServer\" nocase\n        $c3 = \"cdoSendUsingMethod\" nocase\n        $c4 = \"cdoex.dll\" nocase\n        $c5 = \"/cdo/configuration/smtpserver\" nocase\n    condition:\n        any of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('network_p2p_win', 'Communications over P2P network', 3, 'rule network_p2p_win {\n    meta:\n        author = \"x0r\"\n        description = \"Communications over P2P network\"\n	version = \"0.1\"\n    strings:\n     	$c1 = \"PeerCollabExportContact\"\n     	$c2 = \"PeerCollabGetApplicationRegistrationInfo\"\n     	$c3 = \"PeerCollabGetEndpointName\"\n     	$c4 = \"PeerCollabGetEventData\"\n     	$c5 = \"PeerCollabGetInvitationResponse\"\n     	$c6 = \"PeerCollabGetPresenceInfo\"\n     	$c7 = \"PeerCollabGetSigninOptions\"\n     	$c8 = \"PeerCollabInviteContact\"\n     	$c9 = \"PeerCollabInviteEndpoint\"\n     	$c10 = \"PeerCollabParseContact\"\n     	$c11 = \"PeerCollabQueryContactData\"\n     	$c12 = \"PeerCollabRefreshEndpointData\"\n     	$c13 = \"PeerCollabRegisterApplication\"\n     	$c14 = \"PeerCollabRegisterEvent\"\n     	$c15 = \"PeerCollabSetEndpointName\"\n     	$c16 = \"PeerCollabSetObject\"\n     	$c17 = \"PeerCollabSetPresenceInfo\"\n     	$c18 = \"PeerCollabSignout\"\n     	$c19 = \"PeerCollabUnregisterApplication\"\n     	$c20 = \"PeerCollabUpdateContact\"\n    condition:\n        5 of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('network_tor', 'Communications over TOR network', 3, 'rule network_tor {\n    meta:\n        author = \"x0r\"\n        description = \"Communications over TOR network\"\n	version = \"0.1\"\n    strings:\n        $p1 = \"tor\\\\hidden_service\\\\private_key\" nocase\n        $p2 = \"tor\\\\hidden_service\\\\hostname\" nocase\n        $p3 = \"tor\\\\lock\" nocase\n        $p4 = \"tor\\\\state\" nocase\n    condition:\n        any of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('network_irc', 'Communications over IRC network', 3, 'rule network_irc {\n    meta:\n        author = \"x0r\"\n        description = \"Communications over IRC network\"\n	version = \"0.1\"\n    strings:\n        $s1 = \"NICK\"\n        $s2 = \"PING\"\n        $s3 = \"JOIN\"\n        $s4 = \"USER\"\n        $s5 = \"PRIVMSG\"\n    condition:\n        all of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('network_http', 'Communications over HTTP', 3, 'rule network_http {\n    meta:\n        author = \"x0r\"\n        description = \"Communications over HTTP\"\n	version = \"0.1\"\n    strings:\n        $f1 = \"wininet.dll\" nocase\n        $c1 = \"InternetConnect\"\n        $c2 = \"InternetOpen\"\n        $c3 = \"InternetOpenUrl\"\n        $c4 = \"InternetReadFile\"\n        $c5 = \"InternetWriteFile\"\n        $c6 = \"HttpOpenRequest\"\n        $c7 = \"HttpSendRequest\"\n        $c8 = \"IdHTTPHeaderInfo\"\n    condition:\n        $f1 and $c1 and ($c2 or $c3) and ($c4 or $c5 or $c6 or $c7 or $c8)\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('network_dropper', 'File downloader/dropper', 3, 'rule network_dropper {\n    meta:\n        author = \"x0r\"\n        description = \"File downloader/dropper\"\n	version = \"0.1\"\n    strings:\n        $f1 = \"urlmon.dll\" nocase\n        $c1 = \"URLDownloadToFile\"\n        $c2 = \"URLDownloadToCacheFile\"\n        $c3 = \"URLOpenStream\"\n        $c4 = \"URLOpenPullStream\"\n    condition:\n        $f1 and 1 of ($c*)\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('network_ftp', 'Communications over FTP', 3, 'rule network_ftp {\n    meta:\n        author = \"x0r\"\n        description = \"Communications over FTP\"\n	version = \"0.1\"\n    strings:\n	   $f1 = \"Wininet.dll\" nocase\n        $c1 = \"FtpGetCurrentDirectory\"\n        $c2 = \"FtpGetFile\"\n        $c3 = \"FtpPutFile\"\n        $c4 = \"FtpSetCurrentDirectory\"\n        $c5 = \"FtpOpenFile\"\n        $c6 = \"FtpGetFileSize\"\n        $c7 = \"FtpDeleteFile\"\n        $c8 = \"FtpCreateDirectory\"\n        $c9 = \"FtpRemoveDirectory\"\n        $c10 = \"FtpRenameFile\"\n        $c11 = \"FtpDownload\"\n        $c12 = \"FtpUpload\"\n        $c13 = \"FtpGetDirectory\"\n    condition:\n        $f1 and (4 of ($c*))\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('network_tcp_socket', 'Communications over RAW socket', 3, 'rule network_tcp_socket {\n    meta:\n        author = \"x0r\"\n        description = \"Communications over RAW socket\"\n	version = \"0.1\"\n    strings:\n	$f1 = \"Ws2_32.dll\" nocase\n        $f2 = \"wsock32.dll\" nocase\n        $c1 = \"WSASocket\"\n        $c2 = \"socket\"\n        $c3 = \"send\"\n        $c4 = \"WSASend\"\n        $c5 = \"WSAConnect\"\n        $c6 = \"connect\"\n        $c7 = \"WSAStartup\"\n        $c8 = \"closesocket\"\n        $c9 = \"WSACleanup\"\n    condition:\n        1 of ($f*) and 2 of ($c*)\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('network_dns', 'Communications use DNS', 3, 'rule network_dns {\n    meta:\n        author = \"x0r\"\n        description = \"Communications use DNS\"\n	version = \"0.1\"\n    strings:\n        $f1 = \"System.Net\"\n        $f2 = \"Ws2_32.dll\" nocase\n        $f3 = \"Dnsapi.dll\" nocase\n        $f4 = \"wsock32.dll\" nocase\n        $c2 = \"GetHostEntry\"\n	    $c3 = \"getaddrinfo\"\n	    $c4 = \"gethostbyname\"\n	    $c5 = \"WSAAsyncGetHostByName\"\n	    $c6 = \"DnsQuery\"\n    condition:\n        1 of ($f*) and  1 of ($c*)\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('network_ssl', 'Communications over SSL', 3, 'rule network_ssl {\n    meta:\n        author = \"x0r\"\n        description = \"Communications over SSL\"\n        version = \"0.1\"\n    strings:\n        $f1 = \"ssleay32.dll\" nocase\n        $f2 = \"libeay32.dll\" nocase\n        $f3 = \"libssl32.dll\" nocase\n        $c1 = \"IdSSLOpenSSL\" nocase\n    condition:\n        any of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('network_dga', 'Communication using dga', 3, 'rule network_dga {\n    meta:\n        author = \"x0r\"\n        description = \"Communication using dga\"\n	version = \"0.1\"\n    strings:\n        $dll1 = \"Advapi32.dll\" nocase\n        $dll2 = \"wininet.dll\" nocase\n	    $dll3 = \"Crypt32.dll\" nocase\n        $time1 = \"SystemTimeToFileTime\"\n        $time2 = \"GetSystemTime\"\n        $time3 = \"GetSystemTimeAsFileTime\"\n        $hash1 = \"CryptCreateHash\"\n        $hash2 = \"CryptAcquireContext\"\n        $hash3 = \"CryptHashData\"\n        $net1 = \"InternetOpen\"\n        $net2 = \"InternetOpenUrl\"\n        $net3 = \"gethostbyname\"\n        $net4 = \"getaddrinfo\"\n    condition:\n        all of ($dll*) and 1 of ($time*) and 1 of ($hash*) and 1 of ($net*)\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('bitcoin', 'Perform crypto currency mining', 3, 'rule bitcoin {\n    meta:\n        author = \"x0r\"\n        description = \"Perform crypto currency mining\"\n	version = \"0.1\"\n    strings:\n        $f1 = \"OpenCL.dll\" nocase\n        $f2 = \"nvcuda.dll\" nocase\n        $f3 = \"opengl32.dll\" nocase\n        $s1 = \"cpuminer 2.2.2X-Mining-Extensions\"\n        $s2 = \"cpuminer 2.2.3X-Mining-Extensions\"\n	    $s3 = \"Ufasoft bitcoin-miner/0.20\"\n	    $s4 = \"bitcoin\" nocase\n	    $s5 = \"stratum\" nocase\n    condition:\n        1 of ($f*) and 1 of ($s*)\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('certificate', 'Inject certificate in store', 3, 'rule certificate {\n    meta:\n        author = \"x0r\"\n        description = \"Inject certificate in store\"\n	version = \"0.1\"\n    strings:\n        $f1 = \"Crypt32.dll\" nocase\n        $r1 = \"software\\\\microsoft\\\\systemcertificates\\\\spc\\\\certificates\" nocase\n        $c1 = \"CertOpenSystemStore\"\n    condition:\n	all of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('escalate_priv', 'Escalade priviledges', 3, 'rule escalate_priv {\n    meta:\n        author = \"x0r\"\n        description = \"Escalade priviledges\"\n	version = \"0.1\"\n    strings:\n        $d1 = \"Advapi32.dll\" nocase\n        $c1 = \"SeDebugPrivilege\"\n        $c2 = \"AdjustTokenPrivileges\"\n    condition:\n        1 of ($d*) and 1 of ($c*)\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('screenshot', 'Take screenshot', 3, 'rule screenshot {\n    meta:\n        author = \"x0r\"\n        description = \"Take screenshot\"\n	version = \"0.1\"\n    strings:\n        $d1 = \"Gdi32.dll\" nocase\n        $d2 = \"User32.dll\" nocase\n        $c1 = \"BitBlt\"\n        $c2 = \"GetDC\"\n    condition:\n        1 of ($d*) and 1 of ($c*)\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('lookupip', 'Lookup external IP', 3, 'rule lookupip {\n    meta:\n        author = \"x0r\"\n        description = \"Lookup external IP\"\n	version = \"0.1\"\n    strings:\n        $n1 = \"checkip.dyndns.org\" nocase\n        $n2 = \"whatismyip.org\" nocase\n        $n3 = \"whatsmyipaddress.com\" nocase\n        $n4 = \"getmyip.org\" nocase\n        $n5 = \"getmyip.co.uk\" nocase\n    condition:\n        any of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('dyndns', 'Dynamic DNS', 3, 'rule dyndns {\n    meta:\n        author = \"x0r\"\n        description = \"Dynamic DNS\"\n	version = \"0.1\"\n    strings:\n        $s1 = \"SOFTWARE\\\\Vitalwerks\\\\DUC\" nocase\n    condition:\n        any of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('lookupgeo', 'Lookup Geolocation', 3, 'rule lookupgeo {\n    meta:\n        author = \"x0r\"\n        description = \"Lookup Geolocation\"\n	version = \"0.1\"\n    strings:\n        $n1 = \"j.maxmind.com\" nocase\n    condition:\n        any of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('keylogger', 'Run a keylogger', 3, 'rule keylogger {\n    meta:\n        author = \"x0r\"\n        description = \"Run a keylogger\"\n	version = \"0.1\"\n    strings:\n	    $f1 = \"User32.dll\" nocase\n        $c1 = \"GetAsyncKeyState\"\n        $c2 = \"GetKeyState\"\n        $c3 = \"MapVirtualKey\"\n        $c4 = \"GetKeyboardType\"\n    condition:\n        $f1 and 1 of ($c*)\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('cred_local', 'Steal credential', 3, 'rule cred_local {\n    meta:\n        author = \"x0r\"\n        description = \"Steal credential\"\n	version = \"0.1\"\n    strings:\n        $c1 = \"LsaEnumerateLogonSessions\"\n        $c2 = \"SamIConnect\"\n        $c3 = \"SamIGetPrivateData\"\n        $c4 = \"SamQueryInformationUse\"\n        $c5 = \"CredEnumerateA\"\n        $c6 = \"CredEnumerateW\"\n        $r1 = \"software\\\\microsoft\\\\internet account manager\" nocase\n        $r2 = \"software\\\\microsoft\\\\identitycrl\\\\creds\" nocase\n        $r3 = \"Security\\\\Policy\\\\Secrets\"\n    condition:\n        any of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('sniff_audio', 'Record Audio', 3, 'rule sniff_audio {\n    meta:\n        author = \"x0r\"\n        description = \"Record Audio\"\n        version = \"0.1\"\n    strings:\n        $f1 = \"winmm.dll\" nocase\n        $c1 = \"waveInStart\"\n        $c2 = \"waveInReset\"\n        $c3 = \"waveInAddBuffer\"\n        $c4 = \"waveInOpen\"\n        $c5 = \"waveInClose\"\n    condition:\n        $f1 and 2 of ($c*)\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('cred_ff', 'Steal Firefox credential', 3, 'rule cred_ff {\n    meta:\n        author = \"x0r\"\n        description = \"Steal Firefox credential\"\n	version = \"0.1\"\n    strings:\n        $f1 = \"signons.sqlite\"\n        $f2 = \"signons3.txt\"\n        $f3 = \"secmod.db\"\n        $f4 = \"cert8.db\"\n        $f5 = \"key3.db\"\n    condition:\n        any of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('cred_vnc', 'Steal VNC credential', 3, 'rule cred_vnc {\n    meta:\n        author = \"x0r\"\n        description = \"Steal VNC credential\"\n	version = \"0.1\"\n    strings:\n        $s1 = \"VNCPassView\"\n    condition:\n        all of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('cred_ie7', 'Steal IE 7 credential', 3, 'rule cred_ie7 {\n    meta:\n        author = \"x0r\"\n        description = \"Steal IE 7 credential\"\n	version = \"0.1\"\n    strings:\n        $f1 = \"Crypt32.dll\" nocase\n        $c1 = \"CryptUnprotectData\"\n        $s1 = \"abe2869f-9b47-4cd9-a358-c22904dba7f7\" nocase\n    condition:\n        all of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('sniff_lan', 'Sniff Lan network traffic', 3, 'rule sniff_lan {\n    meta:\n        author = \"x0r\"\n        description = \"Sniff Lan network traffic\"\n	version = \"0.1\"\n    strings:\n        $f1 = \"packet.dll\" nocase\n        $f2 = \"npf.sys\" nocase\n        $f3 = \"wpcap.dll\" nocase\n        $f4 = \"winpcap.dll\" nocase\n    condition:\n        any of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('migrate_apc', 'APC queue tasks migration', 3, 'rule migrate_apc {\n    meta:\n        author = \"x0r\"\n        description = \"APC queue tasks migration\"\n	version = \"0.1\"\n    strings:\n        $c1 = \"OpenThread\"\n        $c2 = \"QueueUserAPC\"\n    condition:\n        all of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('spreading_file', 'Malware can spread east-west file', 3, 'rule spreading_file {\n    meta:\n        author = \"x0r\"\n        description = \"Malware can spread east-west file\"\n	version = \"0.1\"\n    strings:\n        $f1 = \"autorun.inf\" nocase\n        $f2 = \"desktop.ini\" nocase\n        $f3 = \"desktop.lnk\" nocase\n    condition:\n        any of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('spreading_share', 'Malware can spread east-west using share drive', 3, 'rule spreading_share {\n    meta:\n        author = \"x0r\"\n        description = \"Malware can spread east-west using share drive\"\n        version = \"0.1\"\n    strings:\n        $f1 = \"netapi32.dll\" nocase\n        $c1 = \"NetShareGetInfo\"\n        $c2 = \"NetShareEnum\"\n    condition:\n        $f1 and 1 of ($c*)\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('rat_vnc', 'Remote Administration toolkit VNC', 3, 'rule rat_vnc {\n    meta:\n        author = \"x0r\"\n        description = \"Remote Administration toolkit VNC\"\n	version = \"0.1\"\n    strings:\n        $f1 = \"ultravnc.ini\" nocase\n        $c2 = \"StartVNC\"\n        $c3 = \"StopVNC\"\n    condition:\n        any of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('rat_rdp', 'Remote Administration toolkit enable RDP', 3, 'rule rat_rdp {\n    meta:\n        author = \"x0r\"\n        description = \"Remote Administration toolkit enable RDP\"\n	version = \"0.1\"\n    strings:\n        $p1 = \"SYSTEM\\\\CurrentControlSet\\\\Control\\\\Terminal Server\" nocase\n        $p2 = \"software\\\\microsoft\\\\windows nt\\\\currentversion\\\\terminal server\" nocase\n        $p3 = \"SYSTEM\\\\CurrentControlSet\\\\Control\\\\Terminal Server\\\\WinStations\\\\RDP-Tcp\" nocase\n        $r1 = \"EnableAdminTSRemote\"\n        $c1 = \"net start termservice\"\n        $c2 = \"sc config termservice start\"\n    condition:\n        any of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('rat_telnet', 'Remote Administration toolkit enable Telnet', 3, 'rule rat_telnet {\n    meta:\n        author = \"x0r\"\n        description = \"Remote Administration toolkit enable Telnet\"\n        version = \"0.1\"\n    strings:\n        $r1 = \"software\\\\microsoft\\\\telnetserver\" nocase\n    condition:\n        any of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('rat_webcam', 'Remote Administration toolkit using webcam', 3, 'rule rat_webcam {\n    meta:\n        author = \"x0r\"\n        description = \"Remote Administration toolkit using webcam\"\n        version = \"0.1\"\n    strings:\n        $f1 = \"avicap32.dll\" nocase\n        $c1 = \"capCreateCaptureWindow\" nocase\n    condition:\n        all of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('win_mutex', 'Create or check mutex', 3, 'rule win_mutex {\n    meta:\n        author = \"x0r\"\n        description = \"Create or check mutex\"\n    version = \"0.1\"\n    strings:\n        $c1 = \"CreateMutex\"\n    condition:\n        1 of ($c*)\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('win_registry', 'Affect system registries', 3, 'rule win_registry {\n    meta:\n        author = \"x0r\"\n        description = \"Affect system registries\"\n    version = \"0.1\"\n    strings:\n        $f1 = \"advapi32.dll\" nocase\n        $c1 = \"RegQueryValueExA\"\n        $c2 = \"RegOpenKeyExA\"\n        $c3 = \"RegCloseKey\"\n        $c4 = \"RegSetValueExA\"\n        $c5 = \"RegCreateKeyA\"\n        $c6 = \"RegCloseKey\"\n    condition:\n        $f1 and 1 of ($c*)\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('win_token', 'Affect system token', 3, 'rule win_token {\n    meta:\n        author = \"x0r\"\n        description = \"Affect system token\"\n    version = \"0.1\"\n    strings:\n        $f1 = \"advapi32.dll\" nocase\n        $c1 = \"DuplicateTokenEx\"\n        $c2 = \"AdjustTokenPrivileges\"\n        $c3 = \"OpenProcessToken\"\n        $c4 = \"LookupPrivilegeValueA\"\n    condition:\n        $f1 and 1 of ($c*)\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('win_private_profile', 'Affect private profile', 3, 'rule win_private_profile {\n    meta:\n        author = \"x0r\"\n        description = \"Affect private profile\"\n    version = \"0.1\"\n    strings:\n        $f1 = \"kernel32.dll\" nocase\n        $c1 = \"GetPrivateProfileIntA\"\n        $c2 = \"GetPrivateProfileStringA\"\n        $c3 = \"WritePrivateProfileStringA\"\n    condition:\n        $f1 and 1 of ($c*)\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('win_files_operation', 'Affect private profile', 3, 'rule win_files_operation {\n    meta:\n        author = \"x0r\"\n        description = \"Affect private profile\"\n    version = \"0.1\"\n    strings:\n        $f1 = \"kernel32.dll\" nocase\n        $c1 = \"WriteFile\"\n        $c2 = \"SetFilePointer\"\n        $c3 = \"WriteFile\"\n        $c4 = \"ReadFile\"\n        $c5 = \"DeleteFileA\"\n        $c6 = \"CreateFileA\"\n        $c7 = \"FindFirstFileA\"\n        $c8 = \"MoveFileExA\"\n        $c9 = \"FindClose\"\n        $c10 = \"SetFileAttributesA\"\n        $c11 = \"CopyFile\"\n\n    condition:\n        $f1 and 3 of ($c*)\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Str_Win32_Winsock2_Library', 'Match Winsock 2 API library declaration', 3, 'rule Str_Win32_Winsock2_Library\n{\n    meta:\n        author = \"@adricnet\"\n        description = \"Match Winsock 2 API library declaration\"\n        method = \"String match\"\n        reference = \"https:\n\n    strings:\n        $ws2_lib = \"Ws2_32.dll\" nocase\n        $wsock2_lib = \"WSock32.dll\" nocase\n\n    condition:\n        (any of ($ws2_lib, $wsock2_lib))\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Str_Win32_Wininet_Library', 'Match Windows Inet API library declaration', 3, 'rule Str_Win32_Wininet_Library\n{\n\n    meta:\n        author = \"@adricnet\"\n        description = \"Match Windows Inet API library declaration\"\n        method = \"String match\"\n        reference = \"https:\n\n    strings:\n        $wininet_lib = \"WININET.dll\" nocase\n\n    condition:\n        (all of ($wininet*))\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Str_Win32_Internet_API', 'Match Windows Inet API call', 3, 'rule Str_Win32_Internet_API\n{\n\n    meta:\n        author = \"@adricnet\"\n        description = \"Match Windows Inet API call\"\n        method = \"String match, trim the As\"\n        reference = \"https:\n\n    strings:\n        $wininet_call_closeh = \"InternetCloseHandle\"\n        $wininet_call_readf = \"InternetReadFile\"\n        $wininet_call_connect = \"InternetConnect\"\n        $wininet_call_open = \"InternetOpen\"\n\n    condition:\n        (any of ($wininet_call*))\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Str_Win32_Http_API', 'Match Windows Http API call', 3, 'rule Str_Win32_Http_API\n{\n    meta:\n        author = \"@adricnet\"\n        description = \"Match Windows Http API call\"\n        method = \"String match, trim the As\"\n        reference = \"https:\n\n    strings:\n        $wininet_call_httpr = \"HttpSendRequest\"\n        $wininet_call_httpq = \"HttpQueryInfo\"\n        $wininet_call_httpo = \"HttpOpenRequest\"\n\n     condition:\n        (any of ($wininet_call_http*))\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('ldpreload', '', 3, 'rule ldpreload\n{\n        meta:\n                author=\"xorseed\"\n                reference= \"https:\n	strings:\n		$a = \"dlopen\" nocase ascii wide\n		$b = \"dlsym\" nocase ascii wide\n		$c = \"fopen\" nocase ascii wide\n		$d = \"fopen64\" nocase ascii wide\n		$e = \"__fxstat\" nocase ascii wide\n		$f = \"__fxstat64\" nocase ascii wide\n		$g = \"accept\" nocase ascii wide\n		$h = \"__lxstat\" nocase ascii wide\n		$i = \"__lxstat64\" nocase ascii wide\n		$j = \"open\" nocase ascii wide\n		$k = \"rmdir\" nocase ascii wide\n		$l = \"__xstat\" nocase ascii wide\n		$m = \"__xstat64\" nocase ascii wide\n		$n = \"unlink\" nocase ascii wide\n		$o = \"unlikat\" nocase ascii wide\n		$p = \"fdopendir\" nocase ascii wide\n		$q = \"opendir\" nocase ascii wide\n		$r = \"readdir\" nocase ascii wide\n		$s = \"readdir64\" nocase ascii wide\n	condition:\n		($a or $b) and 5 of them\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('mysql_database_presence', 'This rule checks MySQL database presence', 3, 'rule mysql_database_presence\n{\n    meta:\n        author=\"CYB3RMX\"\n        description=\"This rule checks MySQL database presence\"\n\n    strings:\n        $db = \"MySql.Data\"\n        $db1 = \"MySqlCommand\"\n        $db2 = \"MySqlConnection\"\n        $db3 = \"MySqlDataReader\"\n        $db4 = \"MySql.Data.MySqlClient\"\n\n    condition:\n        (any of ($db*))\n}', 2, '能力检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Big_Numbers0', 'Looks for big numbers 20:sized', 3, 'rule Big_Numbers0\n{\n	meta:\n		author = \"_pusher_\"\n		description = \"Looks for big numbers 20:sized\"\n		date = \"2016-07\"\n	strings:\n		$c0 = /[0-9a-fA-F]{20}', 2, '加密检测', 1);
