INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Prime_Constants_char', 'List of primes [char]', 3, 'rule Prime_Constants_char {\n	meta:\n		author = \"_pusher_\"\n		description = \"List of primes [char]\"\n		date = \"2016-07\"\n	strings:\n		$c0 = { 03 05 07 0B 0D 11 13 17 1D 1F 25 29 2B 2F 35 3B 3D 43 47 49 4F 53 59 61 65 67 6B 6D 71 7F 83 89 8B 95 97 9D A3 A7 AD B3 B5 BF C1 C5 C7 D3 DF E3 E5 E9 EF F1 FB }', 2, '加密检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Prime_Constants_long', 'List of primes [long]', 3, 'rule Prime_Constants_long {\n	meta:\n		author = \"_pusher_\"\n		description = \"List of primes [long]\"\n		date = \"2016-07\"\n	strings:\n		$c0 = { 03 00 00 00 05 00 00 00 07 00 00 00 0B 00 00 00 0D 00 00 00 11 00 00 00 13 00 00 00 17 00 00 00 1D 00 00 00 1F 00 00 00 25 00 00 00 29 00 00 00 2B 00 00 00 2F 00 00 00 35 00 00 00 3B 00 00 00 3D 00 00 00 43 00 00 00 47 00 00 00 49 00 00 00 4F 00 00 00 53 00 00 00 59 00 00 00 61 00 00 00 65 00 00 00 67 00 00 00 6B 00 00 00 6D 00 00 00 71 00 00 00 7F 00 00 00 83 00 00 00 89 00 00 00 8B 00 00 00 95 00 00 00 97 00 00 00 9D 00 00 00 A3 00 00 00 A7 00 00 00 AD 00 00 00 B3 00 00 00 B5 00 00 00 BF 00 00 00 C1 00 00 00 C5 00 00 00 C7 00 00 00 D3 00 00 00 DF 00 00 00 E3 00 00 00 E5 00 00 00 E9 00 00 00 EF 00 00 00 F1 00 00 00 FB 00 00 00 }', 2, '加密检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Advapi_Hash_API', 'Looks for advapi API functions', 3, 'rule Advapi_Hash_API {\n	meta:\n		author = \"_pusher_\"\n		description = \"Looks for advapi API functions\"\n		date = \"2016-07\"\n	strings:\n		$advapi32 = \"advapi32.dll\" wide ascii nocase\n		$CryptCreateHash = \"CryptCreateHash\" wide ascii\n		$CryptHashData = \"CryptHashData\" wide ascii\n		$CryptAcquireContext = \"CryptAcquireContext\" wide ascii\n	condition:\n		$advapi32 and ($CryptCreateHash and $CryptHashData and $CryptAcquireContext)\n}', 2, '加密检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Crypt32_CryptBinaryToString_API', 'Looks for crypt32 CryptBinaryToStringA function', 3, 'rule Crypt32_CryptBinaryToString_API {\n	meta:\n		author = \"_pusher_\"\n		description = \"Looks for crypt32 CryptBinaryToStringA function\"\n		date = \"2016-08\"\n	strings:\n		$crypt32 = \"crypt32.dll\" wide ascii nocase\n		$CryptBinaryToStringA = \"CryptBinaryToStringA\" wide ascii\n	condition:\n		$crypt32 and ($CryptBinaryToStringA)\n}', 2, '加密检测', 1);
