INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Chacha_256_constant', 'Look for 256-bit key Chacha stream cipher constant', 3, 'rule Chacha_256_constant {\n    meta:\n		author = \"spelissier\"\n		description = \"Look for 256-bit key Chacha stream cipher constant\"\n		date = \"2019-12\"\n		reference = \"https:\n	strings:\n		$c0 = \"expand 32-byte k\"\n		$split1 = \"expand 3\"\n		$split2 = \"2-byte k\"\n	condition:\n		$c0 or ( $split1 and $split2 )\n}', 2, '加密检测', 1);
