INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('MSIETabularActivex', '', 1, 'rule MSIETabularActivex\n{\n        meta:\n                ref = \"CVE-2010-0805\"\n                impact = 7\n                hide = true\n                author = \"@d3t0n4t0r\"\n        strings:\n                $cve20100805_1 = \"333C7BC4-460F-11D0-BC04-0080C7055A83\" nocase fullword\n                $cve20100805_2 = \"DataURL\" nocase fullword\n                $cve20100805_3 = \"true\"\n        condition:\n                ($cve20100805_1 and $cve20100805_3) or (all of them)\n}', 2, 'CVE漏洞利用', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('JavaDeploymentToolkit', '', 1, 'rule JavaDeploymentToolkit\n{\n   meta:\n      ref = \"CVE-2010-0887\"\n      impact = 7\n      author = \"@d3t0n4t0r\"\n   strings:\n      $cve20100887_1 = \"CAFEEFAC-DEC7-0000-0000-ABCDEFFEDCBA\" nocase fullword\n      $cve20100887_2 = \"document.createElement(\\\"OBJECT\\\")\" nocase fullword\n      $cve20100887_3 = \"application/npruntime-scriptable-plugin;deploymenttoolkit\" nocase fullword\n      $cve20100887_4 = \"application/java-deployment-toolkit\" nocase fullword\n      $cve20100887_5 = \"document.body.appendChild(\" nocase fullword\n      $cve20100887_6 = \"launch(\"\n      $cve20100887_7 = \"-J-jar -J\" nocase fullword\n   condition:\n      3 of them\n}', 2, 'CVE漏洞利用', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('FlashNewfunction', '', 1, 'rule FlashNewfunction: decodedPDF\n{\n   meta:  \n      ref = \"CVE-2010-1297\"\n      hide = true\n      impact = 5 \n      ref = \"http:\n   strings:\n      $unescape = \"unescape\" fullword nocase\n      $shellcode = /%u[A-Fa-f0-9]{4}', 2, 'CVE漏洞利用', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('CVE_2012_0158_KeyBoy', 'CVE-2012-0158 variant', 1, 'rule CVE_2012_0158_KeyBoy {\n  meta:\n      author = \"Etienne Maynier <etienne@citizenlab.ca>\"\n      description = \"CVE-2012-0158 variant\"\n      file = \"8307e444cad98b1b59568ad2eba5f201\"\n\n  strings:\n      $a = \"d0cf11e0a1b11ae1000000000000000000000000000000003e000300feff09000600000000000000000000000100000001\" nocase \n      $b = \"ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff\" nocase \n      $c = /5(\\{\\\\b0\\}', 2, 'CVE漏洞利用', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('cve_2013_0074', '', 1, 'rule cve_2013_0074\n{\nmeta:\n	author = \"Kaspersky Lab\"\n	filetype = \"Win32 EXE\"\n	date = \"2015-07-23\"\n	version = \"1.0\"\n\nstrings:\n	$b2=\"Can''t find Payload() address\" ascii wide\n	$b3=\"/SilverApp1;component/App.xaml\" ascii wide\n	$b4=\"Can''t allocate ums after buf[]\" ascii wide\n	$b5=\"------------ START ------------\"\n\ncondition:\n	( (2 of ($b*)) )\n}', 2, 'CVE漏洞利用', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('CVE_2013_0422', 'Java Applet JMX Remote Code Execution', 1, 'rule CVE_2013_0422\n{\n        meta:\n                description = \"Java Applet JMX Remote Code Execution\"\n                cve = \"CVE-2013-0422\"\n                ref = \"http:\n                author = \"adnan.shukor@gmail.com\"\n                date = \"12-Jan-2013\"\n                version = \"1\"\n                impact = 4\n                hide = false\n        strings:\n                $0422_1 = \"com/sun/jmx/mbeanserver/JmxMBeanServer\" fullword\n                $0422_2 = \"com/sun/jmx/mbeanserver/JmxMBeanServerBuilder\" fullword\n                $0422_3 = \"com/sun/jmx/mbeanserver/MBeanInstantiator\" fullword\n                $0422_4 = \"findClass\" fullword\n                $0422_5 = \"publicLookup\" fullword\n                $class = /sun\\.org\\.mozilla\\.javascript\\.internal\\.(Context|GeneratedClassLoader)/ fullword \n        condition:\n                (all of ($0422_*)) or (all of them)\n}', 2, 'CVE漏洞利用', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('CVE_2015_1701_Taihou', 'CVE-2015-1701 compiled exploit code', 1, 'rule CVE_2015_1701_Taihou {\n	meta:\n		description = \"CVE-2015-1701 compiled exploit code\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		date = \"2015-05-13\"\n		hash1 = \"90d17ebd75ce7ff4f15b2df951572653efe2ea17\"\n		hash2 = \"acf181d6c2c43356e92d4ee7592700fa01e30ffb\"\n		hash3 = \"b8aabe12502f7d55ae332905acee80a10e3bc399\"\n		hash4 = \"d9989a46d590ebc792f14aa6fec30560dfe931b1\"\n		hash5 = \"63d1d33e7418daf200dc4660fc9a59492ddd50d9\"\n		score = 70\n	strings:	\n		$s3 = \"VirtualProtect\" fullword\n		$s4 = \"RegisterClass\"\n		$s5 = \"LoadIcon\"\n		$s6 = \"PsLookupProcessByProcessId\" fullword ascii \n		$s7 = \"LoadLibraryExA\" fullword ascii\n		$s8 = \"gSharedInfo\" fullword\n\n		$w1 = \"user32.dll\" wide\n		$w2 = \"ntdll\" wide	\n	condition:\n		uint16(0) == 0x5a4d and filesize < 160KB and all of ($s*) and 1 of ($w*)\n}', 2, 'CVE漏洞利用', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Exploit_MS15_077_078', 'MS15-078 / MS15-077 exploit - generic signature', 1, 'rule Exploit_MS15_077_078: Exploit {\n	meta:\n		description = \"MS15-078 / MS15-077 exploit - generic signature\"\n		author = \"Florian Roth\"\n		reference = \"https:\n		date = \"2015-07-21\"\n		hash1 = \"18e3e840a5e5b75747d6b961fca66a670e3faef252aaa416a88488967b47ac1c\"\n		hash2 = \"0b5dc030e73074b18b1959d1cf7177ff510dbc2a0ec2b8bb927936f59eb3d14d\"\n		hash3 = \"fc609adef44b5c64de029b2b2cff22a6f36b6bdf9463c1bd320a522ed39de5d9\"\n		hash4 = \"ad6bb982a1ecfe080baf0a2b27950f989c107949b1cf02b6e0907f1a568ece15\"\n	strings:\n		$s1 = \"GDI32.DLL\" fullword ascii\n		$s2 = \"atmfd.dll\" fullword wide\n		$s3 = \"AddFontMemResourceEx\" fullword ascii\n		$s4 = \"NamedEscape\" fullword ascii\n		$s5 = \"CreateBitmap\" fullword ascii\n		$s6 = \"DeleteObject\" fullword ascii\n\n		$op0 = { 83 45 e8 01 eb 07 c7 45 e8 }', 2, 'CVE漏洞利用', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Exploit_MS15_077_078_HackingTeam', 'MS15-078 / MS15-077 exploit - Hacking Team code', 1, 'rule Exploit_MS15_077_078_HackingTeam: Exploit {\n	meta:\n		description = \"MS15-078 / MS15-077 exploit - Hacking Team code\"\n		author = \"Florian Roth\"\n		date = \"2015-07-21\"\n		super_rule = 1\n		hash1 = \"ad6bb982a1ecfe080baf0a2b27950f989c107949b1cf02b6e0907f1a568ece15\"\n		hash2 = \"fc609adef44b5c64de029b2b2cff22a6f36b6bdf9463c1bd320a522ed39de5d9\"\n	strings:\n		$s1 = \"\\\\SystemRoot\\\\system32\\\\CI.dll\" fullword ascii \n		$s2 = \"\\\\sysnative\\\\CI.dll\" fullword ascii \n		$s3 = \"Mozilla/5.0 (Windows NT 6.1; WOW64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/36.0.1985.125 Safari/537.36\" fullword ascii \n		$s4 = \"CRTDLL.DLL\" fullword ascii\n		$s5 = \"\\\\sysnative\" fullword ascii \n		$s6 = \"InternetOpenA coolio, trying open %s\" fullword ascii\n	condition:\n		uint16(0) == 0x5a4d and filesize < 2500KB and all of them\n}', 2, 'CVE漏洞利用', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Mal_Dropper_httpEXE_from_CAB', 'Detects a dropper from a CAB file mentioned in the article', 1, 'rule Mal_Dropper_httpEXE_from_CAB : Dropper {\n	meta:\n		description = \"Detects a dropper from a CAB file mentioned in the article\"\n		author = \"Florian Roth\"\n		reference = \"https:\n		date = \"2016-05-25\"\n		score = 60\n		hash1 = \"9e7e5f70c4b32a4d5e8c798c26671843e76bb4bd5967056a822e982ed36e047b\"\n	strings:\n		$s1 = \"029.Hdl\" fullword ascii\n		$s2 = \"http.exe\" fullword ascii\n	condition:\n		( uint16(0) == 0x5a4d and filesize < 1000KB and ( all of ($s*) ) )\n}', 2, 'CVE漏洞利用', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Mal_http_EXE', 'Detects trojan from APT report named http.exe', 1, 'rule Mal_http_EXE : Trojan {\n	meta:\n		description = \"Detects trojan from APT report named http.exe\"\n		author = \"Florian Roth\"\n		reference = \"https:\n		date = \"2016-05-25\"\n		score = 80\n		hash1 = \"ad191d1d18841f0c5e48a5a1c9072709e2dd6359a6f6d427e0de59cfcd1d9666\"\n	strings:\n		$x1 = \"Content-Disposition: form-data; name=\\\"file1\\\"; filename=\\\"%s\\\"\" fullword ascii\n		$x2 = \"%ALLUSERSPROFILE%\\\\Accessories\\\\wordpade.exe\" fullword ascii\n		$x3 = \"\\\\dumps.dat\" fullword ascii\n		$x4 = \"\\\\wordpade.exe\" fullword ascii\n		$x5 = \"\\\\%s|%s|4|%d|%4d-%02d-%02d %02d:%02d:%02d|\" fullword ascii\n		$x6 = \"\\\\%s|%s|5|%d|%4d-%02d-%02d %02d:%02d:%02d|\" fullword ascii\n		$x7 = \"cKaNBh9fnmXgJcSBxx5nFS+8s7abcQ==\" fullword ascii\n		$x8 = \"cKaNBhFLn1nXMcCR0RlbMQ==\" fullword ascii \n\n		$s1 = \"SELECT * FROM moz_logins;\" fullword ascii\n		$s2 = \"makescr.dat\" fullword ascii\n		$s3 = \"%s\\\\Mozilla\\\\Firefox\\\\profiles.ini\" fullword ascii\n		$s4 = \"?moz-proxy:\n		$s5 = \"[%s-%s] Title: %s\" fullword ascii\n		$s6 = \"Cforeign key mismatch - \\\"%w\\\" referencing \\\"%w\\\"\" fullword ascii\n		$s7 = \"Windows 95 SR2\" fullword ascii\n		$s8 = \"\\\\|%s|0|0|\" fullword ascii\n	condition:\n		( uint16(0) == 0x5a4d and filesize < 2000KB and ( 1 of ($x*) and 2 of ($s*) ) ) or ( 3 of ($x*) )\n}', 2, 'CVE漏洞利用', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Mal_PotPlayer_DLL', 'Detects a malicious PotPlayer.dll', 1, 'rule Mal_PotPlayer_DLL : dll {\n	meta:\n		description = \"Detects a malicious PotPlayer.dll\"\n		author = \"Florian Roth\"\n		reference = \"https:\n		date = \"2016-05-25\"\n		score = 70\n		hash1 = \"705409bc11fb45fa3c4e2fa9dd35af7d4613e52a713d9c6ea6bc4baff49aa74a\"\n	strings:\n		$x1 = \"C:\\\\Users\\\\john\\\\Desktop\\\\PotPlayer\\\\Release\\\\PotPlayer.pdb\" fullword ascii\n\n		$s3 = \"PotPlayer.dll\" fullword ascii\n		$s4 = \"\\\\update.dat\" fullword ascii\n	condition:\n		uint16(0) == 0x5a4d and filesize < 200KB and $x1 or all of ($s*)\n}', 2, 'CVE漏洞利用', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Flash_CVE_2015_5119_APT3', 'Exploit Sample CVE-2015-5119', 1, 'rule Flash_CVE_2015_5119_APT3 : Exploit {\n    meta:\n        description = \"Exploit Sample CVE-2015-5119\"\n        author = \"Florian Roth\"\n        score = 70\n        date = \"2015-08-01\"\n    strings:\n        $s0 = \"HT_exploit\" fullword ascii\n        $s1 = \"HT_Exploit\" fullword ascii\n        $s2 = \"flash_exploit_\" ascii\n        $s3 = \"exp1_fla/MainTimeline\" ascii fullword\n        $s4 = \"exp2_fla/MainTimeline\" ascii fullword\n        $s5 = \"_shellcode_32\" fullword ascii\n        $s6 = \"todo: unknown 32-bit target\" fullword ascii \n    condition:\n        uint16(0) == 0x5746 and 1 of them\n}', 2, 'CVE漏洞利用', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Linux_DirtyCow_Exploit', 'Detects Linux Dirty Cow Exploit - CVE-2012-0056 and CVE-2016-5195', 1, 'rule Linux_DirtyCow_Exploit {\n   meta:\n      description = \"Detects Linux Dirty Cow Exploit - CVE-2012-0056 and CVE-2016-5195\"\n      author = \"Florian Roth\"\n      reference = \"http:\n      date = \"2016-10-21\"\n   strings:\n      $a1 = { 48 89 D6 41 B9 00 00 00 00 41 89 C0 B9 02 00 00 00 BA 01 00 00 00 BF 00 00 00 00 }', 2, 'CVE漏洞利用', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('potential_CVE_2017_11882', '', 1, 'rule potential_CVE_2017_11882\n{\n    meta:\n      author = \"ReversingLabs\"\n      reference = \"https:\n      \n    strings:\n        $docfilemagic = { D0 CF 11 E0 A1 B1 1A E1 }', 2, 'CVE漏洞利用', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('crime_ole_loadswf_cve_2018_4878', 'Detects CVE-2018-4878', 1, 'rule crime_ole_loadswf_cve_2018_4878\n{\nmeta:\ndescription = \"Detects CVE-2018-4878\"\nvuln_type = \"Remote Code Execution\"\nvuln_impact = \"Use-after-free\"\naffected_versions = \"Adobe Flash 28.0.0.137 and earlier versions\"\nmitigation0 = \"Implement Protected View for Office documents\"\nmitigation1 = \"Disable Adobe Flash\"\nweaponization = \"Embedded in Microsoft Office first payloads\"\nactor = \"Purported North Korean actors\"\nreference = \"hxxps:\nreport = \"https:\nauthor = \"Vitali Kremez, Flashpoint\"\nversion = \"1.1\"\n\nstrings:\n\n$header = \"rdf:RDF\" wide ascii\n\n\n$title = \"Adobe Flex\" wide ascii\n\n\n$pdb = \"F:\\\\work\\\\flash\\\\obfuscation\\\\loadswf\\\\src\" wide ascii\n\n\n$s0 = \"URLRequest\" wide ascii\n$s1 = \"URLLoader\" wide ascii\n$s2 = \"loadswf\" wide ascii\n$s3 = \"myUrlReqest\" wide ascii\n\ncondition:\nall of ($header*) and all of ($title*) and 3 of ($s*) or all of ($pdb*) and all of ($header*) and 1 of ($s*)\n}', 2, 'CVE漏洞利用', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Android_AVITOMMS_Variant', 'This rule try to detects Spy.Banker AVITO-MMS Variant', 2, 'rule Android_AVITOMMS_Variant\n{\n	meta:\n		author = \"Jacob Soo Lead Re\"\n		date = \"28-May-2016\"\n		description = \"This rule try to detects Spy.Banker AVITO-MMS Variant\"\n		source = \"https:\n\n	condition:\n		(androguard.receiver(/AlarmReceiverKnock/) and \n		 androguard.receiver(/BootReciv/) and \n		 androguard.receiver(/AlarmReceiverAdm/))\n		\n}', 3, '已废弃规则', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Android_AVITOMMS_Rule2', 'This rule try to detects Spy.Banker AVITO-MMS Variant', 2, 'rule Android_AVITOMMS_Rule2\n{\n	meta:\n		author = \"Jacob Soo Lead Re\"\n		date = \"01-July-2016\"\n		description = \"This rule try to detects Spy.Banker AVITO-MMS Variant\"\n		source = \"https:\n\n	condition:\n		androguard.service(/IMService/) and \n		androguard.receiver(/BootReciv/) and \n		androguard.permission(/android.permission.RECEIVE_BOOT_COMPLETED/i) and \n		androguard.permission(/android.permission.KILL_BACKGROUND_PROCESSES/i) and \n		androguard.permission(/android.permission.SEND_SMS/i) and\n		androguard.permission(/android.permission.INTERNET/i)\n}', 3, '已废弃规则', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Android_AliPay_smsStealer', 'Yara rule for detection of Fake AliPay Sms Stealer', 2, 'rule Android_AliPay_smsStealer : android\n{\n	meta:\n		description = \"Yara rule for detection of Fake AliPay Sms Stealer\"\n		sample = \"f4794dd02d35d4ea95c51d23ba182675cc3528f42f4fa9f50e2d245c08ecf06b\"\n		source = \"http:\n		ref = \"https:\n		author = \"https:\n\n	strings:\n		$str_1 = \"START_SERVICE\"\n		$str_2 = \"extra_key_sms\"\n		$str_3 = \"android.provider.Telephony.SMS_RECEIVED\"\n		$str_4 = \"mPhoneNumber\"\n\n	condition:\n		androguard.certificate.sha1(\"0CDFC700D0BDDC3EA50D71B54594BF3711D0F5B2\") or\n		androguard.permission(/android.permission.RECEIVE_SMS/) and\n		androguard.permission(/android.permission.INTERNET/) and\n		androguard.permission(/android.permission.RECEIVE_BOOT_COMPLETED/) and 		\n		all of ($str_*)\n}', 3, '已废弃规则', 1);
