INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('zerox88_js3', '0x88 Exploit Kit Detection', 1, 'rule zerox88_js3\n{\nmeta:\n	author = \"Josh Berry\"\n	date = \"2016-06-26\"\n	description = \"0x88 Exploit Kit Detection\"\n	hash0 = \"9df0ac2fa92e602ec11bac53555e2d82\"\n	sample_filetype = \"js-html\"\n	yaragenerator = \"https:\nstrings:\n	$string0 = \" new ActiveXObject(szHTTP); \"\n	$string1 = \" Csa2;\"\n	$string2 = \"var ADO \"\n	$string3 = \" new ActiveXObject(szOx88);\"\n	$string4 = \" unescape(\"\n	$string5 = \"/test.exe\"\n	$string6 = \" szEtYij;\"\n	$string7 = \"var HTTP \"\n	$string8 = \"%41%44%4F%44%42%2E\"\n	$string9 = \"%4D%65%64%69%61\"\n	$string10 = \"var szSRjq\"\n	$string11 = \"%43%3A%5C%5C%50%72%6F%67%72%61%6D\"\n	$string12 = \"var METHOD \"\n	$string13 = \"ADO.Mode \"\n	$string14 = \"%61%79%65%72\"\n	$string15 = \"%2E%58%4D%4C%48%54%54%50\"\n	$string16 = \" 7 - 6; HTTP.Open(METHOD, szURL, i-3); \"\ncondition:\n	16 of them\n}', 2, '漏洞利用工具包', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('zeus_js', 'Zeus Exploit Kit Detection', 1, 'rule zeus_js : EK\n{\nmeta:\n	author = \"Josh Berry\"\n	date = \"2016-06-26\"\n	description = \"Zeus Exploit Kit Detection\"\n	hash0 = \"c87ac7a25168df49a64564afb04dc961\"\n	sample_filetype = \"js-html\"\n	yaragenerator = \"https:\nstrings:\n	$string0 = \"var jsmLastMenu \"\n	$string1 = \"position:absolute; z-index:99'' \"\n	$string2 = \" -1)jsmSetDisplayStyle(''popupmenu'' \"\n	$string3 = \" ''<tr><td><a href\"\n	$string4 = \"  jsmLastMenu \"\n	$string5 = \"  var ids \"\n	$string6 = \"this.target\"\n	$string7 = \" jsmPrevMenu, ''none'');\"\n	$string8 = \"  if(jsmPrevMenu \"\n	$string9 = \")if(MenuData[i])\"\n	$string10 = \" ''<div style\"\n	$string11 = \"popupmenu\"\n	$string12 = \"  jsmSetDisplayStyle(''popupmenu'' \"\n	$string13 = \"function jsmHideLastMenu()\"\n	$string14 = \" MenuData.length; i\"\ncondition:\n	14 of them\n}', 2, '漏洞利用工具包', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Maldoc_APT10_MenuPass', 'Detects APT10 MenuPass Phishing', 1, 'rule Maldoc_APT10_MenuPass {\n   meta:\n      description = \"Detects APT10 MenuPass Phishing\"\n      author = \"Colin Cowie\"\n      reference = \"https:\n      date = \"2018-09-13\"\n   strings:\n      $s1 = \"C:\\\\ProgramData\\\\padre1.txt\"\n      $s2 = \"C:\\\\ProgramData\\\\padre2.txt\"\n      $s3 = \"C:\\\\ProgramData\\\\padre3.txt\"\n      $s5 = \"C:\\\\ProgramData\\\\libcurl.txt\"\n      $s6 = \"C:\\\\ProgramData\\\\3F2E3AB9\"\n   condition:\n      any of them or\n      hash.md5(0, filesize) == \"4f83c01e8f7507d23c67ab085bf79e97\" or\n      hash.md5(0, filesize) == \"f188936d2c8423cf064d6b8160769f21\" or\n      hash.md5(0, filesize) == \"cca227f70a64e1e7fcf5bccdc6cc25dd\"\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('FE_LEGALSTRIKE_MACRO', 'This rule is designed to identify macros with the specific encoding used in the sample 30f149479c02b741e897cdb9ecd22da7.', 1, 'rule FE_LEGALSTRIKE_MACRO {\n       meta:version=\".1\"\n       filetype=\"MACRO\"\n       author=\"Ian.Ahl@fireeye.com @TekDefense\"\n       date=\"2017-06-02\"\n       description=\"This rule is designed to identify macros with the specific encoding used in the sample 30f149479c02b741e897cdb9ecd22da7.\"\nstrings:\n       \n       $ob1 = \"ChrW(114) & ChrW(101) & ChrW(103) & ChrW(115) & ChrW(118) & ChrW(114) & ChrW(51) & ChrW(50) & ChrW(46) & ChrW(101)\" ascii wide\n       $ob2 = \"ChrW(120) & ChrW(101) & ChrW(32) & ChrW(47) & ChrW(115) & ChrW(32) & ChrW(47) & ChrW(110) & ChrW(32) & ChrW(47)\" ascii wide\n       $ob3 = \"ChrW(117) & ChrW(32) & ChrW(47) & ChrW(105) & ChrW(58) & ChrW(104) & ChrW(116) & ChrW(116) & ChrW(112) & ChrW(115)\" ascii wide\n       $ob4 = \"ChrW(58) & ChrW(47) & ChrW(47) & ChrW(108) & ChrW(121) & ChrW(110) & ChrW(99) & ChrW(100) & ChrW(105) & ChrW(115)\" ascii wide\n       $ob5 = \"ChrW(99) & ChrW(111) & ChrW(118) & ChrW(101) & ChrW(114) & ChrW(46) & ChrW(50) & ChrW(98) & ChrW(117) & ChrW(110)\" ascii wide\n       $ob6 = \"ChrW(110) & ChrW(121) & ChrW(46) & ChrW(99) & ChrW(111) & ChrW(109) & ChrW(47) & ChrW(65) & ChrW(117) & ChrW(116)\" ascii wide\n       $ob7 = \"ChrW(111) & ChrW(100) & ChrW(105) & ChrW(115) & ChrW(99) & ChrW(111) & ChrW(118) & ChrW(101) & ChrW(114) & ChrW(32)\" ascii wide\n       $ob8 = \"ChrW(115) & ChrW(99) & ChrW(114) & ChrW(111) & ChrW(98) & ChrW(106) & ChrW(46) & ChrW(100) & ChrW(108) & ChrW(108)\" ascii wide\n       $obreg1 = /(\\w{5}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('FE_LEGALSTRIKE_MACRO_2', 'This rule was written to hit on specific variables and powershell command fragments as seen in the macro found in the XLSX file3a1dca21bfe72368f2dd46eb4d9b48c4.', 1, 'rule FE_LEGALSTRIKE_MACRO_2 {\n       meta:version=\".1\"\n       filetype=\"MACRO\"\n       author=\"Ian.Ahl@fireeye.com @TekDefense\"\n       date=\"2017-06-02\"\n       description=\"This rule was written to hit on specific variables and powershell command fragments as seen in the macro found in the XLSX file3a1dca21bfe72368f2dd46eb4d9b48c4.\"\nstrings:\n       \n       $env1 = \"Arch = Environ(\\\"PROCESSOR_ARCHITECTURE\\\")\" ascii wide\n       $env2 = \"windir = Environ(\\\"windir\\\")\" ascii wide\n       $env3 = \"windir + \\\"\\\\syswow64\\\\windowspowershell\\\\v1.0\\\\powershell.exe\\\"\" ascii wide\n       \n       $ps1 = \"-NoP\" ascii wide\n       $ps2 = \"-NonI\" ascii wide\n       $ps3 = \"-W Hidden\" ascii wide\n       $ps4 = \"-Command\" ascii wide\n       $ps5 = \"New-Object IO.StreamReader\" ascii wide\n       $ps6 = \"IO.Compression.DeflateStream\" ascii wide\n       $ps7 = \"IO.MemoryStream\" ascii wide\n       $ps8 = \",$([Convert]::FromBase64String\" ascii wide\n       $ps9 = \"ReadToEnd();\" ascii wide\n       $psregex1 = /\\W\\w+\\s+\\s\\\".+\\\"/\ncondition:\n       (\n              (\n                      (uint16(0) != 0x5A4D)\n              )\n              and\n              (\n                      all of ($env*) and 6 of ($ps*)\n                      or\n                      all of ($env*) and 4 of ($ps*) and all of ($psregex*)\n              )\n       )\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('FE_LEGALSTRIKE_RTF', 'Rtf Phishing Campaign leveraging the CVE 2017-0199 exploit, to point to the domain 2bunnyDOTcom', 1, 'rule FE_LEGALSTRIKE_RTF {\n    meta:\n        version=\".1\"\n        filetype=\"MACRO\"\n        author=\"joshua.kim@FireEye.com\"\n        date=\"2017-06-02\"\n        description=\"Rtf Phishing Campaign leveraging the CVE 2017-0199 exploit, to point to the domain 2bunnyDOTcom\"\n\n    strings:\n        $header = \"{\\\\rt\"\n\n        $lnkinfo = \"4c0069006e006b0049006e0066006f\"\n\n        $encoded1 = \"4f4c45324c696e6b\"\n        $encoded2 = \"52006f006f007400200045006e007400720079\"\n        $encoded3 = \"4f0062006a0049006e0066006f\"\n        $encoded4 = \"4f006c0065\"\n\n        $http1 = \"68{\"\n        $http2 = \"74{\"\n        $http3 = \"07{\"\n\n        \n        $domain1 = \"32{\\\\\"\n        $domain2 = \"62{\\\\\"\n        $domain3 = \"75{\\\\\"\n        $domain4 = \"6e{\\\\\"\n        $domain5 = \"79{\\\\\"\n        $domain6 = \"2e{\\\\\"\n        $domain7 = \"63{\\\\\"\n        $domain8 = \"6f{\\\\\"\n        $domain9 = \"6d{\\\\\"\n\n        $datastore = \"\\\\*\\\\datastore\"\n\n    condition:\n        $header at 0 and all of them\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('rtf_objdata_urlmoniker_http', '', 1, 'rule rtf_objdata_urlmoniker_http {\nmeta:\n	ref = \"https:\n strings:\n $header = \"{\\\\rtf1\"\n $objdata = \"objdata 0105000002000000\" nocase\n $urlmoniker = \"E0C9EA79F9BACE118C8200AA004BA90B\" nocase\n $http = \"68007400740070003a002f002f00\" nocase\n condition:\n $header at 0 and $objdata and $urlmoniker and $http\n }', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Maldoc_CVE_2017_11882', 'Detects maldoc With exploit for CVE_2017_11882', 1, 'rule Maldoc_CVE_2017_11882 : Exploit {\n    meta:\n        description = \"Detects maldoc With exploit for CVE_2017_11882\"\n        author = \"Marc Salinas (@Bondey_m)\"\n        reference = \"c63ccc5c08c3863d7eb330b69f96c1bcf1e031201721754132a4c4d0baff36f8\"\n        date = \"2017-10-20\"\n    strings:\n        $doc = \"d0cf11e0a1b11ae1\"\n        $s0 = \"Equation\"\n        $s1 = \"1c000000020\"\n        $h0 = {1C 00 00 00 02 00}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('RTFFILE', 'Detects RTF files', 1, 'private rule RTFFILE {\n   meta:\n      description = \"Detects RTF files\"\n   condition:\n      uint32be(0) == 0x7B5C7274\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('CVE_2017_8759_Mal_HTA', 'Detects malicious files related to CVE-2017-8759 - file cmd.hta', 1, 'rule CVE_2017_8759_Mal_HTA {\n   meta:\n      description = \"Detects malicious files related to CVE-2017-8759 - file cmd.hta\"\n      author = \"Florian Roth\"\n      reference = \"https:\n      date = \"2017-09-14\"\n      hash1 = \"fee2ab286eb542c08fdfef29fabf7796a0a91083a0ee29ebae219168528294b5\"\n   strings:\n      $x1 = \"Error = Process.Create(\\\"powershell -nop cmd.exe /c\" fullword ascii\n   condition:\n      ( uint16(0) == 0x683c and filesize < 1KB and all of them )\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('CVE_2017_8759_Mal_Doc', 'Detects malicious files related to CVE-2017-8759 - file Doc1.doc', 1, 'rule CVE_2017_8759_Mal_Doc {\n   meta:\n      description = \"Detects malicious files related to CVE-2017-8759 - file Doc1.doc\"\n      author = \"Florian Roth\"\n      reference = \"https:\n      date = \"2017-09-14\"\n      hash1 = \"6314c5696af4c4b24c3a92b0e92a064aaf04fd56673e830f4d339b8805cc9635\"\n   strings:\n      $s1 = \"soap:wsdl=http:\n      $s2 = \"soap:wsdl=https:\n\n      $c1 = \"Project.ThisDocument.AutoOpen\" fullword wide\n   condition:\n      ( uint16(0) == 0xcfd0 and filesize < 500KB and 2 of them )\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('CVE_2017_8759_SOAP_via_JS', 'Detects SOAP WDSL Download via JavaScript', 1, 'rule CVE_2017_8759_SOAP_via_JS {\n   meta:\n      description = \"Detects SOAP WDSL Download via JavaScript\"\n      author = \"Florian Roth\"\n      reference = \"https:\n      date = \"2017-09-14\"\n      score = 60\n   strings:\n      $s1 = \"GetObject(\\\"soap:wsdl=https:\n      $s2 = \"GetObject(\\\"soap:wsdl=http:\n   condition:\n      ( filesize < 3KB and 1 of them )\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('CVE_2017_8759_SOAP_Excel', 'Detects malicious files related to CVE-2017-8759', 1, 'rule CVE_2017_8759_SOAP_Excel {\n   meta:\n      description = \"Detects malicious files related to CVE-2017-8759\"\n      author = \"Florian Roth\"\n      reference = \"https:\n      date = \"2017-09-15\"\n   strings:\n      $s1 = \"|''soap:wsdl=\" ascii wide nocase\n   condition:\n      ( filesize < 300KB and 1 of them )\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('CVE_2017_8759_SOAP_txt', 'Detects malicious file in releation with CVE-2017-8759 - file exploit.txt', 1, 'rule CVE_2017_8759_SOAP_txt {\n   meta:\n      description = \"Detects malicious file in releation with CVE-2017-8759 - file exploit.txt\"\n      author = \"Florian Roth\"\n      reference = \"https:\n      date = \"2017-09-14\"\n      hash1 = \"840ad14e29144be06722aff4cc04b377364eeed0a82b49cc30712823838e2444\"\n   strings:\n      $s1 = /<soap:address location=\"http[s]?:\\/\\/[^\"]{8,140}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('CVE_2017_8759_WSDL_in_RTF', 'Detects malicious RTF file related CVE-2017-8759', 1, 'rule CVE_2017_8759_WSDL_in_RTF {\n   meta:\n      description = \"Detects malicious RTF file related CVE-2017-8759\"\n      author = \"Security Doggo @xdxdxdxdoa\"\n      reference = \"https:\n      date = \"2017-09-15\"\n   strings:\n      $doc = \"d0cf11e0a1b11ae1\"\n      $obj = \"\\\\objupdate\"\n      $wsdl = \"7700730064006c003d00\" nocase\n      $http1 = \"68007400740070003a002f002f00\" nocase\n      $http2 = \"680074007400700073003a002f002f00\" nocase\n      $http3 = \"6600740070003a002f002f00\" nocase\n   condition:\n      RTFFILE and $obj and $doc and $wsdl and 1 of ($http*)\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Contains_VBE_File', 'Detect a VBE file inside a byte sequence', 1, 'rule Contains_VBE_File : maldoc\n{\n    meta:\n        author = \"Didier Stevens (https:\n        description = \"Detect a VBE file inside a byte sequence\"\n        method = \"Find string starting with #@~^ and ending with ^#~@\"\n    strings:\n        $vbe = /#@~\\^.+\\^#~@/\n    condition:\n        $vbe\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Contains_DDE_Protocol', 'Detect Dynamic Data Exchange protocol in doc/docx', 1, 'rule Contains_DDE_Protocol\n{\n        meta:\n                author = \"Nick Beede\"\n                description = \"Detect Dynamic Data Exchange protocol in doc/docx\"\n                reference = \"https:\n                date = \"2017-10-19\"\n                filetype = \"Office documents\"\n        \n        strings:\n                $doc = {D0 CF 11 E0 A1 B1 1A E1}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Dridex_Trojan_XML', 'Dridex Malware in XML Document', 1, 'rule Dridex_Trojan_XML : maldoc {\n	meta:\n		description = \"Dridex Malware in XML Document\"\n		author = \"Florian Roth @4nc4p\"\n		reference = \"https:\n		date = \"2015/03/08\"\n		hash1 = \"88d98e18ed996986d26ce4149ae9b2faee0bc082\"\n		hash2 = \"3b2d59adadf5ff10829bb5c27961b22611676395\"\n		hash3 = \"e528671b1b32b3fa2134a088bfab1ba46b468514\"\n		hash4 = \"981369cd53c022b434ee6d380aa9884459b63350\"\n		hash5 = \"96e1e7383457293a9b8f2c75270b58da0e630bea\"\n	strings:\n		\n		$c_xml      = \"<?xml version=\"\n		$c_word     = \"<?mso-application progid=\\\"Word.Document\\\"?>\"\n		$c_macro    = \"w:macrosPresent=\\\"yes\\\"\"\n		$c_binary   = \"<w:binData w:name=\"\n		$c_0_chars  = \"<o:Characters>0</o:Characters>\"\n		$c_1_line   = \"<o:Lines>1</o:Lines>\"\n	condition:\n		all of ($c*)\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('PHISH_02Dez2015_dropped_p0o6543f', 'Phishing Wave - file p0o6543f.exe', 1, 'rule PHISH_02Dez2015_dropped_p0o6543f {\n	meta:\n		description = \"Phishing Wave - file p0o6543f.exe\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		date = \"2015-12-02\"\n		hash = \"db788d6d3a8ed1a6dc9626852587f475e7671e12fa9c9faa73b7277886f1e210\"\n	strings:\n		$s1 = \"netsh.exe\" fullword wide\n		$s2 = \"routemon.exe\" fullword wide\n		$s3 = \"script=\" fullword wide \n		$s4 = \"disconnect\" fullword wide \n		$s5 = \"GetClusterResourceTypeKey\" fullword ascii \n		$s6 = \"QueryInformationJobObject\" fullword ascii \n		$s7 = \"interface\" fullword wide \n		$s8 = \"connect\" fullword wide \n		$s9 = \"FreeConsole\" fullword ascii \n	condition:\n		uint16(0) == 0x5a4d and filesize < 250KB and all of them\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('PHISH_02Dez2015_attach_P_ORD_C_10156_124658', 'Phishing Wave - file P-ORD-C-10156-124658.xls', 1, 'rule PHISH_02Dez2015_attach_P_ORD_C_10156_124658 {\n	meta:\n		description = \"Phishing Wave - file P-ORD-C-10156-124658.xls\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		date = \"2015-12-02\"\n		hash = \"bc252ede5302240c2fef8bc0291ad5a227906b4e70929a737792e935a5fee209\"\n	strings:\n		$s1 = \"Execute\" ascii\n		$s2 = \"Process WriteParameterFiles\" fullword ascii\n		$s3 = \"WScript.Shell\" fullword ascii\n		$s4 = \"STOCKMASTER\" fullword ascii\n		$s5 = \"InsertEmailFax\" ascii\n	condition:\n		uint16(0) == 0xcfd0 and filesize < 200KB and all of them\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Contains_hidden_PE_File_inside_a_sequence_of_numbers', 'Detect a hidden PE file inside a sequence of numbers (comma separated)', 1, 'rule Contains_hidden_PE_File_inside_a_sequence_of_numbers : maldoc\n{\n	meta:\n		author = \"Martin Willing (https:\n		description = \"Detect a hidden PE file inside a sequence of numbers (comma separated)\"\n		reference = \"http:\n		reference = \"http:\n		date = \"2016-01-09\"\n		filetype = \"decompressed VBA macro code\"\n		\n	strings:\n		$a = \"= Array(\" \n		$b = \"77, 90,\" \n		$c = \"33, 84, 104, 105, 115, 32, 112, 114, 111, 103, 114, 97, 109, 32, 99, 97, 110, 110, 111, 116, 32, 98, 101, 32, 114, 117, 110, 32, 105, 110, 32, 68, 79, 83, 32, 109, 111, 100, 101, 46,\" \n	\n	condition:\n	 	all of them\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('MIME_MSO_ActiveMime_base64', 'Detect MIME MSO Base64 encoded ActiveMime file', 1, 'rule MIME_MSO_ActiveMime_base64 : maldoc\n{\n	meta:\n		author = \"Martin Willing (https:\n		description = \"Detect MIME MSO Base64 encoded ActiveMime file\"\n		date = \"2016-02-28\"\n		filetype = \"Office documents\"\n		\n	strings:\n		$mime = \"MIME-Version:\"\n		$base64 = \"Content-Transfer-Encoding: base64\"\n		$mso = \"Content-Type: application/x-mso\"\n		$activemime = /Q(\\x0D\\x0A|)W(\\x0D\\x0A|)N(\\x0D\\x0A|)0(\\x0D\\x0A|)a(\\x0D\\x0A|)X(\\x0D\\x0A|)Z(\\x0D\\x0A|)l(\\x0D\\x0A|)T(\\x0D\\x0A|)W/\n	\n	condition:\n		$mime at 0 and $base64 and $mso and $activemime\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('PDF_Embedded_Exe', '', 1, 'rule PDF_Embedded_Exe : PDF\n{\n	meta:\n		ref = \"https:\n	strings:\n    	$header = {25 50 44 46}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('ppaction', '', 1, 'rule ppaction {\n\nmeta:\n	ref = \"https:\n	Description = \"Malicious PowerPoint Documents Abusing Mouse Over Actions\"\n  hash = \"68fa24c0e00ff5bc1e90c96e1643d620d0c4cda80d9e3ebeb5455d734dc29e7\"\n\nstrings:\n$a = \"ppaction\" nocase\ncondition:\n$a\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('powershell', '', 1, 'rule powershell {\nstrings:\n$a = \"powershell\" nocase\ncondition:\n$a\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Maldoc_Suspicious_OLE_target', 'Detects maldoc With Tartgeting Suspicuios OLE', 1, 'rule Maldoc_Suspicious_OLE_target {\n  meta:\n    description =  \"Detects maldoc With Tartgeting Suspicuios OLE\"\n    author = \"Donguk Seo\"\n    reference = \"https:\n    filetype = \"Office documents\"\n    date = \"2018-06-13\"\n  strings:\n    $env1 = /oleObject\".*Target=.*.http.*.doc\"/\n    $env2 = /oleObject\".*Target=.*.http.*.ppt\"/\n    $env3 = /oleObject\".*Target=.*.http.*.xlx\"/\n  condition:\n    any of them\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Contains_UserForm_Object', 'Detect UserForm object in MS Office document', 1, 'rule Contains_UserForm_Object\n{\n	meta:\n		author = \"Martin Willing (https:\n		description = \"Detect UserForm object in MS Office document\"\n		reference = \"https:\n		date = \"2016-03-05\"\n		filetype = \"Office documents\"\n		\n	strings:\n		$a = \"UserForm1\"\n		$b = \"TextBox1\"\n		$c = \"Microsoft Forms 2.0\"\n	\n	condition:\n	 	all of them\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Contains_VBA_macro_code', 'Detect a MS Office document with embedded VBA macro code', 1, 'rule Contains_VBA_macro_code\n{\n	meta:\n		author = \"evild3ad\"\n		description = \"Detect a MS Office document with embedded VBA macro code\"\n		date = \"2016-01-09\"\n		filetype = \"Office documents\"\n\n	strings:\n		$officemagic = { D0 CF 11 E0 A1 B1 1A E1 }', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Word_2007_XML_Flat_OPC', 'Detect Word 2007 XML Document in the Flat OPC format w/ embedded Microsoft Office 2007+ document', 1, 'rule Word_2007_XML_Flat_OPC : maldoc\n{\n	meta:\n		author = \"Martin Willing (https:\n		description = \"Detect Word 2007 XML Document in the Flat OPC format w/ embedded Microsoft Office 2007+ document\"\n		date = \"2018-04-29\"\n		reference = \"https:\n		hash1 = \"060c036ce059b465a05c42420efa07bf\"\n		hash2 = \"2af21d35bb909a0ac081c2399d0939b1\"\n		hash3 = \"72ffa688c228b0b833e69547885650fe\"\n		filetype = \"Office documents\"\n		\n	strings:\n		$xml = \"<?xml\" \n		$WordML = \"<?mso-application progid=\\\"Word.Document\\\"?>\" \n		$OPC = \"<pkg:package\" \n		$xmlns = \"http:\n		$binaryData = \"<pkg:binaryData>0M8R4KGxGuE\" \n		$docm = \"pkg:name=\\\"/word/vbaProject.bin\\\"\" \n		\n	condition:\n	 	$xml at 0 and $WordML and $OPC and $xmlns and $binaryData and $docm\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('hancitor_dropper', '', 1, 'rule hancitor_dropper : vb_win32api\n{\n  meta:\n    author = \"Jeff White - jwhite@paloaltonetworks @noottrak\"\n    date   = \"18AUG2016\"\n    hash1  = \"03aef51be133425a0e5978ab2529890854ecf1b98a7cf8289c142a62de7acd1a\"\n    hash2  = \"4b3912077ef47515b2b74bc1f39de44ddd683a3a79f45c93777e49245f0e9848\"\n    hash3  = \"a78972ac6dee8c7292ae06783cfa1f918bacfe956595d30a0a8d99858ce94b5a\"\n\n  strings:\n    $api_01 = { 00 56 69 72 74 75 61 6C 41 6C 6C 6F 63 00 }', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('malrtf_ole2link', 'Detect weaponized RTF documents with OLE2Link exploit', 1, 'rule malrtf_ole2link : exploit\n{\n	meta:\n		author = \"@h3x2b <tracker _AT h3x.eu>\"\n		description = \"Detect weaponized RTF documents with OLE2Link exploit\"\n\n	strings:\n		\n		$rtf_format_00 = \"{\\\\rtf1\"\n		\n		$rtf_format_01 = \"{\\\\rt\"\n\n		\n		$rtf_olelink_01 = \"\\\\objdata\" nocase\n\n		\n		$rtf_olelink_02 = \"4f4c45324c696e6b\" nocase\n\n		\n		$rtf_olelink_03 = \"d0cf11e0a1b11ae1\" nocase\n\n		\n		$rtf_payload_01 = \"68007400740070003a002f002f00\" nocase\n\n		\n		$rtf_payload_02 = \"680074007400700073003a002f002f00\" nocase\n\n		\n		$rtf_payload_03 = \"6600740070003a002f002f00\" nocase\n\n\n	condition:\n		\n		any of ($rtf_format_*)\n		and all of ($rtf_olelink_*)\n		and any of ($rtf_payload_*)\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('maldoc_API_hashing', '', 1, 'rule maldoc_API_hashing : maldoc\n{\n    meta:\n        author = \"Didier Stevens (https:\n    strings:\n        $a1 = {AC 84 C0 74 07 C1 CF 0D 01 C7 EB F4 81 FF}', 2, '恶意文档', 1);
