INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('macrocheck', '', 1, 'rule macrocheck : maldoc\n{\n    meta:\n        Author      = \"Fireeye Labs\"\n        Date        = \"2014/11/30\" \n        Description = \"Identify office documents with the MACROCHECK credential stealer in them.  It can be run against .doc files or VBA macros extraced from .docx files (vbaProject.bin files).\"\n        Reference   = \"https:\n\n    strings:\n        $PARAMpword = \"pword=\" ascii wide\n        $PARAMmsg = \"msg=\" ascii wide\n        $PARAMuname = \"uname=\" ascii\n        $userform = \"UserForm\" ascii wide\n        $userloginform = \"UserLoginForm\" ascii wide\n        $invalid = \"Invalid username or password\" ascii wide\n        $up1 = \"uploadPOST\" ascii wide\n        $up2 = \"postUpload\" ascii wide\n \n    condition:\n        all of ($PARAM*) or (($invalid or $userloginform or $userform) and ($up1 or $up2))\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('office_document_vba', 'Office document with embedded VBA', 1, 'rule office_document_vba : maldoc\n{\n	meta:\n		description = \"Office document with embedded VBA\"\n		author = \"Jean-Philippe Teissier / @Jipe_\"\n		date = \"2013-12-17\"\n		reference = \"https:\n\n	strings:\n		$officemagic = { D0 CF 11 E0 A1 B1 1A E1 }', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Office_AutoOpen_Macro', 'Detects an Microsoft Office file that contains the AutoOpen Macro function', 1, 'rule Office_AutoOpen_Macro : maldoc {\n	meta:\n		description = \"Detects an Microsoft Office file that contains the AutoOpen Macro function\"\n		author = \"Florian Roth\"\n		date = \"2015-05-28\"\n		score = 60\n		hash1 = \"4d00695d5011427efc33c9722c61ced2\"\n		hash2 = \"63f6b20cb39630b13c14823874bd3743\"\n		hash3 = \"66e67c2d84af85a569a04042141164e6\"\n		hash4 = \"a3035716fe9173703941876c2bde9d98\"\n		hash5 = \"7c06cab49b9332962625b16f15708345\"\n		hash6 = \"bfc30332b7b91572bfe712b656ea8a0c\"\n		hash7 = \"25285b8fe2c41bd54079c92c1b761381\"\n	strings:\n		$s1 = \"AutoOpen\" ascii fullword\n		$s2 = \"Macros\" wide fullword\n	condition:\n		uint32be(0) == 0xd0cf11e0 and all of ($s*) and filesize < 300000\n}', 2, '恶意文档', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Embedded_EXE_Cloaking', 'Detects an embedded executable in a non-executable file', 1, 'rule Embedded_EXE_Cloaking : maldoc {\n    meta:\n        description = \"Detects an embedded executable in a non-executable file\"\n        author = \"Florian Roth\"\n        date = \"2015/02/27\"\n        score = 80\n    strings:\n        $noex_png = { 89 50 4E 47 }', 2, '恶意文档', 1);
