INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('REDLEAVES_DroppedFile_ObfuscatedShellcodeAndRAT_handkerchief', 'Detect obfuscated .dat file containing shellcode and core REDLEAVES RAT', 1, 'rule REDLEAVES_DroppedFile_ObfuscatedShellcodeAndRAT_handkerchief {\nmeta:\n        description = \"Detect obfuscated .dat file containing shellcode and core REDLEAVES RAT\"\n        author = \"USG\"\n        true_positive = \"fb0c714cd2ebdcc6f33817abe7813c36\" \n        reference = \"https:\n\nstrings:\n        $RedleavesStringObfu = {73 64 65 5e 60 74 75 74 6c 6f 60 6d 5e 6d 64 60 77 64 72 5e 65 6d 6d 6c 60 68 6f 2f 65 6d 6d}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('REDLEAVES_CoreImplant_UniqueStrings', 'Strings identifying the core REDLEAVES RAT in its deobfuscated state', 1, 'rule REDLEAVES_CoreImplant_UniqueStrings {\nmeta:\n        description = \"Strings identifying the core REDLEAVES RAT in its deobfuscated state\"\n        author = \"USG\"\n        reference = \"https:\n\nstrings:\n        $unique2 = \"RedLeavesSCMDSimulatorMutex\" nocase wide ascii\n        $unique4 = \"red_autumnal_leaves_dllmain.dll\" wide ascii\n        $unique7 = \"\\\\NamePipe_MoreWindows\" wide ascii\ncondition:\n        any of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('PLUGX_RedLeaves', '', 1, 'rule PLUGX_RedLeaves\n{\nmeta:\n        author = \"US-CERT Code Analysis Team\"\n        date = \"03042017\"\n        incident = \"10118538\"\n        date = \"2017/04/03\"\n        MD5_1 = \"598FF82EA4FB52717ACAFB227C83D474\"\n        MD5_2 = \"7D10708A518B26CC8C3CBFBAA224E032\"\n        MD5_3 = \"AF406D35C77B1E0DF17F839E36BCE630\"\n        MD5_4 = \"6EB9E889B091A5647F6095DCD4DE7C83\"\n        MD5_5 = \"566291B277534B63EAFC938CDAAB8A399E41AF7D\"\n        info = \"Detects specific RedLeaves and PlugX binaries\"\n        reference = \"https:\n\nstrings:\n        $s0 = { 80343057403D2FD0010072F433C08BFF80343024403D2FD0010072F4 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Ham_backdoor', '', 1, 'rule Ham_backdoor\n{\nmeta:\n        author = \"Cylance Spear Team\"\n        reference = \"https:\nstrings:\n        $a = {8D 14 3E 8B 7D FC 8A 0C 11 32 0C 38 40 8B 7D 10 88 0A 8B 4D 08 3B C3}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Tofu_Backdoor', '', 1, 'rule Tofu_Backdoor\n{\nmeta:\n        author = \"Cylance Spear Team\"\n        reference = \"https:\nstrings:\n	$a = \"Cookies: Sym1.0\"\n	$b = \"\\\\\\\\.\\\\pipe\\\\1[12345678]\"\n	$c = {66 0F FC C1 0F 11 40 D0 0F 10 40 D0 66 0F EF C2 0F 11 40 D0 0F 10 40 E0}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('clean_apt15_patchedcmd', 'This is a patched CMD. This is the CMD that RoyalCli uses.', 1, 'rule clean_apt15_patchedcmd{\n	meta:\n		author = \"Ahmed Zaki\"\n		description = \"This is a patched CMD. This is the CMD that RoyalCli uses.\"\n		reference = \"https:\n		sha256 = \"90d1f65cfa51da07e040e066d4409dc8a48c1ab451542c894a623bc75c14bf8f\"\n	strings:\n	    $ = \"eisableCMD\" wide\n	    $ = \"%WINDOWS_COPYRIGHT%\" wide\n	    $ = \"Cmd.Exe\" wide\n	    $ = \"Windows Command Processor\" wide\n	condition:\n        	all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('malware_apt15_royalcli_1', 'Generic strings found in the Royal CLI tool', 1, 'rule malware_apt15_royalcli_1{\n	meta:\n    description = \"Generic strings found in the Royal CLI tool\"\n    reference = \"https:\n		author = \"David Cannings\"\n		sha256 = \"6df9b712ff56009810c4000a0ad47e41b7a6183b69416251e060b5c80cd05785\"\n\n	strings:\n	    $ = \"%s~clitemp%08x.tmp\" fullword\n	    $ = \"qg.tmp\" fullword\n	    $ = \"%s /c %s>%s\" fullword\n	    $ = \"hkcmd.exe\" fullword\n	    $ = \"%snewcmd.exe\" fullword\n	    $ = \"%shkcmd.exe\" fullword\n	    $ = \"%s~clitemp%08x.ini\" fullword\n	    $ = \"myRObject\" fullword\n	    $ = \"myWObject\" fullword\n	    $ = \"10 %d %x\\x0D\\x0A\"\n	    $ = \"4 %s  %d\\x0D\\x0A\"\n	    $ = \"6 %s  %d\\x0D\\x0A\"\n	    $ = \"1 %s  %d\\x0D\\x0A\"\n	    $ = \"3 %s  %d\\x0D\\x0A\"\n	    $ = \"5 %s  %d\\x0D\\x0A\"\n	    $ = \"2 %s  %d 0 %d\\x0D\\x0A\"\n	    $ = \"2 %s  %d 1 %d\\x0D\\x0A\"\n	    $ = \"%s file not exist\" fullword\n\n	condition:\n	    5 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('malware_apt15_royalcli_2', 'APT15 RoyalCli backdoor', 1, 'rule malware_apt15_royalcli_2{\n	meta:\n    author = \"Nikolaos Pantazopoulos\"\n    description = \"APT15 RoyalCli backdoor\"\n    reference = \"https:\n	strings:\n		$string1 = \"%shkcmd.exe\" fullword\n		$string2 = \"myRObject\" fullword\n		$string3 = \"%snewcmd.exe\" fullword\n		$string4 = \"%s~clitemp%08x.tmp\" fullword\n		$string5 = \"hkcmd.exe\" fullword\n		$string6 = \"myWObject\" fullword\n	condition:\n		uint16(0) == 0x5A4D and 2 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('malware_apt15_bs2005', 'APT15 bs2005', 1, 'rule malware_apt15_bs2005{\n	meta:\n		author	=	\"Ahmed Zaki\"\n		md5	=	\"ed21ce2beee56f0a0b1c5a62a80c128b\"\n		description	=	\"APT15 bs2005\"\n		reference = \"https:\n   	strings:\n		$ = \"%s&%s&%s&%s\"  wide ascii\n		$ = \"%s\\\\%s\"  wide ascii\n		$ = \"WarOnPostRedirect\"  wide ascii fullword\n		$ = \"WarnonZoneCrossing\"  wide ascii fullword\n		$ = \"^^^^^\" wide ascii fullword\n			\n		$ =  /\"?%s\\s*\"?\\s*\\/C\\s*\"?%s\\s*>\\s*\\\\?\"?%s\\\\(\\w+\\.\\w+)?\"\\s*2>&1\\s*\"?/ \n		$ =\"IEharden\" wide ascii fullword\n		$ =\"DEPOff\" wide ascii fullword\n		$ =\"ShownVerifyBalloon\" wide ascii fullword\n		$ =\"IEHardenIENoWarn\" wide ascii fullword\n   	condition:\n		(uint16(0) == 0x5A4D and 5 of them) or \n		( uint16(0) == 0x5A4D and 3 of them and \n		( pe.imports(\"advapi32.dll\", \"CryptDecrypt\") and pe.imports(\"advapi32.dll\", \"CryptEncrypt\") and\n		pe.imports(\"ole32.dll\", \"CoCreateInstance\")))}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('malware_apt15_royaldll', 'DLL implant, originally rights.dll and runs as a service', 1, 'rule malware_apt15_royaldll{\n	meta:\n		author = \"David Cannings\"\n		description = \"DLL implant, originally rights.dll and runs as a service\"\n		reference = \"https:\n		sha256 = \"bc937f6e958b339f6925023bc2af375d669084e9551fd3753e501ef26e36b39d\"          \n	strings:\n	    \n	    \n		$opcodes_jshash = { B8 A7 C6 67 4E 83 C1 02 BA 04 00 00 00 57 90 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('malware_apt15_royaldll_2', 'DNS backdoor used by APT15', 1, 'rule malware_apt15_royaldll_2	{\n	meta:\n		author	=	\"Ahmed Zaki\"\n		sha256	=	\"bc937f6e958b339f6925023bc2af375d669084e9551fd3753e501ef26e36b39d\"\n		description	=	\"DNS backdoor used by APT15\"\n		reference = \"https:\n	strings:\n		    $= \"SOFTWARE\\\\Microsoft\\\\Windows NT\\\\CurrentVersion\\\\Svchost\" wide ascii \n		    $= \"netsvcs\" wide ascii fullword\n		    $= \"%SystemRoot%\\\\System32\\\\svchost.exe -k netsvcs\" wide ascii fullword\n		    $= \"SYSTEM\\\\CurrentControlSet\\\\Services\\\\\" wide ascii\n		    $= \"myWObject\" wide ascii \n	condition:\n		uint16(0) == 0x5A4D and all of them\n		and pe.exports(\"ServiceMain\")\n		and filesize > 50KB and filesize < 600KB\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('malware_apt15_exchange_tool', 'This is a an exchange enumeration/hijacking tool used by an APT 15', 1, 'rule malware_apt15_exchange_tool {\n	meta:\n		author = \"Ahmed Zaki\"\n		md5 = \"d21a7e349e796064ce10f2f6ede31c71\"\n		description = \"This is a an exchange enumeration/hijacking tool used by an APT 15\"\n		reference = \"https:\n	strings:\n		$s1= \"subjectname\" fullword\n		$s2= \"sendername\" fullword\n		$s3= \"WebCredentials\" fullword\n		$s4= \"ExchangeVersion\"	fullword\n		$s5= \"ExchangeCredentials\"	fullword\n		$s6= \"slfilename\"	fullword\n		$s7= \"EnumMail\"	fullword\n		$s8= \"EnumFolder\"	fullword\n		$s9= \"set_Credentials\"	fullword\n		$s10 = \"/de\" wide\n		$s11 = \"/sn\" wide\n		$s12 = \"/sbn\" wide\n		$s13 = \"/list\" wide\n		$s14 = \"/enum\" wide\n		$s15 = \"/save\" wide\n		$s16 = \"/ao\" wide\n		$s17 = \"/sl\" wide\n		$s18 = \"/v or /t is null\" wide\n		$s19 = \"2007\" wide\n		$s20 = \"2010\" wide\n		$s21 = \"2010sp1\" wide\n		$s22 = \"2010sp2\" wide\n		$s23 = \"2013\" wide\n		$s24 = \"2013sp1\" wide\n	condition:\n		uint16(0) == 0x5A4D and 15 of ($s*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('malware_apt15_generic', 'Find generic data potentially relating to AP15 tools', 1, 'rule malware_apt15_generic {\n	meta:\n		author = \"David Cannings\"\n		description = \"Find generic data potentially relating to AP15 tools\"\n		reference = \"https:\n	strings:\n	    \n		$str01 = \"myWObject\" fullword\n		$str02 = \"myRObject\" fullword\n\n	    \n	    \n		$opcodes01 = { 6A (02|03) 6A 00 6A 00 68 00 00 00 C0 50 FF 15 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT17_Sample_FXSST_DLL', 'Detects Samples related to APT17 activity - file FXSST.DLL', 1, 'rule APT17_Sample_FXSST_DLL \n{\n    \n    meta:\n        description = \"Detects Samples related to APT17 activity - file FXSST.DLL\"\n        author = \"Florian Roth\"\n        reference = \"https:\n        date = \"2015-05-14\"\n        hash = \"52f1add5ad28dc30f68afda5d41b354533d8bce3\"\n        \n    strings:\n        $x1 = \"Microsoft? Windows? Operating System\" fullword wide\n        $x2 = \"fxsst.dll\" fullword ascii\n        $y1 = \"DllRegisterServer\" fullword ascii\n        $y2 = \".cSV\" fullword ascii\n        $s1 = \"GetLastActivePopup\"\n        $s2 = \"Sleep\"\n        $s3 = \"GetModuleFileName\"\n        $s4 = \"VirtualProtect\"\n        $s5 = \"HeapAlloc\"\n        $s6 = \"GetProcessHeap\"\n        $s7 = \"GetCommandLine\"\n   \n   condition:\n        uint16(0) == 0x5a4d and filesize < 800KB and ( 1 of ($x*) or all of ($y*) ) and all of ($s*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('GRIZZLY_STEPPE_Malware_1', 'Auto-generated rule - file HRDG022184_certclint.dll', 1, 'rule GRIZZLY_STEPPE_Malware_1\n{\n\n   meta:\n      description = \"Auto-generated rule - file HRDG022184_certclint.dll\"\n      author = \"Florian Roth\"\n      reference = \"https:\n      date = \"2016-12-29\"\n      hash1 = \"9f918fb741e951a10e68ce6874b839aef5a26d60486db31e509f8dcaa13acec5\"\n\n   strings:\n      $s1 = \"S:\\\\Lidstone\\\\renewing\\\\HA\\\\disable\\\\In.pdb\" fullword ascii\n      $s2 = \"Repeat last find command)Replace specific text with different text\" fullword wide\n      $s3 = \"l\\\\Processor(0)\\\\% Processor Time\" fullword wide\n      $s6 = \"Self Process\" fullword wide\n      $s7 = \"Default Process\" fullword wide\n      $s8 = \"Star Polk.exe\" fullword wide\n\n   condition:\n      ( uint16(0) == 0x5a4d and filesize < 300KB and 4 of them )\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('GRIZZLY_STEPPE_Malware_2', 'Auto-generated rule - file 9acba7e5f972cdd722541a23ff314ea81ac35d5c0c758eb708fb6e2cc4f598a0', 1, 'rule GRIZZLY_STEPPE_Malware_2\n{\n\n   meta:\n      description = \"Auto-generated rule - file 9acba7e5f972cdd722541a23ff314ea81ac35d5c0c758eb708fb6e2cc4f598a0\"\n      author = \"Florian Roth\"\n      reference = \"https:\n      date = \"2016-12-29\"\n      hash1 = \"9acba7e5f972cdd722541a23ff314ea81ac35d5c0c758eb708fb6e2cc4f598a0\"\n      hash2 = \"55058d3427ce932d8efcbe54dccf97c9a8d1e85c767814e34f4b2b6a6b305641\"\n      \n   strings:\n      $x1 = \"GoogleCrashReport.dll\" fullword ascii\n      $s1 = \"CrashErrors\" fullword ascii\n      $s2 = \"CrashSend\" fullword ascii\n      $s3 = \"CrashAddData\" fullword ascii\n      $s4 = \"CrashCleanup\" fullword ascii\n      $s5 = \"CrashInit\" fullword ascii\n\n   condition:\n      ( uint16(0) == 0x5a4d and filesize < 1000KB and $x1 ) or ( all of them )\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('PAS_TOOL_PHP_WEB_KIT_mod', 'Detects PAS Tool PHP Web Kit', 1, 'rule PAS_TOOL_PHP_WEB_KIT_mod \n{\n   \n   meta:\n      description = \"Detects PAS Tool PHP Web Kit\"\n      reference = \"https:\n      author = \"US CERT - modified by Florian Roth due to performance reasons\"\n      date = \"2016/12/29\"\n   \n   strings:\n      $php = \"<?php\"\n      $base64decode1 = \"=''base''.(\"\n      $strreplace = \"str_replace(\\\"\\\\n\\\", ''''\"\n      $md5 = \".substr(md5(strrev(\"\n      $gzinflate = \"gzinflate\"\n      $cookie = \"_COOKIE\"\n      $isset = \"isset\"\n   \n   condition:\n      $php at 0 and (filesize > 10KB and filesize < 30KB) and #cookie == 2 and #isset == 3 and all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('WebShell_PHP_Web_Kit_v3', 'Detects PAS Tool PHP Web Kit', 1, 'rule WebShell_PHP_Web_Kit_v3\n{\n\n   meta:\n      description = \"Detects PAS Tool PHP Web Kit\"\n      reference = \"https:\n      author = \"Florian Roth\"\n      date = \"2016/01/01\"\n\n   strings:\n      $php = \"<?php $\"\n      $php2 = \"@assert(base64_decode($_REQUEST[\"\n      $s1 = \"(str_replace(\\\"\\\\n\\\", '''', ''\"\n      $s2 = \"(strrev($\" ascii\n      $s3 = \"de''.''code'';\" ascii\n\n   condition:\n      ( $php at 0 or $php2 ) and filesize > 8KB and filesize < 100KB and all of ($s*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('WebShell_PHP_Web_Kit_v4', 'Detects PAS Tool PHP Web Kit', 1, 'rule WebShell_PHP_Web_Kit_v4\n{\n\n   meta:\n      description = \"Detects PAS Tool PHP Web Kit\"\n      reference = \"https:\n      author = \"Florian Roth\"\n      date = \"2016/01/01\"\n\n   strings:\n      $php = \"<?php $\"\n      $s1 = \"(StR_ReplAcE(\\\"\\\\n\\\",'''',\"\n      $s2 = \";if(PHP_VERSION<''5''){\" ascii\n      $s3 = \"=SuBstr_rePlACe(\" ascii\n\n   condition:\n      $php at 0 and filesize > 8KB and filesize < 100KB and 2 of ($s*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT3102Code', '3102 code features', 1, 'rule APT3102Code\n{\n\n    meta:\n        description = \"3102 code features\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-06-25\"\n\n    strings:\n        $setupthread = { B9 02 07 00 00 BE ?? ?? ?? ?? 8B F8 6A 00 F3 A5 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT3102Strings', '3102 Identifying Strings', 1, 'rule APT3102Strings\n{\n    \n    meta:\n        description = \"3102 Identifying Strings\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-06-25\"\n\n    strings:\n        $ = \"rundll32_exec.dll\\x00Update\"\n        \n        \n\n    condition:\n       any of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT9002Code', '9002 code features', 1, 'rule APT9002Code \n{\n    \n    meta:\n        description = \"9002 code features\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-06-25\"\n        \n    strings:\n        \n        $ = { B9 7A 21 00 00 BE ?? ?? ?? ?? 8B F8 ?? ?? ?? F3 A5 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT9002Strings', '9002 Identifying Strings', 1, 'rule APT9002Strings\n{\n    \n    meta:\n        description = \"9002 Identifying Strings\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-06-25\"\n        \n    strings:\n        $ = \"POST http:\n        $ = \"%%TEMP%%\\\\%s_p.ax\" wide ascii\n        $ = \"%TEMP%\\\\uid.ax\" wide ascii\n        $ = \"%%TEMP%%\\\\%s.ax\" wide ascii\n        \n        $ = \"sysinfo\\x00sysbin01\"\n        $ = \"\\\\FlashUpdate.exe\"\n\n    condition:\n       any of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT9002', '9002', 1, 'rule APT9002 \n{\n    \n    meta:\n        description = \"9002\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-06-25\"\n        \n    condition:\n        APT9002Code or APT9002Strings\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('FE_APT_9002', '', 1, 'rule FE_APT_9002\n{\n    \n    meta:\n        Author      = \"FireEye Labs\"\n        Date        = \"2013/11/10\"\n        Description = \"Strings inside\"\n        Reference   = \"Useful link\"\n        \n    strings:\n        $mz = { 4d 5a }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('apt_backspace', 'Detects APT backspace', 1, 'rule apt_backspace\n{\n\n    meta:\n        description = \"Detects APT backspace\"\n        author = \"Bit Byte Bitten\"\n        date = \"2015-05-14\"\n        hash = \"6cbfeb7526de65eb2e3c848acac05da1e885636d17c1c45c62ad37e44cd84f99\"\n        \n    strings:\n        $s1 = \"!! Use Splice Socket !!\"\n        $s2 = \"User-Agent: SJZJ (compatible; MSIE 6.0; Win32)\"\n        $s3 = \"g_nAV=%d,hWnd:0x%X,className:%s,Title:%s,(%d,%d,%d,%d),BOOL=%d\"\n\n    condition:\n        uint16(0) == 0x5a4d and all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT_bestia', 'Bestia.3.02.012.07 malware used in APT attacks on Polish government', 1, 'rule APT_bestia\n{\nmeta:\n    author = \"Adam Ziaja <adam@adamziaja.com> http:\n    date = \"2014-03-19\"\n    description = \"Bestia.3.02.012.07 malware used in APT attacks on Polish government\"\n    references = \"http:\n    hash0 = \"9bb03bb5af40d1202378f95a6485fba8\"\n    hash1 = \"7d9a806e0da0b869b10870dd6c7692c5\"\n    maltype = \"apt\"\n    filetype = \"exe\"\nstrings:\n    \n    $string0 = \"u4(UeK\"\n    $string1 = \"nMiq/''p\"\n    $string2 = \"_9pJMf\"\n    $string3 = \"ICMP.DLL\"\n    $string4 = \"EG}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('BlackEnergy_BE_2', 'Detects BlackEnergy 2 Malware', 1, 'rule BlackEnergy_BE_2 \n{\n   \n   meta:\n      description = \"Detects BlackEnergy 2 Malware\"\n      author = \"Florian Roth\"\n      reference = \"http:\n      date = \"2015/02/19\"\n      hash = \"983cfcf3aaaeff1ad82eb70f77088ad6ccedee77\"\n   \n   strings:\n      $s0 = \"<description> Windows system utility service  </description>\" fullword ascii\n      $s1 = \"WindowsSysUtility - Unicode\" fullword wide\n      $s2 = \"msiexec.exe\" fullword wide\n      $s3 = \"WinHelpW\" fullword ascii\n      $s4 = \"ReadProcessMemory\" fullword ascii\n   \n   condition:\n      uint16(0) == 0x5a4d and filesize < 250KB and all of ($s*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('BlackEnergy_VBS_Agent', 'Detects VBS Agent from BlackEnergy Report - file Dropbearrun.vbs', 1, 'rule BlackEnergy_VBS_Agent \n{\n\n    meta:\n        description = \"Detects VBS Agent from BlackEnergy Report - file Dropbearrun.vbs\"\n        author = \"Florian Roth\"\n        reference = \"http:\n        date = \"2016-01-03\"\n        hash = \"b90f268b5e7f70af1687d9825c09df15908ad3a6978b328dc88f96143a64af0f\"\n    \n    strings:\n        $s0 = \"WshShell.Run \\\"dropbear.exe -r rsa -d dss -a -p 6789\\\", 0, false\" fullword ascii\n        $s1 = \"WshShell.CurrentDirectory = \\\"C:\\\\WINDOWS\\\\TEMP\\\\Dropbear\\\\\\\"\" fullword ascii\n        $s2 = \"Set WshShell = CreateObject(\\\"WScript.Shell\\\")\" fullword ascii \n   \n    condition:\n        filesize < 1KB and 2 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('DropBear_SSH_Server', 'Detects DropBear SSH Server (not a threat but used to maintain access)', 1, 'rule DropBear_SSH_Server\n {\n\n    meta:\n        description = \"Detects DropBear SSH Server (not a threat but used to maintain access)\"\n        author = \"Florian Roth\"\n        reference = \"http:\n        date = \"2016-01-03\"\n        score = 50\n        hash = \"0969daac4adc84ab7b50d4f9ffb16c4e1a07c6dbfc968bd6649497c794a161cd\"\n    \n    strings:\n        $s1 = \"Dropbear server v%s https:\n        $s2 = \"Badly formatted command= authorized_keys option\" fullword ascii\n        $s3 = \"This Dropbear program does not support ''%s'' %s algorithm\" fullword ascii\n        $s4 = \"/etc/dropbear/dropbear_dss_host_key\" fullword ascii\n        $s5 = \"/etc/dropbear/dropbear_rsa_host_key\" fullword ascii\n    \n    condition:\n        uint16(0) == 0x5a4d and filesize < 1000KB and 2 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('BlackEnergy_BackdoorPass_DropBear_SSH', 'Detects the password of the backdoored DropBear SSH Server - BlackEnergy', 1, 'rule BlackEnergy_BackdoorPass_DropBear_SSH \n{\n    \n    meta:\n        description = \"Detects the password of the backdoored DropBear SSH Server - BlackEnergy\"\n        author = \"Florian Roth\"\n        reference = \"http:\n        date = \"2016-01-03\"\n        hash = \"0969daac4adc84ab7b50d4f9ffb16c4e1a07c6dbfc968bd6649497c794a161cd\"\n    \n    strings:\n        $s1 = \"passDs5Bu9Te7\" fullword ascii\n    \n    condition:\n        uint16(0) == 0x5a4d and $s1\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('BlackEnergy_KillDisk_1', 'Detects KillDisk malware from BlackEnergy', 1, 'rule BlackEnergy_KillDisk_1 \n{\n\n    meta:\n        description = \"Detects KillDisk malware from BlackEnergy\"\n        author = \"Florian Roth\"\n        reference = \"http:\n        date = \"2016-01-03\"\n        score = 80\n        super_rule = 1\n        hash1 = \"11b7b8a7965b52ebb213b023b6772dd2c76c66893fc96a18a9a33c8cf125af80\"\n        hash2 = \"5d2b1abc7c35de73375dd54a4ec5f0b060ca80a1831dac46ad411b4fe4eac4c6\"\n        hash3 = \"c7536ab90621311b526aefd56003ef8e1166168f038307ae960346ce8f75203d\"\n        hash4 = \"f52869474834be5a6b5df7f8f0c46cbc7e9b22fa5cb30bee0f363ec6eb056b95\"\n\n    strings:\n        $s0 = \"system32\\\\cmd.exe\" fullword ascii\n        $s1 = \"system32\\\\icacls.exe\" fullword wide\n        $s2 = \"/c del /F /S /Q %c:\\\\*.*\" fullword ascii\n        $s3 = \"shutdown /r /t %d\" fullword ascii\n        $s4 = \"/C /Q /grant \" fullword wide\n        $s5 = \"%08X.tmp\" fullword ascii\n        $s6 = \"/c format %c: /Y /X /FS:NTFS\" fullword ascii\n        $s7 = \"/c format %c: /Y /Q\" fullword ascii\n        $s8 = \"taskhost.exe\" fullword wide \n        $s9 = \"shutdown.exe\" fullword wide \n \n    condition:\n        uint16(0) == 0x5a4d and filesize < 500KB and 8 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('BlackEnergy_KillDisk_2', 'Detects KillDisk malware from BlackEnergy', 1, 'rule BlackEnergy_KillDisk_2 \n{\n\n    meta:\n        description = \"Detects KillDisk malware from BlackEnergy\"\n        author = \"Florian Roth\"\n        reference = \"http:\n        date = \"2016-01-03\"\n        score = 80\n        super_rule = 1\n        hash1 = \"11b7b8a7965b52ebb213b023b6772dd2c76c66893fc96a18a9a33c8cf125af80\"\n        hash2 = \"5d2b1abc7c35de73375dd54a4ec5f0b060ca80a1831dac46ad411b4fe4eac4c6\"\n        hash3 = \"f52869474834be5a6b5df7f8f0c46cbc7e9b22fa5cb30bee0f363ec6eb056b95\"\n\n    strings:\n        $s0 = \"%c:\\\\~tmp%08X.tmp\" fullword ascii\n        $s1 = \"%s%08X.tmp\" fullword ascii\n        $s2 = \".exe.sys.drv.doc.docx.xls.xlsx.mdb.ppt.pptx.xml.jpg.jpeg.ini.inf.ttf\" fullword wide\n        $s3 = \"%ls_%ls_%ls_%d.~tmp\" fullword wide\n\n    condition:\n        uint16(0) == 0x5a4d and filesize < 500KB and 3 of them\n}', 2, '恶意软件', 1);
