INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('apt_nix_elf_derusbi', '', 1, 'rule apt_nix_elf_derusbi\n{\n\n    meta:\n        Author = \"@seifreed\"\n\n    strings:\n        $ = \"LxMain\"\n        $ = \"execve\"\n        $ = \"kill\"\n        $ = \"cp -a %s %s\"\n        $ = \"%s &\"\n        $ = \"dbus-daemon\"\n        $ = \"--noprofile\"\n        $ = \"--norc\"\n        $ = \"TERM=vt100\"\n        $ = \"/proc/%u/cmdline\"\n        $ = \"loadso\"\n        $ = \"/proc/self/exe\"\n        $ = \"Proxy-Connection: Keep-Alive\"\n        $ = \"Connection: Keep-Alive\"\n        $ = \"CONNECT %s\"\n        $ = \"HOST: %s:%d\"\n        $ = \"User-Agent: Mozilla/4.0\"\n        $ = \"Proxy-Authorization: Basic %s\"\n        $ = \"Server: Apache\"\n        $ = \"Proxy-Authenticate\"\n        $ = \"gettimeofday\"\n        $ = \"pthread_create\"\n        $ = \"pthread_join\"\n        $ = \"pthread_mutex_init\"\n        $ = \"pthread_mutex_destroy\"\n        $ = \"pthread_mutex_lock\"\n        $ = \"getsockopt\"\n        $ = \"socket\"\n        $ = \"setsockopt\"\n        $ = \"select\"\n        $ = \"bind\"\n        $ = \"shutdown\"\n        $ = \"listen\"\n        $ = \"opendir\"\n        $ = \"readdir\"\n        $ = \"closedir\"\n        $ = \"rename\"\n\n    condition:\n        (uint32(0) == 0x4464c457f) and (all of them)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('apt_nix_elf_derusbi_kernelModule', '', 1, 'rule apt_nix_elf_derusbi_kernelModule\n{\n\n    meta:\n        Author = \"@seifreed\"\n\n    strings:\n        $ = \"__this_module\"\n        $ = \"init_module\"\n        $ = \"unhide_pid\"\n        $ = \"is_hidden_pid\"\n        $ = \"clear_hidden_pid\"\n        $ = \"hide_pid\"\n        $ = \"license\"\n        $ = \"description\"\n        $ = \"srcversion=\"\n        $ = \"depends=\"\n        $ = \"vermagic=\"\n        $ = \"current_task\"\n        $ = \"sock_release\"\n        $ = \"module_layout\"\n        $ = \"init_uts_ns\"\n        $ = \"init_net\"\n        $ = \"init_task\"\n        $ = \"filp_open\"\n        $ = \"__netlink_kernel_create\"\n        $ = \"kfree_skb\"\n\n    condition:\n        (uint32(0) == 0x4464c457f) and (all of them)\n}', 2, '恶意软件', 1);
