INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT_Derusbi_Gen', '', 1, 'rule APT_Derusbi_Gen\n{\n\nmeta:\n    author = \"ThreatConnect Intelligence Research Team\"\n\nstrings:\n    $2 = \"273ce6-b29f-90d618c0\" wide ascii\n    $A = \"Ace123dx\" fullword wide ascii\n    $A1 = \"Ace123dxl!\" fullword wide ascii\n    $A2 = \"Ace123dx!@#x\" fullword wide ascii\n    $C = \"/Catelog/login1.asp\" wide ascii\n    $DF = \"~DFTMP$$$$$.1\" wide ascii\n    $G = \"GET /Query.asp?loginid=\" wide ascii\n    $L = \"LoadConfigFromReg failded\" wide ascii\n    $L1 = \"LoadConfigFromBuildin success\" wide ascii\n    $ph = \"/photoe/photo.asp HTTP\" wide ascii\n    $PO = \"POST /photos/photo.asp\" wide ascii\n    $PC = \"PCC_IDENT\" wide ascii\n\ncondition:\n    any of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('derusbi_kernel', 'Derusbi Driver version', 1, 'rule derusbi_kernel\n{\n\n    meta:\n        description = \"Derusbi Driver version\"\n        date = \"2015-12-09\"\n        author = \"Airbus Defence and Space Cybersecurity CSIRT - Fabien Perigaud\"\n\n    strings:\n        $token1 = \"$$$--Hello\"\n        $token2 = \"Wrod--$$$\"\n        $cfg = \"XXXXXXXXXXXXXXX\"\n        $class = \".?AVPCC_BASEMOD@@\"\n        $MZ = \"MZ\"\n\n    condition:\n        $MZ at 0 and $token1 and $token2 and $cfg and $class\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('derusbi_linux', 'Derusbi Server Linux version', 1, 'rule derusbi_linux\n{\n\n    meta:\n        description = \"Derusbi Server Linux version\"\n        date = \"2015-12-09\"\n        author = \"Airbus Defence and Space Cybersecurity CSIRT - Fabien Perigaud\"\n\n    strings:\n        $PS1 = \"PS1=RK# \\\\u@\\\\h:\\\\w \\\\$\"\n        $cmd = \"unset LS_OPTIONS;uname -a\"\n        $pname = \"[diskio]\"\n        $rkfile = \"/tmp/.secure\"\n        $ELF = \"\\x7fELF\"\n\n    condition:\n        $ELF at 0 and $PS1 and $cmd and $pname and $rkfile\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Derusbi_Kernel_Driver_WD_UDFS', 'Detects Derusbi Kernel Driver', 1, 'rule Derusbi_Kernel_Driver_WD_UDFS\n{\n\n    meta:\n        description = \"Detects Derusbi Kernel Driver\"\n        author = \"Florian Roth\"\n        reference = \"http:\n        date = \"2015-12-15\"\n        score = 80\n        hash1 = \"1b449121300b0188ff9f6a8c399fb818d0cf53fd36cf012e6908a2665a27f016\"\n        hash2 = \"50174311e524b97ea5cb4f3ea571dd477d1f0eee06cd3ed73af39a15f3e6484a\"\n        hash3 = \"6cdb65dbfb2c236b6d149fd9836cb484d0608ea082cf5bd88edde31ad11a0d58\"\n        hash4 = \"e27fb16dce7fff714f4b05f2cef53e1919a34d7ec0e595f2eaa155861a213e59\"\n\n    strings:\n        $x1 = \"\\\\\\\\.\\\\pipe\\\\usbpcex%d\" fullword wide\n        $x2 = \"\\\\\\\\.\\\\pipe\\\\usbpcg%d\" fullword wide\n        $x3 = \"\\\\??\\\\pipe\\\\usbpcex%d\" fullword wide\n        $x4 = \"\\\\??\\\\pipe\\\\usbpcg%d\" fullword wide\n        $x5 = \"$$$--Hello\" fullword ascii\n        $x6 = \"Wrod--$$$\" fullword ascii\n        $s1 = \"\\\\Registry\\\\User\\\\%s\\\\Software\\\\Microsoft\\\\Windows\\\\CurrentVersion\\\\Internet Settings\" fullword wide\n        $s2 = \"Update.dll\" fullword ascii\n        $s3 = \"\\\\Registry\\\\Machine\\\\SYSTEM\\\\CurrentControlSet\\\\Control\\\\WMI\" fullword wide\n        $s4 = \"\\\\Driver\\\\nsiproxy\" fullword wide\n        $s5 = \"HOST: %s\" fullword ascii\n\ncondition:\n        uint16(0) == 0x5a4d and filesize < 800KB and (2 of ($x*) or all of ($s*))\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Derusbi_Code_Signing_Cert', 'Detects an executable signed with a certificate also used for Derusbi Trojan - suspicious', 1, 'rule Derusbi_Code_Signing_Cert\n{\n\n    meta:\n        description = \"Detects an executable signed with a certificate also used for Derusbi Trojan - suspicious\"\n        author = \"Florian Roth\"\n        reference = \"http:\n        date = \"2015-12-15\"\n        score = 40\n\n   strings:\n      $s1 = \"Fuqing Dawu Technology Co.,Ltd.0\" fullword ascii\n      $s2 = \"XL Games Co.,Ltd.0\" fullword ascii\n      $s3 = \"Wemade Entertainment co.,Ltd0\" fullword ascii\n\n   condition:\n      uint16(0) == 0x5a4d and filesize < 800KB and 1 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('XOR_4byte_Key', 'Detects an executable encrypted with a 4 byte XOR (also used for Derusbi Trojan)', 1, 'rule XOR_4byte_Key\n{\n\n    meta:\n        description = \"Detects an executable encrypted with a 4 byte XOR (also used for Derusbi Trojan)\"\n        author = \"Florian Roth\"\n        reference = \"http:\n        date = \"2015-12-15\"\n        score = 60\n\n   strings:\n      \n      $s1 = { 85 C9 74 0A 31 06 01 1E 83 C6 04 49 EB F2 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('apt_win32_dll_bergard_pgv_pvid_variant', '', 1, 'rule apt_win32_dll_bergard_pgv_pvid_variant\n{\n\n    meta:\n        copyright = \"Fidelis Cybersecurity\"\n        reference = \"http:\n\n    strings:\n        $ = \"Accept:\"\n        $ = \"User-Agent: %s\"\n        $ = \"Host: %s:%d\"\n        $ = \"Cache-Control: no-cache\"\n        $ = \"Connection: Keep-Alive\"\n        $ = \"Cookie: pgv_pvid=\"\n        $ = \"Content-Type: application/x-octet-stream\"\n        $ = \"User-Agent: %s\"\n        $ = \"Host: %s:%d\"\n        $ = \"Pragma: no-cache\"\n        $ = \"Connection: Keep-Alive\"\n        $ = \"HTTP/1.0\"\n\n    condition:\n        (uint16(0) == 0x5A4D) and (all of them)\n}', 2, '恶意软件', 1);
