INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Dubnium_Sample_2', 'Detects sample mentioned in the Dubnium Report', 1, 'rule Dubnium_Sample_2\n{\n\n    meta:\n        description = \"Detects sample mentioned in the Dubnium Report\"\n        author = \"Florian Roth\"\n        reference = \"https:\n        date = \"2016-06-10\"\n        hash1 = \"5246899b8c74a681e385cbc1dd556f9c73cf55f2a0074c389b3bf823bfc6ce4b\"\n\n    strings:\n        $x1 = \":*:::D:\\\\:c:~:\" fullword ascii\n        $s2 = \"SPMUVR\" fullword ascii\n\n    condition:\n        ( uint16(0) == 0x5a4d and filesize < 2000KB and all of them )\n}', 2, '恶意软件', 1);
