INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('apt_duqu2_loaders', 'Rule to detect Duqu 2.0 samples', 1, 'rule apt_duqu2_loaders \n{ \n\n    meta:\n		copyright = \"Kaspersky Lab\"\n		description = \"Rule to detect Duqu 2.0 samples\"\n		last_modified = \"2015-06-09\"\n		version = \"1.0\"\n\n    strings:\n		$a1 = \"{AAFFC4F0-E04B-4C7C-B40A-B45DE971E81E}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('apt_duqu2_drivers', 'Rule to detect Duqu 2.0 drivers', 1, 'rule apt_duqu2_drivers \n{ \n\n    meta:\n		copyright = \"Kaspersky Lab\"\n		description = \"Rule to detect Duqu 2.0 drivers\"\n		last_modified = \"2015-06-09\"\n		version = \"1.0\"\n	\n    strings:\n		$a1 = \"\\\\DosDevices\\\\port_optimizer\" wide nocase \n		$a2 = \"romanian.antihacker\" \n		$a3 = \"PortOptimizerTermSrv\" wide \n		$a4 = \"ugly.gorilla1\"\n		$b1 = \"NdisIMCopySendCompletePerPacketInfo\" \n		$b2 = \"NdisReEnumerateProtocolBindings\"\n		$b3 = \"NdisOpenProtocolConfiguration\"\n	condition:\n		uint16(0) == 0x5A4D and (any of ($a*) ) and (2 of ($b*)) and filesize < 100000\n}', 2, '恶意软件', 1);
