INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Malware_Updater', '', 1, 'rule Malware_Updater\n{\nmeta:\n	Author=\"US-CERT Code Analysis Team\"\n	Date=\"2017/08/02\"\n	Incident=\"10132963\"\n	MD5_1=\"8F4FC2E10B6EC15A01E0AF24529040DD\"\n	MD5_2=\"584AC94142F0B7C0DF3D0ADDE6E661ED\"\n	Info=\"Malware may be used to update multiple systems with secondary payloads\"\n	super_rule=1\n	report = \"https:\n	report = \"https:\nstrings:\n	$s0 = { 8A4C040480F15D80C171884C04044083F8107CEC }', 2, '恶意软件', 1);
