INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT_Malware_PutterPanda_Gen4', 'Detects Malware related to PutterPanda', 1, 'rule APT_Malware_PutterPanda_Gen4 \n{\n\n    meta:\n        description = \"Detects Malware related to PutterPanda\"\n        author = \"Florian Roth\"\n        score = 70\n        reference = \"VT Analysis\"\n        date = \"2015-06-03\"\n        super_rule = 1\n        hash0 = \"71a8378fa8e06bcf8ee9f019c807c6bfc58dca0c\"\n        hash1 = \"8fdd6e5ed9d69d560b6fdd5910f80e0914893552\"\n        hash2 = \"3c4a762175326b37035a9192a981f7f4cc2aa5f0\"\n        hash3 = \"598430b3a9b5576f03cc4aed6dc2cd8a43324e1e\"\n        hash4 = \"6522b81b38747f4aa09c98fdaedaed4b00b21689\"\n\n    strings:\n        $x1 = \"rz.dat\" fullword ascii \n        $s0 = \"Mozilla/4.0 (Compatible; MSIE 6.0;)\" fullword ascii  \n        $s1 = \"Internet connect error:%d\" fullword ascii  \n        $s2 = \"Proxy-Authorization:Basic \" fullword ascii  \n        $s5 = \"Invalid url\" fullword ascii  \n        $s6 = \"Create file failed\" fullword ascii \n        $s7 = \"myAgent\" fullword ascii \n        $z1 = \"%s%s%d%d\" fullword ascii \n        $z2 = \"HttpQueryInfo failed:%d\" fullword ascii  \n        $z3 = \"read file error:%d\" fullword ascii \n        $z4 = \"down file success\" fullword ascii \n        $z5 = \"kPStoreCreateInstance\" fullword ascii \n        $z6 = \"Avaliable data:%u bytes\" fullword ascii \n        $z7 = \"abe2869f-9b47-4cd9-a358-c22904dba7f7\" fullword ascii   \n\n    condition:\n        filesize < 300KB and (( uint16(0) == 0x5a4d and $x1 and 3 of ($s*) ) or ( 3 of ($s*) and 4 of ($z*) ))\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('malware_red_leaves_generic', 'Red Leaves malware, related to APT10', 1, 'rule malware_red_leaves_generic {\n  meta:\n    author = \"David Cannings\"\n    description = \"Red Leaves malware, related to APT10\"\n    \n    \n    sha256 = \"2e1f902de32b999642bb09e995082c37a024f320c683848edadaf2db8e322c3c\"\n    \n  strings:\n    \n    $ = \"Feb 04 2015\"\n    $ = \"I can not start %s\"\n    $ = \"dwConnectPort\" fullword\n    $ = \"dwRemoteLanPort\" fullword\n    $ = \"strRemoteLanAddress\" fullword\n    $ = \"strLocalConnectIp\" fullword\n    $ = \"\\\\\\\\.\\\\pipe\\\\NamePipe_MoreWindows\" wide\n    $ = \"RedLeavesCMDSimulatorMutex\" wide\n    $ = \"(NT %d.%d Build %d)\" wide\n    $ = \"Mozilla/4.0 (compatible; MSIE 8.0; Windows NT 6.1; WOW64; Trident/4.0; SLCC2; .NET CLR 2.0.50727; .NET CLR 3.5.30729; .NET CLR 3.0.30729; .NET4.0C; .NET4.0E)\" wide\n    $ = \"red_autumnal_leaves_dllmain.dll\" wide ascii\n    $ = \"__data\" wide\n    $ = \"__serial\" wide\n    $ = \"__upt\" wide\n    $ = \"__msgid\" wide\n    \n  condition:\n    7 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('malware_red_leaves_memory', 'Red Leaves C&C left in memory, use with Volatility / Rekall', 1, 'rule malware_red_leaves_memory {\n  meta:\n    author = \"David Cannings\"\n    description = \"Red Leaves C&C left in memory, use with Volatility / Rekall\"\n    \n  strings:\n    $ = \"__msgid=\" wide ascii\n    $ = \"__serial=\" wide ascii\n    $ = \"OnlineTime=\" wide\n\n    \n    $ = \"clientpath=\" wide ascii \n    $ = \"serverpath=\" wide ascii\n\n  condition:\n    3 of them\n}', 2, '恶意软件', 1);
