INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('apt_regin_2013_64bit_stage1', 'Rule to detect Regin 64 bit stage 1 loaders', 1, 'rule apt_regin_2013_64bit_stage1 \n{\n    \n    meta:\n        copyright = \"Kaspersky Lab\"\n        description = \"Rule to detect Regin 64 bit stage 1 loaders\"\n        version = \"1.0\"\n        last_modified = \"2014-11-18\"\n        filename=\"wshnetc.dll\"\n        md5=\"bddf5afbea2d0eed77f2ad4e9a4f044d\"\n        filename=\"wsharp.dll\"\n        md5=\"c053a0a3f1edcbbfc9b51bc640e808ce\"\n\n    strings:\n        $mz=\"MZ\"\n        $a1=\"PRIVHEAD\"\n        $a2=\"\\\\\\\\.\\\\PhysicalDrive%d\"\n        $a3=\"ZwDeviceIoControlFile\"\n\n    condition:\n        ($mz at 0) and (all of ($a*)) and filesize < 100000\n}', 2, '恶意软件', 1);
