INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('apt_ProjectSauron_pipe_backdoor', 'Rule to detect ProjectSauron pipe backdoors', 1, 'rule apt_ProjectSauron_pipe_backdoor  \n{\n\n    meta:\n        copyright = \"Kaspersky Lab\"\n        description = \"Rule to detect ProjectSauron pipe backdoors\"\n        version = \"1.0\"    \n        reference = \"https:\n   \n    strings:\n        $a1 = \"CreateNamedPipeW\" fullword ascii\n        $a2 = \"SetSecurityDescriptorDacl\" fullword ascii\n        $a3 = \"GetOverlappedResult\" fullword ascii\n        $a4 = \"TerminateThread\" fullword ascii\n        $a5 = \"%s%s%X\" fullword wide  \n\n    condition:\n        uint16(0) == 0x5A4D  and (all of ($a*)) and filesize < 100000\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('apt_ProjectSauron_encrypted_LSA', 'Rule to detect ProjectSauron encrypted LSA samples', 1, 'rule apt_ProjectSauron_encrypted_LSA  \n{\n\n    meta:\n        copyright = \"Kaspersky Lab\"\n        description = \"Rule to detect ProjectSauron encrypted LSA samples\"\n        version = \"1.0\"    \n        reference = \"https:\n\n    strings:\n        $a1 = \"EFEB0A9C6ABA4CF5958F41DB6A31929776C643DEDC65CC9B67AB8B0066FF2492\" fullword ascii\n        $a2 = \"\\\\Device\\\\NdisRaw_\" fullword ascii\n        $a3 = \"\\\\\\\\.\\\\GLOBALROOT\\\\Device\\\\{8EDB44DC-86F0-4E0E-8068-BD2CABA4057A}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('apt_ProjectSauron_encrypted_SSPI', 'Rule to detect encrypted ProjectSauron SSPI samples', 1, 'rule apt_ProjectSauron_encrypted_SSPI  \n{\n\n    meta:\n        copyright = \"Kaspersky Lab\"\n        description = \"Rule to detect encrypted ProjectSauron SSPI samples\"\n        version = \"1.0\"\n        reference = \"https:\n\n    condition:\n        uint16(0) == 0x5A4D and filesize < 1000000 and pe.exports(\"InitSecurityInterfaceA\") and pe.characteristics & pe.DLL and (pe.machine == pe.MACHINE_AMD64 or pe.machine == pe.MACHINE_IA64) and math.entropy(0x400, filesize) >= 7.5 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('apt_ProjectSauron_MyTrampoline', 'Rule to detect ProjectSauron MyTrampoline module', 1, 'rule apt_ProjectSauron_MyTrampoline  \n{\n\n    meta:\n        copyright = \"Kaspersky Lab\"\n        description = \"Rule to detect ProjectSauron MyTrampoline module\"\n        version = \"1.0\"\n        reference = \"https:\n\n    strings:\n        $a1 = \":\\\\System Volume Information\\\\{\" wide\n        $a2 = \"\\\\\\\\.\\\\PhysicalDrive%d\" wide\n        $a3 = \"DMWndClassX%d\"\n        $b1 = \"{774476DF-C00F-4e3a-BF4A-6D8618CFA532}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('apt_ProjectSauron_encrypted_container', 'Rule to detect ProjectSauron samples encrypted container', 1, 'rule apt_ProjectSauron_encrypted_container  \n{\n\n    meta:\n        copyright = \"Kaspersky Lab\"\n        description = \"Rule to detect ProjectSauron samples encrypted container\"\n        version = \"1.0\"\n        reference = \"https:\n\n    strings:\n        $vfs_header = {02 AA 02 C1 02 0?}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('apt_ProjectSauron_encryption', 'Rule to detect ProjectSauron string encryption', 1, 'rule apt_ProjectSauron_encryption  \n{\n\n    meta:\n        copyright = \"Kaspersky Lab\"\n        description = \"Rule to detect ProjectSauron string encryption\"\n        version = \"1.0\"\n        reference = \"https:\n\n    strings:\n        $a1 = {81??02AA02C175??8B??0685}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('apt_ProjectSauron_generic_pipe_backdoor', 'Rule to detect ProjectSauron generic pipe backdoors', 1, 'rule apt_ProjectSauron_generic_pipe_backdoor \n{\n\n    meta:\n        copyright = \"Kaspersky Lab\"\n        description = \"Rule to detect ProjectSauron generic pipe backdoors\"\n        version = \"1.0\"\n        reference = \"https:\n\n    strings:\n        $a = { C7 [2-3] 32 32 32 32 E8 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT_Project_Sauron_Scripts', 'Detects scripts (mostly LUA) from Project Sauron report by Kaspersky', 1, 'rule APT_Project_Sauron_Scripts \n{\n\n    meta:\n        description = \"Detects scripts (mostly LUA) from Project Sauron report by Kaspersky\"\n        author = \"Florian Roth\"\n        reference = \"https:\n        date = \"2016-08-08\"\n\n    strings:\n        $x1 = \"local t = w.exec2str(\\\"regedit \"\n        $x2 = \"local r = w.exec2str(\\\"cat\"\n        $x3 = \"ap*.txt link*.txt node*.tun VirtualEncryptedNetwork.licence\"\n        $x4 = \"move O FakeVirtualEncryptedNetwork.dll\"\n        $x5 = \"sinfo | basex b 32url | dext l 30\"\n        $x6 = \"w.exec2str(execStr)\"\n        $x7 = \"netnfo irc | basex b 32url\"\n        $x8 = \"w.exec(\\\"wfw status\\\")\"\n        $x9 = \"exec(\\\"samdump\\\")\"\n        $x10 = \"cat VirtualEncryptedNetwork.ini|grep\"\n        $x11 = \"if string.lower(k) == \\\"securityproviders\\\" then\"\n        $x12 = \"exec2str(\\\"plist b | grep netsvcs\\\")\"\n        $x13 = \".*account.*|.*acct.*|.*domain.*|.*login.*|.*member.*\"\n        $x14 = \"SAURON_KBLOG_KEY =\"\n\n    condition:\n        1 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT_Project_Sauron_arping_module', 'Detects strings from arping module - Project Sauron report by Kaspersky', 1, 'rule APT_Project_Sauron_arping_module \n{\n\n    meta:\n        description = \"Detects strings from arping module - Project Sauron report by Kaspersky\"\n        author = \"Florian Roth\"\n        reference = \"https:\n        date = \"2016-08-08\"\n\n    strings:\n        $s1 = \"Resolve hosts that answer\"\n        $s2 = \"Print only replying Ips\"\n        $s3 = \"Do not display MAC addresses\"\n\n    condition:\n        all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT_Project_Sauron_kblogi_module', 'Detects strings from kblogi module - Project Sauron report by Kaspersky', 1, 'rule APT_Project_Sauron_kblogi_module \n{\n\n    meta:\n        description = \"Detects strings from kblogi module - Project Sauron report by Kaspersky\"\n        author = \"Florian Roth\"\n        reference = \"https:\n        date = \"2016-08-08\"\n\n    strings:\n        $x1 = \"Inject using process name or pid. Default\"\n        $s2 = \"Convert mode: Read log from file and convert to text\"\n        $s3 = \"Maximum running time in seconds\"\n\n    condition:\n        $x1 or 2 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT_Project_Sauron_basex_module', 'Detects strings from basex module - Project Sauron report by Kaspersky', 1, 'rule APT_Project_Sauron_basex_module \n{\n\n    meta:\n        description = \"Detects strings from basex module - Project Sauron report by Kaspersky\"\n        author = \"Florian Roth\"\n        reference = \"https:\n        date = \"2016-08-08\"\n\n    strings:\n        $x1 = \"64, 64url, 32, 32url or 16.\"\n        $s2 = \"Force decoding when input is invalid/corrupt\"\n        $s3 = \"This cruft\"\n\n    condition:\n        $x1 or 2 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT_Project_Sauron_dext_module', 'Detects strings from dext module - Project Sauron report by Kaspersky', 1, 'rule APT_Project_Sauron_dext_module \n{\n\n    meta:\n        description = \"Detects strings from dext module - Project Sauron report by Kaspersky\"\n        author = \"Florian Roth\"\n        reference = \"https:\n        date = \"2016-08-08\"\n    \n    strings:\n        $x1 = \"Assemble rows of DNS names back to a single string of data\"\n        $x2 = \"removes checks of DNS names and lengths (during split)\"\n        $x3 = \"Randomize data lengths (length/2 to length)\"\n        $x4 = \"This cruft\"\n    \n    condition:\n        2 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Hacktool_This_Cruft', 'Detects string ''This cruft'' often used in hack tools like netcat or cryptcat and also mentioned in Project Sauron report', 1, 'rule Hacktool_This_Cruft \n{\n\n    meta:\n        description = \"Detects string ''This cruft'' often used in hack tools like netcat or cryptcat and also mentioned in Project Sauron report\"\n        author = \"Florian Roth\"\n        reference = \"https:\n        date = \"2016-08-08\"\n        score = 60\n\n    strings:\n        $x1 = \"This cruft\" fullword\n\n    condition:\n        ( uint16(0) == 0x5a4d and filesize < 200KB and $x1 )\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT_Project_Sauron_Custom_M1', 'Detects malware from Project Sauron APT', 1, 'rule APT_Project_Sauron_Custom_M1 \n{\n\n    meta:\n        description = \"Detects malware from Project Sauron APT\"\n        author = \"FLorian Roth\"\n        reference = \"https:\n        date = \"2016-08-09\"\n        hash1 = \"9572624b6026311a0e122835bcd7200eca396802000d0777dba118afaaf9f2a9\"\n\n    strings:\n        $s1 = \"ncnfloc.dll\" fullword wide\n        $s4 = \"Network Configuration Locator\" fullword wide\n\n        $op0 = { 80 75 6e 85 c0 79 6a 66 41 83 38 0a 75 63 0f b7 }', 2, '恶意软件', 1);
