INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT_Project_Sauron_Custom_M3', 'Detects malware from Project Sauron APT', 1, 'rule APT_Project_Sauron_Custom_M3 \n{\n\n    meta:\n        description = \"Detects malware from Project Sauron APT\"\n        author = \"FLorian Roth\"\n        reference = \"https:\n        date = \"2016-08-09\"\n        hash1 = \"a4736de88e9208eb81b52f29bab9e7f328b90a86512bd0baadf4c519e948e5ec\"\n   \n    strings:\n        $s1 = \"ExampleProject.dll\" fullword ascii\n        $op0 = { 8b 4f 06 85 c9 74 14 83 f9 13 0f 82 ba }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT_Project_Sauron_Custom_M4', 'Detects malware from Project Sauron APT', 1, 'rule APT_Project_Sauron_Custom_M4 \n{\n\n    meta:\n        description = \"Detects malware from Project Sauron APT\"\n        author = \"FLorian Roth\"\n        reference = \"https:\n        date = \"2016-08-09\"\n        hash1 = \"e12e66a6127cfd2cbb42e6f0d57c9dd019b02768d6f1fb44d91f12d90a611a57\"\n\n    strings:\n        $s1 = \"xpsmngr.dll\" fullword wide\n        $s2 = \"XPS Manager\" fullword wide\n        $op0 = { 89 4d e8 89 4d ec 89 4d f0 ff d2 3d 08 00 00 c6 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT_Project_Sauron_Custom_M6', 'Detects malware from Project Sauron APT', 1, 'rule APT_Project_Sauron_Custom_M6 \n{\n\n    meta:\n        description = \"Detects malware from Project Sauron APT\"\n        author = \"FLorian Roth\"\n        reference = \"https:\n        date = \"2016-08-09\"\n        hash1 = \"3782b63d7f6f688a5ccb1b72be89a6a98bb722218c9f22402709af97a41973c8\"\n\n    strings:\n        $s1 = \"rseceng.dll\" fullword wide\n        $s2 = \"Remote Security Engine\" fullword wide\n        $op0 = { 8b 0d d5 1d 00 00 85 c9 0f 8e a2 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT_Project_Sauron_Custom_M7', 'Detects malware from Project Sauron APT', 1, 'rule APT_Project_Sauron_Custom_M7 \n{\n\n    meta:\n        description = \"Detects malware from Project Sauron APT\"\n        author = \"FLorian Roth\"\n        reference = \"https:\n        date = \"2016-08-09\"\n        hash1 = \"6c8c93069831a1b60279d2b316fd36bffa0d4c407068dbef81b8e2fe8fd8e8cd\"\n        hash2 = \"7cc0bf547e78c8aaf408495ceef58fa706e6b5d44441fefdce09d9f06398c0ca\"\n\n    strings:\n        $sx1 = \"Default user\" fullword wide\n        $sx2 = \"Hincorrect header check\" fullword ascii \n        $sa1 = \"MSAOSSPC.dll\" fullword ascii\n        $sa2 = \"MSAOSSPC.DLL\" fullword wide\n        $sa3 = \"MSAOSSPC\" fullword wide\n        $sa4 = \"AOL Security Package\" fullword wide\n        $sa5 = \"AOL Security Package\" fullword wide\n        $sa6 = \"AOL Client for 32 bit platforms\" fullword wide\n        $op0 = { 8b ce 5b e9 4b ff ff ff 55 8b ec 51 53 8b 5d 08 }', 2, '恶意软件', 1);
