INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Stuxnet_MadeInPython', 'Python has been used frequently by threat actors for compiling executable file with source code. I found python Stuxnet source code that can be executed with required dependencies. This rule is created in hopes to catch potental breakout of future Stuxnet.', 1, 'rule Stuxnet_MadeInPython\n{\n    meta:\n        description = \"Python has been used frequently by threat actors for compiling executable file with source code. I found python Stuxnet source code that can be executed with required dependencies. This rule is created in hopes to catch potental breakout of future Stuxnet.\"\n        author = \"Jin Kim\"\n        reference = \"https:\n        date = \"2020-12-23\"\n    \n    strings:\n    \n        $str1 = \"old_infected_attributes = node_infected_attributes(graph)\"\n    \n	\n	\n	\n	\n	\n	\n	\n        $str2 = \"NodeType.DISCONNECTED_COMPUTER\"\n\n    \n    \n    \n		\n        $str3 = \"add_computer_nodes(graph, EdgeType.LOCAL_WIRELESS, router_node)\"\n    \n    condition:\n        any of them\n}', 2, '恶意软件', 1);
