INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('EquationGroup_Toolset_Apr17__ELV_ESKE_13', 'Detects EquationGroup Tool - April Leak', 1, 'rule EquationGroup_Toolset_Apr17__ELV_ESKE_13 {\n   meta:\n      description = \"Detects EquationGroup Tool - April Leak\"\n      author = \"Florian Roth\"\n      reference = \"https:\n      date = \"2017-04-15\"\n      super_rule = 1\n      hash1 = \"f7fad44560bc8cc04f03f1d30b6e1b4c5f049b9a8a45464f43359cbe4d1ce86f\"\n      hash2 = \"9d16d97a6c964e0658b6cd494b0bbf70674bf37578e2ff32c4779a7936e40556\"\n   strings:\n      $x1 = \"Skip call to PackageRideArea().  Payload has already been packaged. Options -x and -q ignored.\" fullword ascii\n      $s2 = \"ERROR: pGvars->pIntRideAreaImplantPayload is NULL\" fullword ascii\n   condition:\n      ( uint16(0) == 0x5a4d and filesize < 600KB and 1 of them )\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('EquationGroup_Toolset_Apr17__NameProbe_SMBTOUCH_14', 'Detects EquationGroup Tool - April Leak', 1, 'rule EquationGroup_Toolset_Apr17__NameProbe_SMBTOUCH_14 {\n   meta:\n      description = \"Detects EquationGroup Tool - April Leak\"\n      author = \"Florian Roth\"\n      reference = \"https:\n      date = \"2017-04-15\"\n      super_rule = 1\n      hash1 = \"fbe3a4501654438f502a93f51b298ff3abf4e4cad34ce4ec0fad5cb5c2071597\"\n      hash2 = \"7da350c964ea43c149a12ac3d2ce4675cedc079ddc10d1f7c464b16688305309\"\n   strings:\n      $s1 = \"DEC Pathworks TCPIP service on Windows NT\" fullword ascii\n      $s2 = \"<\\\\\\\\__MSBROWSE__> G\" fullword ascii\n      $s3 = \"<IRISNAMESERVER>\" fullword ascii\n   condition:\n      ( uint16(0) == 0x5a4d and filesize < 300KB and all of them )\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('EquationGroup_Toolset_Apr17__ELV_ESKE_EVFR_RPC2_15', 'Detects EquationGroup Tool - April Leak', 1, 'rule EquationGroup_Toolset_Apr17__ELV_ESKE_EVFR_RPC2_15 {\n   meta:\n      description = \"Detects EquationGroup Tool - April Leak\"\n      author = \"Florian Roth\"\n      reference = \"https:\n      date = \"2017-04-15\"\n      super_rule = 1\n      hash1 = \"f7fad44560bc8cc04f03f1d30b6e1b4c5f049b9a8a45464f43359cbe4d1ce86f\"\n      hash2 = \"9d16d97a6c964e0658b6cd494b0bbf70674bf37578e2ff32c4779a7936e40556\"\n      hash3 = \"c5e119ff7b47333f415aea1d2a43cb6cb322f8518562cfb9b90399cac95ac674\"\n      hash4 = \"5c0896dbafc5d8cc19b1bc7924420b20ed5999ac5bee2cb5a91aada0ea01e337\"\n   strings:\n      $x1 = \"** SendAndReceive ** - EXCEPTION_EXECUTE_HANDLER\" fullword ascii\n      $s8 = \"Binding to RPC Interface %s over named pipe\" fullword ascii\n   condition:\n      ( uint16(0) == 0x5a4d and filesize < 2000KB and 1 of them )\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('EquationGroup_Toolset_Apr17__ELV_ESKE_EVFR_16', 'Detects EquationGroup Tool - April Leak', 1, 'rule EquationGroup_Toolset_Apr17__ELV_ESKE_EVFR_16 {\n   meta:\n      description = \"Detects EquationGroup Tool - April Leak\"\n      author = \"Florian Roth\"\n      reference = \"https:\n      date = \"2017-04-15\"\n      super_rule = 1\n      hash1 = \"f7fad44560bc8cc04f03f1d30b6e1b4c5f049b9a8a45464f43359cbe4d1ce86f\"\n      hash2 = \"9d16d97a6c964e0658b6cd494b0bbf70674bf37578e2ff32c4779a7936e40556\"\n      hash3 = \"c5e119ff7b47333f415aea1d2a43cb6cb322f8518562cfb9b90399cac95ac674\"\n   strings:\n      $x1 = \"ERROR: TbMalloc() failed for encoded exploit payload\" fullword ascii\n      $x2 = \"** EncodeExploitPayload ** - EXCEPTION_EXECUTE_HANDLER\" fullword ascii\n      $x4 = \"** RunExploit ** - EXCEPTION_EXECUTE_HANDLER\" fullword ascii\n      $s6 = \"Sending Implant Payload (%d-bytes)\" fullword ascii\n      $s7 = \"ERROR: Encoder failed on exploit payload\" fullword ascii\n      $s11 = \"ERROR: VulnerableOS() != RET_SUCCESS\" fullword ascii\n   condition:\n      ( uint16(0) == 0x5a4d and filesize < 2000KB and 1 of them )\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('EquationGroup_Toolset_Apr17__ETBL_ETRE_SMBTOUCH_17', 'Detects EquationGroup Tool - April Leak', 1, 'rule EquationGroup_Toolset_Apr17__ETBL_ETRE_SMBTOUCH_17 {\n   meta:\n      description = \"Detects EquationGroup Tool - April Leak\"\n      author = \"Florian Roth\"\n      reference = \"https:\n      date = \"2017-04-15\"\n      super_rule = 1\n      hash1 = \"70db3ac2c1a10de6ce6b3e7a7890c37bffde006ea6d441f5de6d8329add4d2ef\"\n      hash2 = \"e0f05f26293e3231e4e32916ad8a6ee944af842410c194fce8a0d8ad2f5c54b2\"\n      hash3 = \"7da350c964ea43c149a12ac3d2ce4675cedc079ddc10d1f7c464b16688305309\"\n   strings:\n      $x1 = \"ERROR: Connection terminated by Target (TCP Ack/Fin)\" fullword ascii\n      $s2 = \"Target did not respond within specified amount of time\" fullword ascii\n   condition:\n      ( uint16(0) == 0x5a4d and filesize < 300KB and 1 of them )\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('EquationGroup_scanner_output', 'Detects output generated by EQGRP scanner.exe', 1, 'rule EquationGroup_scanner_output {\n   meta:\n      description = \"Detects output generated by EQGRP scanner.exe\"\n      author = \"Florian Roth\"\n      reference = \"Internal Research\"\n      date = \"2017-04-17\"\n   strings:\n      $s1 = \"# Scan for windows boxes\" ascii fullword\n      $s2 = \"Going into send\" ascii fullword\n      $s3 = \"# Does not work\" ascii fullword\n      $s4 = \"You are the weakest link, goodbye\" ascii fullword\n      $s5 = \"rpc   Scan for RPC  folks\" ascii fullword\n   condition:\n      filesize < 1000KB and 2 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('COZY_FANCY_BEAR_Hunt', 'Detects Cozy Bear / Fancy Bear C2 Server IPs', 1, 'rule COZY_FANCY_BEAR_Hunt \n{\n\n    meta:\n        description = \"Detects Cozy Bear / Fancy Bear C2 Server IPs\"\n        author = \"Florian Roth\"\n        reference = \"https:\n        date = \"2016-06-14\"\n\n    strings:\n        $s1 = \"185.100.84.134\" ascii wide fullword\n        $s2 = \"58.49.58.58\" ascii wide fullword\n        $s3 = \"218.1.98.203\" ascii wide fullword\n        $s4 = \"187.33.33.8\" ascii wide fullword\n        $s5 = \"185.86.148.227\" ascii wide fullword\n        $s6 = \"45.32.129.185\" ascii wide fullword\n        $s7 = \"23.227.196.217\" ascii wide fullword\n\n    condition:\n        uint16(0) == 0x5a4d and 1 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('COZY_FANCY_BEAR_pagemgr_Hunt', 'Detects a pagemgr.exe as mentioned in the CrowdStrike report', 1, 'rule COZY_FANCY_BEAR_pagemgr_Hunt \n{\n\n    meta:\n        description = \"Detects a pagemgr.exe as mentioned in the CrowdStrike report\"\n        author = \"Florian Roth\"\n        reference = \"https:\n        date = \"2016-06-14\"\n\n    strings:\n        $s1 = \"pagemgr.exe\" wide fullword\n\n    condition:\n        uint16(0) == 0x5a4d and 1 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT_fancybear_Downdelph_magic', 'APT28 downdelph magic string', 1, 'rule APT_fancybear_Downdelph_magic : Bootkit{\n	meta:\n		author = \"Marc Salinas @Bondey_m\"\n		description = \"APT28 downdelph magic string\"\n		reference = \"https:\n	strings:\n		$str1 = \" :3 \"\n	condition:\n		$str1 at 0\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT_fancybear_Downdelph_MBR', 'APT28 downdelph string on MBR (get your MBR with BOOTICE on Win or #dd if=/dev/sda of=./sda.mbr bs=512 count=1', 1, 'rule APT_fancybear_Downdelph_MBR : Bootkit{\n	meta:\n		author = \"Marc Salinas @Bondey_m\"\n		description = \"APT28 downdelph string on MBR (get your MBR with BOOTICE on Win or #dd if=/dev/sda of=./sda.mbr bs=512 count=1\"\n		reference = \"https:\n	strings:\n		$s1 = { 20 3A 33 20 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Furtim_nativeDLL', 'Detects Furtim malware - file native.dll', 1, 'rule Furtim_nativeDLL \n{\n\n    meta:\n        description = \"Detects Furtim malware - file native.dll\"\n        author = \"Florian Roth\"\n        reference = \"MISP 3971\"\n        date = \"2016-06-13\"\n        hash1 = \"4f39d3e70ed1278d5fa83ed9f148ca92383ec662ac34635f7e56cc42eeaee948\"\n\n    strings:\n        $s1 = \"FqkVpTvBwTrhPFjfFF6ZQRK44hHl26\" fullword ascii\n        $op0 = { e0 b3 42 00 c7 84 24 ac }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Furtim_Parent_1', 'Detects Furtim Parent Malware', 1, 'rule Furtim_Parent_1 \n{\n\n    meta:\n        description = \"Detects Furtim Parent Malware\"\n        author = \"Florian Roth\"\n        reference = \"https:\n        date = \"2016-07-16\"\n        hash1 = \"766e49811c0bb7cce217e72e73a6aa866c15de0ba11d7dda3bd7e9ec33ed6963\"\n\n    strings:\n        \n        $x1 = \"dqrChZonUF\" fullword ascii\n        \n        $s1 = \"Egistec\" fullword wide\n        $s2 = \"Copyright (C) 2016\" fullword wide\n        \n        $op1 = { c0 ea 02 88 55 f8 8a d1 80 e2 03 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('BeEF_browser_hooked', 'Yara rule related to hook.js, BeEF Browser hooking capability', 1, 'rule BeEF_browser_hooked \n{\n	meta:\n		description = \"Yara rule related to hook.js, BeEF Browser hooking capability\"\n		author = \"Pasquale Stirparo\"\n		date = \"2015-10-07\"\n		hash1 = \"587e611f49baf63097ad2421ad0299b7b8403169ec22456fb6286abf051228db\"\n	\n	strings:\n		$s0 = \"mitb.poisonAnchor\" wide ascii\n		$s1 = \"this.request(this.httpproto\" wide ascii\n		$s2 = \"beef.logger.get_dom_identifier\" wide ascii\n		$s3 = \"return (!!window.opera\" wide ascii \n		$s4 = \"history.pushState({ Be:\\\"EF\\\" }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('GEN_PowerShell', 'Generic PowerShell Malware Rule', 1, 'rule GEN_PowerShell \n{\n\n    meta:\n        description = \"Generic PowerShell Malware Rule\"\n        author = \"https:\n    \n    strings:\n        $s1 = \"powershell\"\n        $s2 = \"-ep bypass\" nocase\n        $s3 = \"-nop\" nocase\n        $s10 = \"-executionpolicy bypass\" nocase\n        $s4 = \"-win hidden\" nocase\n        $s5 = \"-windowstyle hidden\" nocase\n        $s11 = \"-w hidden\" nocase\n        \n        \n        $s8 = \"-enc\" nocase\n        $s9 = \"-encodedcommand\" nocase\n    \n    condition:\n        $s1 and (($s2 or $s3 or $s10) and ($s4 or $s5 or $s11) and ($s8 or $s9))\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Generic_ATMPot', 'Generic rule for Winpot aka ATMPot', 1, 'rule Generic_ATMPot : Generic_ATMPot\n{\n    meta:\n        description = \"Generic rule for Winpot aka ATMPot\"\n        author = \"xylitol@temari.fr\"\n        date = \"2019-02-24\"\n        reference = \"https:\n        \n    strings:\n        $api1 = \"CSCCNG\" ascii wide\n        $api2 = \"CscCngOpen\" ascii wide\n        $api3 = \"CscCngClose\" ascii wide\n        $string1 = \"%d,%02d;\" ascii wide\n\n        $hex1 = { FF 15 ?? ?? ?? ?? F6 C4 80 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('ATM_HelloWorld', 'Search strings and procedure in HelloWorld ATM Malware', 1, 'rule ATM_HelloWorld : malware\n{\n    meta:\n        description = \"Search strings and procedure in HelloWorld ATM Malware\"\n        author = \"xylitol@temari.fr\"\n        date = \"2019-01-13\"\n\n    strings:\n        $api1 = \"CscCngOpen\" ascii wide\n        $api2 = \"CscCngClose\" ascii wide\n        $string1 = \"%d,%02d;\" ascii wide\n        $string2 = \"MAX_NOTES\" ascii wide\n        $hex_var1 = { FF 15 ?? ?? ?? ?? BF 00 80 00 00 85 C7 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Windows_Malware', 'Match first two bytes, strings, and parts of routines present in Azorult', 1, 'rule Windows_Malware : Azorult_V2\n    {\n            meta:\n                    author = \"Xylitol xylitol@temari.fr\"\n                    date = \"2017-09-30\"\n                    description = \"Match first two bytes, strings, and parts of routines present in Azorult\"\n                    reference = \"http:\n                    \n            strings:\n                    $mz = {4D 5A}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Agenttesla', 'Detecting HTML strings used by Agent Tesla malware', 1, 'rule Agenttesla\n{\n    meta:\n        description = \"Detecting HTML strings used by Agent Tesla malware\"\n        author = \"Stormshield\"\n        reference = \"https:\n        version = \"1.0\"\n\n    strings:\n        $html_username    = \"<br>UserName&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;: \" wide ascii\n        $html_pc_name     = \"<br>PC&nbsp;Name&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;: \" wide ascii\n        $html_os_name     = \"<br>OS&nbsp;Full&nbsp;Name&nbsp;&nbsp;: \" wide ascii\n        $html_os_platform = \"<br>OS&nbsp;Platform&nbsp;&nbsp;&nbsp;: \" wide ascii\n        $html_clipboard   = \"<br><span style=font-style:normal;text-decoration:none;text-transform:none;color:#FF0000;><strong>[clipboard]</strong></span>\" wide ascii\n\n    condition:\n        3 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('agenttesla_smtp_variant', '', 1, 'rule agenttesla_smtp_variant {\n\n    meta:\n        author = \"J from THL <j@techhelplist.com> with thx to @Fumik0_ !!1!\"\n        date = \"2018/2\"\n	reference1 = \"https:\n	reference2 = \"https:\n	reference3 = \"Agent Tesla == negasteal -- @coldshell\"\n	version = 1\n        maltype = \"Stealer\"\n        filetype = \"memory\"\n\n    strings:\n		$a = \"type={\"\n		$b = \"hwid={\"\n		$c = \"time={\"\n		$d = \"pcname={\"\n		$e = \"logdata={\"\n		$f = \"screen={\"\n		$g = \"ipadd={\"\n		$h = \"webcam_link={\"\n		$i = \"screen_link={\"\n		$j = \"site_username={\"\n		$k = \"[passwords]\"\n\n    condition:\n        6 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('almashreq_agent_dotnet', 'Memory rule for a .net RAT/Agent first found with .pdb referencing almashreq', 1, 'rule almashreq_agent_dotnet : almashreq_agent_dotnet\n{\n    meta:\n        description = \"Memory rule for a .net RAT/Agent first found with .pdb referencing almashreq\"\n	author = \"J from THL <j@techhelplist.com> with thx to @malwrhunterteam !!1!\"\n        date = \"2019-05-12\"\n        reference1 = \"https:\n        reference2 = \"https:\n        reference3 = \"https:\n        reference4 = \"https:\n        reference5 = \"https:\n        maltype = \"agent\"\n	filetype = \"memory\"\n\n    strings:\n        $s01 = \"WriteElementString(@\\\"PCName\\\",\" wide\n        $s02 = \"WriteElementString(@\\\"Command\\\",\" wide\n        $s03 = \"WriteElementStringRaw(@\\\"commandID\\\",\" wide\n	$s04 = /^Try Run$/ wide\n        $s05 = \" is running in PC :\" wide\n        $s06 = \"SOAPAction: \\\"http:\n        $s07 = \"Try Run</obj><name>\" wide\n        $s08 = \"Disable</obj><name>\" wide\n        $s09 = \"http:\n\n 	condition: \n 		7 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('alina', 'Identify Alina', 1, 'rule alina\n{\n	meta:\n		author = \"Brian Wallace @botnet_hunter\"\n		author_email = \"bwall@ballastsecurity.net\"\n		date = \"2014-08-09\"\n		description = \"Identify Alina\"\n	strings:\n		$s1 = \"Alina v1.0\"\n		$s2 = \"POST\"\n		$s3 = \"1[0-2])[0-9]\"\n\n	condition:\n        	all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('andromeda', 'Identify Andromeda', 1, 'rule andromeda\n{\n    \n    meta:\n        author = \"Brian Wallace @botnet_hunter\"\n        author_email = \"bwall@ballastsecurity.net\"\n        date = \"2014-03-13\"\n        description = \"Identify Andromeda\"\n    \n    strings:\n        $config = {1c 1c 1d 03 49 47 46}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Worm_Gamarue', 'Gamarue_Andromeda', 1, 'rule Worm_Gamarue \n{\n\n    meta:\n        author = \"Centro Criptológico Nacional (CCN)\"\n        ref = \"https:\n        description = \"Gamarue_Andromeda\"       \n\n    strings:\n        $a = { 69 E1 2A B0 2D 80 44 E3 2D 80 44 E3 2D 80 44 E3 EE 8F 1B E3 2A 80 44 E3 EE 8F 19 E3 3A 80 44 E3 2D 80 45 E3 CD 81 44 E3 0A 46 39 E3 34 80 44 E3 0A 46 29 E3 A5 80 44 E3 0A 46 2A E3 5C 80 44 E3 0A 46 36 E3 2C 80 44 E3 0A 46 3C E3 2C 80 44 E3 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('andromeda_bot', 'IOC looks for the creation or termination of a process associated with the Andromeda Trojan. The malware will execute the msiexec.exe within the suspicious directory. Shortly after, it creates and injects itself into the wuauctl.exe (windows update) process. It then attempts to beacon to its C2.', 1, 'rule andromeda_bot\n{ \n    meta:\n        maltype = \"Andromeda bot\"\n        author = \"https:\n        description = \"IOC looks for the creation or termination of a process associated with the Andromeda Trojan. The malware will execute the msiexec.exe within the suspicious directory. Shortly after, it creates and injects itself into the wuauctl.exe (windows update) process. It then attempts to beacon to its C2.\"\n   \n    strings:\n        $type=\"Microsoft-Windows-Security-Auditing\"\n        $eventid=\"4688\"\n        $data=\"AppData\\\\Local\\\\Temp\\\\_.net_\\\\msiexec.exe\"\n\n    condition:\n        all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Arkei', '', 1, 'rule Arkei : Arkei \n{\n    meta:\n        Author = \"Fumik0_\" \n        Description = \"Arkei Stealer\"\n        Date = \"2018/07/10\"\n        Hash = \"5632c89fe4c7c2c87b69d787bbf0a5b4cc535f1aa02699792888c60e0ef88fc5\"\n\n    strings:\n        $s1 = \"Arkei\" wide ascii\n        $s2 = \"/server/gate\" wide ascii\n        $s3 = \"/server/grubConfig\" wide ascii\n        $s4 = \"\\\\files\\\\\" wide ascii\n        $s5 = \"SQLite\" wide ascii\n\n    condition:\n        all of ($s*)	\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('AthenaHTTP', 'Identify Athena HTTP', 1, 'rule AthenaHTTP\n{\n    \n    meta:\n        author = \"Brian Wallace @botnet_hunter\"\n        author_email = \"bwall@ballastsecurity.net\"\n        date = \"2014-08-09\"\n        description = \"Identify Athena HTTP\"\n    \n    strings:\n        $s1 = \"%s(%s)\"\n        $s2 = \"type:on_exec\"\n        $s3 = \"uid:%s\"\n        $s4 = \"priv:%s\"\n        $s5 = \"arch:x%s\"\n        $s6 = \"gend:%s\"\n        $s7 = \"cores:%i\"\n        $s8 = \"ver:%s\"\n        $s9 = \"net:%s\"\n    \n    condition:\n        all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('AthenaHTTP_v2', 'Athena HTTP identification', 1, 'rule AthenaHTTP_v2 \n{\n    \n    meta:\n        author = \"Jason Jones <jasonjones@arbor.net>\"\n        description = \"Athena HTTP identification\"\n        source = \"https:\n\n    strings:\n        $fmt_str1=\"|type:on_exec|uid:%s|priv:%s|arch:x%s|gend:%s|cores:%i|os:%s|ver:%s|net:%s|\"\n        $fmt_str2=\"|type:repeat|uid:%s|ram:%ld|bk_killed:%i|bk_files:%i|bk_keys:%i|busy:%s|\"\n        $cmd1 = \"filesearch.stop\"\n        $cmd2 = \"rapidget\"\n        $cmd3 = \"layer4.\"\n        $cmd4 = \"slowloris\"\n        $cmd5 = \"rudy\"\n   \n    condition:\n        all of ($fmt_str*) and 3 of ($cmd*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('AthenaIRC', 'Athena IRC v1.8.x, 2.x identification', 1, 'rule AthenaIRC \n{\n\n    meta:\n        author = \"Jason Jones <jasonjones@arbor.net>\"\n        description = \"Athena IRC v1.8.x, 2.x identification\"\n        source = \"https:\n\n    strings:\n        $cmd1 = \"ddos.\" fullword\n        $cmd2 = \"layer4.\" fullword\n        $cmd3 = \"war.\" fullword\n        $cmd4 = \"smartview\" fullword\n        $cmd5 = \"ftp.upload\" fullword\n        $msg1 = \"%s %s :%s LAYER4 Combo Flood: Stopped\"\n        $msg2 = \"%s %s :%s IRC War: Flood started [Type: %s | Target: %s]\"\n        $msg3 = \"%s %s :%s FTP Upload: Failed\"\n        $msg4 = \"Athena v2\"\n        $msg5 = \"%s %s :%s ECF Flood: Stopped [Total Connections: %ld | Rate: %ld Connections/Second]\"\n        \n        $amsg1 = \"ARME flood on %s/%s:%i for %i seconds [Host confirmed vulnerable\"\n        $amsg2 = \" Rapid HTTP Combo flood on %s:%i for %i seconds\"\n        $amsg3 = \"Began flood: %i connections every %i ms to %s:%i\"\n        $amsg4 = \"IPKiller>Athena\"\n        $amsg5 = \"Athena=Shit!\"\n        $amsg6 = \"Athena-v1\"\n        $amsg7 = \"BTC wallet.dat file found\"\n        $amsg8 = \"MineCraft lastlogin file found\"\n        $amsg9 = \"Process ''%s'' was found and scheduled for deletion upon next reboot\"\n        $amsg10 = \"User-Agent: Mozilla/4.0 (compatible; MSIE 7.0; Windows NT 5.1; Trident/4.0; .NET CLR 1.1.4322; .NET CLR 2.0.503l3; .NET CLR 3.0.4506.2152; .NET CLR 3.5.30729; MSOffice 12)\"\n        \n        $amsg11 = \"Rapid Connect/Disconnect\"\n        $amsg12 = \"BTC wallet.dat found,\"\n        \n        $acmd1 = \":!arme\"\n        $acmd2 = \":!openurl\"\n        $acmd3 = \":!condis\"\n        $acmd4 = \":!httpcombo\"\n        $acmd5 = \":!urlblock\"\n        $acmd6 = \":!udp\"\n        $acmd7 = \":!btcwallet\"\n   \n    condition:\n        (all of ($cmd*) and 3 of ($msg*)) or (5 of ($amsg*) and 5 of ($acmd*))\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Atmos_Malware', 'Generic Spyware.Citadel.Atmos Signature', 1, 'rule Atmos_Malware\r\n{\r\n    \r\n    meta:\r\n        description = \"Generic Spyware.Citadel.Atmos Signature\"\r\n        author = \"xylitol@temari.fr\"\r\n        reference = \"http:\n        date = \"20/08/2016\"\r\n        \n\r\n    strings:\r\n        \n        $MZ = {4D 5A}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Atmos_Packed_Malware', 'Second Generic Spyware.Citadel.Atmos signture when builder add a packed layer', 1, 'rule Atmos_Packed_Malware \r\n{\r\n   \r\n    meta:\r\n    description = \"Second Generic Spyware.Citadel.Atmos signture when builder add a packed layer\"\r\n    author = \"xylitol@temari.fr\"\r\n    reference = \"http:\n    date = \"20/08/2016\"\r\n    \n\r\n    strings:\r\n        $MZ = {4D 5A}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Atmos_Builder', 'Generic signature for Hacktool.Atmos.Builder cracked version', 1, 'rule Atmos_Builder\r\n{\r\n    \r\n    meta:\r\n        description = \"Generic signature for Hacktool.Atmos.Builder cracked version\"\r\n        author = \"xylitol@temari.fr\"\r\n        reference = \"http:\n        date = \"20/08/2016\"\r\n        \n\r\n    strings:\r\n        \n        $MZ = {4D 5A}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('custom_ssh_backdoor_server', 'Custome SSH backdoor based on python and paramiko - file server.py', 1, 'rule custom_ssh_backdoor_server\n{\n\n    meta:\n        description = \"Custome SSH backdoor based on python and paramiko - file server.py\"\n        author = \"Florian Roth\"\n        reference = \"https:\n        date = \"2015-05-14\"\n        hash = \"0953b6c2181249b94282ca5736471f85d80d41c9\"\n\n    strings:\n        $s0 = \"command= raw_input(\\\"Enter command: \\\").strip(''n'')\" fullword ascii\n        $s1 = \"print ''[-] (Failed to load moduli -- gex will be unsupported.)''\" fullword ascii\n        $s2 = \"print ''[-] Listen/bind/accept failed: '' + str(e)\" fullword ascii\n        $s3 = \"chan.send(command)\" fullword ascii\n        $s4 = \"print ''[-] SSH negotiation failed.''\" fullword ascii\n        $s5 = \"except paramiko.SSHException, x:\" fullword ascii\n\n    condition:\n        filesize < 10KB and 5 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('backoff', 'Identify Backoff', 1, 'rule backoff \n{\n\n    meta:\n        author = \"Brian Wallace @botnet_hunter\"\n        author_email = \"bwall@ballastsecurity.net\"\n        date = \"2014-08-21\"\n        description = \"Identify Backoff\"\n\n    strings:\n        $s1 = \"&op=%d&id=%s&ui=%s&wv=%d&gr=%s&bv=%s\"\n        $s2 = \"%s @ %s\"\n        $s3 = \"Upload KeyLogs\"\n\n    condition:\n        all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('BangatCode', 'Bangat code features', 1, 'rule BangatCode\n{\n    \n    meta:\n        description = \"Bangat code features\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-07-10\"\n    \n    strings:\n        \n        $ = { FE 4D ?? 8D 4? ?? 50 5? FF }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('BangatStrings', 'Bangat Identifying Strings', 1, 'rule BangatStrings\n{\n    \n    meta:\n        description = \"Bangat Identifying Strings\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-07-10\"\n        \n    strings:\n        $lib1 = \"DreatePipe\"\n        $lib2 = \"HetSystemDirectoryA\"\n        $lib3 = \"SeleaseMutex\"\n        $lib4 = \"DloseWindowStation\"\n        $lib5 = \"DontrolService\"\n        $file = \"~hhC2F~.tmp\"\n        $mc = \"~_MC_3~\"\n\n    condition:\n       all of ($lib*) or $file or $mc\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Bangat', 'Bangat', 1, 'rule Bangat\n{\n    meta:\n        description = \"Bangat\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-07-10\"\n        \n    condition:\n        BangatCode or BangatStrings\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Batel_export_function', 'Batel backdoor', 1, 'rule Batel_export_function\n{\n\n    meta:\n        author = \"@j0sm1\"\n        date = \"2016/10/15\"\n        description = \"Batel backdoor\"\n        reference = \"https:\n        filetype = \"binary\"\n\n    condition:\n        pe.exports(\"run_shell\") and pe.imports(\"kernel32.dll\",\"GetTickCount\") and pe.imports(\"kernel32.dll\",\"IsDebuggerPresent\") and pe.imports(\"msvcr100.dll\",\"_crt_debugger_hook\") and pe.imports(\"kernel32.dll\",\"TerminateProcess\") and pe.imports(\"kernel32.dll\",\"UnhandledExceptionFilter\")\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('BlackRev', 'Black Revolution DDoS Malware. http:\n      origin = ', 1, 'rule BlackRev\n{\n   meta:\n      author = \"Dennis Schwarz\"\n      date = \"2013-05-21\"\n      description = \"Black Revolution DDoS Malware. http:\n      origin = \"https:\n\n   strings: \n      $base1 = \"http\"\n      $base2 = \"simple\"\n      $base3 = \"loginpost\"\n      $base4 = \"datapost\"\n\n      $opt1 = \"blackrev\"\n      $opt2 = \"stop\"\n      $opt3 = \"die\"\n      $opt4 = \"sleep\"\n      $opt5 = \"syn\"\n      $opt6 = \"udp\"\n      $opt7 = \"udpdata\"\n      $opt8 = \"icmp\"\n      $opt9 = \"antiddos\"\n      $opt10 = \"range\"\n      $opt11 = \"fastddos\"\n      $opt12 = \"slowhttp\"\n      $opt13 = \"allhttp\"\n      $opt14 = \"tcpdata\"\n      $opt15 = \"dataget\"\n\n   condition:\n      all of ($base*) and 5 of ($opt*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('BlackWorm', 'Identify BlackWorm', 1, 'rule BlackWorm\n{\n\n    meta:\n        author = \"Brian Wallace @botnet_hunter\"\n        author_email = \"bwall@ballastsecurity.net\"\n        date = \"2015-05-20\"\n        description = \"Identify BlackWorm\"\n\n    strings:\n        $str1 = \"m_ComputerObjectProvider\"\n        $str2 = \"MyWebServices\"\n        $str3 = \"get_ExecutablePath\"\n        $str4 = \"get_WebServices\"\n        $str5 = \"My.WebServices\"\n        $str6 = \"My.User\"\n        $str7 = \"m_UserObjectProvider\"\n        $str8 = \"DelegateCallback\"\n        $str9 = \"TargetMethod\"\n        $str10 = \"000004b0\" wide\n        $str11 = \"Microsoft Corporation\" wide\n\n    condition:\n        all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('BoousetCode', 'Boouset code tricks', 1, 'rule BoousetCode\n{\n    \n    meta:\n        description = \"Boouset code tricks\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-06-19\"\n        \n    strings:\n        $boousetdat = { C6 ?? ?? ?? ?? 00 62 C6 ?? ?? ?? ?? 00 6F C6 ?? ?? ?? ?? 00 6F C6 ?? ?? ?? ?? 00 75 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Bublik', 'Bublik Trojan Downloader', 1, 'rule Bublik\n{\n   \n    meta:\n        author=\"Kevin Falcoz\"\n        date=\"29/09/2013\"\n        description=\"Bublik Trojan Downloader\"\n        \n    strings:\n        $signature1={63 6F 6E 73 6F 6C 61 73}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Win32_Buzus_Softpulse', 'Trojan Buzus / Softpulse', 1, 'rule Win32_Buzus_Softpulse\n{\n\n    meta:\n        description = \"Trojan Buzus / Softpulse\"\n        author = \"Florian Roth\"\n        date = \"2015-05-13\"\n        hash = \"2f6df200e63a86768471399a74180466d2e99ea9\"\n        score = 75\n\n    strings:\n        $x1 = \"pi4izd6vp0.com\" fullword ascii\n        $s1 = \"SELECT * FROM Win32_Process\" fullword wide\n        $s4 = \"CurrentVersion\\\\Uninstall\\\\avast\" fullword wide\n        $s5 = \"Find_RepeatProcess\" fullword ascii\n        $s6 = \"SOFTWARE\\\\Microsoft\\\\Windows\\\\CurrentVersion\\\\\" fullword wide\n        $s7 = \"myapp.exe\" fullword ascii\n        $s14 = \"/c ping -n 1 www.google\" wide\n    \n    condition:\n        uint16(0) == 0x5a4d and ( ( $x1 and 2 of ($s*) ) or all of ($s*) )\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('CAP_HookExKeylogger', '', 1, 'rule CAP_HookExKeylogger\n{\n\nmeta:\n    author = \"Brian C. Bell -- @biebsmalwareguy\"\n    reference = \"https:\n\n    strings:\n    $str_Win32hookapi = \"SetWindowsHookEx\" nocase\n    $str_Win32llkey = \"WH_KEYBOARD_LL\" nocase\n    $str_Win32key = \"WH_KEYBOARD\" nocase\n\n    condition:\n        2 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('ChickenDOS', 'Win32-variant of Chicken ident for both dropper and dropped file', 1, 'rule ChickenDOS\n{\n\n    meta:\n        author = \"Jason Jones <jasonjones@arbor.net>\"\n        description = \"Win32-variant of Chicken ident for both dropper and dropped file\"\n        source = \"https:\n\n    strings:\n        $pdb1 = \"\\\\Chicken\\\\Release\\\\svchost.pdb\"\n        $pdb2 = \"\\\\IntergrateCHK\\\\Release\\\\IntergrateCHK.pdb\"\n        $str2 = \"fake.cf\"\n        $str3 = \"8.8.8.8\"\n        $str4 = \"Processor(%d)\\\\\"\n        $str5 = \"DbProtectSupport\"\n        $str1 = \"dm1712/`jvpnpkte/bpl\"\n        $str6 = \"InstallService NPF %d\"\n        $str7 = \"68961\"\n        $str8 = \"InstallService DbProtectSupport %d\"\n        $str9 = \"C:\\\\Program Files\\\\DbProtectSupport\\\\npf.sys\"\n   \n    condition:\n        ($pdb1 or $pdb2) and 5 of ($str*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('ChickenDOS_Linux', 'Linux-variant of Chicken ident for both dropper and dropped file', 1, 'rule ChickenDOS_Linux \n{\n \n    meta:\n        author = \"Jason Jones <jasonjones@arbor.net>\"\n        description = \"Linux-variant of Chicken ident for both dropper and dropped file\"\n        source = \"https:\n    \n    strings:\n        $cfg = \"fake.cfg\"\n        $file1 = \"ThreadAttack.cpp\"\n        $file2 = \"Fake.cpp\"\n        $str1 = \"dns_array\"\n        $str2 = \"DomainRandEx\"\n        $str3 = \"cpu %llu %llu %llu %llu\"\n        $str4 = \"[ %02d.%02d %02d:%02d:%02d.%03ld ] [%lu] [%s] %s\" ascii\n    \n    condition:\n        $cfg and all of ($file*) and 3 of ($str*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('citadel13xy', 'Citadel 1.5.x.y trojan banker', 1, 'rule citadel13xy\n{\n    \n    meta:\n        author = \"Jean-Philippe Teissier / @Jipe_\"\n        description = \"Citadel 1.5.x.y trojan banker\"\n        date = \"2013-01-12\" \n        version = \"1.0\" \n        filetype = \"memory\"\n   \n    strings:\n        $a = \"Coded by BRIAN KREBS for personnal use only. I love my job & wife.\"\n        $b = \"http:\n        $c = \"%BOTID%\"\n        $d = \"%BOTNET%\"\n        $e = \"cit_video.module\"\n        $f = \"bc_remove\"\n        $g = \"bc_add\"\n        $ggurl = \"http:\n\n    condition:\n        3 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Citadel_Malware', 'Search for nss3.dll pattern indicating an hexed copy of Citadel malware to work on firefox > v23.0', 1, 'rule Citadel_Malware\n{\n    \n    meta:\n        author = \"xylitol@temari.fr\"\n        date = \"2015-10-08\" \n        description = \"Search for nss3.dll pattern indicating an hexed copy of Citadel malware to work on firefox > v23.0\"\n        \n        \n    strings:\n        $s1 = \"Coded by BRIAN KREBS for personal use only. I love my job & wife\" wide ascii\n        $s2 = \"nss3.dll\" wide ascii\n\n        $h1 = {8B C7 EB F5 55 8B EC}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Binary_Drop_Certutil', 'Drop binary as base64 encoded cert trick', 1, 'rule Binary_Drop_Certutil\n{\n\n    meta:\n        description = \"Drop binary as base64 encoded cert trick\"\n        author = \"Florian Roth\"\n        reference = \"https:\n        date = \"2015-07-15\"\n        score = 70\n\n    strings:\n        $s0 = \"echo -----BEGIN CERTIFICATE----- >\" ascii\n        $s1 = \"echo -----END CERTIFICATE----- >>\" ascii\n        $s2 = \"certutil -decode \" ascii\n  \n    condition:\n        filesize < 10KB and all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('StegoKatz', 'Encoded Mimikatz in other file types', 1, 'rule StegoKatz \n{\n\n    meta:\n        description = \"Encoded Mimikatz in other file types\"\n        author = \"Florian Roth\"\n        reference = \"https:\n        date = \"2015-09-11\"\n        score = 70\n\n    strings:\n        $s1 = \"VC92Ny9TSXZMNk5jLy8vOUlqUTFVRlFNQTZMLysvdjlJaTh2L0ZUNXJBUUJJaTFRa1NFaUx6K2hWSS8vL1NJME44bklCQU9pZC92Ny9USTJjSkpBQUFBQXp3RW1MV3hCSmkyc1lTWXR6S0VtTDQxL0R6TXhNaTl4SmlWc0lUWWxMSUUySlF4aFZWbGRCVkVGVlFWWkJWMGlCN1BBQUFBQklnMlFrYUFDNE1BQUFBRW1MNkVTTmNPQ0pSQ1JnaVVRa1pFbU5RN0JKaTlsTWpRWFBGQU1BU0ls\" ascii\n        $s2 = \"Rpd3ovN3FlalVtNklLQ0xNNGtOV1BiY0VOVHROT0Zud25CWGN0WS9BcEdMR28rK01OWm85Nm9xMlNnY1U5aTgrSTBvNkFob1FOTzRHQWdtUElEVmlqald0Tk90b2FmN01ESWJUQkF5T0pYbTB4bFVHRTBZWEFWOXVoNHBkQnRrS0VFWWVBSEE2TDFzU0c5a2ZFTEc3QWd4WTBYY1l3ZzB6QUFXS09JZE9wQVhEK3lnS3lsR3B5Q1ljR1NJdFNseGZKWUlVVkNFdEZPVjRJUldERUl1QXpKZ2pCQWdsd0Va\" ascii\n   \n    condition:\n        filesize < 1000KB and 1 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('CookiesStrings', 'Cookies Identifying Strings', 1, 'rule CookiesStrings\n{\n    meta:\n        description = \"Cookies Identifying Strings\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-06-20\"\n        \n    strings:\n        $zip1 = \"ntdll.exePK\"\n        $zip2 = \"AcroRd32.exePK\"\n        $zip3 = \"Setup=ntdll.exe\\x0d\\x0aSilent=1\\x0d\\x0a\"\n        $zip4 = \"Setup=%temp%\\\\AcroRd32.exe\\x0d\\x0a\"\n        $exe1 = \"Leave GetCommand!\"\n        $exe2 = \"perform exe success!\"\n        $exe3 = \"perform exe failure!\"\n        $exe4 = \"Entry SendCommandReq!\"\n        $exe5 = \"Reqfile not exist!\"\n        $exe6 = \"LeaveDealUpfile!\"\n        $exe7 = \"Entry PostData!\"\n        $exe8 = \"Leave PostFile!\"\n        $exe9 = \"Entry PostFile!\"\n        $exe10 = \"\\\\unknow.zip\" wide ascii\n        $exe11 = \"the url no respon!\"\n        \n    condition:\n      (2 of ($zip*)) or (2 of ($exe*))\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Cookies', 'Cookies', 1, 'rule Cookies\n{\n    meta:\n        description = \"Cookies\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-06-20\"\n        \n    condition:\n        CookiesStrings\n}', 2, '恶意软件', 1);
