INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('cxpidStrings', 'cxpid Identifying Strings', 1, 'rule cxpidStrings\n{\n    meta:\n        description = \"cxpid Identifying Strings\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-06-23\"\n        \n    strings:\n        $ = \"/cxpid/submit.php?SessionID=\"\n        $ = \"/cxgid/\"\n        $ = \"E21BC52BEA2FEF26D005CF\"\n        $ = \"E21BC52BEA39E435C40CD8\"\n        $ = \"                   -,L-,O+,Q-,R-,Y-,S-\"\n        \n    condition:\n       any of them\n}', 2, '恶意软件', 1);
