INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Cythosia', 'Identify Cythosia', 1, 'rule Cythosia\n{\n\n    meta:\n        author = \"Brian Wallace @botnet_hunter\"\n        author_email = \"bwall@ballastsecurity.net\"\n        date = \"2015-03-21\"\n        description = \"Identify Cythosia\"\n\n    strings:\n        $str1 = \"HarvesterSocksBot.Properties.Resources\" wide\n\n    condition:\n        all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('DDosTf', 'Rule to detect ELF.DDosTf infection', 1, 'rule DDosTf\n{\n\nmeta:\n    author = \"benkow_ - MalwareMustDie\"\n    reference = \"http:\n    description = \"Rule to detect ELF.DDosTf infection\"\n\nstrings:\n    $st0 = \"ddos.tf\"\n    $st1 = {E8 AE BE E7 BD AE 54 43  50 5F 4B 45 45 50 49 4E 54 56 4C E9 94 99 E8 AF AF EF BC 9A 00}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Derkziel', 'Derkziel info stealer (Steam, Opera, Yandex, ...)', 1, 'rule Derkziel\n{\n    \n    meta:\n        description = \"Derkziel info stealer (Steam, Opera, Yandex, ...)\"\n        author = \"The Malware Hunter\"\n        filetype = \"pe\"\n        date = \"2015-11\"\n        md5 = \"f5956953b7a4acab2e6fa478c0015972\"\n        site = \"https:\n        reference = \"https:\n    \n    strings:\n        $drz = \"{!}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Dexter_Malware', 'Detects the Dexter Trojan/Agent http:\n        author = ', 1, 'rule Dexter_Malware \n{\n\n    meta:\n        description = \"Detects the Dexter Trojan/Agent http:\n        author = \"Florian Roth\"\n        reference = \"http:\n        date = \"2015/02/10\"\n        score = 70\n\n    strings:\n        $s0 = \"Java Security Plugin\" fullword wide\n        $s1 = \"%s\\\\%s\\\\%s.exe\" fullword wide\n        $s2 = \"Sun Java Security Plugin\" fullword wide\n        $s3 = \"\\\\Internet Explorer\\\\iexplore.exe\" fullword wide\n\n    condition:\n        all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('dexter_strings', 'Identify Dexter POSGrabber', 1, 'rule dexter_strings\n{\n   \n    meta:\n        author = \"Brian Wallace @botnet_hunter\"\n        author_email = \"bwall@ballastsecurity.net\"\n        date = \"2014-09-10\"\n        description = \"Identify Dexter POSGrabber\"\n   \n    strings:\n        $s1 = \"UpdateMutex:\"\n        $s2 = \"response=\"\n        $s3 = \"page=\"\n        $s4 = \"scanin:\"\n   \n    condition:\n        all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('diamond_fox', 'Identify DiamondFox', 1, 'rule diamond_fox\n{\n   \n    meta:\n        author = \"Brian Wallace @botnet_hunter\"\n        author_email = \"bwall@ballastsecurity.net\"\n        date = \"2015-08-22\"\n        description = \"Identify DiamondFox\"\n   \n    strings:\n        $s1 = \"UPDATE_B\"\n        $s2 = \"UNISTALL_B\"\n        $s3 = \"S_PROTECT\"\n        $s4 = \"P_WALLET\"\n        $s5 = \"GR_COMMAND\"\n        $s6 = \"FTPUPLOAD\"\n   \n    condition:\n        all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('DirtJumper_drive', 'Identify first version of drive DDoS malware', 1, 'rule DirtJumper_drive\n{\n   \n    meta:\n        author = \"Jason Jones <jasonjones@arbor.net>\"\n        date = \"2013-08-26\"\n        description = \"Identify first version of drive DDoS malware\"\n        source = \"https:\n   \n    strings:\n        $cmd1 = \"-get\" fullword\n        $cmd2 = \"-ip\" fullword\n        $cmd3 = \"-ip2\" fullword\n        $cmd4 = \"-post1\" fullword\n        $cmd5 = \"-post2\" fullword\n        $cmd6 = \"-udp\" fullword\n        $str1 = \"login=[1000]&pass=[1000]&password=[50]&log=[50]&passwrd=[50]&user=[50]&username=[50]&vb_login_username=[50]&vb_login_md5password=[50]\"\n        $str2 = \"-timeout\" fullword\n        $str3 = \"-thread\" fullword\n        $str4 = \" Local; ru) Presto/2.10.289 Version/\"\n        $str5 = \"Mozilla/4.0 (compatible; MSIE 8.0; Windows NT\"\n        $newver1 = \"-icmp\"\n        $newver2 = \"<xmp>\"\n   \n    condition:\n        4 of ($cmd*) and all of ($str*) and not any of ($newver*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('DirtJumper_drive2', 'Identify newer version of drive DDoS malware', 1, 'rule DirtJumper_drive2\n{\n   \n    meta:\n        author = \"Jason Jones <jasonjones@arbor.net>\"\n        date = \"2013-08-26\"\n        description = \"Identify newer version of drive DDoS malware\"\n        source = \"https:\n   \n    strings:\n        $cmd1 = \"-get\" fullword\n        $cmd2 = \"-ip\" fullword\n        $cmd3 = \"-ip2\" fullword\n        $cmd4 = \"-post1\" fullword\n        $cmd5 = \"-post2\" fullword\n        $cmd6 = \"-udp\" fullword\n        $str1 = \"login=[1000]&pass=[1000]&password=[50]&log=[50]&passwrd=[50]&user=[50]&username=[50]&vb_login_username=[50]&vb_login_md5password=[50]\"\n        $str2 = \"-timeout\" fullword\n        $str3 = \"-thread\" fullword\n        $str4 = \" Local; ru) Presto/2.10.289 Version/\"\n        $str5 = \"Mozilla/4.0 (compatible; MSIE 8.0; Windows NT\"\n        $newver1 = \"-icmp\"\n        $newver2 = \"-byte\"\n        $newver3 = \"-long\"\n        $newver4 = \"<xmp>\"\n  \n    condition:\n        4 of ($cmd*) and all of ($str*) and all of ($newver*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('DirtJumper_drive3', 'Identify version of Drive DDoS malware using compromised sites', 1, 'rule DirtJumper_drive3\n{\n  \n    meta:\n        author = \"Jason Jones <jasonjones@arbor.net>\"\n        date = \"2014-03-17\"\n        description = \"Identify version of Drive DDoS malware using compromised sites\"\n        source = \"https:\n  \n    strings:\n        $cmd1 = \"-get\" fullword\n        $cmd2 = \"-ip\" fullword\n        $cmd3 = \"-ip2\" fullword\n        $cmd4 = \"-post1\" fullword\n        $cmd5 = \"-post2\" fullword\n        $cmd6 = \"-udp\" fullword\n        $str1 = \"login=[1000]&pass=[1000]&password=[50]&log=[50]&passwrd=[50]&user=[50]&username=[50]&vb_login_username=[50]&vb_login_md5password=[50]\"\n        $str2 = \"-timeout\" fullword\n        $str3 = \"-thread\" fullword\n        $str4 = \" Local; ru) Presto/2.10.289 Version/\"\n        $str5 = \"Mozilla/4.0 (compatible; MSIE 8.0; Windows NT\"\n        $newver1 = \"-icmp\"\n        $newver2 = \"-byte\"\n        $newver3 = \"-long\"\n        $drive3 = \"99=1\"\n  \n    condition:\n        4 of ($cmd*) and all of ($str*) and all of ($newver*) and $drive3\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('eicar', 'Rule to detect Eicar pattern', 1, 'rule eicar \n{\n	meta:\n		description = \"Rule to detect Eicar pattern\"\n		author = \"Marc Rivero | @seifreed\"\n		hash1 = \"275a021bbfb6489e54d471899f7db9d1663fc695ec2fe2a2c4538aabf651fd0f\"\n\n	strings:\n		$s1 = \"X5O!P%@AP[4\\\\PZX54(P^)7CC)7}', 2, '恶意软件', 1);
