INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('elknot_xor', 'elknot/Billgates variants with XOR like C2 encryption scheme', 1, 'rule elknot_xor : malware \n{\nmeta:\n    author = \"liuya@360.cn\"\n    date = \"2016-04-25\"\n    description = \"elknot/Billgates variants with XOR like C2 encryption scheme\"\n    reference = \"http:\n    sample = \"474429d9da170e733213940acc9a2b1c, 2579aa65a28c32778790ec1c673abc49\"\n\nstrings:\n   \n   \n    $decrypt_c2_func_1 = {08 83 [5] 02 75 07 81 04 24 00 01 00 00 50 e8 [4] e9}', 2, '恶意软件', 1);
