INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Gafgyt_Botnet_generic', 'Gafgyt Trojan', 1, 'rule Gafgyt_Botnet_generic : MALW\n{\nmeta:\ndescription = \"Gafgyt Trojan\"\nauthor = \"Joan Soriano / @joanbtl\"\ndate = \"2017-05-01\"\nversion = \"1.0\"\nMD5 = \"e3fac853203c3f1692af0101eaad87f1\"\nSHA1 = \"710781e62d49419a3a73624f4a914b2ad1684c6a\"\n\nstrings:\n	$etcTZ = \"/bin/busybox;echo -e ''gayfgt''\"\n	$s2 = \"/proc/net/route\"\n	$s3 = \"admin\"\n	$s4 = \"root\"\n\ncondition:\n	$etcTZ and $s2 and $s3 and $s4\n}', 2, '恶意软件', 1);
