INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Grozlex', 'Grozlex Stealer - Possible HCStealer', 1, 'rule Grozlex : Stealer\n{\n	meta:\n		author=\"Kevin Falcoz\"\n		date=\"20/08/2013\"\n		description=\"Grozlex Stealer - Possible HCStealer\"\n		\n	strings:\n		$signature={4C 00 6F 00 67 00 73 00 20 00 61 00 74 00 74 00 61 00 63 00 68 00 65 00 64 00 20 00 62 00 79 00 20 00 69 00 43 00 6F 00 7A 00 65 00 6E}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Hajime_generic_ARCH', 'Hajime Botnet - generic arch', 1, 'rule Hajime_generic_ARCH : MALW\n{\nmeta:\ndescription = \"Hajime Botnet - generic arch\"\nauthor = \"Joan Soriano / @joanbtl\"\ndate = \"2017-05-01\"\nversion = \"1.0\"\nMD5 = \"77122e0e6fcf18df9572d80c4eedd88d\"\nSHA1 = \"108ee460d4c11ea373b7bba92086dd8023c0654f\"\nref1 = \"https:\nref2 = \"https:\n\nstrings:\n	$userpass = \"%d (!=0),user/pass auth will not work, ignored.\\n\"\n	$etcTZ = \"/etc/TZ\"\n	$Mvrs = \",M4.1.0,M10.5.0\"\n	$bld = \"%u.%u.%u.%u.in-addr.arpa\"\n\ncondition:\n	$userpass and $etcTZ and $Mvrs and $bld\n\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Hajime_MIPS', 'Hajime Botnet - MIPS', 1, 'rule Hajime_MIPS : MALW\n{\nmeta:\ndescription = \"Hajime Botnet - MIPS\"\nauthor = \"Joan Soriano / @joanbtl\"\ndate = \"2017-05-01\"\nversion = \"1.0\"\nMD5 = \"77122e0e6fcf18df9572d80c4eedd88d\"\nSHA1 = \"108ee460d4c11ea373b7bba92086dd8023c0654f\"\nref1 = \"https:\nref2 = \"https:\n\nstrings:\n	$userpass = \"%d (!=0),user/pass auth will not work, ignored.\\n\"\n	$etcTZ = \"/etc/TZ\"\n	$Mvrs = \",M4.1.0,M10.5.0\"\n	$bld = \"%u.%u.%u.%u.in-addr.arpa\"\n\ncondition:\n	$userpass and $etcTZ and $Mvrs and $bld and hash.sha1(0,filesize) == \"108ee460d4c11ea373b7bba92086dd8023c0654f\"\n\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Hajime_ARM5', 'Hajime Botnet - ARM5', 1, 'rule Hajime_ARM5 : MALW\n{\nmeta:\ndescription = \"Hajime Botnet - ARM5\"\nauthor = \"Joan Soriano / @joanbtl\"\ndate = \"2017-05-01\"\nversion = \"1.0\"\nMD5 = \"d8821a03b9dc484144285d9051e0b2d3\"\nSHA1 = \"89ec638b95b289dbce0535b4a2c5aad90c169d06\"\nref1 = \"https:\nref2 = \"https:\n\nstrings:\n	$userpass = \"%d (!=0),user/pass auth will not work, ignored.\\n\"\n	$etcTZ = \"/etc/TZ\"\n	$Mvrs = \",M4.1.0,M10.5.0\"\n	$bld = \"%u.%u.%u.%u.in-addr.arpa\"\n\ncondition:\n	$userpass and $etcTZ and $Mvrs and $bld and hash.sha1(0,filesize) == \"89ec638b95b289dbce0535b4a2c5aad90c169d06\"\n\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Hajime_SH4', 'Hajime Botnet - SH4', 1, 'rule Hajime_SH4 : MALW\n{\nmeta:\ndescription = \"Hajime Botnet - SH4\"\nauthor = \"Joan Soriano / @joanbtl\"\ndate = \"2017-05-01\"\nversion = \"1.0\"\nMD5 = \"6f39d7311091166a285fb0654b454761\"\nSHA1 = \"3ed95ead04e59a2833538541978b79a9a8cb5290\"\nref1 = \"https:\nref2 = \"https:\n\nstrings:\n	$userpass = \"%d (!=0),user/pass auth will not work, ignored.\\n\"\n	$etcTZ = \"/etc/TZ\"\n	$Mvrs = \",M4.1.0,M10.5.0\"\n	$bld = \"%u.%u.%u.%u.in-addr.arpa\"\n\ncondition:\n	$userpass and $etcTZ and $Mvrs and $bld and hash.sha1(0,filesize) == \"3ed95ead04e59a2833538541978b79a9a8cb5290\"\n\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Hajime_DOWNLOADER', 'Hajime Botnet - Downloader', 1, 'rule Hajime_DOWNLOADER : MALW\n{\nmeta:\ndescription = \"Hajime Botnet - Downloader\"\nauthor = \"Joan Soriano / @joanbtl\"\ndate = \"2017-05-01\"\nversion = \"1.0\"\nMD5 = \"f1cc4275d29b7eaa92a4cca015af227e\"\nSHA1 = \"e649e0d97cc23c8c4bbd78be430a49a4babbccd7\"\nref1 = \"https:\nref2 = \"https:\n\nstrings:\n	$get = \"GET /r/sr.arm5 HTTP/1.0\"\n	$nif = \"NIF\\n\"\n\n\ncondition:\n	$get and $nif and filesize < 700KB and hash.sha1(0,filesize) == \"e649e0d97cc23c8c4bbd78be430a49a4babbccd7\"\n\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('is__LinuxHttpsdStrings', 'Strings of ELF Linux/Httpsd (backdoor, downloader, remote command execution)', 1, 'private rule is__LinuxHttpsdStrings {\n\n    meta:\n	description = \"Strings of ELF Linux/Httpsd (backdoor, downloader, remote command execution)\"\n	ref1 = \"https:\n	ref2 = \"https:\n	ref3 = \"https:\n	author = \"unixfreaxjp\"\n	org = \"MalwareMustDie\"\n	date = \"2018-01-02\"\n	sha256 = \"dd1266561fe7fcd54d1eb17efbbb6babaa9c1f44b36cef6e06052e22ce275ccd\"\n	sha256 = \"1b3718698fae20b63fbe6ab32411a02b0b08625f95014e03301b49afaee9d559\"\n		\n	strings:\n		$st01 = \"k.conectionapis.com\" fullword nocase wide ascii\n		$st02 = \"key=%s&host_name=%s&cpu_count=%d&os_type=%s&core_count=%s\" fullword nocase wide ascii\n		$st03 = \"id=%d&result=%s\" fullword nocase wide ascii\n		$st04 = \"rtime\" fullword nocase wide ascii\n		$st05 = \"down\" fullword nocase wide ascii\n		$st06 = \"cmd\" fullword nocase wide ascii\n		$st07 = \"0 */6 * * * root\" fullword nocase wide ascii\n		$st08 = \"/etc/cron.d/httpsd\" fullword nocase wide ascii\n		$st09 = \"cat /proc/cpuinfo |grep processor|wc -l\" fullword nocase wide ascii\n		$st10 = \"k.conectionapis.com\" fullword nocase wide ascii\n		$st11 = \"/api\" fullword nocase wide ascii\n		$st12 = \"/tmp/.httpslog\" fullword nocase wide ascii\n		$st13 = \"/bin/.httpsd\" fullword nocase wide ascii\n		$st14 = \"/tmp/.httpsd\" fullword nocase wide ascii\n		$st15 = \"/tmp/.httpspid\" fullword nocase wide ascii\n		$st16 = \"/tmp/.httpskey\" fullword nocase wide ascii\n\n	condition:\n		all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Linux_Httpsd_malware_ARM', 'Detects Linux/Httpsd ARMv5', 1, 'rule Linux_Httpsd_malware_ARM {\n  \n	meta:\n		description = \"Detects Linux/Httpsd ARMv5\"\n		date = \"2017-12-31\"\n\n	strings:\n		$hexsts01 = { f0 4f 2d e9 1e db 4d e2 ec d0 4d e2 01 40 a0 e1 }', 2, '恶意软件', 1);
