INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('IotReaper', 'Linux.IotReaper', 1, 'rule IotReaper: MALW\n{\n	meta:\n		description = \"Linux.IotReaper\"\n		author = \"Joan Soriano / @w0lfvan\"\n		date = \"2017-10-30\"\n		version = \"1.0\"\n		MD5 = \"95b448bdf6b6c97a33e1d1dbe41678eb\"\n		SHA256 = \"b463ca6c3ec7fa19cd318afdd2fa2365fa9e947771c21c4bd6a3bc2120ba7f28\"\n	strings:\n		$a = \"weruuoqweiur.com\"\n		$b = \"rm -f /tmp/ftpupload.sh \\n\"\n		$c = \"%02x-%02x-%02x-%02x-%02x-%02x\"\n	condition:\n		all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Backdoor_Jolob', 'the backdoor registers an auto start service with the display name \\', 1, 'rule Backdoor_Jolob\n{\n	meta:\n		maltype = \"Backdoor.Jolob\"\n    ref = \"https:\n		reference = \"http:\n		description = \"the backdoor registers an auto start service with the display name \\\"Network Access Management Agent\\\" pointing to the dll netfilter.dll. This is accomplished without notifying the user via the sysprep UAC bypass method.\"\n	strings:   \n		$type = \"Microsoft-Windows-Security-Auditing\"\n		$eventid = \"4673\"\n		$data1 = \"Security\"\n		$data2 = \"SeCreateGlobalPrivilege\"\n		$data3 = \"Windows\\\\System32\\\\sysprep\\\\sysprep.exe\" nocase\n        \n		$type1 = \"Microsoft-Windows-Security-Auditing\"\n		$eventid1 = \"4688\"\n		$data4 = \"Windows\\\\System32\\\\sysprep\\\\sysprep.exe\" nocase\n        \n		$type2 = \"Service Control Manager\"\n		$eventid2 = \"7036\"\n		$data5 = \"Network Access Management Agent\"\n		$data6 = \"running\"\n        \n		$type3 = \"Service Control Manager\"\n		$eventid3 = \"7045\"\n		$data7 = \"Network Access Management Agent\"\n		$data8 = \"user mode service\"\n		$data9 = \"auto start\"      \n    condition:\n    	all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('KINS_dropper', 'Match protocol, process injects and windows exploit present in KINS dropper', 1, 'rule KINS_dropper : dropper {\n	meta:\n		author = \"AlienVault Labs aortega@alienvault.com\"\n		description = \"Match protocol, process injects and windows exploit present in KINS dropper\"\n		reference = \"http:\n	strings:\n		\n		$n1 = \"tid=%d&ta=%s-%x\" fullword\n		$n2 = \"fid=%d\" fullword\n		$n3 = \"%[^.].%[^(](%[^)])\" fullword\n		\n		$i0 = \"%s [%s %d] 77 %s\"\n		$i01 = \"Global\\\\%s%x\"\n		$i1 = \"Inject::InjectProcessByName()\"\n		$i2 = \"Inject::CopyImageToProcess()\"\n		$i3 = \"Inject::InjectProcess()\"\n		$i4 = \"Inject::InjectImageToProcess()\"\n		$i5 = \"Drop::InjectStartThread()\"\n		\n		$uac1 = \"ExploitMS10_092\"\n		$uac2 = \"\\\\globalroot\\\\systemroot\\\\system32\\\\tasks\\\\\" ascii wide\n		$uac3 = \"<RunLevel>HighestAvailable</RunLevel>\" ascii wide\n	condition:\n		2 of ($n*) and 2 of ($i*) and 2 of ($uac*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('KINS_DLL_zeus', 'Match default bot in KINS leaked dropper, Zeus', 1, 'rule KINS_DLL_zeus {\n	meta:\n		author = \"AlienVault Labs aortega@alienvault.com\"\n		description = \"Match default bot in KINS leaked dropper, Zeus\"\n		reference = \"http:\n	strings:\n		\n		$n1 = \"%BOTID%\" fullword\n		$n2 = \"%opensocks%\" fullword\n		$n3 = \"%openvnc%\" fullword\n		$n4 = /Global\\\\(s|v)_ev/ fullword\n		\n		$s1 = \"\\x72\\x6E\\x6D\\x2C\\x36\\x7D\\x76\\x77\"\n		$s2 = \"\\x18\\x04\\x0F\\x12\\x16\\x0A\\x1E\\x08\\x5B\\x11\\x0F\\x13\"\n		$s3 = \"\\x39\\x1F\\x01\\x07\\x15\\x19\\x1A\\x33\\x19\\x0D\\x1F\"\n		$s4 = \"\\x62\\x6F\\x71\\x78\\x63\\x61\\x7F\\x69\\x2D\\x67\\x79\\x65\"\n		$s5 = \"\\x6F\\x69\\x7F\\x6B\\x61\\x53\\x6A\\x7C\\x73\\x6F\\x71\"\n	condition:\n		all of ($n*) and 1 of ($s*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('KelihosHlux', 'http:\n	date = ', 1, 'rule KelihosHlux\n{\n  meta:\n	author = \"@malpush\"\n	maltype = \"KelihosHlux\"\n	description = \"http:\n	date = \"22/02/2014\"\n  strings:\n    $KelihosHlux_HexString = { 73 20 7D 8B FE 95 E4 12 4F 3F 99 3F 6E C8 28 26 C2 41 D9 8F C1 6A 72 A6 CE 36 0F 73 DD 2A 72 B0 CC D1 07 8B 2B 98 73 0E 7E 8C 07 DC 6C 71 63 F4 23 27 DD 17 56 AE AB 1E 30 52 E7 54 51 F7 20 ED C7 2D 4B 72 E0 77 8E B4 D2 A8 0D 8D 6A 64 F9 B7 7B 08 70 8D EF F3 9A 77 F6 0D 88 3A 8F BB C8 89 F5 F8 39 36 BA 0E CB 38 40 BF 39 73 F4 01 DC C1 17 BF C1 76 F6 84 8F BD 87 76 BC 7F 85 41 81 BD C6 3F BC 39 BD C0 89 47 3E 92 BD 80 60 9D 89 15 6A C6 B9 89 37 C4 FF 00 3D 45 38 09 CD 29 00 90 BB B6 38 FD 28 9C 01 39 0E F9 30 A9 66 6B 19 C9 F8 4C 3E B1 C7 CB 1B C9 3A 87 3E 8E 74 E7 71 D1 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('MALW_KeyBase', 'Identifies KeyBase aka Kibex.', 1, 'rule MALW_KeyBase\n{\nmeta:\n	description = \"Identifies KeyBase aka Kibex.\"\n	author = \"@bartblaze\"\n	date = \"2019-02\"\n	tlp = \"White\"\n\nstrings:	\n	$s1 = \" End:]\" ascii wide\n	$s2 = \"Keystrokes typed:\" ascii wide\n	$s3 = \"Machine Time:\" ascii wide\n	$s4 = \"Text:\" ascii wide\n	$s5 = \"Time:\" ascii wide\n	$s6 = \"Window title:\" ascii wide\n	\n	$x1 = \"&application=\" ascii wide\n	$x2 = \"&clipboardtext=\" ascii wide\n	$x3 = \"&keystrokestyped=\" ascii wide\n	$x4 = \"&link=\" ascii wide\n	$x5 = \"&username=\" ascii wide\n	$x6 = \"&windowtitle=\" ascii wide\n	$x7 = \"=drowssap&\" ascii wide\n	$x8 = \"=emitenihcam&\" ascii wide\n\ncondition:\n	uint16(0) == 0x5a4d and (\n		5 of ($s*) or 6 of ($x*) or\n		( 4 of ($s*) and 4 of ($x*) )\n	)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('korlia', '', 1, 'rule korlia\n{ \nmeta:\nauthor = \"Nick Hoffman\" \ncompany = \"Morphick\"\nreference = \"http:\ninformation = \"korlia malware found in apt dump\" \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\nstrings:\n$a = {b2 ?? 8A 86 98 40 00 71 BF 98 40 00 71 32 c2 83 C9 FF 88 86 98 40 00 71 33 C0 46 F2 AE F7 D1 49 3B F1}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Korplug_FAST', 'Rule to detect Korplug/PlugX FAST variant', 1, 'rule Korplug_FAST {\n    meta:\n        description = \"Rule to detect Korplug/PlugX FAST variant\"\n        author = \"Florian Roth\"\n        date = \"2015-08-20\"\n        hash = \"c437465db42268332543fbf6fd6a560ca010f19e0fd56562fb83fb704824b371\"\n    strings:\n        $x1 = \"%s\\\\rundll32.exe \\\"%s\\\", ShadowPlay\" fullword ascii\n\n        $a1 = \"ShadowPlay\" fullword ascii\n\n        $s1 = \"%s\\\\rundll32.exe \\\"%s\\\",\" fullword ascii\n        $s2 = \"nvdisps.dll\" fullword ascii\n        $s3 = \"%snvdisps.dll\" fullword ascii\n        $s4 = \"\\\\winhlp32.exe\" fullword ascii\n        $s5 = \"nvdisps_user.dat\" fullword ascii\n        $s6 = \"%snvdisps_user.dat\" fullword ascii\n    condition:\n        uint16(0) == 0x5a4d and filesize < 500KB and \n        (\n            $x1 or\n            ($a1 and 1 of ($s*)) or \n            4 of ($s*)\n        )\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Korplug', 'IOC looks for events associated with the KORPLUG Backdoor linked to the recent operation greedy wonk activity.', 1, 'rule Korplug\n{ \n	meta:\n		maltype = \"Korplug Backdoor\"\n        author = \"https:\n		reference = \"http:\n		description = \"IOC looks for events associated with the KORPLUG Backdoor linked to the recent operation greedy wonk activity.\"\n		\n	strings:\n		$type=\"Microsoft-Windows-Security-Auditing\"\n		$eventid=\"4688\"\n		$data=\"ProgramData\\\\RasTls\\\\RasTls.exe\"\n\n		$type1=\"Microsoft-Windows-Security-Auditing\"\n		$eventid1=\"4688\"\n		$data1=\"ProgramData\\\\RasTls\\\\rundll32.exe\"\n\n		$type2=\"Microsoft-Windows-Security-Auditing\"\n		$eventid2=\"4688\"\n		$data2=\"ProgramData\\\\RasTls\\\\svchost.exe\"\n	condition:\n		all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Kovter', 'fileless malware', 1, 'rule Kovter\n{ \n	meta:\n		maltype = \"Kovter\"\n    reference = \"http:\n		date = \"9-19-2016\"\n		description = \"fileless malware\"\n	strings:\n		$type=\"Microsoft-Windows-Security-Auditing\" wide ascii\n		$eventid=\"4688\" wide ascii\n		$data=\"Windows\\\\System32\\\\regsvr32.exe\" wide ascii\n		\n		$type1=\"Microsoft-Windows-Security-Auditing\" wide ascii\n		$eventid1=\"4689\" wide ascii\n		$data1=\"Windows\\\\System32\\\\mshta.exe\" wide ascii\n		\n		$type2=\"Microsoft-Windows-Security-Auditing\" wide ascii\n		$eventid2=\"4689\" wide ascii\n		$data2=\"Windows\\\\System32\\\\WindowsPowerShell\\\\v1.0\\\\powershell.exe\" wide ascii\n\n		$type3=\"Microsoft-Windows-Security-Auditing\" wide ascii\n		$eventid3=\"4689\" wide ascii\n		$data3=\"Windows\\\\System32\\\\wbem\\\\WmiPrvSE.exe\" wide ascii\n\n\n	condition:\n		all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Kraken_Bot_Sample', 'Kraken Bot Sample - file inf.bin', 1, 'rule Kraken_Bot_Sample : bot {\n	meta:\n		description = \"Kraken Bot Sample - file inf.bin\"\n		author = \"Florian Roth\"\n		reference = \"https:\n		date = \"2015-05-07\"\n		hash = \"798e9f43fc199269a3ec68980eb4d91eb195436d\"\n		score = 90\n	strings:\n		$s2 = \"%s=?getname\" fullword ascii\n		$s4 = \"&COMPUTER=^\" fullword ascii\n		$s5 = \"xJWFwcGRhdGElAA=\" fullword ascii \n		$s8 = \"JVdJTkRJUi\" fullword ascii \n		$s20 = \"btcplug\" fullword ascii\n	condition:\n		uint16(0) == 0x5a4d and all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Kwampirs', 'Kwampirs dropper and main payload components', 1, 'rule Kwampirs\n{\n meta:\n copyright = \"Symantec\"\n reference = \"https:\n family = \"Kwampirs\"\n description = \"Kwampirs dropper and main payload components\"\n strings:\n$pubkey =\n {\n 06 02 00 00 00 A4 00 00 52 53 41 31 00 08 00 00\n 01 00 01 00 CD 74 15 BC 47 7E 0A 5E E4 35 22 A5\n 97 0C 65 BE E0 33 22 F2 94 9D F5 40 97 3C 53 F9\n E4 7E DD 67 CF 5F 0A 5E F4 AD C9 CF 27 D3 E6 31\n 48 B8 00 32 1D BE 87 10 89 DA 8B 2F 21 B4 5D 0A\n CD 43 D7 B4 75 C9 19 FE CC 88 4A 7B E9 1D 8C 11\n 56 A6 A7 21 D8 C6 82 94 C1 66 11 08 E6 99 2C 33\n 02 E2 3A 50 EA 58 D2 A7 36 EE 5A D6 8F 5D 5D D2\n 9E 04 24 4A CE 4C B6 91 C0 7A C9 5C E7 5F 51 28\n 4C 72 E1 60 AB 76 73 30 66 18 BE EC F3 99 5E 4B\n 4F 59 F5 56 AD 65 75 2B 8F 14 0C 0D 27 97 12 71\n 6B 49 08 84 61 1D 03 BA A5 42 92 F9 13 33 57 D9\n 59 B3 E4 05 F9 12 23 08 B3 50 9A DA 6E 79 02 36\n EE CE 6D F3 7F 8B C9 BE 6A 7E BE 8F 85 B8 AA 82\n C6 1E 14 C6 1A 28 29 59 C2 22 71 44 52 05 E5 E6\n FE 58 80 6E D4 95 2D 57 CB 99 34 61 E9 E9 B3 3D\n 90 DC 6C 26 5D 70 B4 78 F9 5E C9 7D 59 10 61 DF\n F7 E4 0C B3\n }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('SharedStrings', 'Internal names found in LURK0/CCTV0 samples', 1, 'rule SharedStrings : Family {\n	meta:\n		description = \"Internal names found in LURK0/CCTV0 samples\"\n		author = \"Katie Kleemola\"\n		last_updated = \"07-22-2014\"\n	\n	strings:\n		\n		$i1 = \"Butterfly.dll\"\n		$i2 = /\\\\BT[0-9.]+\\\\ButterFlyDLL\\\\/\n		$i3 = \"ETClientDLL\"\n\n		\n		$d1 = \"\\\\DbxUpdateET\\\\\" wide\n		$d2 = \"\\\\DbxUpdateBT\\\\\" wide\n		$d3 = \"\\\\DbxUpdate\\\\\" wide\n		\n		\n		$mc1 = \"\\\\Micet\\\\\"\n\n		\n		$n1 = \"IconCacheEt.dat\" wide\n		$n2 = \"IconConfigEt.dat\" wide\n\n		$m1 = \"\\x00\\x00ERXXXXXXX\\x00\\x00\" wide\n		$m2 = \"\\x00\\x00111\\x00\\x00\" wide\n		$m3 = \"\\x00\\x00ETUN\\x00\\x00\" wide\n		$m4 = \"\\x00\\x00ER\\x00\\x00\" wide\n\n	condition:\n		any of them \n\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('lateral_movement', 'methodology sig looking for signs of lateral movement', 1, 'rule lateral_movement\n{ \n	meta:\n		date = \"3/12/2014\"\n		author = \"https:\n    description = \"methodology sig looking for signs of lateral movement\"\n	strings:\n		$type=\"Microsoft-Windows-Security-Auditing\"\n		$eventid=\"4688\"\n		$data=\"PsExec.exe\"\n\n		$type1=\"Microsoft-Windows-Security-Auditing\"\n		$eventid1=\"4688\"\n		$data1=\"Windows\\\\System32\\\\net.exe\"\n\n		$type2=\"Microsoft-Windows-Security-Auditing\"\n		$eventid2=\"4688\"\n		$data2=\"Windows\\\\System32\\\\at.exe\"\n	condition:\n		($type and $eventid and $data) or ($type1 and $eventid1 and $data1) or ($type2 and $eventid2 and $data2)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('VisualDiscovery_Lonovo_Superfish_SSL_Hijack', 'Lenovo Superfish SSL Interceptor - file VisualDiscovery.exe', 1, 'rule VisualDiscovery_Lonovo_Superfish_SSL_Hijack {\n	meta:\n		description = \"Lenovo Superfish SSL Interceptor - file VisualDiscovery.exe\"\n		author = \"Florian Roth / improved by kbandla\"\n		reference = \"https:\n		date = \"2015/02/19\"\n		hash1 = \"99af9cfc7ab47f847103b5497b746407dc566963\"\n		hash2 = \"f0b0cd0227ba302ac9ab4f30d837422c7ae66c46\"\n		hash3 = \"f12edf2598d8f0732009c5cd1df5d2c559455a0b\"\n		hash4 = \"343af97d47582c8150d63cbced601113b14fcca6\"\n	strings:\n		$mz = { 4d 5a }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('LinuxBew', 'Linux.Bew Backdoor', 1, 'rule LinuxBew: MALW\n{\n	meta:\n		description = \"Linux.Bew Backdoor\"\n		author = \"Joan Soriano / @w0lfvan\"\n		date = \"2017-07-10\"\n		version = \"1.0\"\n		MD5 = \"27d857e12b9be5d43f935b8cc86eaabf\"\n		SHA256 = \"80c4d1a1ef433ac44c4fe72e6ca42395261fbca36eff243b07438263a1b1cf06\"\n	strings:\n		$a = \"src/secp256k1.c\"\n		$b = \"hfir.u230.org\"\n		$c = \"tempfile-x11session\"\n	condition:\n		all of them\n}', 1, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('LinuxHelios', 'Linux.Helios', 1, 'rule LinuxHelios: MALW\n{\n	meta:\n		description = \"Linux.Helios\"\n		author = \"Joan Soriano / @w0lfvan\"\n		date = \"2017-10-19\"\n		version = \"1.0\"\n		MD5 = \"1a35193f3761662a9a1bd38b66327f49\"\n		SHA256 = \"72c2e804f185bef777e854fe86cff3e86f00290f32ae8b3cb56deedf201f1719\"\n	strings:\n		$a = \"LIKE A GOD!!! IP:%s User:%s Pass:%s\"\n		$b = \"smack\"\n		$c = \"PEACE OUT IMMA DUP\\n\"\n	condition:\n		all of them\n}', 1, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('is_elf', '', 1, 'private rule is_elf\n{\n    strings:\n        $header = { 7F 45 4C 46 }', 1, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('moose', '', 1, 'rule moose\n{\n    meta:\n        Author      = \"Thomas Dupuy\"\n        Date        = \"2015/04/21\"\n        Description = \"Linux/Moose malware\"\n        Reference   = \"http:\n        Source = \"https:\n        Contact = \"github@eset.com\"\n        License = \"BSD 2-Clause\"\n\n    strings:\n        $s0 = \"Status: OK\"\n        $s1 = \"--scrypt\"\n        $s2 = \"stratum+tcp:\n        $s3 = \"cmd.so\"\n        $s4 = \"/Challenge\"\n        $s7 = \"processor\"\n        $s9 = \"cpu model\"\n        $s21 = \"password is wrong\"\n        $s22 = \"password:\"\n        $s23 = \"uthentication failed\"\n        $s24 = \"sh\"\n        $s25 = \"ps\"\n        $s26 = \"echo -n -e \"\n        $s27 = \"chmod\"\n        $s28 = \"elan2\"\n        $s29 = \"elan3\"\n        $s30 = \"chmod: not found\"\n        $s31 = \"cat /proc/cpuinfo\"\n        $s32 = \"/proc/%s/cmdline\"\n        $s33 = \"kill %s\"\n\n    condition:\n        is_elf and all of them\n}', 1, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('lost_door', 'Lost Door', 1, 'rule lost_door : Trojan\n{\n	meta:\n		author=\"Kevin Falcoz\"\n		date=\"23/02/2013\"\n		description=\"Lost Door\"\n	\n	strings:\n		$signature1={45 44 49 54 5F 53 45 52 56 45 52}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('LuaBot', 'LuaBot', 1, 'rule LuaBot : MALW\n{\n        meta:\n                description = \"LuaBot\"\n                author = \"Joan Soriano / @joanbtl\"\n                date = \"2017-06-07\"\n                version = \"1.0\"\n                MD5 = \"9df3372f058874fa964548cbb74c74bf\"\n                SHA1 = \"89226865501ee7d399354656d870b4a9c02db1d3\"\n                ref1 = \"http:\n\n        strings:\n                $a = \"LUA_PATH\"\n                $b = \"Hi. Happy reversing, you can mail me: luabot@yandex.ru\"\n                $c = \"/tmp/lua_XXXXXX\"\n                $d = \"NOTIFY\"\n                $e = \"UPDATE\"\n\n        condition:\n                all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('MSILStealer', 'Detects strings from C#/VB Stealers and QuasarRat', 1, 'rule MSILStealer\n{\n    meta:\n        description = \"Detects strings from C#/VB Stealers and QuasarRat\"\n        reference = \"https:\n        author = \"https:\n        last_modified = \"2019-11-21\"\n\n    strings:\n        $ = \"Firefox does not have any profiles, has it ever been launched?\" wide ascii\n        $ = \"Firefox is not installed, or the install path could not be located\" wide ascii\n        $ = \"No installs of firefox recorded in its key.\" wide ascii\n        $ = \"{0}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('MacControl', 'MacControl', 1, 'rule MacControl : Family\n{\n    meta:\n        description = \"MacControl\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-06-16\"\n        \n    condition:\n        MacControlCode or MacControlStrings\n}', 2, '恶意软件', 1);
