INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('fromCharCode_in_unicode', '', 1, 'rule fromCharCode_in_unicode {\n    strings: \n        $ = \"\\\\u0066\\\\u0072\\\\u006f\\\\u006d\\\\u0043\\\\u0068\\\\u0061\\\\u0072\\\\u0043\\\\u006f\\\\u0064\\\\u0065\"\n    condition: \n        any of them and filesize < 500KB\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('function_through_object', '', 1, 'rule function_through_object {\n    strings: \n        $ = \"[''eval'']\"\n        $ = \"[''unescape'']\"\n        $ = \"[''charCodeAt'']\"\n        $ = \"[''fromCharCode'']\"\n    condition: \n        any of them and filesize < 500KB\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('hex_script', '', 1, 'rule hex_script {\n    strings:\n        $ = \"\\\\x73\\\\x63\\\\x72\\\\x69\\\\x70\\\\x74\\\\x22\"\n    condition: \n        any of them and filesize < 500KB\n}', 2, '恶意软件', 1);
