INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('html_upload', '', 1, 'rule html_upload {\n    strings: \n        $ = \"<input type=''submit'' name=''upload'' value=''upload''>\"\n        $ = \"if($_POST[''upload''])\"\n    condition: \n        any of them and filesize < 500KB\n}', 2, '恶意软件', 1);
