INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('scriptkiddies', '', 1, 'rule scriptkiddies {\n    strings:\n        $ = \"lastc0de@Outlook.com\" nocase\n        $ = \"CodersLeet\" nocase\n        $ = \"AgencyCaFc\" nocase\n        $ = \"IndoXploit\" nocase\n        $ = \"Kapaljetz666\" nocase\n    condition: \n        any of them and filesize < 500KB\n}', 2, '恶意软件', 1);
