INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('PM_Email_Sent_By_PHP_Script', '', 1, 'rule PM_Email_Sent_By_PHP_Script\n{\n  strings:\n    $php1=\"X-PHP-Script\" fullword\n    $php2=\"X-PHP-Originating-Script\" fullword\n    $php3=\"/usr/bin/php\" fullword\n\n  condition:\n    any of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('PM_Zip_with_js', '', 1, 'rule PM_Zip_with_js\n{\n  strings:\n    $hdr=\"PK\" \n    $e1=\".js\" nocase\n    $e2=\".jse\" nocase\n\n  condition:\n    $hdr at 0 and (($e1 in (filesize-100..filesize)) or ($e2 in (filesize-100..filesize)))\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('MedussaHTTP_2019', 'MedussaHTTP v20190812', 1, 'rule MedussaHTTP_2019\n{\n\n    meta:\n        author = \"J from THL <j@techhelplist.com>\"\n        date = \"2019-08-12\"\n        reference1 = \"https:\n        reference2 = \"https:\n        reference3 = \"https:\n        version = 1\n        maltype = \"Bot\"\n        filetype = \"memory\"\n        description = \"MedussaHTTP v20190812\"\n\n    strings:\n        $text01 = \"|check|\" ascii\n        $text02 = \"POST!\" ascii\n        $text03 = \"httpactive\" ascii\n        $text04 = \"httpstrong\" ascii\n        $text05 = \"httppost\" ascii\n        $text06 = \"slavicdragon\" ascii\n        $text07 = \"slavicnodragon\" ascii\n        $text08 = \"smartflood\" ascii\n        $text09 = \"stop-all\" ascii\n        $text10 = \"botkill\" ascii\n        $text11 = \"updatehash\" ascii\n        $text12 = \"xyz=\" ascii\n        $text13 = \"abc=\" ascii\n\n\n\n    condition:\n        9 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Trojan_W32_Gh0stMiancha_1_0_0', '', 1, 'rule Trojan_W32_Gh0stMiancha_1_0_0\n{\n    meta:\n        Author      = \"Context Threat Intelligence\"\n        Date        = \"2014/01/27\"\n        Description = \"Bytes inside\"\n        Reference   = \"http:\n\n    strings:\n        $0x = { 57 5b 5a 5a 51 57 40 34 31 67 2e 31 70 34 5c 40 40 44 3b 25 3a 19 1e 5c 7b 67 60 2e 34 31 67 2e 31 70 19 1e 55 77 77 71 64 60 2e 34 3e 3b 3e 19 1e 57 7b 7a 60 71 7a 60 39 40 6d 64 71 2e 34 60 71 6c 60 3b 7c 60 79 78 19 1e 44 66 7b 6c 6d 39 57 7b 7a 7a 71 77 60 7d 7b 7a 2e 34 5f 71 71 64 39 55 78 7d 62 71 19 1e 57 7b 7a 60 71 7a 60 39 78 71 7a 73 60 7c 2e 34 24 19 1e 19 1e }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('MiniAsp3_mem', 'Detect MiniASP3 in memory', 1, 'rule MiniAsp3_mem : memory { \n  meta: author = \"chort (@chort0)\"\n  description = \"Detect MiniASP3 in memory\"\n  strings: \n    $pdb = \"MiniAsp3\\\\Release\\\\MiniAsp.pdb\" fullword \n    $httpAbout = \"http:\n    $httpResult = \"http:\n    $msgInetFail = \"open internet failed…\" fullword \n    $msgRunErr = \"run error!\" fullword \n    $msgRunOk = \"run ok!\" fullword\n    $msgTimeOutM0 = \"time out,change to mode 0\" fullword \n    $msgCmdNull = \"command is null!\" fullword \ncondition:\n  ($pdb and (all of ($http*)) and any of ($msg*))\n  }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Mirai_Generic_Arch', 'Mirai Botnet TR-069 Worm - Generic Architecture', 1, 'rule Mirai_Generic_Arch : MALW\n{\n	meta:\n		description = \"Mirai Botnet TR-069 Worm - Generic Architecture\" \n		author = \"Felipe Molina / @felmoltor\"\n		date = \"2016-12-04\"\n		version = \"1.0\" \n		ref1 = \"http:\n		ref2 = \"https:\n		ref3 = \"https:\n\n	strings:\n		$miname = \"Myname--is:\"\n		$iptables1 = \"busybox iptables -A INPUT -p tcp --destination-port 7547 -j DROP\"\n		$iptables2 = \"busybox iptables -A INPUT -p tcp --destination-port 5555 -j DROP\"\n		$procnet = \"/proc/net/tcp\"\n\n	condition:\n		$miname and $iptables1 and $iptables2 and $procnet\n}', 2, '恶意软件', 1);
