INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Mirai_Dwnl', 'Mirai Downloader', 1, 'rule Mirai_Dwnl : MALW\n{\n	meta:\n		description = \"Mirai Downloader\"\n		author = \"Joan Soriano / @joanbtl\"\n		date = \"2017-04-16\"\n		version = \"1.0\"\n		MD5 = \"85784b54dee0b7c16c57e3a3a01db7e6\"\n		SHA1 = \"6f6c625ef730beefbc23c7f362af329426607dee\"\n	strings:\n		$s1 = \"GET /mirai/\"\n		$s2 = \"dvrHelper\"\n	condition:\n		$s1 and $s2\n}', 2, '恶意软件', 1);
