INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Mirai_Okiru', 'Detects Mirai Okiru MALW', 1, 'rule Mirai_Okiru {\n	meta:\n		description = \"Detects Mirai Okiru MALW\"\n		reference = \"https:\n		date = \"2018-01-05\"\n\n	strings:\n		$hexsts01 = { 68 7f 27 70 60 62 73 3c 27 28 65 6e 69 28 65 72 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('is__Mirai_Satori_gen', 'Detects Mirai Satori_gen', 1, 'private rule is__Mirai_Satori_gen {\n	meta:\n		description = \"Detects Mirai Satori_gen\"\n		reference = \"https:\n		date = \"2018-01-05\"\n\n	strings:\n		$st08 = \"tftp -r satori\" fullword nocase wide ascii\n		$st09 = \"/bins/satori\" fullword nocase wide ascii\n		$st10 = \"satori\" fullword nocase wide ascii\n		$st11 = \"SATORI\" fullword nocase wide ascii\n\n	condition:\n		2 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Mirai_Satori', 'Detects Mirai Satori MALW', 1, 'rule Mirai_Satori {\n	meta:\n		description = \"Detects Mirai Satori MALW\"\n		date = \"2018-01-09\"\n\n	strings:\n		$hexsts01 = { 63 71 75 ?? 62 6B 77 62 75 }', 2, '恶意软件', 1);
