INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('ScanBox_Malware_Generic', 'Scanbox Chinese Deep Panda APT Malware http:\n		author = ', 1, 'rule ScanBox_Malware_Generic {\n	meta:\n		description = \"Scanbox Chinese Deep Panda APT Malware http:\n		author = \"Florian Roth\"\n		reference1 = \"http:\n		reference2 = \"http:\n		date = \"2015/02/28\"\n		hash1 = \"8d168092d5601ebbaed24ec3caeef7454c48cf21366cd76560755eb33aff89e9\"\n		hash2 = \"d4be6c9117db9de21138ae26d1d0c3cfb38fd7a19fa07c828731fa2ac756ef8d\"\n		hash3 = \"3fe208273288fc4d8db1bf20078d550e321d9bc5b9ab80c93d79d2cb05cbf8c2\"\n	strings:\n		\n		$s0 = \"http:\n		$s1 = \"HttpDump 1.1\" fullword ascii\n		\n		\n		$s3 = \"SecureInput .exe\" fullword wide\n		$s4 = \"http:\n		\n		\n		$s5 = \"%SystemRoot%\\\\System32\\\\svchost.exe -k msupdate\" fullword ascii\n		$s6 = \"ServiceMaix\" fullword ascii		\n		\n		\n		$x1 = \"Management Support Team1\" fullword ascii\n		$x2 = \"DTOPTOOLZ Co.,Ltd.0\" fullword ascii\n		$x3 = \"SEOUL1\" fullword ascii\n	condition:\n		( 1 of ($s*) and 2 of ($x*) ) or \n		( 3 of ($x*) )\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('TrojanDownloader', 'Trojan Downloader - Flash Exploit Feb15', 1, 'rule TrojanDownloader {\n	meta:\n		description = \"Trojan Downloader - Flash Exploit Feb15\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		date = \"2015/02/11\"\n		hash = \"5b8d4280ff6fc9c8e1b9593cbaeb04a29e64a81e\"\n		score = 60\n	strings:\n		$x1 = \"Hello World!\" fullword ascii\n		$x2 = \"CONIN$\" fullword ascii\n			\n		$s6 = \"GetCommandLineA\" fullword ascii\n		$s7 = \"ExitProcess\" fullword ascii\n		$s8 = \"CreateFileA\" fullword ascii						\n\n		$s5 = \"SetConsoleMode\" fullword ascii		\n		$s9 = \"TerminateProcess\" fullword ascii	\n		$s10 = \"GetCurrentProcess\" fullword ascii\n		$s11 = \"UnhandledExceptionFilter\" fullword ascii\n		$s3 = \"user32.dll\" fullword ascii\n		$s16 = \"GetEnvironmentStrings\" fullword ascii\n		$s2 = \"GetLastActivePopup\" fullword ascii		\n		$s17 = \"GetFileType\" fullword ascii\n		$s19 = \"HeapCreate\" fullword ascii\n		$s20 = \"VirtualFree\" fullword ascii\n		$s21 = \"WriteFile\" fullword ascii\n		$s22 = \"GetOEMCP\" fullword ascii\n		$s23 = \"VirtualAlloc\" fullword ascii\n		$s24 = \"GetProcAddress\" fullword ascii\n		$s26 = \"FlushFileBuffers\" fullword ascii\n		$s27 = \"SetStdHandle\" fullword ascii\n		$s28 = \"KERNEL32.dll\" fullword ascii\n	condition:\n		$x1 and $x2 and ( all of ($s*) ) and filesize < 35000\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Cloaked_as_JPG', 'Detects a cloaked file as JPG', 1, 'rule Cloaked_as_JPG {\n        meta:\n                description = \"Detects a cloaked file as JPG\"\n                author = \"Florian Roth (eval section from Didier Stevens)\"\n                date = \"2015/02/29\"\n                score = 70\n        strings:\n                $ext = \"extension: .jpg\"\n        condition:\n                $ext and uint16be(0x00) != 0xFFD8\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('rtf_yahoo_ken', 'Test rule', 1, 'rule rtf_yahoo_ken\n{\nmeta:\n	author = \"@patrickrolsen\"\n	maltype = \"Yahoo Ken\"\n	filetype = \"RTF\"\n	version = \"0.1\"\n	description = \"Test rule\"\n	date = \"2013-12-14\"\nstrings:\n	$magic1 = { 7b 5c 72 74 30 31 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('ZXProxy', '', 1, 'rule ZXProxy\n{\nmeta:\n	author = \"ThreatConnect Intelligence Research Team\"\n	\nstrings:\n	$C = \"\\\\Control\\\\zxplug\" nocase wide ascii\n	$h = \"http:\n	$S = \"Shared a shell to %s:%s Successfully\" nocase wide ascii\ncondition:\n	any of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('OrcaRAT', '', 1, 'rule OrcaRAT\n{\n    meta:\n        Author      = \"PwC Cyber Threat Operations\"\n        Date        = \"2014/10/20\" \n        Description = \"Strings inside\"\n        Reference   = \"http:\n\n    strings:\n        $MZ = \"MZ\"\n        $apptype1 = \"application/x-ms-application\"\n        $apptype2 = \"application/x-ms-xbap\"\n        $apptype3 = \"application/vnd.ms-xpsdocument\"\n        $apptype4 = \"application/xaml+xml\"\n        $apptype5 = \"application/x-shockwave-flash\"\n        $apptype6 = \"image/pjpeg\"\n        $err1 = \"Set return time error =   %d!\"\n        $err2 = \"Set return time   success!\"\n        $err3 = \"Quit success!\"\n\n    condition:\n        $MZ at 0 and filesize < 500KB and (all of ($apptype*) and 1 of ($err*))\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('EmiratesStatement', '', 1, 'rule EmiratesStatement \n{\n	meta:\n		Author 		= \"Christiaan Beek\"\n		Date 		= \"2013-06-30\"\n		Description = \"Credentials Stealing Attack\"\n		Reference 	= \"https:\n		\n		hash0 = \"0e37b6efe5de1cc9236017e003b1fc37\"\n		hash1 = \"a28b22acf2358e6aced43a6260af9170\"\n		hash2 = \"6f506d7adfcc2288631ed2da37b0db04\"\n		hash3 = \"8aebade47dc1aa9ac4b5625acf5ade8f\"\n	\n	strings:\n		$string0 = \"msn.klm\"\n		$string1 = \"wmsn.klm\"\n		$string2 = \"bms.klm\"\n	\n	condition:\n		all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('PUP_InstallRex_AntiFWb', 'Malware InstallRex / AntiFW', 1, 'rule PUP_InstallRex_AntiFWb {\n	meta:\n		description = \"Malware InstallRex / AntiFW\"\n		author = \"Florian Roth\"\n		date = \"2015-05-13\"\n		hash = \"bb5607cd2ee51f039f60e32cf7edc4e21a2d95cd\"\n		score = 65\n	strings:\n		$s4 = \"Error %u while loading TSU.DLL %ls\" fullword ascii\n		$s7 = \"GetModuleFileName() failed => %u\" fullword ascii\n		$s8 = \"TSULoader.exe\" fullword wide\n		$s15 = \"\\\\StringFileInfo\\\\%04x%04x\\\\Arguments\" fullword wide\n		$s17 = \"Tsu%08lX.dll\" fullword wide\n	condition:\n		uint16(0) == 0x5a4d and all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('LightFTP_fftp_x86_64', 'Detects a light FTP server', 1, 'rule LightFTP_fftp_x86_64 {\n	meta:\n		description = \"Detects a light FTP server\"\n		author = \"Florian Roth\"\n		reference = \"https:\n		date = \"2015-05-14\"\n		hash1 = \"989525f85abef05581ccab673e81df3f5d50be36\"\n		hash2 = \"5884aeca33429830b39eba6d3ddb00680037faf4\"\n		score = 50\n	strings:\n		$s1 = \"fftp.cfg\" fullword wide\n		$s2 = \"220 LightFTP server v1.0 ready\" fullword ascii\n		$s3 = \"*FTP thread exit*\" fullword wide\n		$s4 = \"PASS->logon successful\" fullword ascii\n		$s5 = \"250 Requested file action okay, completed.\" fullword ascii\n	condition:\n		uint16(0) == 0x5a4d and filesize < 250KB and 4 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('LightFTP_Config', 'Detects a light FTP server - config file', 1, 'rule LightFTP_Config {\n	meta:\n		description = \"Detects a light FTP server - config file\"\n		author = \"Florian Roth\"\n		reference = \"https:\n		date = \"2015-05-14\"\n		hash = \"ce9821213538d39775af4a48550eefa3908323c5\"\n	strings:\n		$s2 = \"maxusers=\" wide\n		$s6 = \"[ftpconfig]\" fullword wide\n		$s8 = \"accs=readonly\" fullword wide\n		$s9 = \"[anonymous]\" fullword wide\n		$s10 = \"accs=\" fullword wide\n		$s11 = \"pswd=\" fullword wide\n	condition:\n		uint16(0) == 0xfeff and filesize < 1KB and all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('SpyGate_v2_9', '', 1, 'rule SpyGate_v2_9\n{\n	meta:\n		date = \"2014/09\"\n		maltype = \"Spygate v2.9 Remote Access Trojan\"\n		filetype = \"exe\"\n		reference = \"https:\n	strings:\n		$1 = \"shutdowncomputer\" wide\n		$2 = \"shutdown -r -t 00\" wide\n		$3 = \"blockmouseandkeyboard\" wide\n		$4 = \"ProcessHacker\"\n		$5 = \"FileManagerSplit\" wide\n	condition:\n		all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('ice_ix_12xy', 'ICE-IX 1.2.x.y trojan banker', 1, 'rule ice_ix_12xy : banker\n{\n	meta:\n		author = \"Jean-Philippe Teissier / @Jipe_\"\n		description = \"ICE-IX 1.2.x.y trojan banker\"\n		date = \"2013-01-12\"\n		filetype = \"memory\"\n		version = \"1.0\" \n	\n	strings:\n		$regexp1= /bn1=.{32}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('qadars', 'Qadars - Mobile part. Maybe Perkele.', 1, 'rule qadars : banker\n{\n	meta:\n		author = \"Jean-Philippe Teissier / @Jipe_\"\n		description = \"Qadars - Mobile part. Maybe Perkele.\"\n		version = \"1.0\" \n		filetype = \"memory\"\n		ref1 = \"http:\n\n	strings:\n		$cmd1 = \"m?D\"\n		$cmd2 = \"m?S\"\n		$cmd3 = \"ALL\"\n		$cmd4 = \"FILTER\"\n		$cmd5 = \"NONE\"\n		$cmd6 = \"KILL\"\n		$cmd7 = \"CANCEL\"\n		$cmd8 = \"SMS\"\n		$cmd9 = \"DIVERT\"\n		$cmd10 = \"MESS\"\n		$nofilter = \"nofilter1111111\"\n		$botherderphonenumber1 = \"+380678409210\"\n\n	condition:\n		all of ($cmd*) or $nofilter or any of ($botherderphonenumber*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('shylock', 'Shylock Banker', 1, 'rule shylock :  banker\n{\n	meta:\n		author = \"Jean-Philippe Teissier / @Jipe_\"\n		description = \"Shylock Banker\"\n		date = \"2013-12-12\" \n		version = \"1.0\" \n		ref1 = \"http:\n		ref2 = \"http:\n		ref3 = \"https:\n\n	strings:\n		$process1 = \"MASTER\"\n		$process2 = \"_SHUTDOWN\"\n		$process3 = \"EVT_VNC\"\n		$process4 = \"EVT_BACK\"\n		$process5 = \"EVT_VNC\"\n		$process6 = \"IE_Hook::GetRequestInfo\"\n		$process7 = \"FF_Hook::getRequestInfo\"\n		$process8 = \"EX_Hook::CreateProcess\"\n		$process9 = \"hijackdll.dll\"\n		$process10 = \"MTX_\"\n		$process11 = \"FF::PR_WriteHook entry\"\n		$process12 = \"FF::PR_WriteHook exit\"\n		$process13 = \"HijackProcessAttach::*** MASTER *** MASTER *** MASTER *** %s PID=%u\"\n		$process14 = \"HijackProcessAttach::entry\"\n		$process15 = \"FF::BEFORE INJECT\"\n		$process16 = \"FF::AFTER INJECT\"\n		$process17 = \"IE::AFTER INJECT\"\n		$process18 = \"IE::BEFORE INJECT\"\n		$process19 = \"*** VNC *** VNC *** VNC *** VNC *** VNC *** VNC *** VNC *** VNC *** VNC *** VNC *** %s\"\n		$process20 = \"*** LOG INJECTS *** %s\"\n		$process21 = \"*** inject to process %s not allowed\"\n		$process22 = \"*** BackSocks *** BackSocks *** BackSocks *** BackSocks *** BackSocks *** BackSocks *** BackSocks *** %s\"\n		$process23 = \".?AVFF_Hook@@\"\n		$process24 = \".?AVIE_Hook@@\"\n		$process25 = \"Inject::InjectDllFromMemory\"\n		$process26 = \"BadSocks.dll\"	\n		$domain1 = \"extensadv.cc\"\n		$domain2 = \"topbeat.cc\"\n		$domain3 = \"brainsphere.cc\"\n		$domain4 = \"commonworldme.cc\"\n		$domain5 = \"gigacat.cc\"\n		$domain6 = \"nw-serv.cc\"\n		$domain7 = \"paragua-analyst.cc\"\n		\n	condition:\n		3 of ($process*) or any of ($domain*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('spyeye', 'SpyEye X.Y memory', 1, 'rule spyeye : banker\n{\n	meta:\n		author = \"Jean-Philippe Teissier / @Jipe_\"\n		description = \"SpyEye X.Y memory\"\n		date = \"2012-05-23\" \n		version = \"1.0\" \n		filetype = \"memory\"\n\n	strings:\n		$spyeye = \"SpyEye\"\n		$a = \"%BOTNAME%\"\n		$b = \"globplugins\"\n		$c = \"data_inject\"\n		$d = \"data_before\"\n		$e = \"data_after\"\n		$f = \"data_end\"\n		$g = \"bot_version\"\n		$h = \"bot_guid\"\n		$i = \"TakeBotGuid\"\n		$j = \"TakeGateToCollector\"\n		$k = \"[ERROR] : Omfg! Process is still active? Lets kill that mazafaka!\"\n		$l = \"[ERROR] : Update is not successfull for some reason\"\n		$m = \"[ERROR] : dwErr == %u\"\n		$n = \"GRABBED DATA\"\n		\n	condition:\n		$spyeye or (any of ($a,$b,$c,$d,$e,$f,$g,$h,$i,$j,$k,$l,$m,$n))\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('spyeye_plugins', 'SpyEye X.Y Plugins memory', 1, 'rule spyeye_plugins : banker\n{\n	meta:\n		author = \"Jean-Philippe Teissier / @Jipe_\"\n		description = \"SpyEye X.Y Plugins memory\"\n		date = \"2012-05-23\" \n		version = \"1.0\" \n		filetype = \"memory\"\n\n	strings:\n		$a = \"webfakes.dll\"\n		$b = \"config.dat\"			\n		$c = \"collectors.txt\"\n		$d = \"webinjects.txt\"\n		$e = \"screenshots.txt\"\n		$f = \"billinghammer.dll\"\n		$g = \"block.dll\"			\n		$h = \"bugreport.dll\"		\n		$i = \"ccgrabber.dll\"\n		$j = \"connector2.dll\"\n		$k = \"creditgrab.dll\"\n		$l = \"customconnector.dll\"\n		$m = \"ffcertgrabber.dll\"\n		$n = \"ftpbc.dll\"\n		$o = \"rdp.dll\"				\n		$p = \"rt_2_4.dll\"\n		$q = \"socks5.dll\"			\n		$r = \"spySpread.dll\"\n		$s = \"w2chek4_4.dll\"\n		$t = \"w2chek4_6.dll\"\n	\n	condition:\n		any of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('callTogether_certificate', '', 1, 'rule callTogether_certificate\n{\n    meta:\n        Author      = \"Fireeye Labs\"\n        Date        = \"2014/11/03\" \n        Description = \"detects binaries signed with the CallTogether certificate\"\n        Reference   = \"https:\n\n    strings:\n        $serial = { 45 21 56 C3 B3 FB 01 76 36 5B DB 5B 77 15 BC 4C }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('qti_certificate', '', 1, 'rule qti_certificate\n{\n    meta:\n        Author      = \"Fireeye Labs\"\n        Date        = \"2014/11/03\" \n        Description = \"detects binaries signed with the QTI International Inc certificate\"\n        Reference   = \"https:\n\n    strings:\n        $cn = \"QTI International Inc\"\n        $serial = { 2e df b9 fd cf a0 0c cb 5a b0 09 ee 3a db 97 b9 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('DownExecute_A', '', 1, 'rule DownExecute_A\n{\n	meta:\n        Author      = \"PwC Cyber Threat Operations :: @tlansec\"\n        Date        = \"2015/04/27\"\n        Description = \"Malware is often wrapped/protected, best to run on memory\"\n        Reference   = \"http:\n\n    strings:\n        $winver1 = \"win 8.1\"\n        $winver2 = \"win Server 2012 R2\"\n        $winver3 = \"win Srv 2012\"\n        $winver4 = \"win srv 2008 R2\"\n        $winver5 = \"win srv 2008\"\n        $winver6 = \"win vsta\"\n        $winver7 = \"win srv 2003 R2\"\n        $winver8 = \"win hm srv\"\n        $winver9 = \"win Strg srv 2003\"\n        $winver10 = \"win srv 2003\"\n        $winver11 = \"win XP prof x64 edt\"\n        $winver12 = \"win XP\"\n        $winver13 = \"win 2000\"\n\n        $pdb1 = \"D:\\\\Acms\\\\2\\\\docs\\\\Visual Studio 2013\\\\Projects\\\\DownloadExcute\\\\DownloadExcute\\\\Release\\\\DownExecute.pdb\"\n        $pdb2 = \"d:\\\\acms\\\\2\\\\docs\\\\visual studio 2013\\\\projects\\\\downloadexcute\\\\downloadexcute\\\\downexecute\\\\json\\\\rapidjson\\\\writer.h\"\n        $pdb3 = \":\\\\acms\\\\2\\\\docs\\\\visual studio 2013\\\\projects\\\\downloadexcute\\\\downloadexcute\\\\downexecute\\\\json\\\\rapidjson\\\\internal/stack.h\"\n        $pdb4 = \"\\\\downloadexcute\\\\downexecute\\\\\"\n\n        $magic1 = \"<Win Get Version Info Name Error\"\n        $magic2 = \"P@$sw0rd$nd\"\n        $magic3 = \"$t@k0v2rF10w\"\n        $magic4 = \"|*|123xXx(Mutex)xXx321|*|6-21-2014-03:06PM\" wide\n\n		$str1 = \"Download Excute\" ascii wide fullword\n        $str2 = \"EncryptorFunctionPointer %d\"\n        $str3 = \"%s\\\\%s.lnk\"\n        $str4 = \"Mac:%s-Cpu:%s-HD:%s\"\n        $str5 = \"feed back responce of host\"\n        $str6 = \"GET Token at host\"\n        $str7 = \"dwn md5 err\"\n\n    condition:\n        all of ($winver*) or any of ($pdb*) or any of ($magic*) or 2 of ($str*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('CVE_2015_1674_CNGSYS', 'Detects exploits for CVE-2015-1674', 1, 'rule CVE_2015_1674_CNGSYS {\n	meta:\n		description = \"Detects exploits for CVE-2015-1674\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		reference2 = \"https:\n		date = \"2015-05-14\"\n		hash = \"af4eb2a275f6bbc2bfeef656642ede9ce04fad36\"\n	strings:\n		$s1 = \"\\\\Device\\\\CNG\" fullword wide\n		\n		$s2 = \"GetProcAddress\" fullword ascii\n		$s3 = \"LoadLibrary\" ascii\n		$s4 = \"KERNEL32.dll\" fullword ascii\n		$s5 = \"ntdll.dll\" fullword ascii\n	condition:\n		uint16(0) == 0x5a4d and filesize < 60KB and all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Pandora', '', 1, 'rule Pandora\n{\n	meta:\n		author = \" Kevin Breen <kevin@techanarchy.net>\"\n		date = \"2014/04\"\n		ref = \"http:\n		maltype = \"Remote Access Trojan\"\n		filetype = \"exe\"\n\n	strings:\n		$a = \"Can''t get the Windows version\"\n		$b = \"=M=Q=U=Y=]=a=e=i=m=q=u=y=}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Base64_encoded_Executable', 'Detects an base64 encoded executable (often embedded)', 1, 'rule Base64_encoded_Executable {\n	meta:\n		description = \"Detects an base64 encoded executable (often embedded)\"\n		author = \"Florian Roth\"\n		date = \"2015-05-28\"\n		score = 50\n	strings:\n		$s1 = \"TVpTAQEAAAAEAAAA\n		$s2 = \"TVoAAAAAAAAAAAAAAAAAAAAAAAA\" \n		$s3 = \"TVqAAAEAAAAEABAAAAAAAAAAAAA\" \n		$s4 = \"TVpQAAIAAAAEAA8A\n		$s5 = \"TVqQAAMAAAAEAAAA\n	condition:\n		1 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Typical_Malware_String_Transforms', 'Detects typical strings in a reversed or otherwise modified form', 1, 'rule Typical_Malware_String_Transforms {\n	meta:\n		description = \"Detects typical strings in a reversed or otherwise modified form\"\n		author = \"Florian Roth\"\n		reference = \"Internal Research\"\n		date = \"2016-07-31\"\n		score = 60\n	strings:\n		\n		$e1 = \"exe.tsohcvs\" fullword ascii\n		$e2 = \"exe.ssasl\" fullword ascii\n		$e3 = \"exe.rerolpxe\" fullword ascii\n		$e4 = \"exe.erolpxei\" fullword ascii\n		$e5 = \"exe.23lldnur\" fullword ascii\n		$e6 = \"exe.dmc\" fullword ascii\n		$e7 = \"exe.llikksat\" fullword ascii\n\n		\n		$l1 = \"lld.23lenreK\" fullword ascii\n		$l2 = \"lld.ESABLENREK\" fullword ascii\n		$l3 = \"lld.esabtpyrc\" fullword ascii\n		$l4 = \"lld.trcvsm\" fullword ascii\n		$l5 = \"LLD.LLDTN\" fullword ascii\n\n		\n		$i1 = \"paeHssecorPteG\" fullword ascii\n		$i2 = \"sserddAcorPteG\" fullword ascii\n		$i3 = \"AyrarbiLdaoL\" fullword ascii\n\n		\n		$r1 = \"teSlortnoCtnerruC\" fullword ascii\n		$r2 = \"nuR\\\\noisreVtnerruC\" fullword ascii\n\n		\n		$f1 = \"\\\\23metsys\\\\\" ascii\n		$f2 = \"\\\\23metsyS\\\\\" ascii\n		$f3 = \"niB.elcyceR$\" fullword ascii\n		$f4 = \"%tooRmetsyS%\" fullword ascii\n\n		\n		$fp1 = \"Application Impact Telemetry Static Analyzer\" fullword wide\n	condition:\n		( uint16(0) == 0x5a4d and 1 of them and not 1 of ($fp*) )\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Invoke_mimikittenz', 'Detects Mimikittenz - file Invoke-mimikittenz.ps1', 1, 'rule Invoke_mimikittenz {\n	meta:\n		description = \"Detects Mimikittenz - file Invoke-mimikittenz.ps1\"\n		author = \"Florian Roth\"\n		reference = \"https:\n		date = \"2016-07-19\"\n		score = 90\n		hash1 = \"14e2f70470396a18c27debb419a4f4063c2ad5b6976f429d47f55e31066a5e6a\"\n	strings:\n		$x1 = \"[mimikittenz.MemProcInspector]\" ascii\n\n		$s1 = \"PROCESS_ALL_ACCESS = PROCESS_TERMINATE | PROCESS_CREATE_THREAD | PROCESS_SET_SESSIONID | PROCESS_VM_OPERATION |\" fullword ascii\n		$s2 = \"IntPtr processHandle = MInterop.OpenProcess(MInterop.PROCESS_WM_READ | MInterop.PROCESS_QUERY_INFORMATION, false, process.Id);\" fullword ascii\n		$s3 = \"&email=.{1,48}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('LinuxAESDDoS', '', 1, 'rule LinuxAESDDoS\n{\n    meta:\n	Author = \"@benkow_\"\n	Date = \"2014/09/12\"\n	Description = \"Strings inside\"\n        Reference = \"http:\n\n    strings:\n        $a = \"3AES\"\n        $b = \"Hacker\"\n        $c = \"VERSONEX\"\n\n    condition:\n        2 of them\n}', 1, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('LinuxBillGates', '', 1, 'rule LinuxBillGates \n{\n    meta:\n       Author      = \"@benkow_\"\n       Date        = \"2014/08/11\" \n       Description = \"Strings inside\"\n       Reference   = \"http:\n\n    strings:\n        $a= \"12CUpdateGates\"\n        $b= \"11CUpdateBill\"\n\n    condition:\n        $a and $b\n}', 1, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('LinuxElknot', '', 1, 'rule LinuxElknot\n{\n    meta:\n	Author      = \"@benkow_\"\n        Date        = \"2013/12/24\" \n        Description = \"Strings inside\"\n        Reference   = \"http:\n\n    strings:\n        $a = \"ZN8CUtility7DeCryptEPciPKci\"\n	$b = \"ZN13CThreadAttack5StartEP11CCmdMessage\"\n\n    condition:\n	all of them\n}', 1, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('LinuxMrBlack', '', 1, 'rule LinuxMrBlack\n{\n    meta:\n	Author      = \"@benkow_\"\n        Date        = \"2014/09/12\" \n        Description = \"Strings inside\"\n        Reference   = \"http:\n\n    strings:\n        $a = \"Mr.Black\"\n	$b = \"VERS0NEX:%s|%d|%d|%s\"\n    condition:\n        $a and $b\n}', 1, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('LinuxTsunami', '', 1, 'rule LinuxTsunami\n{\n    meta:\n	\n		Author      = \"@benkow_\"\n		Date        = \"2014/09/12\" \n		Description = \"Strings inside\"\n		Reference   = \"http:\n\n    strings:\n        $a = \"PRIVMSG %s :[STD]Hitting %s\"\n        $b = \"NOTICE %s :TSUNAMI <target> <secs>\"\n        $c = \"NOTICE %s :I''m having a problem resolving my host, someone will have to SPOOFS me manually.\"\n    condition:\n        $a or $b or $c\n}', 1, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('rootkit', '', 1, 'rule rootkit\n{\n	meta:\n                author=\"xorseed\"\n                reference= \"https:\n	strings:\n		$sys1 = \"sys_write\" nocase ascii wide	\n		$sys2 = \"sys_getdents\" nocase ascii wide\n		$sys3 = \"sys_getdents64\" nocase ascii wide\n		$sys4 = \"sys_getpgid\" nocase ascii wide\n		$sys5 = \"sys_getsid\" nocase ascii wide\n		$sys6 = \"sys_setpgid\" nocase ascii wide\n		$sys7 = \"sys_kill\" nocase ascii wide\n		$sys8 = \"sys_tgkill\" nocase ascii wide\n		$sys9 = \"sys_tkill\" nocase ascii wide\n		$sys10 = \"sys_sched_setscheduler\" nocase ascii wide\n		$sys11 = \"sys_sched_setparam\" nocase ascii wide\n		$sys12 = \"sys_sched_getscheduler\" nocase ascii wide\n		$sys13 = \"sys_sched_getparam\" nocase ascii wide\n		$sys14 = \"sys_sched_setaffinity\" nocase ascii wide\n		$sys15 = \"sys_sched_getaffinity\" nocase ascii wide\n		$sys16 = \"sys_sched_rr_get_interval\" nocase ascii wide\n		$sys17 = \"sys_wait4\" nocase ascii wide\n		$sys18 = \"sys_waitid\" nocase ascii wide\n		$sys19 = \"sys_rt_tgsigqueueinfo\" nocase ascii wide\n		$sys20 = \"sys_rt_sigqueueinfo\" nocase ascii wide\n		$sys21 = \"sys_prlimit64\" nocase ascii wide\n		$sys22 = \"sys_ptrace\" nocase ascii wide\n		$sys23 = \"sys_migrate_pages\" nocase ascii wide\n		$sys24 = \"sys_move_pages\" nocase ascii wide\n		$sys25 = \"sys_get_robust_list\" nocase ascii wide\n		$sys26 = \"sys_perf_event_open\" nocase ascii wide\n		$sys27 = \"sys_uname\" nocase ascii wide\n		$sys28 = \"sys_unlink\" nocase ascii wide\n		$sys29 = \"sys_unlikat\" nocase ascii wide\n		$sys30 = \"sys_rename\" nocase ascii wide\n		$sys31 = \"sys_read\" nocase ascii wide\n		$sys32 = \"kobject_del\" nocase ascii wide\n		$sys33 = \"list_del_init\" nocase ascii wide\n		$sys34 = \"inet_ioctl\" nocase ascii wide\n	condition:\n		9 of them\n}', 1, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('exploit', '', 1, 'rule exploit\n{\n        meta:\n                author=\"xorseed\"\n                reference= \"https:\n	strings:\n		$xpl1 = \"set_fs_root\" nocase ascii wide\n		$xpl2 = \"set_fs_pwd\" nocase ascii wide\n		$xpl3 = \"__virt_addr_valid\" nocase ascii wide\n		$xpl4 = \"init_task\" nocase ascii wide\n		$xpl5 = \"init_fs\" nocase ascii wide\n		$xpl6 = \"bad_file_ops\" nocase ascii wide\n		$xpl7 = \"bad_file_aio_read\" nocase ascii wide\n		$xpl8 = \"security_ops\" nocase ascii wide\n		$xpl9 = \"default_security_ops\" nocase ascii wide\n		$xpl10 = \"audit_enabled\" nocase ascii wide\n		$xpl11 = \"commit_creds\" nocase ascii wide\n		$xpl12 = \"prepare_kernel_cred\" nocase ascii wide\n		$xpl13 = \"ptmx_fops\" nocase ascii wide\n		$xpl14 = \"node_states\" nocase ascii wide\n	condition:\n		7 of them\n}', 1, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('nkminer_monero', 'Detects installer of Monero miner that points to a NK domain', 1, 'rule nkminer_monero {\n\n meta:\n\n description = \"Detects installer of Monero miner that points to a NK domain\"\n\n author = \"cdoman@alienvault.com\"\n \n reference = \"https:\n\n tlp = \"white\"\n\n license = \"MIT License\"\n\n strings:\n\n $a = \"82e999fb-a6e0-4094-aa1f-1a306069d1a5\" nocase wide ascii\n\n $b = \"4JUdGzvrMFDWrUUwY3toJATSeNwjn54LkCnKBPRzDuhzi5vSepHfUckJNxRL2gjkNrSqtCoRUrEDAgRwsQvVCjZbRy5YeFCqgoUMnzumvS\" nocase wide ascii\n\n $c = \"barjuok.ryongnamsan.edu.kp\" nocase wide ascii\n\n $d = \"C:\\\\SoftwaresInstall\\\\soft\" nocase wide ascii\n\n $e = \"C:\\\\Windows\\\\Sys64\\\\intelservice.exe\" nocase wide ascii\n\n $f = \"C:\\\\Windows\\\\Sys64\\\\updater.exe\" nocase wide ascii\n\n $g = \"C:\\\\Users\\\\Jawhar\\\\documents\\\\\" nocase wide ascii\n\n condition:\n\n any of them\n\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('NSFree', 'NSFree', 1, 'rule NSFree : Family\n{\n    meta:\n        description = \"NSFree\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-06-24\"\n        \n    condition:\n        NSFreeCode or NSFreeStrings\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Naikon', 'Naikon', 1, 'rule Naikon : Family\n{\n    meta:\n        description = \"Naikon\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-06-25\"\n        \n    condition:\n        NaikonCode or NaikonStrings\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Backdoor_Naikon_APT_Sample1', 'Detects backdoors related to the Naikon APT', 1, 'rule Backdoor_Naikon_APT_Sample1 {\n	meta:\n		description = \"Detects backdoors related to the Naikon APT\"\n		author = \"Florian Roth\"\n		reference = \"https:\n		date = \"2015-05-14\"\n		hash = \"d5716c80cba8554eb79eecfb4aa3d99faf0435a1833ec5ef51f528146c758eba\"\n		hash = \"f5ab8e49c0778fa208baad660fe4fa40fc8a114f5f71614afbd6dcc09625cb96\"\n	strings:\n		$x0 = \"GET http:\n		$x1 = \"POST http:\n		$x2 = \"greensky27.vicp.net\" fullword ascii\n		$x3 = \"\\\\tempvxd.vxd.dll\" fullword wide\n		$x4 = \"otna.vicp.net\" fullword ascii\n		$x5 = \"smithking19.gicp.net\" fullword ascii\n		\n		$s1 = \"User-Agent: webclient\" fullword ascii\n		$s2 = \"\\\\User.ini\" fullword ascii\n		$s3 = \"User-Agent: Mozilla/5.0 (Windows; U; Windows NT 5.1; zh-EN; rv:1.7.12) Gecko/200\" ascii\n		$s4 = \"\\\\UserProfile.dll\" fullword wide\n		$s5 = \"Connection:Keep-Alive: %d\" fullword ascii\n		$s6 = \"Referer: http:\n		$s7 = \"%s %s %s %d %d %d \" fullword ascii\n		$s8 = \"%s--%s\" fullword wide\n		$s9 = \"Run File Success!\" fullword wide\n		$s10 = \"DRIVE_REMOTE\" fullword wide\n		$s11 = \"ProxyEnable\" fullword wide\n		$s12 = \"\\\\cmd.exe\" fullword wide\n	condition:\n		uint16(0) == 0x5a4d and filesize < 1000KB and\n		(\n			1 of ($x*) or 7 of ($s*)\n		)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('nAspyUpdate', 'nAspyUpdate', 1, 'rule nAspyUpdate : Family\n{\n    meta:\n        description = \"nAspyUpdate\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-07-14\"\n        \n    condition:\n        nAspyUpdateCode or nAspyUpdateStrings\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('NetPass', 'netpass variant', 1, 'rule NetPass : Variant {\n        meta:\n                description = \"netpass variant\"\n                author = \"Katie Kleemola\"\n                last_updated = \"2014-07-08\"\n        condition:\n                NetpassStrings\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('NetTraveler', 'Nettravelr', 1, 'rule NetTraveler : Family {\n	meta:\n		description = \"Nettravelr\"\n		author = \"Katie Kleemola\"\n		last_updated = \"2014-07-08\"\n	\n	condition:\n		NetTravExports or NetTravStrings or NetpassStrings\n\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('NionSpy', 'Triggers on old and new variants of W32/NionSpy file infector', 1, 'rule NionSpy : win32\n{\nmeta:\ndescription = \"Triggers on old and new variants of W32/NionSpy file infector\"\nreference = \"https:\nstrings:\n$variant2015_infmarker = \"aCfG92KXpcSo4Y94BnUrFmnNk27EhW6CqP5EnT\"\n$variant2013_infmarker = \"ad6af8bd5835d19cc7fdc4c62fdf02a1\"\n$variant2013_string = \"%s?cstorage=shell&comp=%s\"\ncondition:\nuint16(0) == 0x5A4D and uint32(uint32(0x3C)) == 0x00004550 and 1 of ($variant*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('TROJAN_Notepad', '', 1, 'rule TROJAN_Notepad {\n    meta:\n        Author = \"RSA_IR\"\n        Date     = \"4Jun13\"\n        File     = \"notepad.exe v 1.1\"\n        MD5      = \"106E63DBDA3A76BEEB53A8BBD8F98927\"\n    strings:\n        $s1 = \"75BAA77C842BE168B0F66C42C7885997\"\n        $s2 = \"B523F63566F407F3834BCC54AAA32524\"\n    condition:\n        $s1 or $s2\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('leverage_a', 'OSX/Leverage.A', 1, 'rule leverage_a\n{\n	meta:\n		author = \"earada@alienvault.com\"\n		version = \"1.0\"\n		description = \"OSX/Leverage.A\"\n		date = \"2013/09\"\n	strings:\n		$a1 = \"ioreg -l | grep \\\"IOPlatformSerialNumber\\\" | awk -F\"\n		$a2 = \"+:Users:Shared:UserEvent.app:Contents:MacOS:\"\n		$a3 = \"rm ''/Users/Shared/UserEvent.app/Contents/Resources/UserEvent.icns''\"\n		$script1 = \"osascript -e ''tell application \\\"System Events\\\" to get the hidden of every login item''\"\n		$script2 = \"osascript -e ''tell application \\\"System Events\\\" to get the name of every login item''\"\n		$script3 = \"osascript -e ''tell application \\\"System Events\\\" to get the path of every login item''\"\n		$properties = \"serverVisible \\x00\"\n	condition:\n		all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Olyx', 'Olyx', 1, 'rule Olyx : Family\n{\n    meta:\n        description = \"Olyx\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-06-19\"\n        \n    condition:\n        OlyxCode or OlyxStrings\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('PittyTiger', 'Detect PittyTiger Trojan via common strings', 1, 'rule PittyTiger {\n  meta: \n    author = \" (@chort0)\"\n    description = \"Detect PittyTiger Trojan via common strings\"\n    strings: \n      $ptUserAgent = \"Mozilla/4.0 (compatible; MSIE 6.0; Windows NT 5.; SV1)\" \n      $ptFC001 = \"FC001\" fullword \n      $ptPittyTiger = \"PittyTiger\" fullword \n      $trjHTMLerr = \"trj:HTML Err.\" nocase fullword \n      $trjworkFunc = \"trj:workFunc start.\" nocase fullword \n      $trjcmdtout = \"trj:cmd time out.\" nocase fullword \n      $trjThrtout = \"trj:Thread time out.\" nocase fullword\n      $trjCrPTdone = \"trj:Create PT done.\" nocase fullword\n      $trjCrPTerr = \"trj:Create PT error: mutex already exists.\" nocase fullword \n      $oddPippeFailed = \"Create Pippe Failed!\" fullword \n      $oddXferingFile = \"Transfering File\" fullword \n      $oddParasError = \"put Paras Error:\" fullword \n      $oddCmdTOutkilled = \"Cmd Time Out..Cmd has been killed.\" fullword \ncondition: \n  (any of ($pt*)) and (any of ($trj*)) and (any of ($odd*)) \n  }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('PolishBankRAT_srservice_xorloop', 'Finds the custom xor decode loop for <PolishBankRAT_srservice>', 1, 'rule PolishBankRAT_srservice_xorloop \n{\n	meta:\n	\n		author = \"Booz Allen Hamilton Dark Labs\"\n		description = \"Finds the custom xor decode loop for <PolishBankRAT_srservice>\"\n	\n	strings:\n\n		$loop = { 48 8B CD E8 60 FF FF FF 48 FF C3 32 44 1E FF 48 FF CF 88 43 FF }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('PolishBankRAT_fdsvc_xor_loop', 'Finds the custom xor decode loop for <PolishBankRAT_fdsvc>', 1, 'rule PolishBankRAT_fdsvc_xor_loop \n{\n	meta:\n\n		author = \"Booz Allen Hamilton Dark Labs\"\n		description = \"Finds the custom xor decode loop for <PolishBankRAT_fdsvc>\"\n\n	strings:\n\n		$loop = {0F B6 42 FF 48 8D 52 FF 30 42 01 FF CF 75 F1}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('PolishBankRAT_fdsvc_decode2', 'Find a constant used as part of a payload decoding function in PolishBankRAT_fdsvc', 1, 'rule PolishBankRAT_fdsvc_decode2 \n{\n	meta:\n		\n		author = \"Booz Allen Hamilton Dark Labs\"\n		description = \"Find a constant used as part of a payload decoding function in PolishBankRAT_fdsvc\"\n\n	strings:\n		\n		$part1 = {A6 EB 96}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('decoded_PolishBankRAT_fdsvc_strings', 'Finds hard coded strings in PolishBankRAT_fdsvc', 1, 'rule decoded_PolishBankRAT_fdsvc_strings \n{\n	meta:\n\n		author = \"Booz Allen Hamilton Dark Labs\"\n		description = \"Finds hard coded strings in PolishBankRAT_fdsvc\"\n\n	strings:\n\n		$str1 = \"ssylka\" wide ascii\n		$str2 = \"ustanavlivat\" wide ascii\n		$str3 = \"poluchit\" wide ascii\n		$str4 = \"pereslat\" wide ascii\n		$str5 = \"derzhat\" wide ascii\n		$str6 = \"vykhodit\" wide ascii\n		$str7 = \"Nachalo\" wide ascii\n\n	condition:\n		\n		(uint16(0) == 0x5A4D and uint32(uint32(0x3C)) == 0x00004550) and 4 of ($str*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Trj_Ponmocup', 'Ponmocup Installer', 1, 'rule Trj_Ponmocup {\n        meta:\n                author = \"Centro Criptológico Nacional (CCN)\"\n                ref =\"https:\n                description = \"Ponmocup Installer\"\n        strings:\n                $mz = { 4d 5a }', 2, '恶意软件', 1);
