INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Trj_Ponmocup_dll', 'Ponmocup Bot DLL', 1, 'rule Trj_Ponmocup_dll {\n        meta:\n                author = \"Centro Criptológico Nacional (CCN)\"\n                ref =\"https:\n                description = \"Ponmocup Bot DLL\"\n        strings:\n                $mz = { 4d 5a }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('pony', 'Identify Pony', 1, 'rule pony {\n    meta:\n        author = \"Brian Wallace @botnet_hunter\"\n        author_email = \"bwall@ballastsecurity.net\"\n        date = \"2014-08-16\"\n        description = \"Identify Pony\"\n	strings:\n    	$s1 = \"{%08X-%04X-%04X-%02X%02X-%02X%02X%02X%02X%02X%02X}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Predator_The_Thief', 'Yara rule for Predator The Thief v2.3.5 & +', 1, 'rule Predator_The_Thief : Predator_The_Thief {\n   meta:\n        description = \"Yara rule for Predator The Thief v2.3.5 & +\"\n        author = \"Fumik0_\"\n        date = \"2018/10/12\"\n        source = \"https:\n   strings:\n        $mz = { 4D 5A }', 2, '恶意软件', 1);
