INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('MALW_PurpleWave_v1', '', 1, 'rule MALW_PurpleWave_v1\n{\n    meta:\n        Description =\"Generic rule to identify PurpleWave v1.0\"\n        Author = \"Xylitol <xylitol@temari.fr>\"\n        date = \"2020-08-01\"\n        reference = \"https:\n        hash1 = \"7de7b866c46f34be28f7085fb1a1727ab939d65abd3128871fb68c42371af2df\"\n        hash2 = \"76bffcf04104a1c4e6a5792d3795d1a03c7497a274042889b8f44c8f8facc304\"\n        hash3 = \"832d667b00c07424f050f84e717f8db22833b1e8e131aa7a33de739c4f4b4cdd\"\n        hash4 = \"917057a6a03252bc2525b326a63111fce050fc86e6e3b26fa9e452489f1358b9\"\n        hash5 = \"a8577e1ccad877ae5ff4bf89aa578989404643c6fdf10baafd4335a1766abb16\"\n        hash6 = \"d5ec98c98a8f56fdeb00cc2404c4527a39726bf43d8b9cf6c4c8c36364f94161\"\n        hash7 = \"d820ec7f9196a5cc3dbc2b5860334a2e174fede80efc3b8463756fb8767dddf9\"\n        hash8 = \"d4572e26b9e6ce963af590979afe3df6e1be78aa8ec0e926e77b0affb7ab1554\"\n        hash9 = \"4b3cb90581dcd77c9ceffbd662b8dac70b68de5a03cd56940434cc035209d61d\"\n\n    strings:\n        $MZ = {4D 5A}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('MALW_FakePyPI', 'Identifies fake PyPI Packages.', 1, 'rule MALW_FakePyPI\n{\nmeta:\n	description = \"Identifies fake PyPI Packages.\"\n	author = \"@bartblaze\"\n	reference = \"http:\n	date = \"2017-09\"\n	tlp = \"white\"\n\nstrings:	\n	$ = \"# Welcome Here! :)\"\n	$ = \"# just toy, no harm :)\"\n	$ = \"[0x76,0x21,0xfe,0xcc,0xee]\"\n\ncondition:\n	all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('PE_File_pyinstaller', 'Detect PE file produced by pyinstaller', 1, 'rule PE_File_pyinstaller\n{\n    meta:\n        author = \"Didier Stevens (https:\n        description = \"Detect PE file produced by pyinstaller\"\n        reference = \"https:\n    strings:\n        $a = \"pyi-windows-manifest-filename\"\n    condition:\n        pe.number_of_resources > 0 and $a\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('MachO_File_pyinstaller', 'Detect Mach-O file produced by pyinstaller', 1, 'rule MachO_File_pyinstaller\n{\n    meta:\n        author = \"KatsuragiCSL (https:\n        description = \"Detect Mach-O file produced by pyinstaller\"\n    strings:\n        $a = \"pyi-runtime-tmpdir\"\n        $b = \"pyi-bootloader-ignore-signals\"\n    condition:\n        any of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Quarian', 'Quarian', 1, 'rule Quarian : Family\n{\n    meta:\n        description = \"Quarian\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-07-09\"\n        \n    condition:\n        QuarianCode or QuarianStrings\n}', 2, '恶意软件', 1);
