INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('rar_with_js', '', 1, 'rule rar_with_js\n{\n  strings:\n  $h1 = \"Rar!\" \n  $s1 = \".js\" nocase\n    \n  condition:\n    $h1 at 0 and $s1\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('RockLoader', 'RockLoader Malware', 1, 'rule RockLoader{\nmeta:\nname = \"RockLoader\"\ndescription = \"RockLoader Malware\"\nauthor = \"@seanmw\"\nstrings:\n$hdr = {4d 5a 90 00}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Rooter', 'Rooter', 1, 'rule Rooter : Family\n{\n    meta:\n        description = \"Rooter\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-07-10\"\n        \n    condition:\n        RooterCode or RooterStrings\n}', 2, '恶意软件', 1);
