INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('with_sqlite', 'Rule to detect the presence of SQLite data in raw image', 1, 'rule with_sqlite : sqlite\n{\n	meta:\n		author = \"Julian J. Gonzalez <info@seguridadparatodos.es>\"\n		reference = \"http:\n		description = \"Rule to detect the presence of SQLite data in raw image\"\n	strings:\n		$hex_string = {53 51 4c 69 74 65 20 66 6f 72 6d 61 74 20 33 00}', 2, '恶意软件', 1);
