INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('hatman_compiled_python', '', 1, 'rule hatman_compiled_python : hatman {\n    condition:\n        filesize < 100KB and hatman_nullsub and hatman_setstatus and hatman_dividers\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('hatman_injector', '', 1, 'rule hatman_injector : hatman {\n    condition:\n        filesize < 100KB and hatman_injector_int and not hatman_payload_int\n}', 2, '恶意软件', 1);
