INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('priv02', '', 1, 'private rule priv02 {\n meta:\n    date = \"2018-02-10\"\n    author = \"@unixfreaxjp\"\n strings:\n    $vare01 = \"socket\" fullword nocase wide ascii\n    $vare02 = \"connect\" fullword nocase wide ascii\n    $vare03 = \"alarm\" fullword nocase wide ascii\n    $vare04 = \"dup2\" fullword nocase wide ascii\n    $vare05 = \"execl\" fullword nocase wide ascii\n    $vare06 = \"openpty\" fullword nocase wide ascii\n    $vare07 = \"putenv\" fullword nocase wide ascii\n    $vare08 = \"setsid\" fullword nocase wide ascii\n    $vare09 = \"ttyname\" fullword nocase wide ascii\n    $vare00 = \"waitpid\" fullword nocase wide ascii\n    $varc01 = \"HISTFIL\" fullword nocase wide ascii\n    $varc02 = \"TERML\" fullword nocase wide ascii\n    $varc03 = \"/bin/sh\" fullword nocase wide ascii\n condition:\n    (5 of ($vare*)\n    or (2 of ($varc*)))\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('MALW_TinyShell_backconnect_OSX', '', 1, 'rule MALW_TinyShell_backconnect_OSX {\n meta:\n    date = \"2018-02-10\"\n    author = \"@unixfreaxjp\"\n condition:\n    is__osx\n    and priv01\n    and priv02\n    and priv03\n    and priv04\n    and filesize < 100KB\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('MALW_TinyShell_backconnect_ELF', '', 1, 'rule MALW_TinyShell_backconnect_ELF {\n meta:\n    date = \"2018-02-10\"\n    author = \"@unixfreaxjp\"\n condition:\n    is__elf\n    and priv01\n    and ((priv02)\n      or ((priv03)\n        or (priv04)))\n    and filesize < 100KB\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('MALW_TinyShell_backconnect_Gen', '', 1, 'rule MALW_TinyShell_backconnect_Gen {\n meta:\n    date = \"2018-02-11\"\n    author = \"@unixfreaxjp\"\n condition:\n    ((is__elf) or  (is__osx))\n    and priv01\n    and priv02\n    and filesize < 100KB\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('MALW_TinyShell_backdoor_Gen', '', 1, 'rule MALW_TinyShell_backdoor_Gen {\n meta:\n    date = \"2018-02-11\"\n    author = \"@unixfreaxjp\"\n condition:\n    ((is__elf) or  (is__osx))\n    and priv01\n    and filesize > 20KB\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('ELF_Linux_Torte_domains', 'Detects ELF Linux/Torte infection', 1, 'rule ELF_Linux_Torte_domains {\n	meta:\n		author = \"@mmorenog,@yararules\"\n		description = \"Detects ELF Linux/Torte infection\"\n		ref1 = \"http:\n	strings:\n		$1 = \"pages.touchpadz.com\" ascii wide nocase\n		$2 = \"bat.touchpadz.com\" ascii wide nocase\n		$3 = \"stat.touchpadz.com\" ascii wide nocase\n		$4 = \"sk2.touchpadz.com\" ascii wide nocase\n\n	condition:\n		any of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('TreasureHunt', '', 1, 'rule TreasureHunt\n  {\n    meta:\n      author = \"Minerva Labs\"\n      ref =\"http:\n      date = \"2016/06\"\n      maltype = \"Point of Sale (POS) Malware\"\n      filetype = \"exe\"\n\n    strings:\n      $a = \"treasureHunter.pdb\"\n      $b = \"jucheck\"\n      $c = \"cmdLineDecrypted\"\n\n    condition:\n      all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('MALW_trickbot_bankBot', 'Detects Trickbot Banking Trojan', 1, 'rule MALW_trickbot_bankBot : Trojan\n{\nmeta:\n author = \"Marc Salinas @Bondey_m\"\n description = \"Detects Trickbot Banking Trojan\"\nstrings:\n$str_trick_01 = \"moduleconfig\"\n$str_trick_02 = \"Start\"\n$str_trick_03 = \"Control\"\n$str_trick_04 = \"FreeBuffer\"\n$str_trick_05 = \"Release\"\ncondition:\nall of ($str_trick_*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('MALW_systeminfo_trickbot_module', 'Detects systeminfo module from Trickbot Trojan', 1, 'rule MALW_systeminfo_trickbot_module :\nTrojan\n{\nmeta:\nauthor = \"Marc Salinas @Bondey_m\"\ndescription = \"Detects systeminfo module from Trickbot Trojan\"\nstrings:\n$str_systeminf_01 = \"<program>\"\n$str_systeminf_02 = \"<service>\"\n$str_systeminf_03 = \"</systeminfo>\"\n$str_systeminf_04 =\n\"GetSystemInfo.pdb\"\n$str_systeminf_05 = \"</autostart>\"\n$str_systeminf_06 = \"</moduleconfig>\"\ncondition:\nall of ($str_systeminf_*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('MALW_dllinject_trickbot_module', ' Detects dllinject module from Trickbot Trojan', 1, 'rule MALW_dllinject_trickbot_module : Trojan\n{\nmeta:\nauthor = \"Marc Salinas @Bondey_m\"\ndescription = \" Detects dllinject module from Trickbot Trojan\"\nstrings:\n$str_dllinj_01 = \"user_pref(\"\n$str_dllinj_02 = \"<ignore_mask>\"\n$str_dllinj_03 = \"<require_header>\"\n$str_dllinj_04 = \"</dinj>\"\ncondition:\nall of ($str_dllinj_*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('MALW_mailsercher_trickbot_module', ' Detects mailsearcher module from Trickbot Trojan', 1, 'rule MALW_mailsercher_trickbot_module :\nTrojan\n{\nmeta:\nauthor = \"Marc Salinas @Bondey_m\"\ndescription = \" Detects mailsearcher module from Trickbot Trojan\"\nstrings:\n$str_mails_01 = \"mailsearcher\"\n$str_mails_02 = \"handler\"\n$str_mails_03 = \"conf\"\n$str_mails_04 = \"ctl\"\n$str_mails_05 = \"SetConf\"\n$str_mails_06 = \"file\"\n$str_mails_07 = \"needinfo\"\n$str_mails_08 = \"mailconf\"\ncondition:\nall of ($str_mails_*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('TrumpBot', 'TrumpBot', 1, 'rule TrumpBot : MALW\n{\n	meta:\n		description = \"TrumpBot\"\n		author = \"Joan Soriano / @joanbtl\"\n		date = \"2017-04-16\"\n		version = \"1.0\"\n		MD5 = \"77122e0e6fcf18df9572d80c4eedd88d\"\n		SHA1 = \"108ee460d4c11ea373b7bba92086dd8023c0654f\"\n\n	strings:\n		$string = \"trumpisdaddy\"\n		$ip = \"198.50.154.188\"\n	condition:\n		 all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Upatre_Hazgurut', 'Detects Upatre malware - file hazgurut.exe', 1, 'rule Upatre_Hazgurut {\n	meta:\n		description = \"Detects Upatre malware - file hazgurut.exe\"\n		author = \"Florian Roth\"\n		reference = \"https:\n		date = \"2015-10-13\"\n		score = 70\n		hash1 = \"7ee0d20b15e24b7fe72154d9521e1959752b4e9c20d2992500df9ac096450a50\"\n		hash2 = \"79ffc620ddb143525fa32bc6a83c636168501a4a589a38cdb0a74afac1ee8b92\"\n		hash3 = \"62d8a6880c594fe9529158b94a9336179fa7a3d3bf1aa9d0baaf07d03b281bd3\"\n		hash4 = \"c64282aca980d558821bec8b3dfeae562d9620139dc43d02ee4d1745cd989f2a\"\n		hash5 = \"a35f9870f9d4b993eb094460b05ee1f657199412807abe6264121dd7cc12aa70\"\n		hash6 = \"f8cb2730ebc8fac1c58da1346ad1208585fe730c4f03d976eb1e13a1f5d81ef9\"\n		hash7 = \"b65ad7e2d299d6955d95b7ae9b62233c34bc5f6aa9f87dc482914f8ad2cba5d2\"\n		hash8 = \"6b857ef314938d37997c178ea50687a281d8ff9925f0c4e70940754643e2c0e3\"\n		hash9 = \"33a288cef0ae7192b34bd2ef3f523dfb7c6cbc2735ba07edf988400df1713041\"\n		hash10 = \"2a8e50afbc376cb2a9700d2d83c1be0c21ef942309676ecac897ba4646aba273\"\n		hash11 = \"3d0f2c7e07b7d64b1bad049b804ff1aae8c1fc945a42ad555eca3e1698c7f7d3\"\n		hash12 = \"951360b32a78173a1f81da0ded8b4400e230125d05970d41621830efc5337274\"\n		hash13 = \"bd90faebfd7663ef89b120fe69809532cada3eb94bb94094e8bc615f70670295\"\n		hash14 = \"8c5823f67f9625e4be39a67958f0f614ece49c18596eacc5620524bc9b6bad3d\"\n	strings:\n		$a1 = \"barcod\" fullword ascii\n\n		$s0 = \"msports.dll\" fullword ascii\n		$s1 = \"nddeapi.dll\" fullword ascii\n		$s2 = \"glmf32.dll\" fullword ascii\n		$s3 = \"<requestedExecutionLevel level=\\\"requireAdministrator\\\" uiAccess=\\\"false\\\">\" fullword ascii\n		$s4 = \"cmutil.dll\" fullword ascii\n		$s5 = \"mprapi.dll\" fullword ascii\n		$s6 = \"glmf32.dll\" fullword ascii\n	condition:\n		uint16(0) == 0x5a4d and filesize < 1500KB\n		and $a1 in (0..4000)\n		and all of ($s*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('urausy_skype_dat', 'Yara rule to match against memory of processes infected by Urausy skype.dat', 1, 'rule urausy_skype_dat : memory {\n	meta:\n		author = \"AlienVault Labs\"\n		description = \"Yara rule to match against memory of processes infected by Urausy skype.dat\"\n	strings:\n		$a = \"skype.dat\" ascii wide\n		$b = \"skype.ini\" ascii wide\n		$win1 = \"CreateWindow\"\n		$win2 = \"YIWEFHIWQ\" ascii wide\n		$desk1 = \"CreateDesktop\"\n		$desk2 = \"MyDesktop\" ascii wide\n	condition:\n		$a and $b and (all of ($win*) or all of ($desk*))\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Vidgrab', 'Vidgrab', 1, 'rule Vidgrab : Family\n{\n    meta:\n        description = \"Vidgrab\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-06-20\"\n        \n    condition:\n        VidgrabCode or VidgrabStrings\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('VirutFileInfector', 'Virut (unknown version) fileinfector detection', 1, 'rule VirutFileInfector\n{\n	meta:\n    	author = \"D00RT <@D00RT_RM>\"\n    	data = \"2017/08/04\"\n\n        description = \"Virut (unknown version) fileinfector detection\"\n        reference = \"http:\n\n        infected_sample1 = \"5755f09d445a5dcab3ea92d978c7c360\"\n        infected_sample2 = \"68e508108ed94c8c391c70ef1d15e0f8\"\n        infected_sample2 = \"2766e8e78ee10264cf1a3f5f4a16ff00\"\n\n	strings:\n    	$sign = { F9 E8 22 00 00 00 ?? 31 EB 56 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('volgmer', 'Malformed User Agent', 1, 'rule volgmer\n{\nmeta:\n    description = \"Malformed User Agent\"\n    ref = \"https:\nstrings:\n    $s = \"Mozillar/\"\ncondition:\n    (uint16(0) == 0x5A4D and uint16(uint32(0x3c)) == 0x4550) and $s\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Wabot', 'Wabot Trojan Worm', 1, 'rule Wabot : Worm\n{\n	meta:\n		author=\"Kevin Falcoz\"\n		date=\"14/08/2015\"\n		description=\"Wabot Trojan Worm\"\n\n	strings:\n		$signature1={43 3A 5C 6D 61 72 69 6A 75 61 6E 61 2E 74 78 74}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Warp', 'Warp', 1, 'rule Warp : Family\n{\n    meta:\n        description = \"Warp\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-07-10\"\n        \n    condition:\n        WarpCode or WarpStrings\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Wimmie', 'Wimmie family', 1, 'rule Wimmie : Family\n{\n    meta:\n        description = \"Wimmie family\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-07-17\"\n   \n    condition:\n        WimmieShellcode or WimmieStrings\n        \n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('XHide', 'XHide - Process Faker', 1, 'rule XHide: MALW\n{\n	meta:\n		description = \"XHide - Process Faker\"\n		author = \"Joan Soriano / @w0lfvan\"\n		date = \"2017-12-01\"\n		version = \"1.0\"\n		MD5 = \"c644c04bce21dacdeb1e6c14c081e359\"\n		SHA256 = \"59f5b21ef8a570c02453b5edb0e750a42a1382f6\"\n	strings:\n		$a = \"XHide - Process Faker\"\n		$b = \"Fakename: %s PidNum: %d\"\n	condition:\n		all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('XMRIG_Miner', '', 1, 'rule XMRIG_Miner\n{\n	meta:\n  ref = \"https:\n  strings:\n    $a1 = \"stratum+tcp\"\n    condition:\n    $a1  \n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('XOR_DDosv1', 'Rule to detect XOR DDos infection', 1, 'rule XOR_DDosv1 : DDoS\n{\n  meta:\n    author = \"Akamai CSIRT\"\n    description = \"Rule to detect XOR DDos infection\"\n  strings:\n    $st0 = \"BB2FA36AAA9541F0\"\n    $st1 = \"md5=\"\n    $st2 = \"denyip=\"\n    $st3 = \"filename=\"\n    $st4 = \"rmfile=\"\n    $st5 = \"exec_packet\"\n    $st6 = \"build_iphdr\"\n  condition:\n    all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Yayih', 'Yayih', 1, 'rule Yayih : Family\n{\n    meta:\n        description = \"Yayih\"\n        author = \"Seth Hardy\"\n        last_modified = \"2014-07-11\"\n        \n    condition:\n        YayihCode or YayihStrings\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('yordanyan_activeagent', 'Memory string yara for Yordanyan ActiveAgent', 1, 'rule yordanyan_activeagent {\n	meta:\n		description = \"Memory string yara for Yordanyan ActiveAgent\"\n		author = \"J from THL <j@techhelplist.com>\"\n		reference1 = \"https:\n		reference2 = \"ETPRO TROJAN Win32.ActiveAgent CnC Create\"\n		date = \"2018-10-04\"\n		maltype = \"Botnet\"\n		filetype = \"memory\"\n\n	strings:\n		\n		$s01 = \"I''m KeepRunner!\" wide\n		$s02 = \"I''m Updater!\" wide\n		$s03 = \"Starting Download...\" wide\n		$s04 = \"Download Complete!\" wide\n		$s05 = \"Running New Agent and terminating updater!\" wide\n		$s06 = \"Can''t Run downloaded file!\" wide\n		$s07 = \"Retrying download and run!\" wide\n		$s08 = \"Can''t init Client.\" wide\n		$s09 = \"Client initialised -\" wide\n		$s10 = \"Client not found!\" wide\n		$s11 = \"Client signed.\" wide\n		$s12 = \"GetClientData\" wide\n		$s13 = \"&counter=\" wide\n		$s14 = \"&agent_file_version=\" wide\n		$s15 = \"&agent_id=\" wide\n		$s16 = \"mac_address=\" wide\n		$s17 = \"Getting Attachments\" wide\n		$s18 = \"public_name\" wide\n		$s19 = \"Yor agent id =\" wide\n		$s20 = \"Yor agent version =\" wide\n		$s21 = \"Last agent version =\" wide\n		$s22 = \"Agent is last version.\" wide\n		$s23 = \"Updating Agent\" wide\n		$s24 = \"Terminating RunKeeper\" wide\n		$s25 = \"Terminating RunKeeper: Done\" wide\n		$s26 = \"ActiveAgent\" ascii\n		$s27 = \"public_name\" ascii\n\n	condition:\n		15 of them\n\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Zegost', 'Zegost Trojan', 1, 'rule Zegost : Trojan\n{\n	meta:\n		author=\"Kevin Falcoz\"\n		date=\"10/06/2013\"\n		description=\"Zegost Trojan\"\n		\n	strings:\n		$signature1={39 2F 66 33 30 4C 69 35 75 62 4F 35 44 4E 41 44 44 78 47 38 73 37 36 32 74 71 59 3D}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Windows_Malware_Zeus', 'Match first two bytes, protocol and string present in Zeus 1.1.3.4', 1, 'rule Windows_Malware_Zeus : Zeus_1134\n    {\n            meta:\n                    author = \"Xylitol xylitol@malwareint.com\"\n                    date = \"2014-03-03\"\n                    description = \"Match first two bytes, protocol and string present in Zeus 1.1.3.4\"\n                    reference = \"http:\n                    \n            strings:\n                    $mz = {4D 5A}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Adwind', 'Adwind RAT', 1, 'rule Adwind\n{\nmeta:\n        author=\"Asaf Aprozper, asafa AT minerva-labs.com\"\n        description = \"Adwind RAT\"\n        reference = \"https:\n        last_modified = \"2017-06-25\"\nstrings:\n        $a0 = \"META-INF/MANIFEST.MF\"\n        $a1 = /Main(\\$)Q[0-9][0-9][0-9][0-9]/\n        $PK = \"PK\"\ncondition:\n        $PK at 0 and $a0 and $a1\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('hancitor', 'Memory string yara for Hancitor', 1, 'rule hancitor {\n	meta:\n		description = \"Memory string yara for Hancitor\"\n		author = \"J from THL <j@techhelplist.com>\"\n		reference1 = \"https:\n		reference2 = \"https:\n		reference3 = \"https:\n		date = \"2018-09-18\"\n		maltype1 = \"Botnet\"\n		filetype = \"memory\"\n\n	strings:\n		$a = \"GUID=\"	ascii\n                $b = \"&BUILD=\"	ascii\n                $c = \"&INFO=\"	ascii\n                $d = \"&IP=\"	ascii\n                $e = \"&TYPE=\" 	ascii\n                $f = \"php|http\"	ascii\n		$g = \"GUID=%I64u&BUILD=%s&INFO=%s&IP=%s&TYPE=1&WIN=%d.%d\" ascii fullword\n\n\n	condition:\n		5 of ($a,$b,$c,$d,$e,$f) or $g\n\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('mimikatz_kirbi_ticket', 'KiRBi ticket for mimikatz', 1, 'rule mimikatz_kirbi_ticket\n{\n	meta:\n		description		= \"KiRBi ticket for mimikatz\"\n		author			= \"Benjamin DELPY (gentilkiwi); Didier Stevens\"\n\n	strings:\n		$asn1			= { 76 82 ?? ?? 30 82 ?? ?? a0 03 02 01 05 a1 03 02 01 16 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('kpot', '', 1, 'rule kpot\n{\n\n    meta:\n        author = \" J from THL <j@techhelplist.com>\"\n        date = \"2018-08-29\"\n        reference1 = \"https:\n        reference2 = \"ETPRO TROJAN KPOT Stealer Check-In [2832358]\"\n        reference3 = \"ETPRO TROJAN KPOT Stealer Exfiltration [2832359]\"\n        version = 1\n        maltype = \"Stealer\"\n        filetype = \"memory\"\n\n    strings:\n        $text01 = \"bot_id=%s\"\n        $text02 = \"x64=%d\"\n        $text03 = \"is_admin=%d\"\n        $text04 = \"IL=%d\"\n        $text05 = \"os_version=%d\"\n        $text06 = \"IP: %S\"\n        $text07 = \"MachineGuid: %s\"\n        $text08 = \"CPU: %S (%d cores)\"\n        $text09 = \"RAM: %S MB\"\n        $text10 = \"Screen: %dx%d\"\n        $text11 = \"PC: %s\"\n        $text12 = \"User: %s\"\n        $text13 = \"LT: %S (UTC+%d:%d)\"\n        $text14 = \"%s/%s.php\"\n        $text15 = \"Host: %s\"\n        $text16 = \"username_value\"\n        $text17 = \"password_value\"\n        $text18 = \"name_on_card\"\n        $text19 = \"last_four\"\n        $text20 = \"exp_month\"\n        $text21 = \"exp_year\"\n        $text22 = \"bank_name\"\n\n\n    condition:\n        16 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('marap', '', 1, 'rule marap \n{\n\n    meta:\n        author = \" J from THL <j@techhelplist.com>\"\n        date = \"2018-08-19\"\n        reference1 = \"https:\n        reference2 = \"https:\n        reference3 = \"https:\n        reference4 = \"https:\n        version = 1\n        maltype = \"Downloader\"\n        filetype = \"memory\"\n\n    strings:\n        $text01 = \"%02X-%02X-%02X-%02X-%02X-%02X\" wide\n        $text02 = \"%s, base=0x%p\" wide\n        $text03 = \"pid=%d\" wide\n        $text04 = \"%s %s\" wide\n        $text05 = \"%d|%d|%s|%s|%s\" wide\n        $text06 = \"%s|1|%d|%d|%d|%d|%d|%s\" wide\n        $text07 = \"%d#%s#%s#%s#%d#%s#%s#%d#%s#%s#%s#%s#%d\" wide\n        $text08 = \"%s|1|%d|%d|%d|%d|%d|%s#%s#%s#%s#%d#%d#%d\" wide\n        $text09 = \"%s|0|%d\" wide\n        $text10 = \"%llx\" wide\n        $text11 = \"%s -a\" wide\n\n    condition:\n        7 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('shifu_shiz', 'Memory string yara for Shifu/Shiz', 1, 'rule shifu_shiz {\n	meta:\n		description = \"Memory string yara for Shifu/Shiz\"\n		author = \"J from THL <j@techhelplist.com>\"\n		reference1 = \"https:\n		reference2 = \"https:\n    reference3 = \"https:\n		date = \"2018-03-16\"\n		maltype1 = \"Banker\"\n		maltype2 = \"Keylogger\"\n		maltype3 = \"Stealer\"\n		filetype = \"memory\"\n\n	strings:\n		$aa = \"auth_loginByPassword\"	fullword ascii\n		$ab = \"back_command\"	fullword ascii\n		$ac = \"back_custom1\"	fullword ascii\n		$ad = \"GetClipboardData\"	fullword ascii\n		$ae = \"iexplore.exe|opera.exe|java.exe|javaw.exe|explorer.exe|isclient.exe|intpro.exe|ipc_full.exe\"	fullword ascii\n		$af = \"mnp.exe|cbsmain.dll|firefox.exe|clmain.exe|core.exe|maxthon.exe|avant.exe|safari.exe\"	fullword ascii\n		$ag = \"svchost.exe|chrome.exe|notepad.exe|rundll32.exe|netscape.exe|tbb-firefox.exe|frd.exe\"	fullword ascii\n		$ah = \"!inject\"	fullword ascii\n		$ai = \"!deactivebc\"	fullword ascii\n		$aj = \"!kill_os\"	fullword ascii\n		$ak = \"!load\"	fullword ascii\n		$al = \"!new_config\"	fullword ascii\n		$am = \"!activebc\"	fullword ascii\n		$an = \"keylog.txt\"	fullword ascii\n		$ao = \"keys_path.txt\"	fullword ascii\n		$ap = \"pass.log\"	fullword ascii\n		$aq = \"passwords.txt\"	fullword ascii\n		$ar = \"Content-Disposition: form-data; name=\\\"file\\\"; filename=\\\"report\\\"\"	fullword ascii\n		$as = \"Content-Disposition: form-data; name=\\\"pcname\\\"\"	fullword ascii\n		$at = \"botid=%s&ver=\"	fullword ascii\n		$au = \"action=auth&np=&login=\"	fullword ascii\n		$av = \"&ctl00%24MainMenu%24Login1%24UserName=\"	fullword ascii\n		$aw = \"&cvv=\"	fullword ascii\n		$ax = \"&cvv2=\"	fullword ascii\n		$ay = \"&domain=\"	fullword ascii\n		$az = \"LOGIN_AUTHORIZATION_CODE=\"	fullword ascii\n		$ba = \"name=%s&port=%u\"	fullword ascii\n		$bb = \"PeekNamedPipe\"	fullword ascii\n		$bc = \"[pst]\"	fullword ascii\n		$bd = \"[ret]\"	fullword ascii\n		$be = \"[tab]\"	fullword ascii\n		$bf = \"[bks]\"	fullword ascii\n		$bg = \"[del]\"	fullword ascii\n		$bh = \"[ins]\"	fullword ascii\n		$bi = \"&up=%u&os=%03u&rights=%s&ltime=%s%d&token=%d&cn=\"	fullword ascii\n\n	condition:\n		18 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('sitrof_fortis_scar', '', 1, 'rule sitrof_fortis_scar {\n\n    meta:\n        author = \"J from THL <j@techhelplist.com>\"\n        date = \"2018/23\"\n        reference1 = \"https:\n	reference2 = \"ETPRO rule 2806032, ETPRO TROJAN Win32.Scar.hhrw POST\"\n	version = 2\n        maltype = \"Stealer\"\n        filetype = \"memory\"\n\n    strings:\n	\n	$a = \"?get&version\"\n	$b = \"?reg&ver=\"\n	$c = \"?get&exe\"\n	$d = \"?get&download\"\n	$e = \"?get&module\"\n	$f = \"&ver=\"\n	$g = \"&comp=\"\n	$h = \"&addinfo=\"\n	$i = \"%s@%s; %s %s \\\"%s\\\" processor(s)\"\n	$j = \"User-Agent: fortis\"\n\n    condition:\n        6 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('viotto_keylogger', '', 1, 'rule viotto_keylogger\n{\nstrings:\n	$hdr = \"MZ\"\n	$s1 = \"Viotto Keylogger\"\n	$s2 = \"msvbvm60\"\n	$s3 = \"FtpPutFileA\"\n	$s4 = \"VBA6\"\n	$s5 = \"SetWindowsHookExA\"\ncondition:\n	($hdr at 0) and all of ($s*)\n\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('xDedic_SysScan_unpacked', '', 1, 'rule xDedic_SysScan_unpacked : crimeware {\nmeta:\nauthor = \" Kaspersky Lab\"\nref = \"https:\nmaltype = \"crimeware\"\ntype =\"crimeware\"\nfiletype = \"Win32 EXE\"\ndate = \"2016-03-14\"\nversion = \"1.0\"\nhash = \"fac495be1c71012682ebb27092060b43\"\nhash = \"e8cc69231e209db7968397e8a244d104\"\nhash = \"a53847a51561a7e76fd034043b9aa36d\"\nhash = \"e8691fa5872c528cd8e72b82e7880e98\"\nhash = \"F661b50d45400e7052a2427919e2f777\"\nstrings:\n$a1=\"/c ping -n 2 127.0.0.1 & del \\\"SysScan.exe\\\"\" ascii wide\n$a2=\"SysScan DEBUG Mode!!!\" ascii wide\n$a3=\"This rechecking? (set 0/1 or press enter key)\" ascii wide\n$a4=\"http:\n$b1=\"Checker end work!\" ascii wide\n$b2=\"Trying send result...\" ascii wide\ncondition:\n((uint16(0) == 0x5A4D)) and (filesize < 5000000) and\n((any of ($a*)) or (all of ($b*)))\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('xdedic_packed_syscan', '', 1, 'rule xdedic_packed_syscan : crimeware {\nmeta:\nauthor = \"Kaspersky Lab\"\ncompany = \"Kaspersky Lab\"\nref = \"https:\nstrings:\n$a1 = \"SysScan.exe\" nocase ascii wide\ncondition:\nuint16(0) == 0x5A4D\nand any of ($a*) and filesize > 1000000 and filesize <1200000 and\npe.number_of_sections == 13 and pe.version_info[\"FileVersion\"] contains \"1.3.4.\"\n}', 2, '恶意软件', 1);
