INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('easterjackpos', 'Identify JackPOS', 1, 'rule easterjackpos {\n    meta:\n        author = \"Brian Wallace @botnet_hunter\"\n        author_email = \"bwall@ballastsecurity.net\"\n        date = \"2014-09-02\"\n        description = \"Identify JackPOS\"\n	strings:\n	    $s1 = \"updateinterval=\"\n        $s2 = \"cardinterval=\"\n        $s3 = \"{[!17!]}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('LogPOS', 'Detects Versions of LogPOS', 1, 'rule LogPOS\n{\n    meta:\n        author = \"Morphick Security\"\n        description = \"Detects Versions of LogPOS\"\n        md5 = \"af13e7583ed1b27c4ae219e344a37e2b\"\n    strings:\n        $mailslot = \"\\\\\\\\.\\\\mailslot\\\\LogCC\"\n        $get = \"GET /%s?encoding=%c&t=%c&cc=%I64d&process=\"\n        \n        \n        \n        \n        $sc = {64 A1 30 00 00 00 8B 40 0C 8B 40 1C 8B 40 08 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('PoS_Malware_MalumPOS', 'Used to detect MalumPOS memory dumper', 1, 'rule PoS_Malware_MalumPOS\n{\n    meta:\n        author = \"Trend Micro, Inc.\"\n        date = \"2015-05-25\"\n        description = \"Used to detect MalumPOS memory dumper\"\n        sample_filtype = \"exe\"\n    strings:\n        $string1 = \"SOFTWARE\\\\Borland\\\\Delphi\\\\RTL\"\n        $string2 = \"B)[0-9]{13,19}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Mozart', 'Detects samples of the Mozart POS RAM scraping utility', 1, 'rule Mozart\n{\n   meta:\n       author = \"Nick Hoffman - Morphick Inc\"\n       description = \"Detects samples of the Mozart POS RAM scraping utility\"\n       reference = \"http:\n   strings:\n       $pdb = \"z:\\\\Slender\\\\mozart\\\\mozart\\\\Release\\\\mozart.pdb\" nocase wide ascii\n       $output = {67 61 72 62 61 67 65 2E 74 6D 70 00}', 2, '恶意软件', 1);
