INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Ransom_Satana', 'Regla para detectar Ransom.Satana', 1, 'rule Ransom_Satana\n{\n    meta:\n        description = \"Regla para detectar Ransom.Satana\"\n        author = \"CCN-CERT\"\n        version = \"1.0\"\n    strings:\n        $a = { 21 00 73 00 61 00 74 00 61 00 6E 00 61 00 21 00 2E 00 74 00 78 00 74 00 00 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Ransom_Satana_Dropper', 'Regla para detectar el dropper de Ransom.Satana', 1, 'rule Ransom_Satana_Dropper\n{\n    meta:\n        description = \"Regla para detectar el dropper de Ransom.Satana\"\n        author = \"CCN-CERT\"\n        version = \"1.0\"\n    strings:\n        $a = { 25 73 2D 54 72 79 45 78 63 65 70 74 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('unpacked_shiva_ransomware', 'Rule to detect an unpacked sample of Shiva ransopmw', 1, 'rule unpacked_shiva_ransomware {\n\n   meta:\n\n      description = \"Rule to detect an unpacked sample of Shiva ransopmw\"\n      author = \"Marc Rivero | @seifreed\"\n      reference = \"https:\n    \n   strings:\n\n      $s1 = \"c:\\\\Users\\\\sys\\\\Desktop\\\\v 0.5\\\\Shiva\\\\Shiva\\\\obj\\\\Debug\\\\shiva.pdb\" fullword ascii\n      $s2 = \"This email will be as confirmation you are ready to pay for decryption key.\" fullword wide\n      $s3 = \"Your important files are now encrypted due to a security problem with your PC!\" fullword wide\n      $s4 = \"write.php?info=\" fullword wide\n      $s5 = \" * Do not try to decrypt your data using third party software, it may cause permanent data loss.\" fullword wide\n      $s6 = \" * Do not rename encrypted files.\" fullword wide\n      $s7 = \".compositiontemplate\" fullword wide\n      $s8 = \"You have to pay for decryption in Bitcoins. The price depends on how fast you write to us.\" fullword wide\n      $s9 = \"\\\\READ_IT.txt\" fullword wide\n      $s10 = \".lastlogin\" fullword wide\n      $s11 = \".logonxp\" fullword wide\n      $s12 = \" * Decryption of your files with the help of third parties may cause increased price\" fullword wide\n      $s13 = \"After payment we will send you the decryption tool that will decrypt all your files.\" fullword wide\n   \n   condition:\n\n      ( uint16(0) == 0x5a4d and filesize < 800KB ) and all of them \n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('sigma_ransomware', '', 1, 'rule sigma_ransomware {\n\n  meta:\n    author = \"J from THL <j@techhelplist.com>\"\n    date = \"20180509\"\n    reference1 = \"https:\n    reference2 = \"https:\n    version = 1\n    maltype = \"Ransomware\"\n    filetype = \"memory\"\n\n  strings:\n    $a = \".php?\"\n    $b = \"uid=\"\n    $c = \"&uname=\"\n    $d = \"&os=\"\n    $e = \"&pcname=\"\n    $f = \"&total=\"\n    $g = \"&country=\"\n    $h = \"&network=\"\n    $i = \"&subid=\"\n\n  condition:\n    all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('SnakeRansomware', '', 1, 'rule SnakeRansomware\n{\n    meta:\n        Author = \"Nishan Maharjan\"\n        Description = \"A yara rule to catch snake ransomware\"\n        Reference = \"https:\n        Data = \"15th May 2020\"\n    strings:\n        $go_build_id = \"Go build ID: \\\"X6lNEpDhc_qgQl56x4du/fgVJOqLlPCCIekQhFnHL/rkxe6tXCg56Ez88otHrz/Y-lXW-OhiIbzg3-ioGRz\\\"\"\n        $math_rand_seed_calling = { 89 C8 BB 00 CA 9A 3B 89 D1 F7 E3 81 E1 FF FF FF 3F 89 C3 01 C8 89 C6 05 00 00 1A 3D 89 04 24 69 ED 00 CA 9A 3B 01 EA 89 CD C1 F9 1F 01 EB 11 CA 81 C6 00 00 1A 3D 81 D2 EB 03 B2 A1 89 54 24 04 E8 10 62 F6 FF }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('stampado_overlay', 'Catches Stampado samples looking for \\\\r at the beginning of PE overlay section', 1, 'rule stampado_overlay\n{\nmeta:\ndescription = \"Catches Stampado samples looking for \\\\r at the beginning of PE overlay section\"\nreference = \"\"\nauthor = \"Fernando Merces, FTR, Trend Micro\"\ndate = \"2016-07\"\nmd5 = \"a393b9536a1caa34914636d3da7378b5\"\nmd5 = \"dbf3707a9cd090853a11dda9cfa78ff0\"\nmd5 = \"dd5686ca7ec28815c3cf3ed3dbebdff2\"\nmd5 = \"6337f0938e4a9c0ef44ab99deb0ef466\"\n\ncondition:\npe.characteristics == 0x122 and\npe.number_of_sections == 5 and\npe.imports(\"VERSION.dll\", \"VerQueryValueW\") and uint8(pe.sections[4].raw_data_offset + pe.sections[4].raw_data_size) == 0x0d\n\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('TeslaCrypt', 'Regla para detectar Tesla con md5', 1, 'rule TeslaCrypt {\nmeta:\n    description = \"Regla para detectar Tesla con md5\"\n    author = \"CCN-CERT\"\n    version = \"1.0\"\nstrings:\n    $ = { 4E 6F 77 20 69 74 27 73 20 25 49 3A 25 4D 25 70 2E 00 00 00 76 61 6C 20 69 73 20 25 64 0A 00 00 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('screenlocker_acroware', 'Rule to detect Acroware ScreenLocker', 1, 'rule screenlocker_acroware {\n\n   meta:\n\n      description = \"Rule to detect Acroware ScreenLocker\"\n      author = \"Marc Rivero | @seifreed\"\n      reference = \"https:\n      \n   strings:\n\n      $s1 = \"C:\\\\Users\\\\patri\\\\Documents\\\\Visual Studio 2015\\\\Projects\\\\Advanced Ransi\\\\Advanced Ransi\\\\obj\\\\Debug\\\\Advanced Ransi.pdb\" fullword ascii\n      $s2 = \"All your Personal Data got encrypted and the decryption key is stored on a hidden\" fullword ascii\n      $s3 = \"alphaoil@mail2tor.com any try of removing this Ransomware will result in an instantly \" fullword ascii\n      $s4 = \"HKEY_CURRENT_USER\\\\SoftwareE\\\\Microsoft\\\\Windows\\\\CurrentVersion\\\\Run\" fullword wide\n      $s5 = \"webserver, after 72 hours the decryption key will get removed and your personal\" fullword ascii\n      \n   condition:\n      ( uint16(0) == 0x5a4d and filesize < 2000KB ) and all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('jeff_dev_ransomware', 'Rule to detect Jeff DEV Ransomware', 1, 'rule jeff_dev_ransomware {\n\n   meta:\n   \n      description = \"Rule to detect Jeff DEV Ransomware\"\n      author = \"Marc Rivero | @seifreed\"\n      reference = \"https:\n      \n   strings:\n\n      $s1 = \"C:\\\\Users\\\\Umut\\\\Desktop\\\\takemeon\" fullword wide\n      $s2 = \"C:\\\\Users\\\\Umut\\\\Desktop\\\\\" fullword ascii\n      $s3 = \"PRESS HERE TO STOP THIS CREEPY SOUND AND VIEW WHAT HAPPENED TO YOUR COMPUTER\" fullword wide\n      $s4 = \"WHAT YOU DO TO MY COMPUTER??!??!!!\" fullword wide\n\n   condition:\n\n      ( uint16(0) == 0x5a4d and filesize < 5000KB ) and all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('locdoor_ransomware', 'Rule to detect Locdoor/DryCry', 1, 'rule locdoor_ransomware {\n\n   meta:\n\n      description = \"Rule to detect Locdoor/DryCry\"\n      author = \"Marc Rivero | @seifreed\"\n      reference = \"https:\n\n   strings:\n\n      $s1 = \"copy \\\"Locdoor.exe\\\" \\\"C:\\\\ProgramData\\\\Microsoft\\\\Windows\\\\Start Menu\\\\Programs\\\\StartUp\\\\temp00000000.exe\\\"\" fullword ascii\n      $s2 = \"copy wscript.vbs C:\\\\ProgramData\\\\Microsoft\\\\Windows\\\\Start Menu\\\\Programs\\\\StartUp\\\\wscript.vbs\" fullword ascii\n      $s3 = \"!! Your computer''s important files have been encrypted! Your computer''s important files have been encrypted!\" fullword ascii\n      $s4 = \"echo CreateObject(\\\"SAPI.SpVoice\\\").Speak \\\"Your computer''s important files have been encrypted! \" fullword ascii    \n      $s5 = \"! Your computer''s important files have been encrypted! \" fullword ascii\n      $s7 = \"This program is not supported on your operating system.\" fullword ascii\n      $s8 = \"echo Your computer''s files have been encrypted to Locdoor Ransomware! To make a recovery go to localbitcoins.com and create a wa\" ascii\n      $s9 = \"Please enter the password.\" fullword ascii\n\n   condition:\n\n      ( uint16(0) == 0x5a4d and filesize < 600KB ) and all of them \n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('screenlocker_5h311_1nj3c706', 'Rule to detect the screenlocker 5h311_1nj3c706', 1, 'rule screenlocker_5h311_1nj3c706 {\n\n   meta:\n\n      description = \"Rule to detect the screenlocker 5h311_1nj3c706\"\n      author = \"Marc Rivero | @seifreed\"\n      reference = \"https:\n\n   strings:\n\n      $s1 = \"C:\\\\Users\\\\Hoang Nam\\\\source\\\\repos\\\\WindowsApp22\\\\WindowsApp22\\\\obj\\\\Debug\\\\WindowsApp22.pdb\" fullword ascii\n      $s2 = \"cmd.exe /cREG add HKCU\\\\Software\\\\Microsoft\\\\Windows\\\\CurrentVersion\\\\Policies\\\\ActiveDesktop /v NoChangingWallPaper /t REG_DWOR\" wide\n      $s3 = \"C:\\\\Users\\\\file1.txt\" fullword wide\n      $s4 = \"C:\\\\Users\\\\file2.txt\" fullword wide\n      $s5 = \"C:\\\\Users\\\\file.txt\" fullword wide\n      $s6 = \" /v Wallpaper /t REG_SZ /d %temp%\\\\IMG.jpg /f\" fullword wide\n      $s7 = \" /v DisableAntiSpyware /t REG_DWORD /d 1 /f\" fullword wide\n      $s8 = \"All your file has been locked. You must pay money to have a key.\" fullword wide\n      $s9 = \"After we receive Bitcoin from you. We will send key to your email.\" fullword wide\n   \n   condition:\n\n      ( uint16(0) == 0x5a4d and filesize < 200KB ) and all of them \n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('shrug2_ransomware', 'Rule to detect Shrug2 ransomware', 1, 'rule shrug2_ransomware {\n\n   meta:\n\n      description = \"Rule to detect Shrug2 ransomware\"\n      author = \"Marc Rivero | @seifreed\"\n      reference = \"https:\n       \n   strings:\n\n      $s1 = \"C:\\\\Users\\\\Gamer\\\\Desktop\\\\Shrug2\\\\ShrugTwo\\\\ShrugTwo\\\\obj\\\\Debug\\\\ShrugTwo.pdb\" fullword ascii\n      $s2 = \"http:\n      $s4 = \"Shortcut for @ShrugDecryptor@.exe\" fullword wide\n      $s5 = \"C:\\\\Users\\\\\" fullword wide\n      $s6 = \"http:\n      $s7 = \"\\\\Desktop\\\\@ShrugDecryptor@.lnk\" fullword wide\n   \n   condition:\n      ( uint16(0) == 0x5a4d and filesize < 2000KB ) and all of them \n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('termite_ransomware', 'Rule to detect Termite Ransomware', 1, 'rule termite_ransomware {\n\n   meta:\n\n      description = \"Rule to detect Termite Ransomware\"\n      author = \"Marc Rivero | @seifreed\"\n      reference = \"https:\n      \n   strings:\n      \n      $s1 = \"C:\\\\Windows\\\\SysNative\\\\mswsock.dll\" fullword ascii\n      $s2 = \"C:\\\\Windows\\\\SysWOW64\\\\mswsock.dll\" fullword ascii\n      $s3 = \"SOFTWARE\\\\Microsoft\\\\Windows\\\\CurrentVersion\\\\Run\\\\Termite.exe\" fullword ascii\n      $s4 = \"SOFTWARE\\\\Microsoft\\\\Windows\\\\CurrentVersion\\\\Run\\\\Payment.exe\" fullword ascii\n      $s5 = \"C:\\\\Windows\\\\Termite.exe\" fullword ascii\n      $s6 = \"\\\\Shell\\\\Open\\\\Command\\\\\" fullword ascii\n      $s7 = \"t314.520@qq.com\" fullword ascii\n      $s8 = \"(*.JPG;*.PNG;*.BMP;*.GIF;*.ICO;*.CUR)|*.JPG;*.PNG;*.BMP;*.GIF;*.ICO;*.CUR|JPG\" fullword ascii\n      \n   condition:\n   \n      ( uint16(0) == 0x5a4d and filesize < 6000KB ) and all of them \n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('win_asyncrat_j1', 'detects AsyncRAT', 1, 'rule win_asyncrat_j1 {\n\n    meta:\n        author      = \"Johannes Bader @viql\"\n        date        = \"2020-04-26\"\n        description = \"detects AsyncRAT\"\n        references  = \"https:\n        tlp         = \"white\"\n\n    strings:\n        $str_anti_1 = \"VIRTUAL\" wide\n        $str_anti_2 = \"vmware\" wide\n        $str_anti_3 = \"VirtualBox\" wide\n        $str_anti_4 = \"SbieDll.dll\" wide\n\n        $str_miner_1 = \"--donate-level=\" wide\n\n        $str_b_rev_run    = \"\\\\nuR\\\\noisreVtnerruC\\\\swodniW\\\\tfosorciM\\\\erawtfoS\" wide\n        $str_b_msg_pack_1 = \"(ext8,ext16,ex32) type $c7,$c8,$c9\" wide\n        $str_b_msg_pack_2 = \"(never used) type $c1\" wide\n        $str_b_schtask_1  = \"/create /f /sc ONLOGON /RL HIGHEST /tn \\\"''\" wide\n        $str_b_schtask_2  = \"\\\"'' /tr \\\"''\" wide\n\n        $str_config_1 = \"Antivirus\" wide\n        $str_config_2 = \"Pastebin\" wide\n        $str_config_3 = \"HWID\" wide\n        $str_config_4 = \"Installed\" wide\n        $str_config_5 = \"Pong\" wide\n        $str_config_6 = \"Performance\" wide\n\n    condition:\n        all of ($str_anti_*)  and \n        4 of ($str_config_*) and ( \n            all of ($str_miner_*) or \n            3 of ($str_b_*)\n        )\n        \n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('BlackShades_4', 'BlackShades', 1, 'rule BlackShades_4 : rat\n{\n	meta:\n		description = \"BlackShades\"\n		author = \"Jean-Philippe Teissier / @Jipe_\"\n		date = \"2013-01-12\"\n		filetype = \"memory\"\n		version = \"1.0\" \n\n	strings:\n		$a = { 42 00 6C 00 61 00 63 00 6B 00 73 00 68 00 61 00 64 00 65 00 73 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('BlackShades', 'BlackShades Server', 1, 'rule BlackShades : Trojan\n{\n	meta:\n		author=\"Kevin Falcoz\"\n		date=\"26/06/2013\"\n		description=\"BlackShades Server\"\n		\n	strings:\n		$signature1={62 73 73 5F 73 65 72 76 65 72}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('BlackShades_25052015', '', 1, 'rule BlackShades_25052015\n{\n    meta:\n        author = \"Brian Wallace (@botnet_hunter)\"\n        date = \"2014/04\"\n        ref = \"http:\n        ref = \"http:\n        family = \"blackshades\"\n\n    strings:\n        $string1 = \"bss_server\"\n        $string2 = \"txtChat\"\n        $string3 = \"UDPFlood\"\n    condition:\n        all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Bolonyokte', 'UnknownDotNet RAT - Bolonyokte', 1, 'rule Bolonyokte : rat \n{\n	meta:\n		description = \"UnknownDotNet RAT - Bolonyokte\"\n		author = \"Jean-Philippe Teissier / @Jipe_\"\n		date = \"2013-02-01\"\n		filetype = \"memory\"\n		version = \"1.0\" \n\n	strings:\n		$campaign1 = \"Bolonyokte\" ascii wide\n		$campaign2 = \"donadoni\" ascii wide\n		\n		$decoy1 = \"nyse.com\" ascii wide\n		$decoy2 = \"NYSEArca_Listing_Fees.pdf\" ascii wide\n		$decoy3 = \"bf13-5d45cb40\" ascii wide\n		\n		$artifact1 = \"Backup.zip\"  ascii wide\n		$artifact2 = \"updates.txt\" ascii wide\n		$artifact3 = \"vdirs.dat\" ascii wide\n		$artifact4 = \"default.dat\"\n		$artifact5 = \"index.html\"\n		$artifact6 = \"mime.dat\"\n		\n		$func1 = \"FtpUrl\"\n		$func2 = \"ScreenCapture\"\n		$func3 = \"CaptureMouse\"\n		$func4 = \"UploadFile\"\n\n		$ebanking1 = \"Internet Banking\" wide\n		$ebanking2 = \"(Online Banking)|(Online banking)\"\n		$ebanking3 = \"(e-banking)|(e-Banking)\" nocase\n		$ebanking4 = \"login\"\n		$ebanking5 = \"en ligne\" wide\n		$ebanking6 = \"bancaires\" wide\n		$ebanking7 = \"(eBanking)|(Ebanking)\" wide\n		$ebanking8 = \"Anmeldung\" wide\n		$ebanking9 = \"internet banking\" nocase wide\n		$ebanking10 = \"Banking Online\" nocase wide\n		$ebanking11 = \"Web Banking\" wide\n		$ebanking12 = \"Power\"\n\n	condition:\n		any of ($campaign*) or 2 of ($decoy*) or 2 of ($artifact*) or all of ($func*) or 3 of ($ebanking*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Bozok', '', 1, 'rule Bozok : RAT\n{\n	meta:\n		author = \" Kevin Breen <kevin@techanarchy.net>\"\n		date = \"2014/04\"\n		ref = \"http:\n		maltype = \"Remote Access Trojan\"\n		filetype = \"exe\"\n\n	strings:\n		$a = \"getVer\" nocase\n		$b = \"StartVNC\" nocase\n		$c = \"SendCamList\" nocase\n		$d = \"untPlugin\" nocase\n		$e = \"gethostbyname\" nocase\n\n	condition:\n		all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Crimson', '', 1, 'rule Crimson: RAT\n{\n	meta:\n		author = \" Kevin Breen <kevin@techanarchy.net>\"\n		Description = \"Crimson Rat\"\n		date = \"2015/05\"\n		ref = \"http:\n		maltype = \"Remote Access Trojan\"\n		filetype = \"jar\"\n\n	strings:\n		$a1 = \"com/crimson/PK\"\n		$a2 = \"com/crimson/bootstrapJar/PK\"\n		$a3 = \"com/crimson/permaJarMulti/PermaJarReporter$1.classPK\"\n		$a4 = \"com/crimson/universal/containers/KeyloggerLog.classPK\"\n        $a5 = \"com/crimson/universal/UploadTransfer.classPK\"\n        \n	condition:\n        all of ($a*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('CrossRAT', 'Detects CrossRAT known hash', 1, 'rule CrossRAT: RAT\n{\n    meta:\n        description = \"Detects CrossRAT known hash\"\n        author = \"Simon Sigre (simon.sigre@gmail.com)\"\n        date = \"26/01/2018\"\n        ref = \"https:\n        ref= \"https:\n    strings:\n        $magic = { 50 4b 03 04 ( 14 | 0a ) 00 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('CyberGate', '', 1, 'rule CyberGate : RAT\n{\n\n	meta:\n		author = \" Kevin Breen <kevin@techanarchy.net>\"\n		date = \"2014/04\"\n		ref = \"http:\n		maltype = \"Remote Access Trojan\"\n		filetype = \"exe\"\n\n	strings:\n		$string1 = {23 23 23 23 40 23 23 23 23 E8 EE E9 F9 23 23 23 23 40 23 23 23 23}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('DarkComet_1', 'DarkComet RAT', 1, 'rule DarkComet_1 : RAT\n{\n    meta:\n        description = \"DarkComet RAT\"\n	author = \"botherder https:\n\n    strings:\n        $bot1 = /(#)BOT#OpenUrl/ wide ascii\n        $bot2 = /(#)BOT#Ping/ wide ascii\n        $bot3 = /(#)BOT#RunPrompt/ wide ascii\n        $bot4 = /(#)BOT#SvrUninstall/ wide ascii\n        $bot5 = /(#)BOT#URLDownload/ wide ascii\n        $bot6 = /(#)BOT#URLUpdate/ wide ascii\n        $bot7 = /(#)BOT#VisitUrl/ wide ascii\n        $bot8 = /(#)BOT#CloseServer/ wide ascii\n\n        $ddos1 = /(D)DOSHTTPFLOOD/ wide ascii\n        $ddos2 = /(D)DOSSYNFLOOD/ wide ascii\n        $ddos3 = /(D)DOSUDPFLOOD/ wide ascii\n\n        $keylogger1 = /(A)ctiveOnlineKeylogger/ wide ascii\n        $keylogger2 = /(U)nActiveOnlineKeylogger/ wide ascii\n        $keylogger3 = /(A)ctiveOfflineKeylogger/ wide ascii\n        $keylogger4 = /(U)nActiveOfflineKeylogger/ wide ascii\n\n        $shell1 = /(A)CTIVEREMOTESHELL/ wide ascii\n        $shell2 = /(S)UBMREMOTESHELL/ wide ascii\n        $shell3 = /(K)ILLREMOTESHELL/ wide ascii\n\n    condition:\n        4 of ($bot*) or all of ($ddos*) or all of ($keylogger*) or all of ($shell*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('DarkComet_2', 'DarkComet', 1, 'rule DarkComet_2 : rat\n{\n	meta:\n		description = \"DarkComet\" \n		author = \"Jean-Philippe Teissier / @Jipe_\"\n		date = \"2013-01-12\"\n		filetype = \"memory\"\n		version = \"1.0\" \n\n	strings:\n		$a = \"#BEGIN DARKCOMET DATA --\"\n		$b = \"#EOF DARKCOMET DATA --\"\n		$c = \"DC_MUTEX-\"\n		$k1 = \"#KCMDDC5#-890\"\n		$k2 = \"#KCMDDC51#-890\"\n\n	condition:\n		any of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('DarkComet_3', '', 1, 'rule DarkComet_3 : RAT\n{\n	meta:\n		author = \" Kevin Breen <kevin@techanarchy.net>\"\n		date = \"2014/04\"\n		ref = \"http:\n		maltype = \"Remote Access Trojan\"\n		filetype = \"exe\"\n\n	strings:\n		\n		$a1 = \"#BOT#URLUpdate\"\n		$a2 = \"Command successfully executed!\"\n		$a3 = \"MUTEXNAME\" wide\n		$a4 = \"NETDATA\" wide\n		\n		$b1 = \"FastMM Borland Edition\"\n		$b2 = \"%s, ClassID: %s\"\n		$b3 = \"I wasn''t able to open the hosts file\"\n		$b4 = \"#BOT#VisitUrl\"\n		$b5 = \"#KCMDDC\"\n	condition:\n		all of ($a*) or all of ($b*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('DarkComet_Keylogger_File', 'Looks like a keylogger file created by DarkComet Malware', 1, 'rule DarkComet_Keylogger_File  : RAT\n{\n	meta:\n		author = \"Florian Roth\"\n		description = \"Looks like a keylogger file created by DarkComet Malware\"\n		date = \"25.07.14\"\n		reference = \"https:\n		score = 50\n	strings:\n		$magic = \"::\"\n		$entry = /\\n:: [A-Z]/\n		$timestamp = /\\([0-9]?[0-9]:[0-9][0-9]:[0-9][0-9] [AP]M\\)/\n	condition:\n		($magic at 0) and #entry > 10 and #timestamp > 10\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('DarkComet_4', '', 1, 'rule DarkComet_4  : RAT\n{	meta:\n		reference = \"https:\n	strings:\n	    $a1 = \"#BOT#\"\n	    $a2 = \"WEBCAMSTOP\"\n	    $a3 = \"UnActiveOnlineKeyStrokes\"\n	    $a4 = \"#SendTaskMgr\"\n	    $a5 = \"#RemoteScreenSize\"\n	    $a6 = \"ping 127.0.0.1 -n 4 > NUL &&\"\n	condition:\n		all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('DarkComet_5', 'Malware creates the MSDCSC directory, which is a common path utilized by DarkComet, as well as the mutex pattern.', 1, 'rule DarkComet_5\n{ \n	meta:\n		maltype = \"DarkComet RAT\"\n		author = \"https:\n		description = \"Malware creates the MSDCSC directory, which is a common path utilized by DarkComet, as well as the mutex pattern.\"\n	strings:\n		$type=\"Microsoft-Windows-Security-Auditing\"\n		$eventid=\"4688\"\n		$data=/AppData\\\\Local\\\\Temp\\\\MSDCSC\\\\.+\\.exe/\n\n		$type1=\"Microsoft-Windows-Security-Auditing\"\n		$eventid1=\"4674\"\n		$data1=/DC_MUTEX-[0-9A-Z]{7}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('FlyingKitten', '', 1, 'rule FlyingKitten : rat\n{\n    meta:\n        Author      = \"CrowdStrike, Inc\"\n        Date        = \"2014/05/13\"\n        Description = \"Flying Kitten RAT\"\n        Reference   = \"http:\n\n    strings:\n        $classpath = \"Stealer.Properties.Resources.resources\"\n        $pdbstr = \"\\\\Stealer\\\\obj\\\\x86\\\\Release\\\\Stealer.pdb\"\n\n    condition:\n        all of them and uint16(0) == 0x5A4D and uint32(uint32(0x3c)) == 0x4550 and uint16(uint32(0x3C) + 0x16) & 0x2000 == 0 and ((uint16(uint32(0x3c)+24) == 0x010b and uint32(uint32(0x3c)+232) > 0) or (uint16(uint32(0x3c)+24) == 0x020b and uint32(uint32(0x3c)+248) > 0)) \n\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('APT_WIN_Gh0st_ver', '', 1, 'rule APT_WIN_Gh0st_ver : RAT\n{\nmeta:\n   author = \"@BryanNolen\"\n   date = \"2012-12\"\n   type = \"APT\"\n   version = \"1.1\"\n   ref = \"Detection of Gh0st RAT server DLL component\"\n   ref1 = \"http:\n strings:  \n   $library = \"deflate 1.1.4 Copyright 1995-2002 Jean-loup Gailly\"\n   $capability = \"GetClipboardData\"\n   $capability1 = \"capCreateCaptureWindowA\"\n   $capability2 = \"CreateRemoteThread\"\n   $capability3 = \"WriteProcessMemory\"\n   $capability4 = \"LsaRetrievePrivateData\"\n   $capability5 = \"AdjustTokenPrivileges\"\n   $function = \"ResetSSDT\"\n   $window = \"WinSta0\\\\Default\"\n   $magic = {47 6C 6F 62 61 6C 5C [5-9] 20 25 64}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Gh0st', 'Gh0st', 1, 'rule Gh0st : RAT\n{\n    meta:\n        description = \"Gh0st\"\n	author = \"botherder https:\n\n    strings:\n        $ = /(G)host/\n        $ = /(i)nflate 1\\.1\\.4 Copyright 1995-2002 Mark Adler/\n        $ = /(d)eflate 1\\.1\\.4 Copyright 1995-2002 Jean-loup Gailly/\n        $ = /(%)s\\\\shell\\\\open\\\\command/\n        $ = /(G)etClipboardData/\n        $ = /(W)riteProcessMemory/\n        $ = /(A)djustTokenPrivileges/\n        $ = /(W)inSta0\\\\Default/\n        $ = /(#)32770/\n        $ = /(#)32771/\n        $ = /(#)32772/\n        $ = /(#)32774/\n\n    condition:\n        all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('gh0st', '', 1, 'rule gh0st\n\n{\n\nmeta:\n	author = \"https:\n\n   strings:\n      $a = { 47 68 30 73 74 ?? ?? ?? ?? ?? ?? ?? ?? 78 9C }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('gholeeV1', '', 1, 'rule gholeeV1\n{\n    meta:\n	 Author = \"@GelosSnake\"\n    	 Date = \"2014/08\"\n    	 Description = \"Gholee first discovered variant \"\n	 Reference = \"http:\n\n    strings:\n    	 $a = \"sandbox_avg10_vc9_SP1_2011\"\n    	 $b = \"gholee\"\n\n    condition:\n    	 all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('gholeeV2', '', 1, 'rule gholeeV2\n{\n   meta:\n	Author = \"@GelosSnake\"\n	Date = \"2015-02-12\"\n    	Description = \"Gholee first discovered variant \"\n	Reference = \"http:\n\n   strings:\n	$string0 = \"RichHa\"\n	$string1 = \"         (((((                  H\" wide\n	$string2 = \"1$1,141<1D1L1T1\\\\1d1l1t1\"\n	$string3 = \"<8;$O'' \"\n	$string4 = \"@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\\\]\"\n	$string5 = \"jYPQTVTSkllZTTXRTUiHceWda/\"\n	$string6 = \"urn:schemas-microsoft-com:asm.v1\"\n	$string7 = \"8.848H8O8i8s8y8\"\n	$string8 = \"wrapper3\" wide\n	$string9 = \"pwwwwwwww\"\n	$string10 = \"Sunday\"\n	$string11 = \"YYuTVWh\"\n	$string12 = \"DDINGPADDINGXXPADDINGPADDINGXXPADDINGPADDINGXXPADDINGPADDINGXXPADDINGPADDINGXXPADDINGPADDINGXXPADDIN\"\n	$string13 = \"ytMMMMMMUbbrrrrrxxxxxxxxrriUMMMMMMMMMUuzt\"\n	$string15 = \"wrapper3 Version 1.0\" wide\n	$string16 = \"77A779\"\n	$string17 = \"<C<G<M<R<X<\"\n	$string18 = \"9 9-9N9X9s9\"\n\n    condition:\n	18 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('MW_gholee_v1', 'http:\n    date = ', 1, 'rule MW_gholee_v1 : v1\n{\nmeta:\n    Author = \"@GelosSnake\"\n    description = \"http:\n    date = \"2014-08\"\n    maltype = \"Remote Access Trojan\"\n    sample_filetype = \"dll\"\n    hash0 = \"48573a150562c57742230583456b4c02\"\n   \nstrings:\n    $a = \"sandbox_avg10_vc9_SP1_2011\"\n    $b = \"gholee\"\n   \ncondition:\n    all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('MW_gholee_v2', 'http:\n        hash0 = ', 1, 'rule MW_gholee_v2 : v2\n{\nmeta:\n        author = \"@GelosSnake\"\n        date = \"2015-02-12\"\n        description = \"http:\n        hash0 = \"05523761ca296ec09afdf79477e5f18d\"\n        hash1 = \"08e424ac42e6efa361eccefdf3c13b21\"\n        hash2 = \"5730f925145f1a1cd8380197e01d9e06\"\n        hash3 = \"73461c8578dd9ab86d42984f30c04610\"\n        sample_filetype = \"dll\"\nstrings:\n        $string0 = \"RichHa\"\n        $string1 = \"         (((((                  H\" wide\n        $string2 = \"1$1,141<1D1L1T1\\\\1d1l1t1\"\n        $string3 = \"<8;$O'' \"\n        $string4 = \"@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\\\]\"\n        $string5 = \"jYPQTVTSkllZTTXRTUiHceWda/\"\n        $string6 = \"urn:schemas-microsoft-com:asm.v1\"\n        $string7 = \"8.848H8O8i8s8y8\"\n        $string8 = \"wrapper3\" wide\n        $string9 = \"pwwwwwwww\"\n        $string10 = \"Sunday\"\n        $string11 = \"YYuTVWh\"\n        $string12 = \"DDINGPADDINGXXPADDINGPADDINGXXPADDINGPADDINGXXPADDINGPADDINGXXPADDINGPADDINGXXPADDINGPADDINGXXPADDIN\"\n        $string13 = \"ytMMMMMMUbbrrrrrxxxxxxxxrriUMMMMMMMMMUuzt\"\n        $string15 = \"wrapper3 Version 1.0\" wide\n        $string16 = \"77A779\"\n        $string17 = \"<C<G<M<R<X<\"\n        $string18 = \"9 9-9N9X9s9\"\ncondition:\n        18 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('glassrat', '', 1, 'rule glassrat: RAT\n{\n   meta:\n        author = \"Brian Wallace @botnet_hunter\"\n   strings:\n    	$a = \"PostQuitMessage\"\n        $b = \"pwlfnn10,gzg\"\n        $c = \"update.dll\"\n        $d = \"_winver\"\n   condition:\n    	all of them\n\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Win32OPCHavex', '', 1, 'rule Win32OPCHavex\n{\n    meta:\n        Author      = \"BAE Systems\"\n        Date        = \"2014/06/23\"\n        Description = \"Rule for identifying OPC version of HAVEX\"\n        Reference   = \"www.f-secure.com/weblog/archives/00002718.html\"\n\n    strings:\n        $mzhdr = \"MZ\"\n        $dll = \"7CFC52CD3F87.dll\"\n        $a1 = \"Start finging of LAN hosts...\" wide\n        $a2 = \"Finding was fault. Unexpective error\" wide\n        $a3 = \"Was found %i hosts in LAN:\" wide\n        $a4 = \"Hosts was''t found.\" wide\n        $a5 = \"Start finging of OPC Servers...\" wide\n        $a6 = \"Was found %i OPC Servers.\" wide\n        $a7 = \"OPC Servers not found. Programm finished\" wide\n        $a8 = \"%s[%s]!!!EXEPTION %i!!!\" wide\n        $a9 = \"Start finging of OPC Tags...\" wide\n\n    condition:\n        $mzhdr at 0 and ($dll or (any of ($a*)))\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Win32FertgerHavex', '', 1, 'rule Win32FertgerHavex\n{\n    meta:\n        Author      = \"BAE Systems\"\n        Date        = \"2014/06/23\"\n        Description = \"Rule for identifying Fertger version of HAVEX\"\n        Reference   = \"www.f-secure.com/weblog/archives/00002718.html\"\n\n    strings:\n        $mz = \"MZ\"\n        $a1=\"\\\\\\\\.\\\\pipe\\\\mypipe-f\" wide\n        $a2=\"\\\\\\\\.\\\\pipe\\\\mypipe-h\" wide\n        $a3=\"\\\\qln.dbx\" wide\n        $a4=\"*.yls\" wide\n        $a5=\"\\\\*.xmd\" wide\n        $a6=\"fertger\" wide\n        $a7=\"havex\"\n    \n    condition:\n        $mz at 0 and 3 of ($a*) \n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Havex_Trojan_PHP_Server', '', 1, 'rule Havex_Trojan_PHP_Server\n{\n    meta:\n        Author      = \"Florian Roth\"\n        Date        = \"2014/06/24\"\n        Description = \"Detects the PHP server component of the Havex RAT\"\n        Reference   = \"www.f-secure.com/weblog/archives/00002718.html\"\n\n    strings:\n        $s1 = \"havex--></body></head>\"\n        $s2 = \"ANSWERTAG_START\"\n        $s3 = \"PATH_BLOCKFILE\"\n\n    condition:\n        all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('SANS_ICS_Cybersecurity_Challenge_400_Havex_Memdump', 'Detects Havex Windows process executable from memory dump', 1, 'rule SANS_ICS_Cybersecurity_Challenge_400_Havex_Memdump : memory\n	{\n	meta:\n		description = \"Detects Havex Windows process executable from memory dump\"\n		date = \"2015-12-2\"\n		author = \"Chris Sistrunk\"\n		hash = \"8065674de8d79d1c0e7b3baf81246e7d\"\n	strings:\n		$magic = { 4d 5a }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('apt_win32_dll_rat_hiZor_RAT', 'Detects hiZor RAT', 1, 'rule apt_win32_dll_rat_hiZor_RAT: RAT\n{\n	meta:\n    description = \"Detects hiZor RAT\"\n		hash1 = \"75d3d1f23628122a64a2f1b7ef33f5cf\"\n		hash2 = \"d9821468315ccd3b9ea03161566ef18e\"\n		hash3 = \"b9af5f5fd434a65d7aa1b55f5441c90a\"\n    ref1 = \"http:\n    ref2 = \"https:\n    reference = \"https:\n	strings:\n		\n		$s1 = { c7 [5] 40 00 62 00 c7 [5] 77 00 64 00 c7 [5] 61 00 61 00 c7 [5] 6c 00 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Indetectables_RAT', 'Detects Indetectables RAT based on strings found in research by Paul Rascagneres & Ronan Mouchoux', 1, 'rule Indetectables_RAT: RAT {\n	meta:\n		description = \"Detects Indetectables RAT based on strings found in research by Paul Rascagneres & Ronan Mouchoux\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		date = \"2015-10-01\"\n		super_rule = 1\n		hash1 = \"081905074c19d5e32fd41a24b4c512d8fd9d2c3a8b7382009e3ab920728c7105\"\n		hash2 = \"66306c2a55a3c17b350afaba76db7e91bfc835c0e90a42aa4cf59e4179b80229\"\n		hash3 = \"1fa810018f6dd169e46a62a4f77ae076f93a853bfc33c7cf96266772535f6801\"\n	strings:\n		$s1 = \"Coded By M3\" fullword wide\n		$s2 = \"Stub Undetector M3\" fullword wide\n		$s3 = \"www.webmenegatti.com.br\" wide\n		$s4 = \"M3n3gatt1\" fullword wide\n		$s5 = \"TheMisterFUD\" fullword wide\n		$s6 = \"KillZoneKillZoneKill\" fullword ascii\n		$s7 = \"[[__M3_F_U_D_M3__]]$\" fullword ascii\n		$s8 = \"M3_F_U_D_M3\" ascii\n		$s9 = \"M3n3gatt1hack3r\" fullword wide\n		$s9a = \"M3n3gatt1hack3r\" fullword ascii\n	condition:\n		uint16(0) == 0x5a4d and filesize < 5000KB and 1 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('BergSilva_Malware', 'Detects a malware from the same author as the Indetectables RAT', 1, 'rule BergSilva_Malware : RAT {\n	meta:\n		description = \"Detects a malware from the same author as the Indetectables RAT\"\n		author = \"Florian Roth\"\n		date = \"2015-10-01\"\n		super_rule = 1\n		hash1 = \"00e175cbad629ee118d01c49c11f3d8b8840350d2dd6d16bd81e47ae926f641e\"\n		hash2 = \"6b4cbbee296e4a0e867302f783d25d276b888b1bf1dcab9170e205d276c22cfc\"\n	strings:\n		$x1 = \"C:\\\\Users\\\\Berg Silva\\\\Desktop\\\\\" wide\n		$x2 = \"URLDownloadToFileA 0, \\\"https:\n\n		$s1 = \" Process.Start (Path.GetTempPath() & \\\"name\\\" & \\\".exe\\\") ''start server baixado\" fullword wide\n		$s2 = \"FileDelete(@TempDir & \\\"\\\\nome.exe\\\") ;Deleta o Arquivo para que possa ser executado normalmente\" fullword wide\n		$s3 = \" Lib \\\"\\\\WINDOWS\\\\system32\\\\UsEr32.dLl\\\"\" fullword wide\n		$s4 = \"$Directory = @TempDir & \\\"\\\\nome.exe\\\" ;Define a variavel\" fullword wide\n		$s5 = \"https:\n	condition:\n		uint16(0) == 0x5a4d and ( 1 of ($x*) or 2 of ($s*) )\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('apt_win32_dll_rat_1a53b0cp32e46g0qio7', '', 1, 'rule apt_win32_dll_rat_1a53b0cp32e46g0qio7\n{\n	meta:\n		author = \"https:\n        	info = \"Indicators for FTA-1020\"\n		hash1 = \"75d3d1f23628122a64a2f1b7ef33f5cf\"\n		hash2 = \"d9821468315ccd3b9ea03161566ef18e\"\n		hash3 = \"b9af5f5fd434a65d7aa1b55f5441c90a\"\n		reference = \"https:\n	strings:\n    	\n		$ = { c7 [2] 64 00 63 00 c7 [2] 69 00 62 00 c7 [2] 7a 00 7e 00 c7 [2] 2d 00 43 00 c7 [2] 59 00 2d 00 c7 [2] 3b 00 23 00 c7 [2] 3e 00 36 00 c7 [2] 2d 00 5a 00 c7 [2] 42 00 5a 00 c7 [2] 3b 00 39 00 c7 [2] 36 00 2d 00 c7 [2] 59 00 7f 00 c7 [2] 64 00 69 00 c7 [2] 68 00 63 00 c7 [2] 79 00 22 00 c7 [2] 3a 00 23 00 c7 [2] 3d 00 36 00 c7 [2] 2d 00 7f 00 c7 [2] 7b 00 37 00 c7 [2] 3c 00 3c 00 c7 [2] 23 00 3d 00 c7 [2] 24 00 2d 00 c7 [2] 61 00 64 00 c7 [2] 66 00 68 00 c7 [2] 2d 00 4a 00 c7 [2] 68 00 6e 00 c7 [2] 66 00 62 00 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Meterpreter_Reverse_Tcp', 'Meterpreter reverse TCP backdoor in memory. Tested on Win7x64.', 1, 'rule Meterpreter_Reverse_Tcp { \n  meta: \n    author = \"chort (@chort0)\" \n    description = \"Meterpreter reverse TCP backdoor in memory. Tested on Win7x64.\" \n  strings: \n    $a = { 4d 45 54 45 52 50 52 45 54 45 52 5f 54 52 41 4e 53 50 4f 52 54 5f 53 53 4c [32-48] 68 74 74 70 73 3a 2f 2f 58 58 58 58 58 58 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Nanocore_RAT_Gen_1', 'Detetcs the Nanocore RAT and similar malware', 1, 'rule Nanocore_RAT_Gen_1 {\n	meta:\n		description = \"Detetcs the Nanocore RAT and similar malware\"\n		author = \"Florian Roth\"\n		reference = \"https:\n		date = \"2016-04-22\"\n		score = 70\n		hash1 = \"e707a7745e346c5df59b5aa4df084574ae7c204f4fb7f924c0586ae03b79bf06\"\n	strings:\n		$x1 = \"C:\\\\Users\\\\Logintech\\\\Dropbox\\\\Projects\\\\New folder\\\\Latest\\\\Benchmark\\\\Benchmark\\\\obj\\\\Release\\\\Benchmark.pdb\" fullword ascii\n		$x2 = \"RunPE1\" fullword ascii\n		$x3 = \"082B8C7D3F9105DC66A7E3267C9750CF43E9D325\" fullword ascii\n		$x4 = \"$374e0775-e893-4e72-806c-a8d880a49ae7\" fullword ascii\n		$x5 = \"Monitorinjection\" fullword ascii\n	condition:\n		( uint16(0) == 0x5a4d and filesize < 100KB and ( 1 of them ) ) or ( 3 of them )\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Nanocore_RAT_Gen_2', 'Detetcs the Nanocore RAT', 1, 'rule Nanocore_RAT_Gen_2 {\n	meta:\n		description = \"Detetcs the Nanocore RAT\"\n		author = \"Florian Roth\"\n		score = 100\n		reference = \"https:\n		date = \"2016-04-22\"\n		hash1 = \"755f49a4ffef5b1b62f4b5a5de279868c0c1766b528648febf76628f1fe39050\"\n	strings:\n		$x1 = \"NanoCore.ClientPluginHost\" fullword ascii\n		$x2 = \"IClientNetworkHost\" fullword ascii\n		$x3 = \"#=qjgz7ljmpp0J7FvL9dmi8ctJILdgtcbw8JYUc6GC8MeJ9B11Crfg2Djxcf0p8PZGe\" fullword ascii\n	condition:\n		( uint16(0) == 0x5a4d and filesize < 1000KB and 1 of them ) or ( all of them )\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Nanocore_RAT_Sample_1', 'Detetcs a certain Nanocore RAT sample', 1, 'rule Nanocore_RAT_Sample_1 {\n	meta:\n		description = \"Detetcs a certain Nanocore RAT sample\"\n		author = \"Florian Roth\"\n		score = 75\n		reference = \"https:\n		date = \"2016-04-22\"\n		hash2 = \"b7cfc7e9551b15319c068aae966f8a9ff563b522ed9b1b42d19c122778e018c8\"\n	strings:\n		$x1 = \"TbSiaEdJTf9m1uTnpjS.n9n9M7dZ7FH9JsBARgK\" fullword wide\n		$x2 = \"1EF0D55861681D4D208EC3070B720C21D885CB35\" fullword ascii\n		$x3 = \"popthatkitty.Resources.resources\" fullword ascii\n	condition:\n		( uint16(0) == 0x5a4d and filesize < 900KB and ( 1 of ($x*) ) ) or ( all of them )\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Nanocore_RAT_Sample_2', 'Detetcs a certain Nanocore RAT sample', 1, 'rule Nanocore_RAT_Sample_2 {\n	meta:\n		description = \"Detetcs a certain Nanocore RAT sample\"\n		author = \"Florian Roth\"\n		score = 75\n		reference = \"https:\n		date = \"2016-04-22\"\n		hash1 = \"51142d1fb6c080b3b754a92e8f5826295f5da316ec72b480967cbd68432cede1\"\n	strings:\n		$s1 = \"U4tSOtmpM\" fullword ascii\n		$s2 = \")U71UDAU_QU_YU_aU_iU_qU_yU_\" fullword wide\n		$s3 = \"Cy4tOtTmpMtTHVFOrR\" fullword ascii\n	condition:\n		uint16(0) == 0x5a4d and filesize < 40KB and all of ($s*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('NetWiredRC_B', 'NetWiredRC', 1, 'rule NetWiredRC_B : RAT\n{\n	meta:\n		description = \"NetWiredRC\"\n		author = \"Jean-Philippe Teissier / @Jipe_\"\n		date = \"2014-12-23\"\n		filetype = \"memory\"\n		version = \"1.1\" \n\n	strings:\n		$mutex = \"LmddnIkX\"\n\n		$str1 = \"%s.Identifier\"\n		$str2 = \"%d:%I64u:%s%s;\"\n		$str3 = \"%s%.2d-%.2d-%.4d\"\n		$str4 = \"[%s] - [%.2d/%.2d/%d %.2d:%.2d:%.2d]\"\n		$str5 = \"%.2d/%.2d/%d %.2d:%.2d:%.2d\"\n		\n		$klg1 = \"[Backspace]\"\n		$klg2 = \"[Enter]\"\n		$klg3 = \"[Tab]\"\n		$klg4 = \"[Arrow Left]\"\n		$klg5 = \"[Arrow Up]\"\n		$klg6 = \"[Arrow Right]\"\n		$klg7 = \"[Arrow Down]\"\n		$klg8 = \"[Home]\"\n		$klg9 = \"[Page Up]\"\n		$klg10 = \"[Page Down]\"\n		$klg11 = \"[End]\"\n		$klg12 = \"[Break]\"\n		$klg13 = \"[Delete]\"\n		$klg14 = \"[Insert]\"\n		$klg15 = \"[Print Screen]\"\n		$klg16 = \"[Scroll Lock]\"\n		$klg17 = \"[Caps Lock]\"\n		$klg18 = \"[Alt]\"\n		$klg19 = \"[Esc]\"\n		$klg20 = \"[Ctrl+%c]\"\n\n	condition: \n		$mutex or (1 of ($str*) and 1 of ($klg*))\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Njrat', 'Njrat', 1, 'rule Njrat: RAT\n{\n    meta:\n        description = \"Njrat\"\n	author = \"botherder https:\n\n    strings:\n        $string1 = /(F)romBase64String/\n        $string2 = /(B)ase64String/\n        $string3 = /(C)onnected/ wide ascii\n        $string4 = /(R)eceive/\n        $string5 = /(S)end/ wide ascii\n        $string6 = /(D)ownloadData/ wide ascii\n        $string7 = /(D)eleteSubKey/ wide ascii\n        $string8 = /(g)et_MachineName/\n        $string9 = /(g)et_UserName/\n        $string10 = /(g)et_LastWriteTime/\n        $string11 = /(G)etVolumeInformation/\n        $string12 = /(O)SFullName/ wide ascii\n        $string13 = /(n)etsh firewall/ wide\n        $string14 = /(c)md\\.exe \\/k ping 0 & del/ wide\n        $string15 = /(c)md\\.exe \\/c ping 127\\.0\\.0\\.1 & del/ wide\n        $string16 = /(c)md\\.exe \\/c ping 0 -n 2 & del/ wide\n        $string17 = {7C 00 27 00 7C 00 27 00 7C}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('njrat1', 'Identify njRat', 1, 'rule njrat1: RAT\n{\n    meta:\n        author = \"Brian Wallace @botnet_hunter\"\n        author_email = \"bwall@ballastsecurity.net\"\n        date = \"2015-05-27\"\n        description = \"Identify njRat\"\n    strings:\n        $a1 = \"netsh firewall add allowedprogram \" wide\n        $a2 = \"SEE_MASK_NOZONECHECKS\" wide\n\n        $b1 = \"[TAP]\" wide\n        $b2 = \" & exit\" wide\n\n        $c1 = \"md.exe /k ping 0 & del \" wide\n        $c2 = \"cmd.exe /c ping 127.0.0.1 & del\" wide\n        $c3 = \"cmd.exe /c ping\" wide\n    condition:\n        1 of ($a*) and 1 of ($b*) and 1 of ($c*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('win_exe_njRAT', '', 1, 'rule win_exe_njRAT \n{\nmeta:\nauthor = \"info@fidelissecurity.com\"\ndescripion = \"njRAT - Remote Access Trojan\"\ncomment = \"Variants have also been observed obfuscated with .NET Reactor\"\nfiletype = \"pe\"\ndate = \"2013-07-15\"\nversion = \"1.0\"\nhash1 = \"92ee1fb5df21d8cfafa2b02b6a25bd3b\"\nhash2 = \"3576d40ce18bb0349f9dfa42b8911c3a\"\nhash3 = \"24cc5b811a7f9591e7f2cb9a818be104\"\nhash4 = \"3ad5fded9d7fdf1c2f6102f4874b2d52\"\nhash5 = \"a98b4c99f64315aac9dd992593830f35\"\nhash6 =\"5fcb5282da1a2a0f053051c8da1686ef\"\nhash7 = \"a669c0da6309a930af16381b18ba2f9d\"\nhash8 = \"79dce17498e1997264346b162b09bde8\"\nhash9 = \"fc96a7e27b1d3dab715b2732d5c86f80\"\nref1 = \"http:\nref2 = \"http:\nref3 = \"http:\nref4 = \"http:\n\nstrings:\n$magic = \"MZ\"\n$string_setA_1 = \"FromBase64String\"\n$string_setA_2 = \"Base64String\"\n$string_setA_3 = \"Connected\" wide ascii\n$string_setA_4 = \"Receive\"\n$string_setA_5 = \"DeleteSubKey\" wide ascii\n$string_setA_6 = \"get_MachineName\"\n$string_setA_7 = \"get_UserName\"\n$string_setA_8 = \"get_LastWriteTime\"\n$string_setA_9 = \"GetVolumeInformation\"\n\n$string_setB_1 = \"OSFullName\" wide ascii\n$string_setB_2 = \"Send\" wide ascii\n$string_setB_3 = \"Connected\" wide ascii\n$string_setB_4 = \"DownloadData\" wide ascii\n$string_setB_5 = \"netsh firewall\" wide\n$string_setB_6 = \"cmd.exe /k ping 0 & del\" wide\n\ncondition:\n($magic at 0) and ( all of ($string_setA*) or all of ($string_setB*) ) \n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('network_traffic_njRAT', '', 1, 'rule network_traffic_njRAT \n{\nmeta:\nauthor = \"info@fidelissecurity.com\"\ndescripion = \"njRAT - Remote Access Trojan\"\ncomment = \"Rule to alert on network traffic indicators\"\nfiletype = \"PCAP - Network Traffic\"\ndate = \"2013-07-15\"\nversion = \"1.0\"\nhash1 = \"92ee1fb5df21d8cfafa2b02b6a25bd3b\"\nhash2 =\"3576d40ce18bb0349f9dfa42b8911c3a\"\nhash3 =\"24cc5b811a7f9591e7f2cb9a818be104\"\nhash4 = \"3ad5fded9d7fdf1c2f6102f4874b2d52\"\nhash5 = \"a98b4c99f64315aac9dd992593830f35\"\nhash6 = \"5fcb5282da1a2a0f053051c8da1686ef\"\nhash7 = \"a669c0da6309a930af16381b18ba2f9d\"\nhash8 = \"79dce17498e1997264346b162b09bde8\"\nhash9 = \"fc96a7e27b1d3dab715b2732d5c86f80\"\nref1 = \"http:\nref2 = \"http:\nref3 = \"http:\nref4 = \"http:\n\nstrings:\n$string1 = \"FM|''|''|\"     \n$string2 = \"nd|''|''|\"     \n$string3 = \"rn|''|''|\"      \n$string4 = \"sc~|''|''|\"     \n$string5 = \"scPK|''|''|\"     \n$string6 = \"CAM|''|''|\"     \n$string7 = \"USB Video Device[endof]\" \n$string8 = \"rs|''|''|\"     \n$string9 = \"proc|''|''|\"     \n$string10 = \"k|''|''|\"     \n$string11 = \"RG|''|''|~|''|''|\"    \n$string12 = \"kl|''|''|\"     \n$string13 = \"ret|''|''|\"     \n$string14 = \"pl|''|''|\"     \n$string15 = \"lv|''|''|\"     \n$string16 = \"prof|''|''|~|''|''|\"   \n$string17 = \"un|''|''|~[endof]\"   \n$idle_string = \"P[endof]\"    \n\ncondition:\nany of ($string*) or #idle_string > 4  \n\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('RAT_Orcus', '', 1, 'rule RAT_Orcus \n{\n\n    meta:\n        author = \" J from THL <j@techhelplist.com> with thx to MalwareHunterTeam\"\n        date = \"2017/01\"\n        reference = \"https:\n        version = 1\n        maltype = \"RAT\"\n        filetype = \"memory\"\n\n    strings:\n        $text01 = \"Orcus.CommandManagement\"\n        $text02 = \"Orcus.Commands.\"\n        $text03 = \"Orcus.Config.\"\n        $text04 = \"Orcus.Connection.\"\n        $text05 = \"Orcus.Core.\"\n        $text06 = \"Orcus.exe\"\n        $text07 = \"Orcus.Extensions.\"\n        $text08 = \"Orcus.InstallationPromptForm\"\n        $text09 = \"Orcus.MainForm.\"\n        $text10 = \"Orcus.Native.\"\n        $text11 = \"Orcus.Plugins.\"\n        $text12 = \"orcus.plugins.dll\"\n        $text13 = \"Orcus.Properties.\"\n        $text14 = \"Orcus.Protection.\"\n        $text15 = \"Orcus.Share.\"\n        $text16 = \"Orcus.Shared\"\n        $text17 = \"Orcus.StaticCommands\"\n        $text18 = \"Orcus.Utilities.\"\n        $text19 = \"\\\\Projects\\\\Orcus\\\\Source\\\\Orcus.\"\n        $text20 = \".orcus.plugins.dll.zip\"\n        $text21 = \".orcus.shared.dll.zip\"\n        $text22 = \".orcus.shared.utilities.dll.zip\"\n        $text23 = \".orcus.staticcommands.dll.zip\"\n        $text24 = \"HvncCommunication\"\n        $text25 = \"HvncAction\"\n        $text26 = \"hvncDesktop\"\n        $text27 = \".InstallationPromptForm\"\n        $text28 = \"RequestKeyLogCommand\"\n        $text29 = \"get_KeyLogFile\"\n        $text30 = \"LiveKeyloggerCommand\"\n        $text31 = \"ORCUS.STATICCOMMANDS, VERSION=\"\n        $text32 = \"PrepareOrcusFileToRemove\"\n        $text33 = \"ConvertFromOrcusValueKind\"\n\n    condition:\n        13 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('plugX', 'PlugX RAT', 1, 'rule plugX : rat\n{\n	meta:\n		author = \"Jean-Philippe Teissier / @Jipe_\"\n		description = \"PlugX RAT\"\n		date = \"2014-05-13\"\n		filetype = \"memory\"\n		version = \"1.0\" \n		ref1 = \"https:\n		\n	strings:\n		$v1a = { 47 55 4C 50 00 00 00 00 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('PlugX_mw', 'Malware creates a randomized directory within the appdata roaming directory and launches the malware. Should see multiple events for create process rundll32.exe and iexplorer.exe as it repeatedly uses iexplorer to launch the rundll32 process.', 1, 'rule PlugX_mw\n{ \n	meta:\n		maltype = \"plugX\"\n		author = \"https:\n		reference = \"http:\n		description = \"Malware creates a randomized directory within the appdata roaming directory and launches the malware. Should see multiple events for create process rundll32.exe and iexplorer.exe as it repeatedly uses iexplorer to launch the rundll32 process.\"\n	strings:\n		$type=\"Microsoft-Windows-Security-Auditing\"\n		$eventid=\"4688\"\n		$data=/\\\\AppData\\\\Roaming\\\\[0-9]{9,12}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('PoetRat_Doc', '', 1, 'rule PoetRat_Doc\n{\n    meta:\n        Author = \"Nishan Maharjan\"\n        Description = \"A yara rule to catch PoetRat Word Document\"\n        Data = \"6th May 2020\"\n    strings:\n        $pythonRegEx = /(\\.py$|\\.pyc$|\\.pyd$|Python)/  \n\n        \n        $pythonFile1 = \"launcher.py\"\n        $zipFile = \"smile.zip\"\n        $pythonFile2 = \"smile_funs.py\"\n        $pythonFile3 = \"frown.py\"\n        $pythonFile4 = \"backer.py\"\n        $pythonFile5 = \"smile.py\"\n        $pythonFile6 = \"affine.py\" \n\n        \n        $dlls = /\\.dll/\n        $cmd = \"cmd\"\n        $exe = \".exe\"   \n    condition:\n    all of them        \n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('PoetRat_Python', '', 1, 'rule PoetRat_Python\n{\n    meta:\n        Author = \"Nishan Maharjan\"\n        Description = \"A yara rule to catch PoetRat python scripts\"\n        Data = \"6th May 2020\"\n    strings:\n\n        \n        $encrptionFunction = \"Affine\"\n        $commands = /version|ls|cd|sysinfo|download|upload|shot|cp|mv|link|register|hid|compress|jobs|exit|tasklist|taskkill/\n        $domain = \"dellgenius.hopto.org\"\n        $grammer_massacre = /BADD|Bad Error Happened|/\n        $mayBePresent = /self\\.DIE|THE_GUID_KEY/\n        $pipe_out = \"Abibliophobia23\"\n        $shot = \"shot_{0}', 2, '恶意软件', 1);
