INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('PoisonIvy_Generic_3', 'PoisonIvy RAT Generic Rule', 1, 'rule PoisonIvy_Generic_3 {\n	meta:\n		description = \"PoisonIvy RAT Generic Rule\"\n		author = \"Florian Roth\"\n		date = \"2015-05-14\"\n		hash = \"e1cbdf740785f97c93a0a7a01ef2614be792afcd\"\n	strings:\n		$k1 = \"Tiger324{\" fullword ascii\n		\n		$s2 = \"WININET.dll\" fullword ascii\n		$s3 = \"mscoree.dll\" fullword wide\n		$s4 = \"WS2_32.dll\" fullword\n		$s5 = \"Explorer.exe\" fullword wide\n		$s6 = \"USER32.DLL\"\n		$s7 = \"CONOUT$\"\n		$s8 = \"login.asp\"\n		\n		$h1 = \"HTTP/1.0\"\n		$h2 = \"POST\"\n		$h3 = \"login.asp\"\n		$h4 = \"check.asp\"\n		$h5 = \"result.asp\"\n		$h6 = \"upload.asp\"\n	condition:\n		uint16(0) == 0x5a4d and filesize < 500KB and\n			( \n				$k1 or all of ($s*) or all of ($h*)\n			)\n}', 2, '恶意软件', 1);
