INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('ShadowTech_2', 'ShadowTech RAT', 1, 'rule ShadowTech_2\n{\n    meta:\n        description = \"ShadowTech RAT\"\n	author = \"botherder https:\n\n    strings:\n        $string1 = /\\#(S)trings/\n        $string2 = /\\#(G)UID/\n        $string3 = /\\#(B)lob/\n        $string4 = /(S)hadowTech Rat\\.exe/\n        $string5 = /(S)hadowTech_Rat/\n\n    condition:\n        all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('ShadowTech', '', 1, 'rule ShadowTech\n{\n	meta:\n		author = \" Kevin Breen <kevin@techanarchy.net>\"\n		date = \"2014/04\"\n		ref = \"http:\n		maltype = \"Remote Access Trojan\"\n		filetype = \"exe\"\n\n	strings:\n		$a = \"ShadowTech\" nocase\n		$b = \"DownloadContainer\"\n		$c = \"MySettings\"\n		$d = \"System.Configuration\"\n		$newline = \"#-@NewLine@-#\" wide\n		$split = \"pSIL\" wide\n		$key = \"ESIL\" wide\n\n	condition:\n		4 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('shimrat', 'Detects ShimRat and the ShimRat loader', 1, 'rule shimrat: RAT\n{\n meta:\n  description = \"Detects ShimRat and the ShimRat loader\"\n  author = \"Yonathan Klijnsma (yonathan.klijnsma@fox-it.com)\"\n  date = \"20/11/2015\"\n  ref = \"https:\n  \n strings:\n  $dll = \".dll\"\n  $dat = \".dat\"\n  $headersig = \"QWERTYUIOPLKJHG\"\n  $datasig = \"MNBVCXZLKJHGFDS\"\n  $datamarker1 = \"Data$$00\"\n  $datamarker2 = \"Data$$01%c%sData\"\n  $cmdlineformat = \"ping localhost -n 9 /c %s > nul\"\n  $demoproject_keyword1 = \"Demo\"\n  $demoproject_keyword2 = \"Win32App\"\n  $comspec = \"COMSPEC\"\n  $shim_func1 = \"ShimMain\"\n  $shim_func2 = \"NotifyShims\"\n  $shim_func3 = \"GetHookAPIs\"\n\n\n condition:\n  ($dll and $dat and $headersig and $datasig) or ($datamarker1 and $datamarker2) or ($cmdlineformat and $demoproject_keyword1 and $demoproject_keyword2 and $comspec) or ($dll and $dat and $shim_func1 and $shim_func2 and $shim_func3)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('shimratreporter', 'Detects ShimRatReporter', 1, 'rule shimratreporter: RAT\n{\n meta:\n  description = \"Detects ShimRatReporter\"\n  author = \"Yonathan Klijnsma (yonathan.klijnsma@fox-it.com)\"\n  date = \"20/11/2015\"\n  ref = \"https:\n\n\n strings:\n  $IpInfo = \"IP-INFO\"\n  $NetworkInfo = \"Network-INFO\"\n  $OsInfo = \"OS-INFO\"\n  $ProcessInfo = \"Process-INFO\"\n  $BrowserInfo = \"Browser-INFO\"\n  $QueryUserInfo = \"QueryUser-INFO\"\n  $UsersInfo = \"Users-INFO\"\n  $SoftwareInfo = \"Software-INFO\"\n  $AddressFormat = \"%02X-%02X-%02X-%02X-%02X-%02X\"\n  $proxy_str = \"(from environment) = %s\"\n\n  $netuserfun = \"NetUserEnum\"\n  $networkparams = \"GetNetworkParams\"\n\n condition:\n  all of them\n}', 2, '恶意软件', 1);
