INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('zbot', '', 3, 'rule zbot : banker\n{\n      meta:\n		author=\"malware-lu\"\n     strings:\n        $a = \"__SYSTEM__\" wide\n        $b = \"*tanentry*\"\n        $c = \"*<option\"\n        $d = \"*<select\"\n        $e = \"*<input\"\n\n     condition:\n        ($a and $b) or ($c and $d and $e)\n}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('banbra', '', 3, 'rule banbra : banker\n{\n      meta:\n		author=\"malware-lu\"\n    strings:\n        $a = \"senha\" fullword nocase\n        $b = \"cartao\" fullword nocase\n        $c = \"caixa\"\n        $d = \"login\" fullword nocase\n        $e = \".com.br\"\n\n     condition:\n        #a > 3 and #b > 3 and #c > 3 and #d > 3 and #e > 3\n}', 2, '加壳检测', 1);
