INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('dotfuscator', 'Dotfuscator', 3, 'rule dotfuscator : packer\n{\n	meta:\n		author = \"Jean-Philippe Teissier / @Jipe_\"\n		description = \"Dotfuscator\"\n		date = \"2013-02-01\"\n		filetype = \"memory\"\n		version = \"1.0\"\n\n	strings:\n		$a = \"Obfuscated with Dotfuscator\"\n\n	condition:\n		$a\n}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('AutoIt_2', 'AutoIT packer', 3, 'rule AutoIt_2 : packer\n{\n	meta:\n		author = \"Jean-Philippe Teissier / @Jipe_\"\n		description = \"AutoIT packer\"\n		date = \"2013-02-01\"\n		filetype = \"memory\"\n		version = \"1.0\"\n\n	strings:\n		$a = \"This is a compiled AutoIt script. AV researchers please email avsupport@autoitscript.com for support.\"\n\n	condition:\n		$a\n}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('mumblehard_packer', 'Mumblehard i386 assembly code responsible for decrypting Perl code', 3, 'rule mumblehard_packer\n{\n    meta:\n        description = \"Mumblehard i386 assembly code responsible for decrypting Perl code\"\n        author = \"Marc-Etienne M.Leveille\"\n        date = \"2015-04-07\"\n        reference = \"http:\n        version = \"1\"\n\n    strings:\n\n	$decrypt = { 31 db [1-10] ba ?? 00 00 00 [0-6] (56 5f | 89 F7) 39 d3 75 13 81 fa ?? 00 00 00 75 02 31 d2 81 c2 ?? 00 00 00 31 db 43 ac 30 d8 aa 43 e2 e2 }', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('IsPE32', '', 3, 'rule IsPE32 : PECheck\n{\n	condition:\n		\n		uint16(0) == 0x5A4D and\n		\n		uint16(uint32(0x3C)+0x18) == 0x010B\n}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('IsPE64', '', 3, 'rule IsPE64 : PECheck\n{\n	condition:\n		\n		uint16(0) == 0x5A4D and\n		\n		uint16(uint32(0x3C)+0x18) == 0x020B\n}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('IsNET_EXE', '', 3, 'rule IsNET_EXE : PECheck\n{\n	condition:\n		pe.imports (\"mscoree.dll\",\"_CorExeMain\")\n}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('IsNET_DLL', '', 3, 'rule IsNET_DLL : PECheck\n{\n	condition:\n		pe.imports (\"mscoree.dll\",\"_CorDllMain\")\n}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('IsDLL', '', 3, 'rule IsDLL : PECheck\n{\n	condition:\n		\n		uint16(0) == 0x5A4D and\n		\n		(uint16(uint32(0x3C)+0x16) & 0x2000) == 0x2000\n\n}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('IsConsole', '', 3, 'rule IsConsole : PECheck\n{\n	condition:\n		\n		uint16(0) == 0x5A4D and\n		\n		uint16(uint32(0x3C)+0x5C) == 0x0003\n}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('IsWindowsGUI', '', 3, 'rule IsWindowsGUI : PECheck\n{\n	condition:\n		\n		uint16(0) == 0x5A4D and\n		\n		uint16(uint32(0x3C)+0x5C) == 0x0002\n}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('IsPacked', 'Entropy Check', 3, 'rule IsPacked : PECheck\n{\n	meta: \n		description = \"Entropy Check\"\n	condition:\n		\n		uint16(0) == 0x5A4D and\n		\n		uint32(uint32(0x3C)) == 0x00004550 and\n		math.entropy(0, filesize) >= 7.0\n}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('HasOverlay', 'Overlay Check', 3, 'rule HasOverlay : PECheck\n{\n	meta: \n		author=\"_pusher_\"\n		description = \"Overlay Check\"\n	condition:\n		\n		uint16(0) == 0x5A4D and\n		\n		uint32(uint32(0x3C)) == 0x00004550 and\n		\n		\n\n		(pe.sections[pe.number_of_sections-1].raw_data_offset+pe.sections[pe.number_of_sections-1].raw_data_size) < filesize\n		\n}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('HasTaggantSignature', 'TaggantSignature Check', 3, 'rule HasTaggantSignature : PECheck\n{\n	meta: \n		author=\"_pusher_\"\n		description = \"TaggantSignature Check\"\n		date=\"2016-07\"\n	strings:		\n		$a0 = { 54 41 47 47 ?? ?? ?? ?? ?? ?? 00 00 ?? 00 30 82 ?? ?? 06 09 2A 86 48 86 F7 0D 01 07 02 A0 82 ?? ?? 30 82 ?? ?? 02 01 01 31 09 30 07 06 05 2B 0E 03 02 1A 30 82 ?? ?? 06 09 2A 86 48 86 F7 0D 01 07 01 A0 82 ?? ?? 04 82 ?? ?? ?? 00 01 00 ?? ?? }', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('HasDigitalSignature', 'DigitalSignature Check', 3, 'rule HasDigitalSignature : PECheck\n{\n	meta: \n		author=\"_pusher_\"\n		description = \"DigitalSignature Check\"\n		date=\"2016-07\"\n	strings:		\n		\n		$a0 = { ?? ?? ?? ?? 00 02 02 00 30 82 ?? ?? 06 09 2A 86 48 86 F7 0D 01 07 02 A0 82 ?? ?? 30 82 ?? ?? 02 01 01 31 0B 30 09 06 05 2B 0E 03 02 1A 05 00 30 68 06 0A 2B 06 01 04 01 82 37 02 01 04 A0 5A 30 58 30 33 06 0A 2B 06 01 04 01 82 37 02 01 0F 30 25 03 01 00 A0 20 A2 1E 80 1C 00 3C 00 3C 00 3C 00 4F 00 62 00 73 00 6F 00 6C 00 65 00 74 00 65 00 3E 00 3E 00 3E 30 21 30 09 06 05 2B 0E 03 02 1A 05 00 04 14 }', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('HasDebugData', 'DebugData Check', 3, 'rule HasDebugData : PECheck\n{\n	meta: \n		author = \"_pusher_\"\n		description = \"DebugData Check\"\n		date=\"2016-07\"\n	condition:\n		\n		uint16(0) == 0x5A4D and\n		\n		uint32(uint32(0x3C)) == 0x00004550 and\n		\n		\n		\n		(IsPE32 or IsPE64) and\n		((uint32(uint32(0x3C)+0xA8+((uint16(uint32(0x3C)+0x18) & 0x200) >> 5)) >0x0) and (uint32be(uint32(0x3C)+0xAC+((uint16(uint32(0x3C)+0x18) & 0x200) >> 5)) >0x0))\n}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('IsBeyondImageSize', 'Data Beyond ImageSize Check', 3, 'rule IsBeyondImageSize : PECheck\n{\n	meta: \n		author = \"_pusher_\"\n		date = \"2016-07\"\n		description = \"Data Beyond ImageSize Check\"\n	condition:\n		\n		uint16(0) == 0x5A4D and\n		\n		uint32(uint32(0x3C)) == 0x00004550 and\n		for any i in (0..pe.number_of_sections-1):\n		( \n		(pe.sections[i].virtual_address+pe.sections[i].virtual_size) > (uint32(uint32(0x3C)+0x50)) or\n		(pe.sections[i].raw_data_offset+pe.sections[i].raw_data_size) > filesize\n		)\n}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('ImportTableIsBad', 'ImportTable Check', 3, 'rule ImportTableIsBad : PECheck\n{\n	meta: \n		author = \"_pusher_ & mrexodia\"\n		date = \"2016-07\"\n		description = \"ImportTable Check\"\n	condition:\n		\n		uint16(0) == 0x5A4D and\n		\n		uint32(uint32(0x3C)) == 0x00004550 and\n		(IsPE32 or IsPE64) and\n		( 		\n		((uint32(uint32(0x3C)+0x80+((uint16(uint32(0x3C)+0x18) & 0x200) >> 5) )) + (uint32(uint32(0x3C)+0x84+((uint16(uint32(0x3C)+0x18) & 0x200) >> 5))))     > (uint32(uint32(0x3C)+0x50)) \n		or\n		(((uint32(uint32(0x3C)+0x80+((uint16(uint32(0x3C)+0x18) & 0x200) >> 5) )) + (uint32(uint32(0x3C)+0x84+((uint16(uint32(0x3C)+0x18) & 0x200) >> 5))))  == 0x0)\n		\n\n		\n		\n\n		\n		\n		\n		\n		\n		\n		\n		\n\n		\n\n		\n		\n		\n		\n\n		\n\n		or\n		\n		(uint32(0x3C)+0x80+((uint16(uint32(0x3C)+0x18) & 0x200) >> 5) > filesize)\n\n		\n		\n   		\n		\n		)				\n}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('ExportTableIsBad', 'ExportTable Check', 3, 'rule ExportTableIsBad : PECheck\n{\n	meta: \n		author = \"_pusher_ & mrexodia\"\n		date = \"2016-07\"\n		description = \"ExportTable Check\"\n	condition:\n		\n		uint16(0) == 0x5A4D and\n		\n		uint32(uint32(0x3C)) == 0x00004550 and\n		(IsPE32 or IsPE64) and\n		( 		\n		((uint32(uint32(0x3C)+0x78+((uint16(uint32(0x3C)+0x18) & 0x200) >> 5) )) + (uint32(uint32(0x3C)+0x7C+((uint16(uint32(0x3C)+0x18) & 0x200) >> 5))))     > (uint32(uint32(0x3C)+0x50)) \n		)		\n}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('HasModified_DOS_Message', 'DOS Message Check', 3, 'rule HasModified_DOS_Message : PECheck\n{\n	meta: \n		author = \"_pusher_\"\n		description = \"DOS Message Check\"\n		date=\"2016-07\"\n	strings:	\n		$a0 = \"This program must be run under Win32\" wide ascii nocase\n		$a1 = \"This program cannot be run in DOS mode\" wide ascii nocase\n		\n		$a2 = \"This program requires Win32\" wide ascii nocase\n		$a3 = \"This program must be run under Win64\" wide ascii nocase\n	condition:\n		\n		uint16(0) == 0x5A4D and\n		\n		uint32(uint32(0x3C)) == 0x00004550 and not\n		(for any of ($a*) : ($ in (0x0..uint32(0x3c) )))\n}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('HasRichSignature', 'Rich Signature Check', 3, 'rule HasRichSignature : PECheck\n{\n	meta: \n		author = \"_pusher_\"\n		description = \"Rich Signature Check\"\n		date=\"2016-07\"\n	strings:	\n		$a0 = \"Rich\" ascii\n	condition:\n		\n		uint16(0) == 0x5A4D and\n		\n		uint32(uint32(0x3C)) == 0x00004550 and\n		(for any of ($a*) : ($ in (0x0..uint32(0x3c) )))\n}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('IsSuspicious', 'Might be PE Virus', 3, 'rule IsSuspicious\n{\n	meta:\n		author=\"_pusher_\"\n		date = \"2016-07\"\n		description=\"Might be PE Virus\"\n	condition:\n		uint32(0x20) == 0x20202020	\n}', 2, '加壳检测', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('IsGoLink', 'www.GoDevTool.com', 3, 'rule IsGoLink\n{\n	meta:\n		author=\"_pusher_\"\n		date = \"2016-08\"\n		description=\"www.GoDevTool.com\"\n	strings:\n		$a0 = { 47 6F 4C 69 6E 6B }', 2, '加壳检测', 1);
