INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Parallels_Detection', 'Looks for Parallels presence', 3, 'rule Parallels_Detection : AntiVM\n{\n    meta:\n        description = \"Looks for Parallels presence\"\n    strings:\n        $a0 = \"magi\"\n        $a1 = \"c!nu\"\n        $a2 = \"mber\"\n\n        \n        $parallels_vid_1 = \"VEN_80EE\" nocase wide ascii\n    condition:\n        all of them\n}', 2, '检测工具', 1);
