INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Dropper_Strings', 'May have dropper capabilities', 3, 'rule Dropper_Strings\n{\n    meta:\n        description = \"May have dropper capabilities\"\n        author = \"Ivan Kwiatkowski (@JusticeRage)\"\n    strings:\n        $a0 = \"CurrentVersion\\\\Run\" nocase wide ascii\n        $a1 = \"CurrentControlSet\\\\Services\" nocase wide ascii\n        $a2 = \"Programs\\\\Startup\" nocase wide ascii\n        $a3 = \"%temp%\" nocase wide ascii\n        $a4 = \"%allusersprofile%\" nocase wide ascii\n    condition:\n        any of them\n}', 2, '检测工具', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('AutoIT_compiled_script', 'Is an AutoIT compiled script', 3, 'rule AutoIT_compiled_script\n{\n    meta:\n        description = \"Is an AutoIT compiled script\"\n        author = \"Ivan Kwiatkowski (@JusticeRage)\"\n    strings:\n        $a0 = \"AutoIt Error\" ascii wide\n        $a1 = \"reserved for AutoIt internal use\" ascii wide\n    condition:\n        any of them\n}', 2, '检测工具', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('WMI_strings', 'Accesses the WMI', 3, 'rule WMI_strings\n{\n    meta:\n        description = \"Accesses the WMI\"\n        author = \"Ivan Kwiatkowski (@JusticeRage)\"\n    strings:\n        \n        $a0 = /ROOT\\\\(CIMV2|AccessLogging|ADFS|aspnet|Cli|Hardware|interop|InventoryLogging|Microsoft.{10}', 2, '检测工具', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Obfuscated_Strings', 'Contains obfuscated function names', 3, 'rule Obfuscated_Strings\n{\n	meta:\n		description = \"Contains obfuscated function names\"\n		author = \"Ivan Kwiatkowski (@JusticeRage)\"\n	strings:\n		$a0 = { (46 | 66) 64 75 (51 | 71) 73 6E 62 (40 | 60) 65 65 73 64 72 72 }', 2, '检测工具', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Base64d_PE', 'Contains a base64-encoded executable', 3, 'rule Base64d_PE\n{\n	meta:\n		description = \"Contains a base64-encoded executable\"\n		author = \"Florian Roth\"\n		date = \"2017-04-21\"\n		\n	strings:\n		$s0 = \"TVqQAAIAAAAEAA8A\n		$s1 = \"TVqQAAMAAAAEAAAA\n		\n	condition:\n		any of them\n}', 2, '检测工具', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Misc_Suspicious_Strings', 'Miscellaneous malware strings', 3, 'rule Misc_Suspicious_Strings\n{\n    meta:\n        description = \"Miscellaneous malware strings\"\n        author = \"Ivan Kwiatkowski (@JusticeRage)\"\n    strings:\n        $a0 = \"backdoor\" nocase ascii wide\n        $a1 = \"virus\" nocase ascii wide fullword\n        $a2 = \"hack\" nocase ascii wide fullword\n        $a3 = \"exploit\" nocase ascii wide\n        $a4 = \"cmd.exe\" nocase ascii wide\n        $a5 = \"CWSandbox\" nocase wide ascii \n        $a6 = \"System32\\\\drivers\\\\etc\\\\hosts\" nocase wide ascii\n    condition:\n        any of them\n}', 2, '检测工具', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('BITS_CLSID', 'References the BITS service.', 3, 'rule BITS_CLSID\n{\n    meta:\n        description = \"References the BITS service.\"\n        author = \"Ivan Kwiatkowski (@JusticeRage)\"\n        \n    strings:\n        $uuid_background_copy_manager_1_5 =     { 1F 77 87 F0 4F D7 1A 4C BB 8A E1 6A CA 91 24 EA }', 2, '检测工具', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('HexEncodedTextPE', 'Text string with hexadecimal encoded MZ/PE and comma+ separation', 3, 'rule HexEncodedTextPE\n{\n    meta:\n        author = \"Malware Utkonos\"\n        date = \"2020-01-28\"\n        reference = \"https:\n        description = \"Text string with hexadecimal encoded MZ/PE and comma+ separation\"\n    strings:\n        $mz = /4D,.{0,6}', 2, '检测工具', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('url', '', 3, 'rule url {\n    meta:\n        author = \"Antonio S. <asanchez@plutec.net>\"\n    strings:\n        $url_regex = /https?:\\/\\/([\\w\\.-]+)([\\/\\w \\.-]*)/ wide ascii\n    condition:\n        $url_regex\n}', 2, '检测工具', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('asp_file', 'Laudanum Injector Tools - file file.asp', 1, 'rule asp_file : webshell {\n	meta:\n		description = \"Laudanum Injector Tools - file file.asp\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		date = \"2015-06-22\"\n		hash = \"ff5b1a9598735440bdbaa768b524c639e22f53c5\"\n	strings:\n		$s1 = \"'' *** Written by Tim Medin <tim@counterhack.com>\" fullword ascii\n		$s2 = \"Response.BinaryWrite(stream.Read)\" fullword ascii\n		$s3 = \"Response.Write(Response.Status & Request.ServerVariables(\\\"REMOTE_ADDR\\\"))\" fullword ascii \n		$s4 = \"%><a href=\\\"<%=Request.ServerVariables(\\\"URL\\\")%>\\\">web root</a><br/><%\" fullword ascii \n		$s5 = \"set folder = fso.GetFolder(path)\" fullword ascii\n		$s6 = \"Set file = fso.GetFile(filepath)\" fullword ascii\n	condition:\n		uint16(0) == 0x253c and filesize < 30KB and 5 of them\n}', 2, 'Webshell', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('php_killnc', 'Laudanum Injector Tools - file killnc.php', 1, 'rule php_killnc : webshell {\n	meta:\n		description = \"Laudanum Injector Tools - file killnc.php\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		date = \"2015-06-22\"\n		hash = \"c0dee56ee68719d5ec39e773621ffe40b144fda5\"\n	strings:\n		$s1 = \"if ($_SERVER[\\\"REMOTE_ADDR\\\"] == $IP)\" fullword ascii \n		$s2 = \"header(\\\"HTTP/1.0 404 Not Found\\\");\" fullword ascii\n		$s3 = \"<?php echo exec(''killall nc'');?>\" fullword ascii \n		$s4 = \"<title>Laudanum Kill nc</title>\" fullword ascii \n		$s5 = \"foreach ($allowedIPs as $IP) {\" fullword ascii\n	condition:\n		filesize < 15KB and 4 of them\n}', 2, 'Webshell', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('asp_shell', 'Laudanum Injector Tools - file shell.asp', 1, 'rule asp_shell : webshell {\n	meta:\n		description = \"Laudanum Injector Tools - file shell.asp\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		date = \"2015-06-22\"\n		hash = \"8bf1ff6f8edd45e3102be5f8a1fe030752f45613\"\n	strings:\n		$s1 = \"<form action=\\\"shell.asp\\\" method=\\\"POST\\\" name=\\\"shell\\\">\" fullword ascii \n		$s2 = \"%ComSpec% /c dir\" fullword ascii \n		$s3 = \"Set objCmd = wShell.Exec(cmd)\" fullword ascii \n		$s4 = \"Server.ScriptTimeout = 180\" fullword ascii \n		$s5 = \"cmd = Request.Form(\\\"cmd\\\")\" fullword ascii \n		$s6 = \"'' ***  http:\n		$s7 = \"Dim wshell, intReturn, strPResult\" fullword ascii \n	condition:\n		filesize < 15KB and 4 of them\n}', 2, 'Webshell', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('settings', 'Laudanum Injector Tools - file settings.php', 1, 'rule settings : webshell {\n	meta:\n		description = \"Laudanum Injector Tools - file settings.php\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		date = \"2015-06-22\"\n		hash = \"588739b9e4ef2dbb0b4cf630b73295d8134cc801\"\n	strings:\n		$s1 = \"Port: <input name=\\\"port\\\" type=\\\"text\\\" value=\\\"8888\\\">\" fullword ascii \n		$s2 = \"<li>Reverse Shell - \" fullword ascii \n		$s3 = \"<li><a href=\\\"<?php echo plugins_url(''file.php'', __FILE__);?>\\\">File Browser</a>\" ascii \n	condition:\n		filesize < 13KB and all of them\n}', 2, 'Webshell', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('asp_proxy', 'Laudanum Injector Tools - file proxy.asp', 1, 'rule asp_proxy : webshell {\n	meta:\n		description = \"Laudanum Injector Tools - file proxy.asp\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		date = \"2015-06-22\"\n		hash = \"51e97040d1737618b1775578a772fa6c5a31afd8\"\n	strings:\n		$s1 = \"''response.write \\\"<br/>  -value:\\\" & request.querystring(key)(j)\" fullword ascii \n		$s2 = \"q = q & \\\"&\\\" & key & \\\"=\\\" & request.querystring(key)(j)\" fullword ascii \n		$s3 = \"for each i in Split(http.getAllResponseHeaders, vbLf)\" fullword ascii\n		$s4 = \"''urlquery = mid(urltemp, instr(urltemp, \\\"?\\\") + 1)\" fullword ascii \n		$s5 = \"s = urlscheme & urlhost & urlport & urlpath\" fullword ascii \n		$s6 = \"Set http = Server.CreateObject(\\\"Microsoft.XMLHTTP\\\")\" fullword ascii \n	condition:\n		filesize < 50KB and all of them\n}', 2, 'Webshell', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('cfm_shell', 'Laudanum Injector Tools - file shell.cfm', 1, 'rule cfm_shell : webshell {\n	meta:\n		description = \"Laudanum Injector Tools - file shell.cfm\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		date = \"2015-06-22\"\n		hash = \"885e1783b07c73e7d47d3283be303c9719419b92\"\n	strings:\n		$s1 = \"Executable: <Input type=\\\"text\\\" name=\\\"cmd\\\" value=\\\"cmd.exe\\\"><br>\" fullword ascii \n		$s2 = \"<cfif ( #suppliedCode# neq secretCode )>\" fullword ascii \n		$s3 = \"<cfif IsDefined(\\\"form.cmd\\\")>\" fullword ascii\n	condition:\n		filesize < 20KB and 2 of them\n}', 2, 'Webshell', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('aspx_shell', 'Laudanum Injector Tools - file shell.aspx', 1, 'rule aspx_shell  : webshell{\n	meta:\n		description = \"Laudanum Injector Tools - file shell.aspx\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		date = \"2015-06-22\"\n		hash = \"076aa781a004ecb2bf545357fd36dcbafdd68b1a\"\n	strings:\n		$s1 = \"remoteIp = HttpContext.Current.Request.Headers[\\\"X-Forwarded-For\\\"].Split(new\" ascii \n		$s2 = \"remoteIp = Request.UserHostAddress;\" fullword ascii \n		$s3 = \"<form method=\\\"post\\\" name=\\\"shell\\\">\" fullword ascii \n		$s4 = \"<body onload=\\\"document.shell.c.focus()\\\">\" fullword ascii \n	condition:\n		filesize < 20KB and all of them\n}', 2, 'Webshell', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('php_shell', 'Laudanum Injector Tools - file shell.php', 1, 'rule php_shell  : webshell{\n	meta:\n		description = \"Laudanum Injector Tools - file shell.php\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		date = \"2015-06-22\"\n		hash = \"dc5c03a21267d024ef0f5ab96a34e3f6423dfcd6\"\n	strings:\n		$s1 = \"command_hist[current_line] = document.shell.command.value;\" fullword ascii \n		$s2 = \"if (e.keyCode == 38 && current_line < command_hist.length-1) {\" fullword ascii \n		$s3 = \"array_unshift($_SESSION[''history''], $command);\" fullword ascii \n		$s4 = \"if (preg_match(''/^[[:blank:]]*cd[[:blank:]]*$/'', $command)) {\" fullword ascii \n	condition:\n		filesize < 40KB and all of them\n}', 2, 'Webshell', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('php_reverse_shell', 'Laudanum Injector Tools - file php-reverse-shell.php', 1, 'rule php_reverse_shell : webshell {\n	meta:\n		description = \"Laudanum Injector Tools - file php-reverse-shell.php\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		date = \"2015-06-22\"\n		hash = \"3ef03bbe3649535a03315dcfc1a1208a09cea49d\"\n	strings:\n		$s1 = \"$process = proc_open($shell, $descriptorspec, $pipes);\" fullword ascii \n		$s2 = \"printit(\\\"Successfully opened reverse shell to $ip:$port\\\");\" fullword ascii \n		$s3 = \"$input = fread($pipes[1], $chunk_size);\" fullword ascii \n	condition:\n		filesize < 15KB and all of them\n}', 2, 'Webshell', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('php_dns', 'Laudanum Injector Tools - file dns.php', 1, 'rule php_dns  : webshell{\n	meta:\n		description = \"Laudanum Injector Tools - file dns.php\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		date = \"2015-06-22\"\n		hash = \"01d5d16d876c55d77e094ce2b9c237de43b21a16\"\n	strings:\n		$s1 = \"$query = isset($_POST[''query'']) ? $_POST[''query''] : '''';\" fullword ascii \n		$s2 = \"$result = dns_get_record($query, $types[$type], $authns, $addtl);\" fullword ascii \n		$s3 = \"if ($_SERVER[\\\"REMOTE_ADDR\\\"] == $IP)\" fullword ascii \n		$s4 = \"foreach (array_keys($types) as $t) {\" fullword ascii\n	condition:\n		filesize < 15KB and all of them\n}', 2, 'Webshell', 1);
