INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('php_file', 'Laudanum Injector Tools - file file.php', 1, 'rule php_file  : webshell{\n	meta:\n		description = \"Laudanum Injector Tools - file file.php\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		date = \"2015-06-22\"\n		hash = \"7421d33e8007c92c8642a36cba7351c7f95a4335\"\n	strings:\n		$s1 = \"$allowedIPs =\" fullword ascii \n		$s2 = \"<a href=\\\"<?php echo $_SERVER[''PHP_SELF'']  ?>\\\">Home</a><br/>\" fullword ascii \n		$s3 = \"$dir  = isset($_GET[\\\"dir\\\"])  ? $_GET[\\\"dir\\\"]  : \\\".\\\";\" fullword ascii\n		$s4 = \"$curdir .= substr($curdir, -1) != \\\"/\\\" ? \\\"/\\\" : \\\"\\\";\" fullword ascii\n	condition:\n		filesize < 10KB and all of them\n}', 2, 'Webshell', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('warfiles_cmd', 'Laudanum Injector Tools - file cmd.jsp', 1, 'rule warfiles_cmd : webshell {\n	meta:\n		description = \"Laudanum Injector Tools - file cmd.jsp\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		date = \"2015-06-22\"\n		hash = \"3ae3d837e7b362de738cf7fad78eded0dccf601f\"\n	strings:\n		$s1 = \"Process p = Runtime.getRuntime().exec(request.getParameter(\\\"cmd\\\"));\" fullword ascii \n		$s2 = \"out.println(\\\"Command: \\\" + request.getParameter(\\\"cmd\\\") + \\\"<BR>\\\");\" fullword ascii \n		$s3 = \"<FORM METHOD=\\\"GET\\\" NAME=\\\"myform\\\" ACTION=\\\"\\\">\" fullword ascii\n		$s4 = \"String disr = dis.readLine();\" fullword ascii\n	condition:\n		filesize < 2KB and all of them\n}', 2, 'Webshell', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('asp_dns', 'Laudanum Injector Tools - file dns.asp', 1, 'rule asp_dns  : webshell{\n	meta:\n		description = \"Laudanum Injector Tools - file dns.asp\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		date = \"2015-06-22\"\n		hash = \"5532154dd67800d33dace01103e9b2c4f3d01d51\"\n	strings:\n		$s1 = \"command = \\\"nslookup -type=\\\" & qtype & \\\" \\\" & query \" fullword ascii \n		$s2 = \"Set objCmd = objWShell.Exec(command)\" fullword ascii \n		$s3 = \"Response.Write command & \\\"<br>\\\"\" fullword ascii \n		$s4 = \"<form name=\\\"dns\\\" method=\\\"POST\\\">\" fullword ascii \n	condition:\n		filesize < 21KB and all of them\n}', 2, 'Webshell', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('php_reverse_shell_2', 'Laudanum Injector Tools - file php-reverse-shell.php', 1, 'rule php_reverse_shell_2  : webshell{\n	meta:\n		description = \"Laudanum Injector Tools - file php-reverse-shell.php\"\n		author = \"Florian Roth\"\n		reference = \"http:\n		date = \"2015-06-22\"\n		hash = \"025db3c3473413064f0606d93d155c7eb5049c42\"\n	strings:\n		$s1 = \"$process = proc_open($shell, $descriptorspec, $pipes);\" fullword ascii \n		$s7 = \"$shell = ''uname -a; w; id; /bin/sh -i'';\" fullword ascii \n	condition:\n		filesize < 10KB and all of them\n}', 2, 'Webshell', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Backdoor_WebShell_asp', 'Detect ASPXSpy', 1, 'rule Backdoor_WebShell_asp : ASPXSpy\n{\n    meta:\n    description= \"Detect ASPXSpy\"\n    author = \"xylitol@temari.fr\"\n    date = \"2019-02-26\"\n    \n    strings:\n    $string1 = \"CmdShell\" wide ascii\n    $string2 = \"ADSViewer\" wide ascii\n    $string3 = \"ASPXSpy.Bin\" wide ascii\n    $string4 = \"PortScan\" wide ascii\n    $plugin = \"Test.AspxSpyPlugins\" wide ascii\n \n    condition:\n    3 of ($string*) or $plugin\n}', 2, 'Webshell', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('webshell_ChinaChopper_aspx', 'Detect China Chopper ASPX webshell', 1, 'rule webshell_ChinaChopper_aspx\n{\n  meta:\n    author      = \"Ryan Boyle randomrhythm@rhythmengineering.com\"\n    date        = \"2020/10/28\"\n    description = \"Detect China Chopper ASPX webshell\"\n    reference1  = \"https:\n    filetype    = \"aspx\"\n  strings:\n	$ChinaChopperASPX = {25 40 20 50 61 67 65 20 4C 61 6E 67 75 61 67 65 3D ?? 4A 73 63 72 69 70 74 ?? 25 3E 3C 25 65 76 61 6C 28 52 65 71 75 65 73 74 2E 49 74 65 6D 5B [1-100] 75 6E 73 61 66 65}', 2, 'Webshell', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('webshell_ChinaChopper_php', 'Detect China Chopper PHP webshell', 1, 'rule webshell_ChinaChopper_php\n{\n  meta:\n    author      = \"Ryan Boyle randomrhythm@rhythmengineering.com\"\n    date        = \"2020/10/29\"\n    description = \"Detect China Chopper PHP webshell\"\n    reference1  = \"https:\n    filetype    = \"php\"\n  strings:\n	$ChinaChopperPHP = {3C 3F 70 68 70 20 40 65 76 61 6C 28 24 5F 50 4F 53 54 5B ?? 70 61 73 73 77 6F 72 64 ?? 5D 29 3B 3F 3E}', 2, 'Webshell', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('Dotico_PHP_webshell', '.ico PHP webshell - file <eight-num-letter-chars>.ico', 1, 'rule Dotico_PHP_webshell : webshell {\n    meta:\n        description = \".ico PHP webshell - file <eight-num-letter-chars>.ico\"\n        author = \"Luis Fueris\"\n        reference = \"https:\n        date = \"2019/12/04\"\n    strings:\n        $php = \"<?php\" ascii\n        $regexp = /basename\\/\\*[a-z0-9]{,6}', 2, 'Webshell', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('php_anuna', 'Catches a PHP Trojan', 1, 'rule php_anuna\n{\n    meta:\n        author      = \"Vlad https:\n        date        = \"2016/07/18\"\n        description = \"Catches a PHP Trojan\"\n    strings:\n        $a = /<\\?php \\$[a-z]+ = ''/\n        $b = /\\$[a-z]+=explode\\(chr\\(\\([0-9]+[-+][0-9]+\\)\\)/\n        $c = /\\$[a-z]+=\\([0-9]+[-+][0-9]+\\)/\n        $d = /if \\(!function_exists\\(''[a-z]+''\\)\\)/\n    condition:\n        all of them\n}', 2, 'Webshell', 1);
