INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('chinese_spam_spreader', 'Catches chinese PHP spam files (autospreaders)', 1, 'rule chinese_spam_spreader : webshell\n{\n    meta:\n        author      = \"Vlad https:\n        date        = \"2016/07/18\"\n        description = \"Catches chinese PHP spam files (autospreaders)\"\n    strings:\n        $a = \"User-Agent: aQ0O010O\"\n        $b = \"<font color=''red''><b>Connection Error!</b></font>\"\n        $c = /if ?\\(\\$_POST\\[Submit\\]\\) ?{/\n    condition:\n        all of them\n}', 2, 'Webshell', 1);
INSERT INTO `malware_rule` (`name`, `description`, `risk_level`, `rule_content`, `os_type`, `category`, `status`) VALUES ('chinese_spam_echoer', 'Catches chinese PHP spam files (printers)', 1, 'rule chinese_spam_echoer : webshell\n{\n    meta:\n        author      = \"Vlad https:\n        date        = \"2016/07/18\"\n        description = \"Catches chinese PHP spam files (printers)\"\n    strings:\n        $a = \"set_time_limit(0)\"\n        $b = \"date_default_timezone_set(''PRC'');\"\n        $c = \"$Content_mb;\"\n        $d = \"/index.php?host=\"\n    condition:\n        all of them\n}', 2, 'Webshell', 1);
